    ["……4"] = false,
    ["……5"] = false,
    ["……不像我们想的那样，这里的助学基金足以覆盖我的所有支出。"] = "...Это не то, что мы думали; стипендиального фонда здесь достаточно, чтобы покрыть все мои расходы.",
    ["……不好意思啊客人，今天刚好卖完了，下次一定。"] = "...Извини, покупатель, мы только что распродали билеты. Определенно в следующий раз.",
    ["……不过，你瞧这只小白猫，我是说，她还挺漂亮，对吧？我把她收养了怎么样？"] = "...Однако взгляните на эту маленькую белую кошку, я имею в виду, она довольно хорошенькая, правда? Как насчет того, чтобы я ее усыновил?",
    ["……不，不，如果真让他听到有人在议论，我们两个明天就得坐火车逃命去！"] = "...Нет-нет, если он действительно услышит, как кто-то об этом говорит, завтра нам обоим придется сесть на поезд и бежать, спасая свои жизни!",
    ["……你刚刚讲了个笑话？"] = "...Ты только что рассказал анекдот?",
    ["……你被骂不冤。"] = "...Вы заслуживаете того, чтобы вас отругали.",
    ["……先别说这些，快下来吧，呃，我原谅你。"] = "...Не будем сейчас об этом, спускайся скорее, э-э, я прощаю тебя.",
    ["……准确地说，在等它回来。"] = "...Точнее говоря, жду его возвращения.",
    ["……到底谁在买？"] = "...Кто именно покупает?",
    ["……可是上次带头罢工的，年终奖金被扣完了。"] = "...Но у последнего человека, возглавившего забастовку, полностью вычли премию по итогам года.",
    ["……呃，阁、阁下，或许您……"] = "...Э-э, Ваше, Ваше Превосходительство, может быть, вы...",
    ["……呵，你身上没有老鼠的味道。"] = "...Хех, ты не пахнешь крысой.",
    ["……和客人的数量差不多吧，我、我会成为全廷根最幽默的咖啡师的。"] = "...Это примерно столько же, сколько клиентов. Я, я стану самым юмористическим бариста во всем Тингене.",
    ["……和我吗？呃……我，抱歉，我有些紧张。"] = "...Со мной? Э... Извините, я немного нервничаю.",
    ["……哦，请原谅，没有留意到您的到来，我再占用这里一小会就好。"] = "...Ой, простите меня, я не заметил вашего прихода. Я просто займу это место еще немного.",
    ["……因为我不想结业。结业考试之后，我就要去城里生活了。老师说，这是为了让我得到更好的教育。"] = "...Потому что я не хочу выпускаться. После выпускного экзамена мне придётся уехать жить в город. Учитель говорит, что это ради лучшего образования.",
    ["……多余的事就少打听。"] = "...Не спрашивай о ненужных вещах.",
    ["……大白天的，这是可以直接说的吗！"] = "...Средь бела дня об этом можно сказать прямо!",
    ["……好想喝“焦糖炸弹”！"] = "...Мне очень хочется выпить «Карамельную бомбу»!",
    ["……如果病床上的亲人拖垮了你的耐心、你的生活、甚至你的爱，你会怎么对待他呢？"] = "...Если любимый человек на смертном одре истощает ваше терпение, вашу жизнь и даже вашу любовь, как бы вы с ним поступили?",
    ["……就这一晚上，别叫我太太。行吗？"] = "...Только сегодня вечером не называй меня «мэм». Сможешь ли ты это сделать?",
    ["……我再考虑考虑吧。"] = "...Я еще подумаю.",
    ["……我只押一点点钱，就一点点，绝对不会影响生活，嘿嘿。"] = "...Ставлю немного денег, совсем немного, это точно не повлияет на мою жизнь, хе-хе.",
    ["……我必须确认，湖灵会造成什么危害？它是否损伤过你们的身体或精神？"] = "...Я должен подтвердить, какой вред причиняет Дух Озера? Это повредило ваше тело или разум?",
    ["……我怎么知道你们合约是真是假！反正……反正扣得太狠了……算我倒霉！"] = "...Откуда мне знать, настоящий твой контракт или поддельный! В любом случае... в любом случае, вывод был слишком суровым... считайте, что мне не повезло!",
    ["……我要去买更多能让自己时尚的珠宝！"] = "...Я куплю еще украшений, чтобы выглядеть модно!",
    ["……或许我们不该与那样低劣的境况相比——哦该死！我发誓刚才有只大蜘蛛爬过你的帽檐！"] = "...Возможно, нам не следует сравнивать себя с такими низшими обстоятельствами - ох, черт возьми! Клянусь, большой паук только что заполз по полям твоей шляпы!",
    ["……抱歉，我失态了，我刚把学生们的结业试卷收上来，那个小混蛋——<P_Yellow>罗丁</>突然跳起来，叫着要去厕所。"] = "...Прошу прощения, я потерял самообладание. Я только что собрал экзаменационные работы учеников, как вдруг этот сорванец — <P_Yellow>Родин</> — вскочил с места с криками, что ему срочно нужно в туалет.",
    ["……抱，抱歉，我……我不……那个，擅长接、接待……别在意。"] = "...Итак, извини, я... я не... ну, я не умею получать... не обращай на меня внимания.",
    ["……欠得好。"] = "...Заслуженно.",
    ["……看起来命运的指点已经降下，今天您还是适合进入俱乐部，找一名真正的占卜师占卜一下。"] = "...Похоже, указание судьбы уже снизошло. Сегодня вам всё же стоит зайти в клуб и найти настоящего гадателя для гадания.",
    ["……真有这么神奇？"] = "...Неужели это так волшебно?",
    ["……等等，是拉夫老师派你来拿东西的吗？"] = "...Подожди, Учитель Лав послал тебя за чем-то?",
    ["……算了算了，我给你就是了。真是长见识……"] = "...Забудь, забудь, я тебе отдам. Сегодня я действительно кое-чему научился...",
    ["……让我们彻底忘掉那场战争，安娜。"] = "...Давайте совсем забудем о той войне, Анна.",
    ["……谢谢您接受我的采访，桌上的食物，这些都是采访的报酬"] = "...Спасибо, что согласились на мое интервью. Еда на столе — это плата за собеседование.",
    ["……走开，让我自己一个人在这里。"] = "...Уходи, позволь мне побыть здесь одному.",
    ["……这世上存在一些超乎寻常的事情。教授是个讲究人，但我上次见他时，他的体毛和指甲已经垂到地上了。"] = "...В этом мире случаются вещи за гранью понимания. Профессор всегда был безупречно опрятным человеком, но когда я видел его в последний раз, его волосы на теле и ногти уже волочились по полу.",
    ["……这没你的事，你最好小心自己因为翘课太多而被开除！"] = "...Это не имеет к вам никакого отношения. Вам лучше быть осторожным, чтобы вас не исключили за пропуск слишком большого количества занятий!",
    ["……这种事，也不少见。 但是，您的曲子……至少在我这儿，永远是最好的。"] = "...Такое случается сплошь и рядом. Но ваши мелодии... по крайней мере, для меня они навсегда останутся лучшими.",
    ["……这要是登不出来，我就完蛋了。"] = "...Если это не будет опубликовано, мне конец.",
    ["……那可是酒馆！我不能再给自己花钱的机会了！"] = "...Это таверна! Я не могу дать себе еще один шанс потратить деньги!",
    ["……那场官司，纺织厂的老板都要来亲自找我。"] = "...Из-за той тяжбы владельцу ткацкой фабрики пришлось лично прийти ко мне.",
    ["……那我9便士！"] = "...Тогда я заплачу 9 пенсов!",
    ["《廷根市老实人报》说我们的安全条例像歌剧院的假胡子——中看不中用。"] = "Газета «Честный человек Тинген» утверждает, что наши правила безопасности подобны накладным бородам в оперном театре: на них приятно смотреть, но они бесполезны.",
    ["《暴风山庄》，它读起来离奇又浪漫，很让人着迷……不过这已经是佛尔思女士很早期的书了。"] = "«Грозовой перевал» читается причудливо и романтично, очень увлекательно... но это уже очень ранняя книга г-жи Форс.",
    ["《背叛者指环》海报消失的速度和没上锁的脚踏车一样快！"] = "Плакаты «Кольца предателя» исчезают так же быстро, как незапертый велосипед!",
    ["一个**奇怪**的马桶。他上一位主人显然在这里进行过某种仪式。仪式的结果仍留在里面，散发着**诡异**的气味，并且拒绝被文明社会承认。"] = "**Странный** туалет. Его предыдущий владелец явно проводил здесь какой-то ритуал. Результаты ритуала остаются внутри, источая **странный** запах, и он отказывается признаваться цивилизованным обществом.",
    ["一个戴着高帽子，穿着正装？或许还应该加上——总是对着空气说话的，这么一个人。"] = "Человек в цилиндре и формальной одежде? Возможно, мне следует добавить: тот, кто всегда разговаривает с воздухом.",
    ["一会，只需要再看一会就好，我会努力的，只要成为政府雇员，母亲就不需要这么辛苦了……"] = "Всего лишь мгновение, еще немного — это нормально. Я буду усердно работать. Как только я стану государственным служащим, маме не придется так много работать...",
    ["一位朋友送的，扉页还有作者签名。他还写过《迷雾港》，前年那出，写码头工人的。"] = "Подарок от друга, титульный лист подписан автором. Он также написал «Туманную гавань», вышедшую в позапрошлом году и посвященную докерам.",
    ["一分耕耘，一分收获。"] = "You reap what you sow.",
    ["一切都好，亲爱的！你带沃尔特去那边买一份报纸来好吗？好了，快去吧！"] = "Все хорошо, дорогая! Не мог бы ты отвезти Уолтера туда купить газету? Хорошо, продолжай сейчас!",
    ["一只尖叫的水壶，迸发着水与火激烈博弈的蒸汽。"] = "Кричащий чайник, лопающийся паром от жестокой битвы воды и огня.",
    ["一天只需要花5苏勒……不，3苏勒，就能带它去“那些”酒馆报名，它能替你赢钱的。"] = "Это стоит всего 5 суле в день... нет, 3 суле, чтобы принести его в «те» таверны и зарегистрироваться, это может принести вам деньги.",
    ["一定会的。"] = "Она обязательно это сделает.",
    ["一定是你要长脑子了！"] = "Должно быть, это потому, что твой мозг растет!",
    ["一定能找到的，小姐，祝你好运。"] = "Вы обязательно найдете его, мисс, удачи.",
    ["一定！"] = "Определенно!",
    ["一想到要去这么美丽的城市定居……呵呵，我这颗老心脏都恢复活力了。"] = "Просто думаю о том, чтобы поселиться в таком прекрасном городе... Хе-хе, мое старое сердце обрело свою жизненную силу.",
    ["一把足够精准的枪械，正适合您这样优雅的{{先生|女士}}。您想看哪一种？"] = "Достаточно точное огнестрельное оружие как раз подойдет такому элегантному {{Mr.|Ms.}}, как вы. Какой из них вы бы хотели увидеть?",
    ["一整个屋子刷下来，五苏勒，还得管饭。"] = "Пять суле, чтобы покрасить всю комнату, и им нужно обеспечить еду.",
    ["一楼是舞步和酒杯交织的地方。您要是想找姑娘们喝一杯，不妨过去坐坐。不管您打算聊什么，她们都懂得如何让人开口。"] = "На первом этаже переплетаются танцевальные па и бокалы для вина. Если вы хотите найти дам, чтобы выпить, не стесняйтесь подойти и присесть. Независимо от того, о чем вы собираетесь говорить, они знают, как заставить людей открыться.",
    ["一楼有什么好的。客人大多只往台上看，台下也没人请我喝一杯。"] = "Чем хорош первый этаж? Большинство гостей смотрят только на сцену, и никто не приглашает меня выпить внизу.",
    ["一点小伤，阻碍不了我的成功。"] = "Небольшая травма не помешает моему успеху.",
    ["一片废墟散落在水面上，木板和碎石凌乱堆积，依稀还能看出原本拱起的轮廓。"] = "Груда руин разбросана по воде, деревянные доски и щебень свалены в кучу, хотя первоначальный арочный контур все еще можно смутно различить.",
    ["一股神奇的冲动促使你迫切地想要尝试下。 “去拿起来试试吧”他说, 恶魔的语言在你心底挠痒痒"] = "Неведомый импульс заставляет вас непреодолимо захотеть попробовать. «Возьми и опробуй», — говорит он, и дьявольские речи сладко щекочут ваше сердце.",
    ["丈夫去世得早，两夫妇也没有孩子，只留下这些花给她。"] = "Ее муж рано ушел из жизни, а детей у пары не было, оставив ей только эти цветы.",
    ["三段式尊名不仅是一个名字，它更接近一种神性的注视、一种召唤的咒文。"] = "Трехчастное почетное имя – это не просто имя, оно ближе к божественному взору, заклинанию призыва.",
    ["上一位工人摔死了。"] = "Предыдущий рабочий упал насмерть.",
    ["上个学期的选修课又被劳伦斯老师打了不及格，我是不是应该去初代校长雕像那儿祈祷一下？"] = "В прошлом семестре профессор Лоуренс снова завалил меня на факультативе... Может, мне стоит помолиться у статуи первого ректора?",
    ["上回向盥洗室之主祈祷后，就从天而降一位警察{{先生|女士}}，帮助我们解决了腹泻问题，如果再祈祷一次，是不是能让“焦糖炸弹”复活？"] = "После последней молитвы Лорду Уборной с неба спустился полицейский {{Mr.|Ms.}} и помог нам решить нашу проблему с диареей. Если мы помолимся еще раз, сможем ли мы вернуть «Карамельную бомбу» к жизни?",
    ["上篇至少值五苏勒的报道，他只给我两苏勒。"] = "Он дал мне всего два суле за отчет, который стоил не меньше пяти.",
    ["下一站，你将前往真实的战场，直面战争的历史。"] = "At the next stop, you will head to a real battlefield and face the history of war directly.",
    ["下午好，{{PlayerName}}，我预感到了你会出现。"] = "Добрый день, {{PlayerName}}, предчувствовал, что ты появишься.",
    ["下午好，和你相遇真是意外之喜，请问愿意顺道和我一起享用下午茶吗？"] = "Добрый день! Наша встреча — право, приятнейшая неожиданность. Не согласитесь ли разделить со мной послеполуденный чай?",
    ["下午好，请问我可以为你做些什么？"] = "Добрый день. Могу ли я что-нибудь сделать для тебя?",
    ["下周开组会，我一定会被导师夸的，嘿嘿！看来今年不用延毕咯！ "] = "На следующей неделе у меня собрание группы, мой наставник обязательно похвалит меня, хе-хе! Похоже, мне не придется откладывать выпускной в этом году!",
    ["下周的场次，位置还不错。 "] = "На следующей неделе места довольно хорошие.",
    ["下来！快把帽子和野餐布还给我！"] = "Спускайся! Верните мне мою шляпу и одеяло для пикника!",
    ["下次再把新谱子带来吧。我等着弹。 但是，别再熬到后半夜了，好吗？"] = "В следующий раз принеси новые ноты. Я буду ждать, чтобы сыграть в нее. Но больше не ложись спать до середины ночи, ладно?",
    ["下次我会为你引荐廷根时尚协会的。"] = "В следующий раз я порекомендую вас Ассоциации моды Тинген.",
    ["不不不。相处下来，我发现他们为人友善，力气也大，很快，大家就一起捕鱼出海了。不然，你哪能见到我来廷根度假？"] = "Нет, нет. Поладив, я обнаружил, что они дружелюбны и сильны, и вскоре все вместе ловили рыбу и отправлялись в море. Иначе как бы вы могли представить, что я приеду в Тинген на каникулы?",
    ["不不不，我不养那种大家伙，我喜欢那种小巧可爱，不会叫的小宠物。"] = "Нет, нет, нет, я не держу этих больших парней; Мне нравятся эти маленькие, милые домашние животные, которые не шумят.",
    ["不不不，我并没有恰好拿走什么东西。"] = "Нет, нет, нет, я ничего не брал.",
    ["不了，赶时间。 "] = "Нет, я тороплюсь. ",
    ["不仅如此，偶尔还有人说它会惨叫……大约只是传言罢了。"] = "Мало того, иногда люди говорят, что оно кричит... возможно, это просто слухи.",
    ["不仅如此，它竟然连放屁都很动听，不然怎么“屁美”呢？真是头神奇的猪……"] = "Мало того, он даже звучит приятно, когда пукает, иначе почему бы его называли «Пердежная красавица»? Какая волшебная свинья...",
    ["不仅如此，我兄弟说工厂后面最近总有怪声，像是……在磨骨头！ "] = "Мало того, мой брат сказал, что в последнее время за фабрикой всегда раздавались странные звуки, вроде... перемалывания костей!",
    ["不去下面看吗？"] = "Почему бы не спуститься вниз и посмотреть?",
    ["不可思议！你居然让阿比输掉了比赛，我可从没有看到他在擂台晕过去！"] = "Невероятный! Ты фактически заставил Аби проиграть матч. Я никогда раньше не видел, чтобы он терял сознание на ринге!",
    ["不可犹豫，不可退缩，心怀信念。所以我也称呼它为“信仰之跃”。"] = "Не сомневайтесь, не отступайте, сохраняйте веру в своем сердце. Вот почему я также называю это «Прыжком веры».",
    ["不可犹豫，不可退缩，心怀信念。所以我也称呼它为“红月之跃”。"] = "Нельзя колебаться, нельзя отступать, нужно хранить веру в сердце. Вот почему я зову это «Прыжком Алой Луны».",
    ["不可能！廷根怎么会有比我更懂时尚的人！"] = "Невозможный! Как может быть в Тингене кто-то, кто разбирается в моде лучше меня!",
    ["不吃就还给我。"] = "Отдай его обратно, если не собираешься его есть.",
    ["不同的是它们鲜少会迎来你这样的客人——旁边克制不住地用余光瞥着你的老人才是它们的常客。"] = "Разница в том, что они редко видят такого покупателя, как вы: пожилая женщина неподалеку, которая не может не взглянуть на вас, является их постоянным клиентом.",
    ["不好意思，容我再考虑考虑。"] = "Извините, позвольте мне подумать об этом еще немного.",
    ["不好意思，我还有事情，恐怕得先走了。"] = "Прошу прощения, у меня дела, я вынужден откланяться.",
    ["不如来看看我手头的这几套房子，不收押金，合同正规，包您满意！"] = "Почему бы не взглянуть на дома, которые у меня есть? Без залога, официальный договор, гарантирую, вы останетесь довольны!",
    ["不如看看报纸对此的评论。"] = "Почему бы не посмотреть комментарий газеты по этому поводу.",
    ["不必担心，下面有堆草垛……想试试吗？跃下的感觉棒极了！"] = "Не волнуйтесь, внизу куча сена... хотите попробовать? Ощущение прыжка вниз фантастическое!",
    ["不必担忧，女神会眷顾祂的每一位信徒。"] = "Не беспокойтесь, Богиня позаботится о каждом Своем верующем.",
    ["不是你说想听实话吗？说了你又不高兴，真搞不懂……"] = "Разве ты не говорил, что хочешь услышать правду? Ты недовольна, когда я это говорю, я правда не понимаю...",
    ["不是偷的，也不是抢的，是用我的第一桶金买的。"] = "Их не украли и не ограбили; Я купил их на свой первый горшок с золотом.",
    ["不是陪伴的问题……我把剪羊毛换来的私房钱全藏在咸鱼里了！"] = "Дело не в компании... Все свои личные деньги от стрижки овец я ​​спрятал в соленой рыбе!",
    ["不是，是给报社投稿的文章。"] = "Нет, это статья для газеты.",
    ["不然它为什么叫猫呢？在瑞恩收养猫之前，他的煎肉摊总是被老鼠光顾。"] = "Иначе почему бы его назвали Котом? До того, как Райан усыновил кота, его ларек с жареным мясом всегда посещали мыши.",
    ["不用在意，阁下，您同我说话的声音像落叶一样轻。"] = "Не обращайте на это внимания, милорд, ваш голос, когда вы говорите со мной, легок, как падающий лист.",
    ["不用担心房租，在哪都能住……"] = "Вам не нужно беспокоиться об аренде, вы можете жить где угодно...",
    ["不用紧张，只是日常巡逻。"] = "Не волнуйтесь, это обычный патруль.",
    ["不用羞于开口，{{先生|女士}}，像你这样没有足够的钱买车票的人还有很多。"] = "Не стыдись высказываться, {{ Mr. | Ms. }}. Есть много таких, как вы, у которых не хватает денег на билет.",
    ["不用谢，你都需要一笔“启动资金”嘛。"] = "Пожалуйста, ведь вам нужен «стартовый капитал».",
    ["不瞒你说，我们家四口人生日都是同一天。"] = "Не буду вам врать, у всех четверых в нашей семье день рождения в один и тот же день.",
    ["不瞒你说，我略懂些灵摆占卜和塔罗占卜。 "] = "Признаться, я немного смыслю в гадании на маятнике и картах Таро.",
    ["不知道她白天看上的那一款需要多少钱？这还是我第一次买这样的奢侈品……"] = "Интересно, сколько стоит тот, который она увидела днем? Впервые покупаю такую ​​роскошную вещь...",
    ["不知道那个特伦什么帝国在哪里，我从来没听说过。"] = "Я не знаю, где находится эта Тренская Империя; Я никогда об этом не слышал.",
    ["不知道阿尔菲他们现在过得怎么样……"] = "Интересно, как сейчас дела у Алфи и остальных...",
    ["不管怎么样，我还是想要试试。"] = "Несмотря ни на что, я все еще хочу попробовать.",
    ["不管怎样，我可不建议您掺和进去。"] = "В любом случае, я не предлагаю вам вмешиваться.",
    ["不行，新品的味道还是不够特别……"] = "Нет, вкус новинки все же недостаточно особенный...",
    ["不要再追我了，我有不得不拿的理由。"] = "Перестань меня преследовать, у меня есть причина, почему я должен это принять.",
    ["不要忘记带上冒险故事，千万别忘。"] = "Не забудьте взять с собой приключенческие истории; не забывай, обязательно.",
    ["不要随意靠近它，否则会沾染厄运。"] = "Не подходите к нему небрежно, иначе вас запятнает несчастье.",
    ["不识抬举的小家伙们！等你们饿得受不了的时候，可别回来求我……"] = "Неблагодарные маленькие дети! Когда ты умираешь от голода и не можешь больше этого терпеть, не возвращайся и не умоляй меня...",
    ["不过在这之后爷爷就生病了，就是门外那位医生。"] = "Но после этого дедушке стало плохо, а за дверью врач.",
    ["不过她偶尔也会来买白色的百合，安安静静包好。我问过一次，她说“是去看望一位总在睡觉的老朋友啦”，应该是去拉斐尔墓园吧。"] = "Однако время от времени она приходит купить белые лилии, тихо заворачивая их. Однажды я спросил, и она сказала: «Я собираюсь навестить старую подругу, которая всегда спит». Должно быть, она идет на кладбище Рафаэля.",
    ["不过妈妈说他会是个好裁缝的，你想要找妈妈做衣服还是找哥哥做衣服呢？"] = "Но мама говорит, что он будет отличным портным. Ты ищешь маму, чтобы сшить тебе одежду, или моего брата?",
    ["不过对于淑女的甜点来说，或许刚好。"] = "Впрочем, для дамского десерта, пожалуй, в самый раз.",
    ["不过我十分感谢奥斯汀先生的收留，你一定想象不到，在那之前我是一个整天游荡在大街上抢钱的赖皮鬼。"] = "Но я очень благодарен мистеру Остину за то, что он приютил меня. Вы даже представить не можете, что до этого я был обычным бродягой, который целыми днями слонялся по улицам и грабил прохожих.",
    ["不过没事，我这不来找他了吗？看见我他一定会很惊喜的！"] = "Но ничего страшного, разве я не пришел его найти? Он точно будет приятно удивлен, увидев меня!",
    ["不过瞧着方向，他应该往家里去了。他家在集市上做<P_Yellow>酿酒</>生意，沿着<P_Yellow>河堤</>就到了。"] = "Но судя по направлению, он пошел к дому. Его семья держит <P_Yellow>винодельню</> на рынке — ступайте вдоль <P_Yellow>набережной</>, и как раз туда придете.",
    ["不过蒸汽列车也能带来别的地方的报纸和杂志，比如贝克兰德日报。像家庭杂志、故事评论，塔索克报也不错。"] = "Однако паровозы также могут привозить газеты и журналы из других мест, например, из Бэкланд Daily. Семейные журналы, обзоры историй и Тасок Times тоже хороши.",
    ["不过话说回来……虽然喜欢教学，但我毕竟一把年纪了，像现在这样每天从早忙到晚实在是吃不消。"] = "Но, сказав это... хотя мне нравится преподавать, я преклоняюсь в годах, и быть таким занятым с утра до вечера - это действительно больше, чем я могу выдержать.",
    ["不过话说回来，整个鲁恩王国都是这样，希望你不讨厌雨天。"] = "Но опять же, всё королевство Лоен такое. Надеюсь, ты не любишь дождливые дни.",
    ["不过说起海上冒险家……我只想得到《大冒险家》里写的那位。"] = "Но если говорить об авантюристах с моря... единственный, о ком я могу вспомнить, это тот, о котором написано в «Великом авантюристе».",
    ["不过还不够，这广阔的世界本身就是个传奇……"] = "Но этого мало: сам этот огромный мир — легенда...",
    ["不过，“黑夜渐袭”……呵，或许也不全算是巧合。我向来是女神的虔诚信徒，若说冥冥之中蒙受些许黑夜的眷顾，倒也合乎情理。"] = "Однако «Ночь приближается»… Хех, возможно, это не совсем совпадение. Я всегда был ревностным поклонником Богини. Если говорят, что ночь в темноте оказала мне какую-то небольшую услугу, то это разумно.",
    ["不过，你的建议有一定的价值。我会和他们提议的。"] = "Однако ваше предложение имеет определенную ценность. Я им это предложу.",
    ["不过，她很漂亮，也很善良，像我们这样的艺术家都喜欢美的东西不是吗？我经常邀请她来画室做客呢！"] = "К тому же она очень красива и добра, а мы, художники, ведь питаем слабость ко всему прекрасному, не так ли? Я часто приглашаю ее в свою мастерскую!",
    ["不过，我需要提醒你一点。如果遇见非凡事件，记得及时上报教会，也算是为你自己着想。"] = "Однако мне нужно кое о чём тебе напомнить. Если столкнёшься с Потусторонним происшествием, не забудь вовремя сообщить об этом Церкви — это и в твоих интересах.",
    ["不过，望着海面，我感受到了风暴的启示。"] = "Однако, глядя на море, я почувствовал предчувствие шторма.",
    ["不过，罗塞尔大帝说过，只要尝试组合字句的次数够多，卷毛狒狒也能写出伟大的诗作。"] = "Однако император Розель сказал, что если вы попытаетесь объединить слова достаточное количество раз, кудрявый павиан также сможет писать отличные стихи.",
    ["不需要，不需要！本来收租就烦，离我远点！"] = "Нет, нет! Сбор арендной платы и так раздражает, держись от меня подальше!",
    ["不！我一天见不到毛球心就要碎了，你再去多贴几张告示。"] = "Нет! Мое сердце разорвется, если я хоть день не увижу Пушка. Иди и расклей еще объявлений.",
    ["不！我离开莉莉会失去对生活的热爱……吉娜离开我会发疯，她们两个我都无法放弃。"] = "Нет! Если я брошу Лили, я потеряю любовь к жизни... Если Джина бросит меня, я сойду с ума. Я не могу отказаться ни от одного из них.",
    ["不，不是你想的那样！"] = "Нет, это не то, что вы думаете!",
    ["不，亲爱的，你比我要年轻整整两个月呢，我才是不中用的老头子！"] = "Нет, голубушка, ты меня моложе на целых два месяца, это я никуда не годюсь, старик!",
    ["不，在现实世界我有很多身份，你如果想找我，可以去鲁恩慈善基金会。至于心理治疗，这是“观众”途径的非凡能力。"] = "Нет, в реальном мире у меня много личностей. Если хочешь меня найти, отправляйся в Благотворительный фонд Лоэн. Что касается психотерапии, это Потусторонняя способность Пути «Зрителя».",
    ["不，我是说那个脏兮兮的搬运工长得和比尔一模一样！"] = "Нет, я имею в виду, что этот грязный носильщик выглядит точно так же, как Билл!",
    ["不，这并不是我厉害，而是因为我所卖的材料。"] = "Нет, дело вовсе не во мне, а в материалах, которыми я торгую.",
    ["世上竟然有这么巧的事情。"] = "Я не могу поверить, что в мире существует такое совпадение.",
    ["两只小猫都好可爱……"] = "Оба котенка такие милые...",
    ["两居室的房租是每周5苏勒6便士，相信我，这是全廷根市最划算的公寓！"] = "Арендная плата за трехкомнатную квартиру 5 суле 6 пенсов в неделю, поверьте, это самая экономичная квартира во всем Тингене!",
    ["两年前的战争里，要不是教会那位枢机主教出手，我们早就喂鱼了。"] = "В той войне два года назад, если бы не архиепископ из Церкви, мы бы уже давно кормили рыб.",
    ["中间这颗25克拉的蓝宝石，更是纯净得如同星辰垂下的眼泪。"] = "Сапфир весом 25 карат в центре чист, как слезы, пролитые звездами.",
    ["为了你，无论是高墙还是深渊，我都愿意越过。"] = "Ради тебя, будь то высокая стена или пропасть, Я готов ее перейти.",
    ["为了家人！为了未来！"] = "Для семьи! На будущее!",
    ["为了普通人的安全，非凡事件的真相无法公布出去，但我还是希望更多人知道他们的故事。"] = "В целях безопасности простых людей правда о необычных событиях не может быть обнародована, но я все же надеюсь, что больше людей узнают их истории.",
    ["为什么一定要赶尽杀绝？你们得到的东西还不够多吗？"] = "Почему ты должен убить их всех? Разве ты не получил достаточно?",
    ["为什么不像其他摊主一样把垃圾留给清洁工呢？"] = "Почему бы не оставить мусор уборщицам, как это делают другие владельцы ларьков?",
    ["为什么不去富人更多的地区试试呢？那里的人也许会更有兴趣。"] = "Почему бы не попробовать районы с более богатыми людьми? Люди там могут быть более заинтересованы.",
    ["为什么不自己写呢？"] = "Почему бы тебе не сделать это самому?",
    ["为什么他们会叫它“甜冰茶”呢？"] = "Почему они назвали это «Сладкий чай со льдом»?",
    ["为什么在这里看书？"] = "Почему ты читаешь здесь?",
    ["为什么突然不租了？他怎么跟你说的？"] = "Почему он вдруг решил не арендовать его? Что он тебе сказал?",
    ["为什么这么便宜？"] = "Почему так дешево?",
    ["为什么？"] = "Почему?",
    ["为您打点好在廷根租房的一切事宜……我保证！"] = "Я позабочусь обо всем по аренде дома в Тингене для вас... обещаю!",
    ["之前是欧维一家住在里面，欧维夫人死在了工厂，小欧维冬天冻死了。"] = "Раньше внутри жила семья Уве; Госпожа Уве умерла на фабрике, а маленький Уве замерз зимой.",
    ["之前有个人，因为受不了自己太太打呼噜，还专门去二楼的隐蔽包厢待了一晚上，来安抚自己被折磨的神经。"] = "Раньше был парень, который терпеть не мог храпа своей жены, поэтому провел целую ночь в отдельной кабинке на втором этаже, чтобы успокоить свои измученные нервы.",
    ["乐意之至，虽然我们只是一群无家可归的孩子，但我们的能力绝不容小觑。"] = "С удовольствием. Хотя мы всего лишь группа бездомных детей, наши способности никогда не следует недооценивать.",
    ["乞丐的命不值钱，老乞丐的命更不值得救，我只有这一个心愿了……"] = "Жизнь нищего многого не стоит, а жизнь старого нищего и того меньше стоит спасать. Это мое единственное желание, которое осталось...",
    ["也就是说，你用灵视除了能直接看到一些灵体、鬼魂和怨灵，还能看到“以太体”，可以通过气场不同的状态来判断对方的健康和情绪。"] = "Другими словами, помимо возможности напрямую видеть некоторых духов, призраков и мстительных духов с помощью духовного видения, вы также можете видеть «Эфирное тело» и судить о здоровье и эмоциях другой стороны по различным состояниям ауры.",
    ["也感谢你们为廷根所做的一切，愿女神庇佑你们！"] = "Спасибо всем вам за все, что вы сделали для Тингена, да хранит вас Богиня!",
    ["也是我们认识一周年的纪念日！"] = "А еще это годовщина со дня нашего знакомства!",
    ["也许我能帮你把帽子取来？"] = "Может быть, я смогу помочь тебе принести шляпу?",
    ["也许该突击检查质检公司的账户。"] = "Возможно, нам следует провести внезапную проверку счетов компании, занимающейся проверкой качества.",
    ["也请不要告诉她我知道她在看小说的事，这是她的小秘密，我希望她自己告诉我。"] = "И еще, пожалуйста, не говорите ей, что я знаю, что она читает романы. Это ее маленький секрет, и я надеюсь, что она сама мне расскажет.",
    ["习惯了。每天扫这一段，就当活动筋骨，也能看看这条街。"] = "Я к этому привык. Подметать этот участок каждый день — это все равно, что тренировать кости, и я вижу эту улицу.",
    ["买吗？不买的话我要去问别人了。"] = "Покупаете? Если нет, я пойду спрошу других.",
    ["争论？呵呵，只是就一些研究和我的学生彼此交流罢了，谈不上争论。"] = "Аргумент? Хех, это просто обмен исследованиями с моими учениками, это не считается аргументом.",
    ["事实上，交朋友的话，街对面的画室更适合一点。"] = "На самом деле, если вы хотите завести друзей, лучше подойдет арт-студия через дорогу.",
    ["事故？"] = "Несчастный случай?",
    ["二位在做什么？"] = "Чем вы вдвоем занимаетесь?",
    ["二楼更安静，更私密。私下谈生意的、想一个人待会儿的，还有……<P_Heart>（压低声音）</>有些不方便公开聊的，都上二楼去。"] = "Второй этаж более тихий и приватный. Люди, обсуждающие дела наедине, те, кто хочет побыть какое-то время в одиночестве, и... <P_Heart>(Понижает голос)</> некоторые вещи, о которых неудобно говорить публично, все уходят на второй этаж.",
    ["二楼有什么？"] = "Что на втором этаже?",
    ["五便士也可以啊！朋友！不要走！"] = "Пять пенсов тоже хорошо! Друг! Не уходи!",
    ["五十镑！整整五十镑啊！我……我都算不过来……贝蒂，你脑子快，五十镑是多少便士？够咱这条街所有人吃多久？"] = "Пятьдесят фунтов! Полные пятьдесят фунтов! Я... я даже не могу сосчитать столько... Бетти, у тебя быстрый мозг, сколько пенсов в пятидесяти фунтах? Как долго он будет кормить всех на этой улице?",
    ["交不起就一边去吧，多的是人来争这一个名额。"] = "Если вы не можете себе этого позволить, отойдите в сторону; за это место претендует множество людей.",
    ["亨……亨特……你……你说得真……真好！"] = "Хан... Хантер... ты... ты сказал это так... так хорошо!",
    ["亨……亨特……这……这位女士……说……说得……有道理！"] = "Хун... Хантер... эта... эта леди... имеет... имеет смысл!",
    ["亨特的手指被轧断时，那声惨叫连蒸汽管道的漏气声都盖不住…… "] = "Когда палец Хантера был сломан, этот крик был громче, чем звук протекающей паровой трубы...",
    ["亲爱的，什么时候我才能有一个正式的名分？"] = "Дорогая, когда я смогу иметь официальный статус?",
    ["亲爱的，你知道吗？我最近发现了个好主意——请那些廷根大学的穷学生来做家教。"] = "Дорогая моя, ты знаешь? Недавно я придумал хорошую идею — пригласить этих бедных студентов из Тингенского университета стать репетиторами.",
    ["亲爱的，我会的。"] = "Моя дорогая, я так и сделаю.",
    ["亲爱的，这已经是我为你求来的房租减半了！"] = "Дорогая, это уже половина арендной платы, которую я для тебя просил!",
    ["人们会通过服饰去理解一个人，不同的场合、不同的身份，都有属于它的风尚语言。让我们来一场时尚品鉴吧！"] = "Люди понимают человека по его одежде; разные случаи и разные личности имеют свой собственный язык моды. Давайте устроим конкурс на оценку моды!",
    ["人们在村庄里过着安宁幸福的生活，但其实这里酝酿着一个诡异的阴谋……"] = "В деревне люди живут мирной и счастливой жизнью, но на самом деле здесь назревает странный заговор...",
    ["人啊，终归是要有一份正经工作，才能堂堂正正的吃饱饭。"] = "В конце концов, людям нужна нормальная работа, чтобы иметь возможность питаться достойно.",
    ["人生的意义就是去码头整点薯条！"] = "Смысл жизни – пойти на пристань и поесть картошки фри!",
    ["人类最珍贵的东西？难不成……"] = "Самое ценное для человечества? Может быть...",
    ["什么书都有吗？"] = "Здесь есть любые книги?",
    ["什么事？告诉你，我可不是在偷懒。"] = "В чем дело? Скажу вам, я не расслабляюсь.",
    ["什么叫“行测”？"] = "Что такое «экзамен на государственную службу»?",
    ["什么吱吱？"] = "Какие пищалки?",
    ["什么困扰？有我们的到来，这家珠宝店应该感到荣幸！"] = "Какая беда? С нашим приездом этот ювелирный магазин должен чувствовать себя польщенным!",
    ["什么太幽默了？"] = "Что слишком смешно?",
    ["什么小人？你已经够丢人了，还好有我在……不过，这酒有那么烈吗？"] = "Какие еще человечки? Ты и так опозорился, хорошо еще я рядом... Неужели эта выпивка настолько крепкая?",
    ["什么意思？"] = "Что это значит?",
    ["什么老规矩？"] = "Какие обычные правила?",
    ["什么都有，工人、工厂、工厂主、议员，在廷根市里发生的一切。"] = "Там есть все: рабочие, фабрики, фабриканты, советники — все, что происходит в Тингене.",
    ["什么都有，结婚戒指、大人物的私密照……甚至还有一张弗萨克谍报！"] = "Здесь есть все: обручальные кольца, частные фотографии важных людей... и даже кусочек шпионской информации Фьюсака!",
    ["什么都能写吗？"] = "Ты можешь написать что угодно?",
    ["什么！五张都找到了……还好我没有真的用试卷擦……"] = "Что! Все пять листов были найдены... Хорошо, что я не протерла тестовой бумагой...",
    ["什么？"] = "Что?",
    ["什么？我们之前有什么交集吗？我写过你？你要做什么？"] = "Что? Была ли у нас какая-то связь раньше? Я писал о тебе? Чем ты планируешь заняться?",
    ["什么？苏茜女士在隐身？"] = "Что? Мисс Сьюзи невидима?",
    ["什，什么？他要用那些葡萄做成酒。呃，好吧，听上去是很不错……我喜欢喝酒！"] = "Ч-что? Он собирается сделать вино из этого винограда. Э-э, ну, это звучит неплохо... Я люблю выпить!",
    ["今天天气真好，亲爱的先生/小姐，来串葡萄尝尝，这没准是金秋湖最好吃的葡萄呢！"] = "Погода сегодня такая хорошая, дорогой сэр/госпожа. Приходите попробовать гроздь винограда; возможно, это самый вкусный виноград на озере Золотой Осени!",
    ["今天我是来归还的，我们已经成功回到了自己的王国，我也想以个人的名义再次感谢帽子帮的成员们——"] = "Сегодня я пришел вернуть его. Мы успешно вернулись в свое королевство, и я также хочу еще раз поблагодарить членов Шляпной банды от себя лично…",
    ["今天早上错过了九点钟的点名……反正已经错过点名了，去和不去也没有什么区别了。"] = "Сегодня утром я пропустил девятичасовую перекличку... Впрочем, раз уж я ее пропустил, то все равно, пойду я или нет.",
    ["今天是情人的登台一周年，市长候选人要来看她的演出。"] = "Сегодня год со дня дебюта возлюбленной, и кандидат в мэры придет посмотреть на ее выступление.",
    ["今天有家人不在，没让进。"] = "Семьи сегодня не было дома, меня не впустили.",
    ["今天累得都快散架了。"] = "Я сегодня так вымотался, что просто разваливаюсь на части.",
    ["今天这首，你弹得真好。"] = "Сегодня ты сыграл эту пьесу просто замечательно.",
    ["今年的政府雇员统一考试报名开始了，你准备好了吗？"] = "Регистрация на единый экзамен для госслужащих в этом году началась, вы готовы?",
    ["今晚？我要去工作，多赚一点钱给珍妮弗。"] = "Сегодня вечером? Мне нужно работать, чтобы заработать больше денег для Дженнифер.",
    ["介意为我介绍一下帽子帮吗？"] = "Не возражаете рассказать мне о Банде в шляпах?",
    ["从1315年起，船身的装饰还添加了赞助者的名字，在冲出终点线的那一刻。我们将共享荣誉。"] = "Начиная с 1315 года на борт корабля наносится и имя спонсора. В тот миг, когда мы пересечем финишную черту, эта слава станет нашей общей.",
    ["从去年春天开始，每次夜班休息时写几句。看，这是我的笔记本。"] = "С весны прошлого года я пишу несколько строк во время перерывов в ночную смену. Смотри, это мой блокнот.",
    ["从我入学的时候就在这了，好像是某个学长的，不知道他顺利毕业没有。"] = "Она стоит здесь с самого моего поступления. Вроде принадлежала какому-то старшекурснику, уж не знаю, выпустился ли он благополучно.",
    ["从那开始，我就经常找不到工作，慢慢变成了流浪汉。"] = "С тех пор я часто не мог найти работу и постепенно стал бездомным.",
    ["他……到底怎么了？ "] = "Что... именно с ним случилось?",
    ["他也找你了？那老头，一杯劣质啤酒就想打发我。想得美！"] = "Он тебя тоже спросил? Этот старик хочет уволить меня стаканом дешевого пива. Мечтайте!",
    ["他们会老实赔偿？看看今天的新闻吧！"] = "Думаете, они честно компенсируют? Посмотрите сегодняшние новости!",
    ["他们平时不是上班就是做家务，已经很辛苦了，如果笔能替我分担作业，后天我就有空和他们一起准备聚会了。"] = "Они либо работают, либо занимаются домашними делами, и уже очень устали. Если бы ручка могла разделить бремя моей домашней работы, у меня было бы время помочь им подготовиться к послезавтрашней вечеринке.",
    ["他们懂什么？自从到艺术学派学习跳舞之后，我根本腾不出手来喝酒！"] = "Что они знают? С тех пор, как я начал учиться танцам в Школе искусств, у меня не было времени выпить!",
    ["他们看到我，说不定会爱上我的舞姿，把我从这个小镇带走，去贝克兰德做歌舞明星！"] = "Если они увидят меня, возможно, они влюбятся в мой танец и заберут меня из этого маленького городка, чтобы я стал звездой песни и танца в Баклунде!",
    ["他们简直是太划算了！而且特别认真，孩子成绩不好还会主动提出退钱。女神保佑！"] = "Их услуги обходятся так дёшево! При этом они невероятно добросовестны: если у ребёнка плохие оценки, они сами предлагают вернуть деньги. Хвала Богине!",
    ["他出了钱，买断了署名权，对外宣传是他写的，但是真正的作者却被拿走了名声。"] = "Он заплатил деньги, чтобы купить права на авторство, и продвигал его как свое собственное, но у настоящего автора была украдена репутация.",
    ["他只是看，也不找我。我猜他就是没钱，想掩饰一下自己而已。"] = "Он просто наблюдает и не приближается ко мне. Думаю, он просто сломлен и пытается это скрыть.",
    ["他叫珀恩，是鲁恩农学院的教授，半年前来做研究，现在连同资料一起消失了。"] = "Его зовут Порн, он профессор сельскохозяйственного колледжа Лоен. Он приехал проводить исследования полгода назад, а теперь исчез вместе со своими материалами.",
    ["他太难应付了。他还让我——"] = "С ним слишком сложно иметь дело. Он даже попросил меня…",
    ["他家里那么有钱，想要什么都能得到，居然也要去占卜吗？想不到他会问些啥呢……"] = "У него дома столько денег, что он может получить всё, что захочет, а он всё равно идёт гадать? Даже не представляю, о чём он будет спрашивать...",
    ["他对自己的队员们都很爱护，唯一的缺点是记忆不太好，他最常说的话是“等等，还有件事情”。"] = "Он очень любит своих товарищей по команде. Единственный его недостаток в том, что у него не очень хорошая память. Чаще всего он говорит: «Подожди, есть еще кое-что».",
    ["他应该是现在值夜者里最清楚邓恩队长以前事情的人了。"] = "Он должен быть единственным среди Ночные Ястребы, кто больше всех знает о прошлом капитана Данна.",
    ["他很少出门，更喜欢待在家里。不过他偶尔会去大地母神教会的丰收教堂做义工，也许你们能在那里偶遇。"] = "Он редко выходит на улицу и предпочитает оставаться дома. Однако время от времени он работает волонтером в Жатвенной церкви Матери-Земли, возможно, вы сможете встретить его там.",
    ["他怎么了？"] = "Что с ним случилось?",
    ["他总是执着于种出最香甜的南瓜，哈哈，不过，他的南瓜的确非常美味！"] = "Он прямо одержим идеей вырастить самую сладкую и ароматную тыкву! Ха-ха, но надо признать, тыквы у него и впрямь отменные!",
    ["他是不是和帽子帮一伙，是个小偷？"] = "Он из «Шляпной банды»? Он вор?",
    ["他是个英雄，如果你想了解他，可以去问伦纳德先生。"] = "Он был героем. Если вы хотите узнать о нем больше, вы можете спросить мистера Леонарда.",
    ["他是我的父亲……我只想再拥抱他一次，让他知道我很好，继续生活下去吧……"] = "Он мой отец... Я просто хочу обнять его ещё разок, дать знать, что со мной всё хорошо, и продолжать жить дальше...",
    ["他是费内波特来的，和鲁恩的老师理念差得很多。"] = "Он из Фейнапота, и его философия сильно отличается от философии учителей в Лоэне.",
    ["他说弗兰奇公寓，狗都不租！"] = "Он сказал: «Квартира Фрэнки», ее не снимет даже собака!",
    ["他说没厕纸了，就把全班同学的试卷抢走了！嘴里还喊着什么“只擦一下”。我叫都叫不住！"] = "Он сказал, что туалетная бумага кончилась, и выхватил контрольные у всего класса! И еще кричал что-то вроде «я только разок подтереться»! Я даже остановить его не смог!",
    ["仗是打赢了，<P_Heart>（抹了把脸）</>可惜同伴们没那么幸运。整个小队就剩我们两个，要是主教大人来早一点……"] = "Битва была выиграна, <P_Heart> (Вытирает лицо) </>, но жаль, что нашим товарищам не так повезло. Из всего отряда остались только мы двое. Если бы кардинал пришел немного раньше...",
    ["以前每年会去一两次，我记得拍卖会上有件趣事：巴顿男爵坚称某幅油画是名家真迹，花了八百镑拍下。"] = "Раньше я ходил один или два раза в год. Помню интересный случай на аукционе: барон Бартон настоял на том, что определенная картина маслом является подлинной работой известного мастера, и потратил восемьсот фунтов, чтобы выиграть торги.",
    ["以往一个重伤就会把一个家搞垮。现在靠手术，不少人都能重返岗位了。就算术后偶有感染，我们把后续的消毒和换药流程也早练得熟透了，大多都能稳住！"] = "Раньше одна серьезная травма могла разрушить семью. Сейчас, благодаря операции, многие люди могут вернуться на свои посты. Даже если случайно возникает послеоперационная инфекция, мы уже давно практикуем последующую дезинфекцию и смену повязок, и большинство из них можно стабилизировать!",
    ["仪式结束后，是否有不知名的存在向你们许下承诺？你们到底……在用什么献祭？"] = "После ритуала какое-то неизвестное существо давало вам обещание? Что именно... ты используешь в качестве жертвы?",
    ["价格……比隔壁墓地贵1金镑，女士，先别急着摇头。购买我们的墓地，还额外附赠我们公司的“灵魂安息保险”——"] = "Цена... на 1 фунт больше, чем на соседнем участке, мадам. Не спешите качать головой. Покупка нашего участка также включает в себя «Страхование покоя души» нашей компании —",
    ["价格取决于您选择的品类，先生。"] = "Цена зависит от сорта, который вы выберете, сэр.",
    ["任务开始"] = "Задание началось",
    ["任务结束"] = "Квест завершен",
    ["伊凡不让我工作时间说闲话……你别和我聊了！"] = "Иван не дает мне общаться в рабочее время... хватит со мной разговаривать!",
    ["休伯特先生平时很宝贝他的盥洗室，我们进去打扫时，也被勒令小心谨慎。"] = "Мистер Хьюберт обычно дорожит своей ванной, и когда мы идем убираться, нам также приказано быть осторожными.",
    ["伙计，把这瓶劣质啤酒当香槟喝吧，听说厂长用克扣的我们的周薪，给他心爱的夫人买了一枚华贵的发卡。"] = "Дружище, пей это пойло, как шампанское. Я слышал, что директор фабрики использовал еженедельную зарплату, которую он получал от нас, чтобы купить своей любимой жене роскошную заколку для волос.",
    ["伙计，有“吱吱”吗？"] = "Дружище, а у тебя есть какие-нибудь \"скрипы\"?",
    ["伙计，欢迎光临，看上杜比了吗？"] = "Привет, друг, добро пожаловать! Приглянулся Долби?",
    ["会花一些报名和考试费用，阁下。"] = "Это стоит некоторых регистрационных и экзаменационных сборов, милорд.",
    ["会说话的猫……你是一名真正的观众？"] = "Говорящий кот... ты настоящий Зритель?",
    ["伟大的占卜家，<P_Yellow>金秋湖</>和<P_Yellow>拉姆德古堡</>都有人在等我，但我的金钱只允许我前往一个地点赴约。"] = "Великий Провидец, люди ждут меня и в <P_Yellow>, у Озера Золотой Осени, </>, и в <P_Yellow>, Замке Ламуд, </>, но мои деньги позволяют мне пойти на встречу только в одно место.",
    ["伟大的占卜家，请问我该去哪？"] = "Великий Провидец, могу я спросить, куда мне идти?",
    ["伦纳德先生，您不是官方非凡者吗？为什么您会出现在……这种非官方非凡者的隐秘集会处？"] = "Мистер Леонард, разве вы не официальный Потусторонний? Почему ты появляешься в... таком секретном месте сбора неофициальных Потусторонних?",
    ["伸手试探，宝箱纹丝不动——它被锁住了。"] = "Когда я протягиваю руку, чтобы проверить его, сундук с сокровищами не сдвигается с места — он заперт.",
    ["似乎需要燃料启动，可以用来销毁这双舞鞋吗？"] = "Кажется, для запуска требуется топливо. Можно ли с его помощью уничтожить эти танцевальные туфли?",
    ["但、但我们只带了烟丝、报纸和南瓜馅饼，万一他们看、看不上我的东西……"] = "Но мы принесли только табак, газеты и тыквенные пироги. А что, если им не понравятся мои вещи...",
    ["但你确实是位不错的{{绅士|小姐}}，愿意成为我的第76位情人吗？"] = "Но ты действительно прекрасный {{gentleman|lady}}, согласишься ли ты стать моим 76-м любовником?",
    ["但只要有闲暇时间，或者心情不好的时候，我就会来这里坐坐。然后，我就能平静下来……"] = "Но всякий раз, когда у меня появляется свободное время или когда у меня плохое настроение, я прихожу сюда посидеть. Тогда я смогу успокоиться...",
    ["但她现在，就算在摊位上坐着的时候，也时不时盯着丈夫留给她的项链看。"] = "Но теперь, даже когда она сидит в ларьке, она все равно время от времени смотрит на ожерелье, оставленное ей мужем.",
    ["但恐怕我要让您伤心了，对于约会，我的答案是不。"] = "Боюсь, мне придется огорчить вас: на свидание я не пойду.",
    ["但您瞧，我们不需要怜悯。铁针和丝线擅长跑腿，毡毡和布布的编织技术很好，羊毛适合打听消息……样样在行。"] = "Но, видите ли, нам не нужна жалость. Железная игла и шелковая нить хороши в выполнении поручений, войлок и ткань хороши в ткачестве, шерсть хороши в сборе информации... мы хороши во всем.",
    ["但愿这次别再有坏货了，上次那批红酒全漏了，熏得我头疼了整整一周！"] = "Надеюсь, в этот раз не будет плохого груза, последняя партия красного вина вытекла, и от запаха у меня целую неделю болела голова!",
    ["但我得感谢他，否则我无法获得这份工作，家里的孩子都要饿死。"] = "Но я должен его поблагодарить, иначе я бы не получил эту работу, а дети дома умерли бы от голода.",
    ["但我明白您的意思了，如果去其中一个不会有好结果，那我就两个都去！"] = "Но я понимаю, что вы имеете в виду. Если поход в один из них не даст хорошего результата, то пойду в оба!",
    ["但我觉得应该叫“潮湿之城”或者“多雨之城”，因为这里总是下雨。"] = "Но я думаю, что его следует называть «Сырым городом» или «Дождливым городом», потому что здесь всегда идет дождь.",
    ["但我需要补习文法、法律和数学……这需要花费一笔不小的钱，还有我全部的精力。"] = "Но мне нужно пройти дополнительные занятия по грамматике, юриспруденции и математике... это стоит значительной суммы денег плюс все мои силы.",
    ["但时尚协会的大门，只对时尚的人敞开，而你……"] = "Но двери Ассоциации моды открыты лишь для тех, кто обладает вкусом, а вы...",
    ["但是我最喜欢留在村里，我会帮贝利亚学习、帮奶奶犁地。大家说，我很善良。"] = "Но больше всего мне нравится оставаться в деревне. Я помогаю Белле учиться и помогаю бабушке пахать поля. Все говорят, что я очень добрый.",
    ["但是我根本不在家啊！"] = "Но меня вообще нет дома!",
    ["但是这份悠闲是因为什么而得到变化呢？"] = "Но из-за чего нарушилось это спокойствие?",
    ["但是这里有个牌子，写着闲人勿入，违者重罚……"] = "Но здесь висит табличка: «Посторонним вход воспрещен, нарушители будут строго наказаны»…",
    ["但是，就你一个人吗？"] = "Но ты один?",
    ["但每份调查报告都写着“无法复现故障”，您不觉得这很蹊跷吗？"] = "Но в каждом отчете о расследовании говорится, что «невозможно воспроизвести неисправность». Вам не кажется это подозрительным?",
    ["但看他跳舞的认真劲，让我有点摸不准她到底是想出道，还是想出任务了。"] = "Но видя, насколько серьезно она относится к танцам, я не могу сказать, хочет ли она дебютировать или отправиться на миссию.",
    ["但这道河流可能被许多因素干扰：占卜者自身的潜意识、环境中游离的灵性、甚至其他高位存在的无意一瞥，都会让水面映出扭曲的倒影。 "] = "Но этой реке могут помешать многие факторы: собственное подсознание прорицателя, свободно плавающая духовность в окружающей среде или даже непреднамеренный взгляд других существ высокого уровня, все из которых заставят поверхность воды отражать искаженные изображения.",
    ["但这附近多是工薪阶层的普通家庭，恐怕负担不起钢琴课。"] = "Но большинство людей здесь — обычные семьи рабочего класса; Боюсь, они не могут позволить себе уроки игры на фортепиано.",
    ["低序列者有时会引发小范围的短暂异变，比如让雨滴悬浮或让风短暂转向——不过大多是无意识的行为，很难持续。"] = "Потусторонние низких Последовательностей порой вызывают кратковременные локальные аномалии — например, заставляют зависнуть капли дождя или ненадолго меняют направление ветра. Впрочем, чаще всего это происходит неосознанно и не может длиться долго.",
    ["作为从金秋湖来到霍伊大学的学生，我感到非常骄傲。"] = "Как студент, приехавший из Золотоосеннего озера в Университет Хой, я очень этим горжусь.",
    ["作为驯兽师，我不可能驯服命运这头巨兽。但是作为一个塔罗爱好者，我却能解读它。"] = "Как укротитель зверей, я не могу приручить гигантского зверя, который есть судьба. Но как энтузиаст Таро, я могу это интерпретировать.",
    ["你一个人喝酒吗？"] = "Ты пьешь один?",
    ["你一直在看那边那个喝醉的人吗？"] = "Ты всё это время смотришь на того пьяного вон там?",
    ["你不会想要坐三等座的，米娜，那种座位拥挤又肮脏。"] = "Ты бы не хотела сидеть в третьем классе, Мина. Эти места переполнены и грязны.",
    ["你不是在路边找到了一个愿意和你合租的室友吗？他人呢？"] = "Ты разве не нашёл на улице соседа, согласного снимать жильё вместе с тобой? Где же он?",
    ["你不知道那老家伙多吝啬，见我找到了工厂的工作，就每个月要求涨租金，呸！比吃了狼鱼罐头还恶心！"] = "Вы не представляете, насколько скуп этот старик. Увидев, что я нашел работу на заводе, он каждый месяц просил повышать арендную плату, ба! Хуже, чем есть консервированную волчью рыбу!",
    ["你不说我怎么给你考试范围。"] = "Если ты мне не скажешь, как я смогу дать тебе объем экзамена?",
    ["你与小狗并排坐下，它困惑地看了你一眼，礼貌地待在你身边，安静的你们与喧闹的牌桌互相对峙着。"] = "Вы садитесь рядом со щенком. Он растерянно смотрит на вас, вежливо остается рядом, и вы двое в тишине стоите напротив шумного карточного стола.",
    ["你为什么会在地下交易市场卖人偶？"] = "Почему ты продаешь куклы на Подземном рынке?",
    ["你为什么成为了流浪汉？"] = "Почему ты стал бомжом?",
    ["你为什么被关在里面？"] = "Почему тебя заперли внутри?",
    ["你也明白吧？怪人总是会有一些怪癖，比如人偶狂热爱好什么的……"] = "Вы понимаете, да? У чудаков всегда есть какие-нибудь странные причуды, например, фанатичная одержимость куклами или что-то в этом роде...",
    ["你也欠钱了？"] = "Вы тоже должны деньги?",
    ["你也知道咖啡重要？那还不赶紧还钱！如果每个人都像你这样，我的小摊子早就关门了！"] = "Вы знаете, что кофе важен? Тогда поторопитесь и верните мне деньги! Если бы все были такими, как ты, мой ларек давно бы закрылся!",
    ["你也被困在这里了……"] = "Вы тоже здесь в ловушке...",
    ["你也这么觉得对不对！我这次一定能成！她收我项链的时候眼睛都在笑呢——一定是心动了。 "] = "Вы тоже так думаете, да! На этот раз у меня обязательно получится! Ее глаза улыбались, когда она приняла мое ожерелье — она, должно быть, тронута.",
    ["你仔细挑选了一磅肉，并满怀期待地把钱塞到了狗肚子底下。"] = "Вы тщательно отбираете фунт мяса и в предвкушении засовываете деньги собаке под брюхо.",
    ["你以为每家店铺都能得到廷根时尚协会的认可吗？"] = "Как вы думаете, каждый магазин может получить одобрение Ассоциации моды Тинген?",
    ["你们……都是孤儿？"] = "Вы... все сироты?",
    ["你们在聊谁？"] = "О ком вы говорите?",
    ["你们女神信徒就是好，银饰戴着多体面。我信仰蒸汽与机械之神，祂的象征金属是青铜……总不能穿一身青铜盔甲出门吧？"] = "Вам, верующим в Богиню, повезло: серебряные украшения так приятно носить. Я верю в Бога пара и машин, Его символический металл - бронза... Я не могу выйти на улицу в полном комплекте бронзовых доспехов, не так ли?",
    ["你们好，我是热可可。"] = "Привет всем, я Hot Cocoa.",
    ["你们的房间甚至有安装煤气管道，但我没有涨房租，你们再也找不到比我更慷慨的房东了！"] = "В вашей комнате даже проведен газ, но я не поднял квартплату. Вы никогда не найдете более щедрого хозяина, чем я!",
    ["你们看！我搞到了他们三年前的航线图！据说“黄金梦想号”在某个神秘岛屿埋藏了无法估量的宝藏！"] = "Смотреть! Я получил их карту маршрутов трехлетней давности! Говорят, что «Золотая мечта» закопала на загадочном острове неисчислимые сокровища!",
    ["你们看，我定制的手包。用纯银镶嵌出繁星，这样随身带着，就像被女神祝福一样。"] = "Смотри, моя сумочка, сделанная на заказ. Для инкрустации звезд используется чистое серебро, поэтому носить его с собой — все равно, что получить благословение Богини.",
    ["你们确实令人敬佩。那么，你们的未来呢？"] = "Вы действительно достойны восхищения. Так что насчет твоего будущего?",
    ["你们要绑架谁？"] = "Кого вы планируете похитить?",
    ["你们说得太夸张了，我只是一个老乞丐呀。"] = "Вы слишком преувеличиваете. Я просто старый нищий.",
    ["你们读过上周更新的那章了吗？富豪先生在宴会上与冒险家朋友联手窃取情报的故事。"] = "Вы читали главу, обновленную на прошлой неделе? История о том, как богатый человек объединился со своим другом-искателем приключений, чтобы украсть разведданные на банкете.",
    ["你倒是直接。"] = "Вы довольно прямолинейны.",
    ["你先去忙吧，以后还有很多机会问问题。"] = "Сначала займитесь своими делами; позже будет много возможностей задать вопросы.",
    ["你再说一遍，这幅肖像收我多少钱？"] = "Скажите еще раз, сколько вы берете с меня за этот портрет?",
    ["你写了这么多夸张的报道？！"] = "Ты понаписал столько преувеличенных репортажей?!",
    ["你刚刚提到了二楼……"] = "Вы только что упомянули второй этаж...",
    ["你别误会，我可不是怕打针。"] = "Не пойми меня неправильно, я вовсе не боюсь уколов.",
    ["你前往金秋湖和拉姆德古堡的结果在我的占卜里都不算好。爱人还是要一心一意，对您和那两位姑娘都好。"] = "Результаты твоей поездки к озеру Золотой Осени и замку Ламуд не очень хороши для моих предсказаний. Любовь должна быть целеустремленной; так будет лучше для тебя и этих двух молодых леди.",
    ["你发现了吗？金秋小镇的葡萄长得飞快，简直像蒸汽机塞了涡轮一样！"] = "Вы заметили? Виноград в Городе Золотой Осени растёт быстро, почти как паровой двигатель с турбонаддувом!",
    ["你叫什么名字？"] = "Как вас зовут?",
    ["你可以慢慢来，先把眼前的学业搞定，之后再考虑找工作的事情。路都是一步一步走出来的。"] = "Вы можете не торопиться, сначала закончить учебу, а затем подумать о поиске работы. Путь проходится шаг за шагом.",
    ["你可以试试巴贝特副教授的古典音乐史。她从来不点名，只要期末参加考试就行。"] = "Вы можете попробовать «Историю классической музыки» доцента Бабетты. Она никогда не берет посещаемость, нужно просто сдать экзамен в конце семестра.",
    ["你听到什么了？我告诉你根本没有这回事！"] = "Что ты услышал? Я вам говорю, такого нет!",
    ["你听见病人的惨叫声了吗？这家诊所很不对劲。"] = "Вы слышали крик пациента? Что-то не так с этой клиникой.",
    ["你听说了吗？有人说那边的稻草人会扭来扭去，喏，就在那儿。"] = "Вы слышали? Некоторые говорят, что чучело вон там крутится-вертится, смотри, вот тут.",
    ["你和你旁边的人是双胞胎？"] = "Вы и человек рядом с вами близнецы?",
    ["你咒骂的老女人，不会是你的妻子吧？"] = "Старуха, которую вы проклинаете... уж не ваша ли это жена?",
    ["你在偷东西！！！"] = "Вы воруете!!!",
    ["你在哪里搞到的？他们的航线图怎么会落到你手上？是真的吗？"] = "Откуда ты это взял? Как их карта маршрутов могла попасть к вам в руки? Это правда?",
    ["你在学写字？"] = "Вы учитесь писать?",
    ["你在害怕吗？"] = "Вы боитесь?",
    ["你在干什么？"] = "Что ты делаешь?",
    ["你在收老鼠？收老鼠干什么？"] = "Ты собираешь крыс? Зачем?",
    ["你在构思什么？小说么？"] = "Что вы мозговой штурм? Роман?",
    ["你在煮什么？"] = "Что ты готовишь?",
    ["你在看什么？"] = "На что ты смотришь?",
    ["你在等人吗？"] = "Вы кого-то ждете?",
    ["你在这里做什么呢？"] = "Что ты здесь делаешь?",
    ["你在这里教课？"] = "Вы преподаете здесь уроки?",
    ["你在这里站着做什么呢？"] = "Зачем ты здесь стоишь?",
    ["你大醉了一场。"] = "Ты сильно напился.",
    ["你好先生，我想尝试挑战拳王阿比。"] = "Здравствуйте, сэр. Я хотел бы попробовать бросить вызов чемпиону Аби.",
    ["你好呀，这里是玛丽与天使衣帽店，不过请小心一些，不要吓跑小鸟哦。"] = "Привет! Это магазин шляп Мэри и Ангела, но, пожалуйста, будьте осторожны и не пугайте маленьких птичек.",
    ["你好啊同志"] = "Здравствуйте, товарищ.",
    ["你好，{PlayerName}，要来点什么吗？"] = "Привет, {PlayerName}, хочешь что-нибудь?",
    ["你好，{{先生|女士}}。如你所见，我正在研究关于污水治理的……神奇议案。"] = "Здравствуйте, {{господин|госпожа}}. Как видите, я изучаю... удивительный законопроект об очистке сточных вод.",
    ["你好，{{先生|女士}}，又见面了。"] = "Hello, {{gentleman|lady}}, we meet again.",
    ["你好，{{先生|女士}}，我看见你的脸上洋溢着求知的光芒！"] = "Привет, {{Mr.|Ms.}}, я вижу свет жажды знаний, сияющий на твоем лице!",
    ["你好，你是在取景吗？"] = "Здравствуйте! Вы выбираете ракурс?",
    ["你好，先生。我们在排练黑夜颂歌，准备在下次的月亮弥撒上献给女神。"] = "Здравствуйте, сэр. Мы репетируем гимн Вечной Ночи, чтобы спеть его для Богини на следующей Лунной мессе.",
    ["你好，年轻人，看到你在这里半天，想一起参加讨论吗？"] = "Здравствуйте, молодой человек. Увидев вас здесь некоторое время, не хотели бы вы присоединиться к обсуждению?",
    ["你好，我要看看。"] = "Здравствуйте, я бы хотел посмотреть.",
    ["你好，新客人，欢迎来到……哦，欢迎光临“命运”咖啡厅！"] = "Привет, новый гость, добро пожаловать в... о, добро пожаловать в кафе «Судьба»!",
    ["你好，有看到我的猫吗？我一直在找它。"] = "Привет, ты не видел моего кота? Я искал его повсюду.",
    ["你好，看上去，这位是您的客人？ "] = "Здравствуйте, похоже, этот человек ваш гость?",
    ["你好，试试珍妮特奶奶的正宗迪西馅饼吗？"] = "Здравствуйте! Не хотите попробовать настоящий десийский пирог от бабушки Джанет?",
    ["你好，迷茫的客人，想试试灵摆占卜吗？"] = "Привет, заблудший гость, не хочешь попробовать маятниковое гадание?",
    ["你将头盔放置在其中。<P_Heart>（失去道具——头盔）</>"] = "Вы кладете в него шлем. <P_Heart>(Потерян — Шлем)</>",
    ["你将玩偶放置在其中。<P_Heart>（失去道具——玩偶）</>"] = "Вы кладете куклу внутрь. <P_Heart>(Потерян предмет: Кукла)</>",
    ["你将蛤蟆放置在其中。<P_Heart>（失去道具——蛤蟆）</>"] = "Вы помещаете в него жабу. <P_Heart>(Потерянный предмет — Жаба)</>",
    ["你将象棋放置在其中。<P_Heart>（失去道具——象棋）</>"] = "Вы кладете в него шахматную фигуру. <P_Heart>(Потерянный предмет — шахматная фигура)</>",
    ["你小点声啊，这里人多，别给人听到了。"] = "Держи голос тише! Здесь слишком много людей; не позволяй никому слышать тебя.",
    ["你应该也看出来了，我能在一个横放的木桶上保持平衡。"] = "Ты, должно быть, и сам видишь: я могу удерживать равновесие на лежащей бочке.",
    ["你应该获得比她们更高级的称号，“时尚公爵”怎么样？"] = "Тебе следует получить более высокий титул, чем у них, как насчет «Герцога моды»?",
    ["你很聪明，孩子，并且你看起来干净整洁，令人感到舒适。"] = "Ты очень умная, дитя, и выглядишь чисто и опрятно, и это утешает.",
    ["你怎么了？身体不舒服吗？"] = "В чем дело? Вы плохо себя чувствуете?",
    ["你想买下这位水手吗，年轻人？"] = "Хотите купить этого матроса, молодой человек?",
    ["你想去哪里，我一定准时送达！"] = "Куда вы хотите поехать? Доставлю точно в срок!",
    ["你想去警察局喝饮料？"] = "Хочешь пойти в полицейский участок попить чаю?",
    ["你想租一层楼40个人公用一间盥洗室，三层上下铺之间连帘子都没有，空气中全是汗味和脚臭味的这个鬼地方？"] = "Ты правда хочешь снять эту дыру, где сорок человек на этаже делят одну уборную, между трехъярусными койками нет даже занавески, а воздух пропитан потом и вонью грязных ног?",
    ["你感觉你身上失去了点什么。"] = "Вы чувствуете, что что-то потеряли.",
    ["你或许看不出来，但我的腿受过严重的伤，它们每到雨天都会因为潮湿而阵痛。"] = "Вы, может, и не заметите, но мои ноги были тяжело ранены, и в каждый дождь они ноют от сырости.",
    ["你把他买走，他就有钱给我了。"] = "Если вы купите его, у него появятся деньги, чтобы отдать мне.",
    ["你把泻药放进哪颗南瓜里了？最好没人发现我们动了手脚……"] = "В какую тыкву ты положил слабительное? Будет лучше, если никто не узнает, что мы вмешались в него...",
    ["你明明演的是个真正的男子汉，却被写成了怂包，要是我被羞辱，可不会这么好说话！"] = "Ты явно играл настоящего мужчину, но тебя написали трусом. Если бы меня унижали, со мной не было бы так легко разговаривать!",
    ["你是……不，您、您是占卜家吗！"] = "Ты... нет, ты Провидец!",
    ["你是不是也收到了那封信？该死，我就该在看到那封信的时候一把火把它烧掉！"] = "Вы тоже получили это письмо? Черт возьми, я должен был сжечь его, как только увидел!",
    ["你是不是外面有其他女人了？怎么连陪我的时间都没有？"] = "У вас есть еще одна женщина снаружи? Почему у тебя даже нет времени сопровождать меня?",
    ["你是和家人走散了吗？"] = "Вы отделены от своей семьи?",
    ["你是和珍妮特奶奶一起来的吗？"] = "Ты с бабушкой Джанет?",
    ["你是在回答我的问题吗？好聪明呀！"] = "Вы отвечаете на мой вопрос? Какой умный!",
    ["你是大学生？"] = "Вы студент университета?",
    ["你是来问我关于马桶的事吧？"] = "Ты здесь, чтобы спросить меня о туалете, да?",
    ["你是说《大冒险家》？"] = "Вы имеете в виду «Великого авантюриста»?",
    ["你是说莱茵？她真的是一个很内向的女孩，你去找她说说话就会明白了，哈哈哈。"] = "Вы имеете в виду Рейн? Она действительно очень замкнутая девушка. Ты поймешь, когда поговоришь с ней, ха-ха-ха.",
    ["你是说那个闹鬼的房子吗？窗户还是我帮忙钉上的。"] = "Вы имеете в виду дом с привидениями? Я помогал забивать окна.",
    ["你是食堂的厨师吧？遇上什么难事了？ "] = "Ты повар в столовой, да? У вас возникли какие-то проблемы?",
    ["你有些不忍，终于还是走过去，站在了他的身后。"] = "Вам стало не по себе, и вы все же подошли и встали позади него.",
    ["你有没有见过……"] = "Вы когда-нибудь видели...",
    ["你来了…… 你终于来了…… 门在天上…… 别回头…… 你是逃脱不了的！！！！！"] = "Ты здесь... Ты наконец здесь... Дверь в небе... Не оглядывайся... Тебе не сбежать!!!!!",
    ["你来了。知识皇冠已经感知到了你——在无数平行世界的沙盘之上，祂在等待新的征服者。"] = "You have arrived. The Crown of Knowledge has sensed you—upon the sandbox of countless parallel worlds, It awaits a new Conqueror.",
    ["你来了，想必你已经见过那些奇异的漂浮物了，教会称它们为“异象之物”。\n如果你收集到了一些，可以交付给我。"] = "Вот и ты. Должно быть, ты уже видел те странные парящие предметы: Церковь называет их «объектами аномалии».\nЕсли тебе удалось собрать хоть немного, можешь передать их мне.",
    ["你来得晚，那是几年前的事情了。"] = "Ты опоздал; это произошло несколько лет назад.",
    ["你来看我演出不会被拍到吧，最近可是你的竞选关键期。"] = "Если ты придешь посмотреть мое выступление, тебя не сфотографируют, верно? Это критический период вашей кампании.",
    ["你每天早上一杯咖啡，雷打不动，怎么不说手头紧？没有咖啡，你连机器都开不动，别以为我不知道！"] = "Вы обязательно выпиваете чашку кофе каждое утро, как вы можете говорить, что у вас мало денег? Без кофе даже машины не заведешь, не думайте, что я не знаю!",
    ["你父亲生前可是条硬汉，向他学着点！"] = "Твой отец при жизни был крутым человеком, учись у него!",
    ["你现在已经是非凡者了，但如何真正掌握魔药的力量，还需要你自己去挖掘它的象征意义。在这个过程中，你要小心规避失控的风险。"] = "Теперь вы уже Потусторонний, но для того, чтобы по-настоящему овладеть силой зелья, вам все равно придется самостоятельно разобраться в его символическом значении. В этом процессе необходимо быть осторожным, чтобы избежать риска потери контроля.",
    ["你的喜好还挺特别……到底是什么宠物？"] = "Ваши предпочтения весьма уникальны... что это за питомец?",
    ["你的妈妈一定很爱你。"] = "Твоя мать, должно быть, очень тебя любила.",
    ["你的搭配，比这片终年不化的白雪更令人印象深刻。来吧，让我看看，你会如何诠释属于雪境的品鉴方式。"] = "Твой наряд впечатляет больше, чем этот вечный белый снег. Давай, позволь мне посмотреть, как ты интерпретируешь способ признания принадлежности к снежному царству.",
    ["你的灵性真敏锐，竟然能找出藏着的我。\n不如来玩一场捉迷藏吧，把附近的宝箱都找出来，就能开启我的宝藏。"] = "Какая острая у тебя духовность — надо же, сумел отыскать моё убежище!\nА давай сыграем в прятки? Отыщи все сундуки поблизости, и тогда сможешь открыть мою сокровищницу.",
    ["你的舞步，有什么特别的？"] = "Что такого особенного в твоих танцевальных движениях?",
    ["你的诗，不该只待在这种地方。 "] = "Ваша поэзия не должна просто оставаться в таком месте.",
    ["你看上去很兴奋啊。"] = "Ты выглядишь очень взволнованным.",
    ["你看起来不像这附近的教师。"] = "Ты не похож на местного учителя.",
    ["你看起来好惬意啊。没有课吗？"] = "Ты выглядишь так комфортно. Нет класса?",
    ["你看起来心情不好，遇到什么事了吗？"] = "Кажется, у тебя плохое настроение. С тобой что-то случилось?",
    ["你看起来遇到了麻烦。"] = "Похоже, ты попал в беду.",
    ["你看，在这里，连摊主都不必时刻盯着摊位，这在之前是不可想象的。"] = "Посмотрите, здесь даже владельцам ларьков не приходится все время пялиться на свои ларьки, что раньше было невообразимо.",
    ["你看，我面前这些卷心菜，看似朴素，却藏着你未曾知晓的非凡力量。我就是吃了它，才获得了平衡之力！"] = "Посмотрите, эта капуста передо мной, хотя и кажется простой, скрывает в себе силы Потустороннего, о которых вы никогда не знали. И только после того, как я их съел, я обрел силу равновесия!",
    ["你瞅瞅，这码头上的猫，全给我招来了，赶都赶不走！ "] = "Посмотрите, всех кошек на пристани я сюда заманил, я не могу их прогнать!",
    ["你知道我在说什么，{{先生|女士}}。用用你们的气象仪或者别的，让我们船长知道今天不应该出发！"] = "Ты знаешь, о чем я говорю, {{ Mr.| Ms.}}. Используйте свою астролябию или что-нибудь еще, чтобы сообщить нашему капитану, что нам сегодня не следует отправляться в плавание!",
    ["你知道我这辈子在哪里见到的穷人最多吗？"] = "Знаешь, где я видел самых бедных людей в своей жизни?",
    ["你知道的，我不能独自留在这里。"] = "Знаешь, я не могу оставаться здесь один.",
    ["你租这个房子花了和邻居一样的钱，你们是一样的，不需要因为别人的不礼貌而内疚。"] = "Вы заплатили за этот дом ту же арендную плату, что и ваши соседи. Вы тот же самый; не нужно чувствовать себя виноватым из-за чужой грубости.",
    ["你聊历史，她能接住；聊政治，她能接住；聊生意、聊艺术、聊哪家剧院新上演的戏……她都能接住。而且接得漂亮。"] = "Вы говорите об истории, она может не отставать; говорить о политике, она может не отставать; поговорить о бизнесе, об искусстве, о том, в каком театре новая пьеса... она все успевает. И делает она это элегантно.",
    ["你肯定不知道，现在风靡鲁恩的投球运动，一开始来自金秋湖的一场儿童游戏。"] = "Вы, вероятно, не знаете, что питчерский вид спорта, который в настоящее время охватывает Лоэн, зародился из детской игры на озере Золотая Осень.",
    ["你能感受到吗？我总觉得……他，我的孩子就在这里。"] = "Ты чувствуешь это? Я всегда чувствую, что... он, мой ребенок, здесь.",
    ["你要是没有活老鼠，就赶紧走，别惹麻烦！"] = "Если у вас нет живых крыс, уходите быстро и не создавайте проблем!",
    ["你要是碰巧在大学那边看见他，一定替我带声好。我灰头土脸，就不去那边给他丢人啦。"] = "Если случайно встретишь его возле университета, обязательно передай привет. Я весь в пыли и грязи, так что сам туда не пойду, чтобы его не позорить.",
    ["你觉得新警车怎么样？"] = "Что вы думаете о новой полицейской машине?",
    ["你记得我上次穿什么？"] = "Помнишь, что я носил в прошлый раз?",
    ["你说什么？我刚刚没听清。"] = "Что вы сказали? Я сейчас не расслышал тебя ясно.",
    ["你说奎迪？是我的哥哥哦，只有对着布料才能正常说话的哥哥。"] = "Ты имеешь в виду Крида? Он мой старший брат, из тех, кто может нормально говорить только тогда, когда разговаривает с тканью.",
    ["你说得对，或许……我想我应该再多等等。"] = "Возможно, ты прав... Я думаю, мне стоит подождать еще немного.",
    ["你说我家老头子啊，他是外出问诊了吧。放心，我大儿子在坐班，交给他你可以放心。"] = "Ты спрашиваешь о моем старике? Он вышел на дом. Не волнуйтесь, мой старший сын на дежурстве, ему можно доверять.",
    ["你说的珍是谁？"] = "Кто эта Джейн, о которой ты говоришь?",
    ["你说，弗兰奇先生会允许我养宠物吗？"] = "Скажите, разрешит ли мне мистер Фрэнк держать домашнее животное?",
    ["你说，我今天运气怎么样？"] = "Скажи мне, как мне сегодня повезло?",
    ["你说，等我们长大了，是不是也能像那些大人一样，每天穿着体面的衣服，口袋里装着叮当响的硬币？"] = "Скажи мне, когда мы вырастем, сможем ли мы быть такими же взрослыми, носить каждый день приличную одежду и звенеть монетами в карманах?",
    ["你走吧！我的生意都要被你挡完了。"] = "Уходите! Ты блокируешь все мои дела.",
    ["你还在磨蹭什么？那个蠢货的怀表都快晃到我脸上了！你到底干不干？"] = "Чего ты тянешь? Этот остолоп своими карманными часами мне чуть ли не в нос тычет! Ты берешься за дело или нет?",
    ["你还好吗，怎么一个人在这里喝闷酒？"] = "Ты в порядке? Почему ты здесь пьешь один?",
    ["你还是这么会说情话，萨里斯先生。"] = "Вы всё так же щедры на нежные слова, мистер Сарис.",
    ["你这是在干什么？"] = "Что это ты делаешь?",
    ["你这是怎么了？"] = "Что с тобой не так?",
    ["你这身衣服……"] = "Эта твоя одежда...",
    ["你连原著都读过？那书可不好找。"] = "Вы хоть оригинал читали? Эту книгу нелегко найти.",
    ["你那点头疼算什么，瞧瞧这个——我上次被那车从西维拉斯郡运过来的矿石砸到脚，到现在还肿着呢。"] = "Эта головная боль у тебя пустяковая, посмотри на это: в прошлый раз меня сбил по ноге грузовик с рудой, привезенный из округа Вест-Верас, и она до сих пор опухла.",
    ["你镜头中的主角是？"] = "Кто главный герой в твоём объективе?",
    ["你难道不知道现在的咖啡豆有多么昂贵吗？如果你再不还钱，我得去找你的经理谈谈了！"] = "Разве вы не знаете, насколько дороги сейчас кофейные зерна? Если вы не вернете мне деньги, мне придется поговорить с вашим менеджером!",
    ["你，你好……"] = "Х-привет...",
    ["信仰之跃，那是雄鹰翱翔般，真正自由的感觉！"] = "Прыжок веры, это словно парящий орел, ощущение настоящей свободы!",
    ["修阳台材料费至少2苏勒，人工另算。"] = "Материалы для ремонта балкона стоят минимум 2 суле, работа оплачивается дополнительно.",
    ["借我五十，不，五金镑，我会给你百分之百的利润报酬！"] = "Одолжите мне пятьдесят, нет, пять фунтов, и я дам вам стопроцентную прибыль!",
    ["值！怎么不值？她看我那一眼，比我家那位看我一年都热乎。"] = "Стоило того! Как это могло быть не так? Тот единственный взгляд, который она бросила на меня, теплее, чем тот, который моя жена смотрела на меня за год.",
    ["健壮的猪，沉稳的牛，听话的狗，灵巧的兔！只有您想不到的，没有我们没有的！来，选一位吧！"] = "Сильные свиньи, выносливые коровы, послушные собаки, ловкие кролики! Нет ничего такого, чего бы вы не могли придумать, чего бы у нас не было! Давай, выбери один!",
    ["偶尔也会有得不到答案的情况，这种时候，也许是命运在向你说“这个不能问”吧。"] = "Иногда возникают ситуации, когда вы не можете получить ответ. В такие моменты, возможно, судьба говорит вам: «Ты не можешь спрашивать об этом».",
    ["像参加永远无法通关的礼仪考试。上周我在三场茶会重复了七遍“您今天的帽子真别致”。"] = "Это как сдать экзамен по этикету, который ты никогда не сможешь сдать. На прошлой неделе я семь раз повторил: «Твоя шляпа сегодня действительно шикарна» на трех чаепитиях.",
    ["像房屋租赁合同这种，六便士一份；遗嘱和诉状，至少一苏勒，你得告诉我你的情况，才能判断。"] = "Что-то вроде договора аренды жилья стоит шесть пенсов; завещания и прошения составляют не менее одного сол. Вам придется рассказать мне о своей ситуации, прежде чем я смогу судить.",
    ["兄……兄弟！我、我问个路……"] = "Брат... брат! Я, позвольте мне спросить дорогу...",
    ["兄弟们，厂里欠了我们一个月薪水了，我和利奥、桑托商量了一下，今天不给出说法就不开工！"] = "Братцы, завод нам задолжал зарплату за месяц, я обсудил это с Лео и Санто, мы сегодня не начнем работу, пока они нам не объяснят!",
    ["先去那几个熟人家门口晃，呵呵，尽可能让他们眼红。"] = "Для начала пойди потусуйся у дверей этих знакомых, хе-хе, заставь их как можно больше завидовать.",
    ["先将我在船舶公司的股份，短期质押给银行，拿到贷款后买入脚踏车股票，之后再把脚踏车股票质押给银行，用贷款归还前面的贷款。"] = "Сначала заложите мои акции судоходной компании банку на короткий срок, получите кредит на покупку запасов велосипедов, затем заложите запасы велосипедов банку и используйте кредит для погашения предыдущего кредита.",
    ["先生，不好意思，这是一次意外。"] = "Сэр, извините, это был несчастный случай.",
    ["先生，也许小昂格只是想交个新朋友。"] = "Сэр, возможно, маленький Унгер просто хочет завести нового друга.",
    ["先生，您为何一直在看报纸？"] = "Сэр, почему вы все время смотрели в газету?",
    ["先生，您是南大陆人？"] = "Сэр, вы с Южного континента?",
    ["先生，我们当然不是……那个印子确实比较深，修补需要材料和时间……"] = "Сэр, конечно нет... Эта отметина действительно очень глубокая, а ремонт требует материалов и времени...",
    ["先生，我刚才听您说，有一个叫弗兰奇公寓的地方需要租客，对吗？"] = "Сэр, я только что услышал, как вы сказали, что есть место под названием «Квартира Фрэнки», которому нужны арендаторы, верно?",
    ["先生，我的头好痛，眼睛也睁不开……"] = "Сэр, у меня так сильно болит голова, и глаза никак не открыть...",
    ["先生，我这里有一份草药配方很适合您啊，请务必收下。"] = "Сэр, у меня есть травяной препарат, который вам очень подходит, пожалуйста, обязательно примите его.",
    ["先生，是你在叫我？"] = "Сэр, вы мне звоните?",
    ["先生，是否有人往马桶里扔过垃圾？"] = "Сэр, кто-нибудь когда-нибудь выбрасывал мусор в унитаз?",
    ["先生，最近有民众投诉“塔索克河污水治理”不达标。"] = "Сэр, недавно появились жалобы общественности на то, что «очистка сточных вод реки Тасок» не соответствует стандартам.",
    ["先生，现在很晚了，你应该回家休息。"] = "Сэр, уже очень поздно, вам следует пойти домой и отдохнуть.",
    ["先生，要去哪里？"] = "Сэр, куда?",
    ["先生，请问您需要什么启示？"] = "Сэр, какое откровение вам нужно?",
    ["光是想想，就知道有多帅了！"] = "Да от одной мысли дух захватывает, как это круто!",
    ["克莱恩先生教会了我许多特色菜的做法，让挑剔的男爵都赞不绝口；班森先生作为政府雇员为我出具了推荐信；梅丽莎小姐更是一直与我通信，鼓励我追求事业。"] = "Мистер Клейн научил меня готовить множество фирменных блюд, которые заставляли даже привередливого барона бесконечно их хвалить; Г-н Бенсон предоставил мне рекомендательное письмо как государственного служащего; и мисс Мелисса писала мне, поощряя меня продолжить карьеру.",
    ["八、八万？嗯……还是有点太贵了。"] = "Э-восемьдесят тысяч? Хм... это всё равно слишком дорого.",
    ["八万金镑，尊贵的小姐。"] = "Восемьдесят тысяч фунтов, благородная леди.",
    ["六便士？昨天可是八便士。偷懒了？"] = "Шесть пенсов? Вчера это было восемь пенсов. Расслабиться?",
    ["六点？我从未在六点走出过工厂的大门！"] = "Шесть часов? Я никогда не выходил из заводских ворот в шесть часов!",
    ["兰格其实很欣赏你的，我是说我们国王，他也觉得你是个好首领。我们两个孤儿组织也没必要那么敌对，你说是吧？"] = "Ланге на самом деле тобой очень восхищается. Я имею в виду нашего короля, он тоже считает тебя хорошим лидером. Незачем нашим двум сиротским организациям быть такими враждебными, верно?",
    ["关于什么内容的？"] = "О чем идет речь?",
    ["关于爱情，{{先生|女士}}，爱情是诗歌永恒的主题之一！"] = "О любви, {{Mr.|Ms.}}, любовь – одна из вечных тем поэзии!",
    ["兴许是退伍军人，或者警察吧，我也看到过。不过，好像也有不少年轻人。说不准啊……"] = "Может, ветераны, а может, полицейские — я их тоже видел. Впрочем, среди них вроде бы и молодёжи немало. Трудно сказать наверняка...",
    ["其实像这样的布料还能卖给码头帮人修船帆的人，但您手上这一片是白色的，收集一批卖给造纸厂价格会更好。"] = "На самом деле такую ​​ткань можно продать людям в доках, которые ремонтируют паруса, но кусок в ваших руках белый, поэтому сбор партии для продажи на бумажной фабрике принесет более выгодную цену.",
    ["其实常见的款式妈妈都会做，大概说一下你想要的样子，妈妈都能做出来，只收布料钱和一些手工费！"] = "На самом деле мама может создавать самые распространенные стили. Просто опишите, что вы хотите, и мама сможет это сделать. Она берет плату только за ткань и немного работы!",
    ["其实我们还有另外的招牌，鲁恩王国阿霍瓦郡警察厅特殊行动部第七小组。"] = "На самом деле у нас есть и другая вывеска: Полицейское управление графства Ахор королевства Лоэн, отдел специальных операций, Седьмая группа.",
    ["其实这也是“愚者”先生的启示，他总是考虑得如此周到。可能……因为我没有缺过钱，所以总是忘记钱对于一个新生非凡者有多么重要。"] = "Собственно, это тоже откровение господина Шута; Он всегда такой задумчивый. Возможно... потому что у меня никогда не было недостатка в деньгах, я всегда забываю, насколько важны деньги для нового Потустороннего.",
    ["其实这是旧时代淑女们在社交场合不便直言时，发展出的一套视觉暗语。比如将扇子缓缓划过脸颊，通常表示“我很无聊”。"] = "На самом деле это набор визуальных тайных кодов, разработанных дамами старой эпохи, когда в социальных ситуациях было неудобно говорить напрямую. Например, медленное проведение веера по щеке обычно означает: «Мне очень скучно».",
    ["其实，见到他我就会抑制不住去拥抱他。"] = "На самом деле, стоит мне увидеть его, как я не могу удержаться от желания обнять его.",
    ["其次，注意那些永远不碰特定食物的人。比如坚决不碰带血牛排的，可能是“吸血鬼”……抱歉，是血族。"] = "Во-вторых, обратите внимание на тех, кто никогда не прикасается к определенным продуктам. Например, те, кто категорически отказывается прикасаться к редкому стейку, могут оказаться «вампирами»… извините, я имею в виду сангвиников.",
    ["再往外是“心智体”，从这里开始与肉体有了结合。它涉及头脑、属于推理、思考、洞察和认识事物能力的综合呈现。"] = "Далее находится «Ментальное тело», которое отсюда начинает объединяться с физическим телом. Он задействует разум и представляет собой комплексное представление рассуждений, мышления, проницательности и способности понимать вещи.",
    ["再来一把？还是回去带孩子？"] = "Сыграем еще партию? Или пойдешь нянчиться с детьми?",
    ["再来一轮？这次我一定压住准心。"] = "Еще один раунд? На этот раз я определенно сконцентрируюсь.",
    ["再次向您表达我的感谢！"] = "Выражаю Вам еще раз свою благодарность!",
    ["再等等，再等等……"] = "Еще немного, подожди еще немного...",
    ["写一份多少钱？"] = "Сколько за штуку?",
    ["冰冷的焚烧炉，静静地在车间正中央。"] = "Холодный мусоросжигательный завод, тихо стоящий в центре мастерской.",
    ["冰山中将的船？我听过一些传闻。"] = "Корабль Айсберг-Адмирала? Я слышал некоторые слухи.",
    ["冲激——！"] = "Удар—!",
    ["冷静，大家都冷静一下。我知道这件事情很突然，但我们必须想好对策。"] = "Успокойся, все успокойся. Я знаю, что это очень неожиданно, но мы должны подумать о контрмере.",
    ["净化污染"] = "Очистка",
    ["准备好了吗？世界的沙盘已经为你打开。入局吧！"] = "Are you ready? The sandbox of the world has already opened for you. Enter the game!",
    ["准备好当下一个勇士了吗？"] = "Готовы ли вы стать следующим воином?",
    ["准备开启仪式"] = "Приготовьтесь начать ритуал.",
    ["凑近点……"] = "Подойди ближе...",
    ["几年前，这些紫藤花开得还没这般茂密，太阳就是最好的煤油灯，我在这里读完了很多很多本书。"] = "Несколько лет назад эти цветы глицинии не были такими пышными, как сейчас. Солнце было лучшей керосиновой лампой, и я закончил здесь много-много книг.",
    ["凯洛斯正在夺回自己的领地。"] = "Кайрос возвращает свою территорию.",
    ["出去打听打听吧，这里是地下市场！不是宝宝集市！"] = "Сходите поспрашивайте, это подземный рынок! Не детский базар!",
    ["出门在外身份都是自己给的，我要穿的像乞丐，谁会买我的东西？"] = "Когда вы в пути, ваша личность — это то, что вы из нее представляете. Если я оденусь как нищий, кто будет покупать мои товары?",
    ["切，你那算什么。上周她跳舞时朝我眨了下眼，我老婆问我“你傻笑什么”，我说“想到涨工资了”。"] = "Пфф, это ничего. На прошлой неделе она подмигнула мне во время танца, и моя жена спросила: «Почему ты ухмыляешься, как идиот?» Я сказал: «Я думал о повышении».",
    ["刚刚来的小姐还没有自我介绍呢，快让我们认识一下。"] = "Только что пришедшая дама еще не представилась. Давайте познакомимся с ней.",
    ["刚才那组，第三发你还是太急。呼吸，科尔，要像吻姑娘前那样，先沉住气。"] = "В последнем сете твой третий бросок все еще был слишком поспешным. Дыши, Коул, ты должен сохранять спокойствие, как перед тем, как поцеловать девушку.",
    ["别为难孩子了，这事我来处理。"] = "Не дави на ребенка, я сам с этим разберусь.",
    ["别吵，我在思考。"] = "Не шуми, я думаю.",
    ["别小看孤儿们收集情报的能力，您有什么事吗？"] = "Не стоит недооценивать способность сирот собирать информацию. Есть ли что-то, что вам нужно?",
    ["别急，我听说六点以后叠加的“女神之惠”折扣才会生效，日用品还能再打九折！"] = "Не волнуйтесь, я слышал, что наложенная скидка «Благосклонность богини» вступит в силу только после шести часов, а на предметы первой необходимости можно будет получить скидку еще на 10%!",
    ["别担心，小姐。也许……猫也有些必须要去做的事。"] = "Не волнуйтесь, мисс. Возможно... у кошек тоже есть дела, которые они должны делать.",
    ["别提了，一想到明天要跟经理核对那该死的季度账目，我这手指头就想扣扳机。今天还没打够，我这老腰就告假了。"] = "Не упоминай об этом. Одна мысль о том, чтобы завтра проверить эти чертовы квартальные отчеты с менеджером, вызывает у меня желание нажать на курок. Я сегодня недостаточно настрелял, а моя старая спина уже заболевает.",
    ["别提带孩子——快快快，还有五分钟我就要回家了，在那之前还来得及再来一把！"] = "Не говоря уже о том, чтобы взять с собой детей — торопитесь, торопитесь, торопитесь, мне нужно идти домой через пять минут, до этого еще есть время еще на один раунд!",
    ["别犹豫了，这个名额是我挤破脑袋才争取到的。不信你去工厂大门，看看多少人在排着长队应聘。"] = "Не сомневайтесь, я боролся изо всех сил, чтобы получить это место. Если вы мне не верите, подойдите к воротам фабрики и посмотрите, сколько людей выстраивается в очередь, чтобы подать заявку.",
    ["别狡辩了，向亚特先生传个话，今年我会种出最大最甜的南瓜，比他的葡萄还要甜呢！"] = "Перестаньте оправдываться. Передайте господину Арте сообщение: в этом году я вырасту самые большие и сладкие тыквы, даже слаще его винограда!",
    ["别看了，还有两车的海报要贴！"] = "Хватит глазеть, нам ещё две тележки плакатов расклеить надо!",
    ["别着急，怎么了？"] = "Не волнуйся, что случилось?",
    ["别瞎说，我只爱你一个。"] = "Не говори глупостей, я люблю только тебя.",
    ["别紧张，亲爱的孩子，我只是好奇你在写什么。"] = "Не нервничай, дорогой ребенок, мне просто интересно, что ты пишешь.",
    ["到时候就让格尔曼从那边入场，然后直接……"] = "Когда придет время, пусть Герман войдет оттуда, а потом прямо...",
    ["前两周，我给新的话剧投稿了主题曲，但是他们最后选了一个和剧目完全不搭调的，那个作曲者也不知道从哪里冒出来的。"] = "Две недели назад я представил музыкальную тему для новой пьесы, но в итоге выбрали ту, которая совершенно не соответствовала пьесе. Я даже не знаю, откуда взялся этот композитор.",
    ["前几天有个穿得很华丽的管家来带走了，可能被有钱人收藏了吧。"] = "Несколько дней назад приходил пышно одетый дворецкий и забрал ее. Наверное, какой-то богач купил в свою коллекцию.",
    ["前辈评价说我的肢体还不够协调。"] = "Старший заметил, что моей координации тела недостаточно.",
    ["剧本单薄得像酒杯里的冰块——化了，就什么都没了。"] = "Сценарий был тонким, как лед в бокале: как только он растает, ничего не останется.",
    ["加上要到交稿的时候了，我看着他才比较稳妥。"] = "К тому же, уже почти пора отправлять рукопись, так что мне будет безопаснее присматривать за ним.",
    ["努力过上有周末的人生？噢，女神。你或许应该问问，廷根有多少人渴望成为你这样的贵族小姐？"] = "Стремитесь прожить жизнь без выходных? О, Богиня. Возможно, вам следует спросить, сколько людей в Тингене мечтают стать такой благородной дамой, как вы?",
    ["劳工手册有提过，工厂会赔偿工伤的。"] = "В трудовой книжке указано, что завод будет компенсировать производственные травмы.",
    ["勋爵愣了三秒，然后说：“看来这杯茶比我先一步想拥有您。”现在他们订婚了。 "] = "Господь замер на три секунды, а затем сказал: «Кажется, эта чашка чая хотела заполучить тебя раньше меня». Теперь они помолвлены.",
    ["医生，你这是怎么了，需不需要看看医生？"] = "Доктор, что с вами? Вам нужно обратиться к врачу?",
    ["午安，汤姆森先生。关于扣款明细，清单上每一项都有您入住时签字确认的现状记录作为对照。我们可以再一起核对一遍。"] = "Добрый день, мистер Томсон. Что касается деталей вычета, каждый элемент в списке имеет запись о состоянии, которую вы подписали и подтвердили при регистрации в качестве ссылки. Мы можем проверить это вместе еще раз.",
    ["卓绝的眼光！这是本店最畅销的武器之一，连贵族们都为它的威力与外表折服。"] = "Исключительный глаз! Это одно из наших самых продаваемых видов оружия; даже знать очарована его мощью и внешним видом.",
    ["单纯地想要认识一下。"] = "Я просто хотел с тобой познакомиться.",
    ["南部真是发财的好地方。"] = "The South is truly a great place to make a fortune.",
    ["占位"] = "Инфо",
    ["占卜家永远无法占卜自己的命运……"] = "A Seer can never divine their own fate...",
    ["占卜真的能预言未来吗？"] = "Действительно ли гадание может предсказать будущее?",
    ["占坑"] = "Инфо",
    ["卡萝女士是上上任的值夜者队长，邓恩队长和戴莉女士和她非常熟悉。"] = "Мисс Кэрол была капитаном до последнего. Капитан Данн и мисс Дейли были с ней очень хорошо знакомы.",
    ["危机解除！感谢您！您真是个通情达理的大人！"] = "Кризис предотвращен! Спасибо! Вы действительно разумный взрослый человек!",
    ["即使身为政府官员，也会有深入坊间的时候，偶遇我不奇怪。"] = "Даже будучи государственным чиновником, будут времена, когда я буду углубляться в общественную жизнь. Я не удивлён, что встретил его случайно.",
    ["即便是搬到了更富有的北区别墅，夫人还是会经常回来。"] = "Даже переехав в особняк в более богатом Северном районе, госпожа все равно часто сюда возвращается.",
    ["厂区的活不敢接——那地方，干久了肺里全是棉絮。"] = "За работу в фабричном районе браться не рискую — если батрачить там слишком долго, все лёгкие забьются хлопком.",
    ["历史因为人们的视角不同，呈现出不一样的真相。我可以先跟你讲讲鲁恩的地理和气候。"] = "История представляет разные истины из-за разных точек зрения людей. Сначала я могу рассказать вам о географии и климате Лоена.",
    ["厉害，你现在也要表演这个节目吗？"] = "Впечатляющий. Собираетесь ли вы совершить это действие сейчас?",
    ["原来你知道她在做什么。"] = "Так ты знаешь, чем она занимается.",
    ["原来是在卖画……不用了谢谢。"] = "Так вы продаёте картины... Нет, спасибо.",
    ["原来是这样……你也有自己的苦衷。请放心吧。"] = "Так вот так... у тебя тоже есть свои трудности. Пожалуйста, будьте уверены.",
    ["原来是追稿的。"] = "А, так вы пришли выбивать рукопись.",
    ["原来神明除了宠爱的植物，连金属都有所偏爱……"] = "Так что, помимо растений, которые они предпочитают, боги отдают предпочтение даже металлам...",
    ["原来顾客是用来帮你消耗啤酒份额的啊！"] = "Таким образом, клиенты здесь только для того, чтобы помочь вам потреблять вашу норму пива!",
    ["原著里那位夫人最后跳了河，剧本改成大团圆，还把三段铺垫全删了。没了那三段，前面所有的挣扎都站不住脚。"] = "В оригинальном произведении эта дама в конце прыгнула в реку, но сценарий был изменен на счастливый конец, а все три сегмента предзнаменования были удалены. Без этих трех сегментов вся предыдущая борьба не выдерживает критики.",
    ["原谅我急于动身，无法陪同您前往。所幸还有一位管家偶尔打理，只要把契约书给他，自然能证明您的所有者身份。"] = "Простите, что спешу уйти и не могу вас сопровождать. К счастью, есть дворецкий, который время от времени обо всем позаботится. Если вы отдадите ему контракт, это, естественно, подтвердит вашу личность как владельца.",
    ["去“狂野之心”喝一杯怎么样？今天我差点滑进钢炉里，再不放松一下，我都要疯了！"] = "Как насчет выпить в «Диком сердце»? Я сегодня чуть не поскользнулся в сталеплавильной печи, если не расслаблюсь, то сойду с ума!",
    ["去年我在那里度假时，每天醒来窗外都是不同的海岛。<P_Heart>（微笑）</>唯一的麻烦是——有次巨龟和它的女朋友私奔了，我们漂流了三天。"] = "Когда я отдыхал там в прошлом году, каждое утро за окном был новый остров. <P_Heart>（Улыбается）</>Единственной проблемой было то, что однажды гигантская черепаха сбежала со своей подружкой, и мы дрейфовали три дня.",
    ["去年我给发烧患者配好的药剂里，被药剂科主任往里掺水——就为省下钱给他情妇买貂皮大衣。"] = "В прошлом году заведующий аптекой разбавил лекарство, которое я приготовил для больных лихорадкой, просто чтобы сэкономить на покупке своей хозяйке норковой шубы.",
    ["去年有人用金色火漆寄催债信，收信人以为发现了古代宝藏地图，带着挖掘工具去了约定地点。 "] = "В прошлом году кто-то прислал письмо о взыскании долга с золотой сургучной печатью. Получатель подумал, что нашел древнюю карту сокровищ, и отправился в оговоренное место с инструментами для раскопок.",
    ["去香槟街。"] = "Идите на улицу Шампани.",
    ["又见面了朋友，这里的曲子同样蕴藏着往日回响。"] = "Мы снова встретились, друг. Музыка здесь также содержит отголоски прошлого.",
    ["友善？他们还不是只看重抵押物，您看，我这不需要抵押就能给您贷出钱来。"] = "Дружелюбно? Их волнует только залог. Слушай, я могу одолжить тебе деньги здесь без какого-либо залога.",
    ["反正啊，等我有了钱，一定要离开铁十字街，去个更好的地方……到时候，你也一起来！"] = "В любом случае, когда у меня будут деньги, я должен покинуть Айрон-Кросс-стрит и отправиться в лучшее место... Когда это время придет, ты пойдешь со мной!",
    ["变化藏在细节里。七十年前我们改用滑动座板，1313年定制了第一艘白蜡木木艇……"] = "Изменения скрыты в деталях. Семьдесят лет назад мы перешли на раздвижные сиденья, а в 1313 году спустили в эксплуатацию первую лодку из белого ясеня...",
    ["口袋里还有点面包碎屑。吃吧，小家伙。"] = "В моем кармане еще остались хлебные крошки. Ешь, малыш.",
    ["古老的村庄中，沉睡着庞大的宝藏……"] = "В древней деревне сокрыты несметные сокровища...",
    ["另外，这里我已经调查过了，不是什么邪教组织，你可以放心在此活动。"] = "Кроме того, я уже исследовал это место; это не культовая организация, поэтому вы можете быть уверены, что будете здесь активны.",
    ["只、只能算是勉强有些审美吧！下次一定不会让你赢了！"] = "Т-так и быть, вкус у тебя хоть немного, но есть! Но в следующий раз я точно не дам тебе победить!",
    ["只为守护您的健康而存在。"] = "Существует только для того, чтобы охранять ваше здоровье.",
    ["只会念诗可没什么用。"] = "Просто читать стихи бесполезно.",
    ["只是向您问个好，警官。"] = "Просто здороваюсь, офицер.",
    ["只是字母而已，没什么特别的。您要是没事，就别在这儿站着了。"] = "Просто буквы, ничего особенного. Если вам нечего делать, пожалуйста, не стойте здесь.",
    ["只有变得更便宜，才能被更多人买到，只要买的人足够多，我们就能定义什么是风尚——这可比原料贵重得多。"] = "Только подешевев, его сможет купить больше людей. Пока достаточное количество людей покупают это, мы можем определить, что такое мода — это гораздо более ценно, чем сырье.",
    ["只有这一小块面包吗……"] = "Это единственный маленький кусочек хлеба...",
    ["只用给我2苏勒，这个月的加班名额就让给你。"] = "Просто дайте мне 2 суле, и я предоставлю вам сверхурочную работу в этом месяце.",
    ["只要是阳光充沛的地方就好，我的后半生，只想在轻松与闲适中度过了。"] = "Главное, чтобы там было вдоволь солнца. Вторую половину жизни мне хочется провести в тишине и безмятежности.",
    ["只需要付出一到两周的利息，大约两三百镑，就能获得脚踏车公司10%的股份。"] = "Вам нужно всего лишь заплатить проценты за одну или две недели, около двух или трехсот фунтов, чтобы получить 10% акций велосипедной компании.",
    ["可、可他是真心对我好……"] = "Но, но он по-настоящему добр ко мне...",
    ["可一周前它丢了，有人看见它跑进了火车站。"] = "Но неделю назад он пропал, и кто-то видел, как он вбежал на вокзал.",
    ["可两张二等座车票要花整整三十镑！这和我两周的薪水一样多！"] = "Но два билета второго класса стоят целых тридцать фунтов! Это столько же, сколько моя зарплата за две недели!",
    ["可以了，但你想帮他们写更长的信，还需要再掌握一百个单词。"] = "Можно, но если вы хотите помочь им писать более длинные буквы, вам нужно освоить еще сотню слов.",
    ["可以向您咨询一下这里的条件吗？"] = "Могу ли я спросить вас об условиях здесь?",
    ["可以彰显身份和力量的华丽战斧，可以用于处理那些滋长过头的敌人，也能顺便帮您保持庭院整洁。"] = "Великолепный боевой топор, подчеркивающий статус и силу: им можно как расправляться с чрезмерно расплодившимися врагами, так и заодно поддерживать порядок в саду.",
    ["可以的话希望您不要将这次的经历说出去……"] = "Если возможно, надеюсь, вы не будете рассказывать об этом опыте...",
    ["可以讲讲基础医学常识，让大家认清常见病的应对方法，避免恐慌和误判。 "] = "Вы могли бы поговорить об элементарном медицинском здравом смысле, позволить всем понять, как бороться с распространенными заболеваниями, и избежать паники и неверных суждений.",
    ["可你不是说，我们要调查码头势力分布，然后占据领地，最后成为最强黑帮吗？"] = "Но разве вы не говорили, что мы собираемся расследовать распределение сил в доках, затем оккупировать территорию и, наконец, стать сильнейшей бандой?",
    ["可你们还这么小，生活一定很艰难吧？"] = "Но вы ведь ещё совсем дети... Вам, должно быть, очень тяжело приходится?",
    ["可怜的孩子……"] = "Бедный ребенок...",
    ["可怜的孩子，现在一定很饿吧，我们再去别处找找，话说，小猫还认得出我们这两个熟客吗？"] = "Бедный ребенок, он, должно быть, очень голоден, пойдем искать где-нибудь еще. Кстати, котенок все еще узнает нас, двух постоянных клиентов?",
    ["可惜我没在地图上找到“伦敦”的具体位置，可能是个不知名的小城。我猜，那也是一个，总是下雨的希望之城吧。"] = "Жаль, что мне не удалось найти на карте конкретное местоположение «Лондона»; это может быть неизвестный маленький город. Я думаю, это также город надежды, в котором всегда идет дождь.",
    ["可是……"] = "Но...",
    ["可是……你们家的房租价钱也不低……"] = "Но... арендная плата за ваш дом тоже не низкая...",
    ["可是大海很危险……据说海上最可怕的，甚至不是狂风暴雨，而是那些看不见的东西。 "] = "Но море опасно... Говорят, что самое страшное на море - это даже не бури, а те невидимые существа.",
    ["可是我真的好饿。"] = "Но я очень голоден.",
    ["可是老师，只有教会典籍中才更多记载了有关四皇之战的内容。从文献中找到具有共性的真相也许更有可能……"] = "Но учитель, только церковные писания содержат больше записей о Войне Четырех Императоров. Поиск общих истин в литературе может оказаться более вероятным...",
    ["可是这和最强黑帮有什么关系……"] = "Но какое это имеет отношение к тому, чтобы быть сильнейшей бандой...",
    ["可是，你们招牌上都写了！我只是想尝尝预言之酒……"] = "Но это написано на вашем знаке! Я просто хочу попробовать вино пророчества...",
    ["可老汤姆说他亲眼见过！黄金梦想号经过时，连汹涌的海浪都会静止！"] = "Но Старый Том сказал, что видел это собственными глазами! Когда «Золотая мечта» проходила мимо, даже бушующие морские волны затихали!",
    ["可能是海上的风浪太大，耽误了行程。我敢打赌，那些浪头一定比圣数教堂的尖顶还要高！"] = "Возможно, ветер и волны на море были слишком сильными и задержали поездку. Могу поспорить, что эти волны были выше шпиля собора Святого числа!",
    ["吃豆腐脑必然得加糖！"] = "Вы должны добавить сахар в пудинг с тофу!",
    ["吃豆腐脑必然得加酱油！"] = "Вы должны добавить соевый соус в пудинг с тофу!",
    ["合伙做什么生意？"] = "Для какого бизнеса мы сотрудничаем?",
    ["吉米，{{先生|女士}}……妈妈白天做女仆，晚上还要穿很冷的衣服出去跳舞。她说等攒够钱就送我去学徒。可是……可是警察说妈妈做了坏事……妈妈是坏人吗？"] = "Джимми, {{ Mr. | Ms. }}... Мама днем ​​работает горничной, а по ночам ей приходится выходить на танцы в очень холодной одежде. Она сказала, что отправит меня в ученики, как только накопит достаточно денег. Но... но полиция сказала, что мама сделала что-то плохое... Мама плохой человек?",
    ["同时，这也能让我学习更多人类的说话艺术。"] = "В то же время это позволяет мне больше узнать о человеческом искусстве разговора.",
    ["同样祝福你。"] = "Благословений и вам.",
    ["后来……后来就不接活了。"] = "Позже... позже я перестал работать.",
    ["后来呢"] = "Что произошло позже?",
    ["后来呢？"] = "А потом?",
    ["后来呢？他们为什么上岸？是不是想抢夺你们拜亚姆的资源？"] = "А потом? Почему они сошли на берег? Они пытались захватить ваши ресурсы в Баяме?",
    ["后来风暴教会严查了此事，毕竟这类现象极易暴露非凡存在，也可能波及无辜船只。"] = "Позже Церковь Штормов строго расследовала это дело. В конце концов, такие явления легко разоблачают существование Потустороннего, а также могут повлиять на невинные корабли.",
    ["向您解释一下，猫就是它的名字，我希望它能帮我抓住那些偷煎肉的老鼠！"] = "Позвольте мне объяснить вам, его зовут Кот, я надеюсь, что он поможет мне поймать тех мышей, которые крадут жареное мясо!",
    ["听“倒吊人”先生提过，他曾目睹两位中序列非凡者为争夺一件封印物在海上交战，余波竟让海面燃烧了十几分钟。"] = "Я слышал, как «Повешенный» упоминал, что однажды он стал свидетелем того, как два Потусторонних в середине эпизода сражались в море из-за Запечатанного Артефакта, и в результате этого поверхность моря фактически горела более десяти минут.",
    ["听上去很不错，所以你是要去那里发财吗？"] = "Звучит здорово, так ты собираешься туда разбогатеть?",
    ["听不懂，听不懂！"] = "Не понимаю, не понимаю!",
    ["听好了，我们今天只做二等车厢的生意，那里的先生小姐虽不阔绰，但总不会付假钞票。"] = "Послушайте, сегодня мы занимаемся только вагонами второго класса. Господа там небогатые, но фальшивыми купюрами расплачиваться не будут.",
    ["听好了，本周的熔炉班，每天工作12小时，一天1苏勒，谁想干？"] = "Слушайте, смена печи на этой неделе 12 часов в день, 1 суле в день, кто хочет это сделать?",
    ["听我说。我们今天的行动是为了整点薯条。"] = "Послушай меня. Наше сегодняшнее действие — получить немного картошки фри.",
    ["听着，“罪恶廷根”是所有人憋在心里的烂摊子具象化出来的城市暗面，像不像见不得光的下水道？"] = "Послушай, «Преступный Тинген» — это тёмная изнанка города, материализовавшийся бардак, который каждый копит в себе. Разве не похоже на сточную канаву, никогда не видящую солнечного света?",
    ["听着，这间屋子不干净，‘它’就在外面。"] = "Слушай, в этой комнате нечисто, «оно» снаружи.",
    ["听话，我下次一定给你买，我们先回家……"] = "Веди себя хорошо, я куплю это тебе в следующий раз. Сначала пойдём домой...",
    ["听说……去年埃斯科森岛那场风暴里，沉了二十条船……"] = "Я слышал... во время шторма на острове Эскерсон в прошлом году затонуло двадцать кораблей...",
    ["听说了吗？恶龙酒吧出现了一位冒险家，还带着一件来自海上的神秘物品。"] = "Вы слышали? В баре ««Злой Дракон»» появился искатель приключений, несущий из моря загадочный предмет.",
    ["听说他们在贝克兰德过得很好，我也为他们高兴。只是可惜了克莱恩先生……"] = "Я слышал, что у них в Баклунде дела идут очень хорошо, и я рад за них. Жаль только мистера Клейн...",
    ["听说他们把牛排煎得外皮焦香，内里嫩得很，肉汁锁得足足的， 酱汁也熬得浓郁醇厚。哪像食堂的汤水，寡淡得连个味道都没有。 "] = "Я слышал, что они поджаривают стейк до тех пор, пока корочка не станет обугленной и ароматной, а внутри не станет нежной и сочной, с густым и мягким соусом. В отличие от супа из столовой, который настолько пресный, что даже не имеет вкуса.",
    ["听说你们在找人试驾？（出示警徽）我想试试。"] = "Я слышал, вы ищете людей для тест-драйва? (Показывает полицейский значок) Я бы попробовал.",
    ["听说你最近缺钱？"] = "Я слышал, тебе в последнее время не хватает денег?",
    ["听说凡森特先生死于心脏病，之前从未听说他有这方面的疾病啊！"] = "I heard Mr. Vincent died of a heart attack. I had never heard of him having any such illness before!",
    ["听说哈罗德百货开业后，会在第一周周五下午三点过后进行特惠活动。"] = "Я слышал, что после открытия универмага Гарольда в первую пятницу после 15:00 у них будет специальная акция со скидками.",
    ["听说她船上有个图书馆，里面的书会自己翻页！"] = "Я слышал, что на ее корабле есть библиотека, и книги внутри сами по себе переворачивают страницы!",
    ["听说您需要一笔钱扩大杂货店的规模？银行那些趾高气昂的业务员只会让您白跑一趟，不如……"] = "Я слышал, вам нужна сумма денег, чтобы расширить свой продуктовый магазин? Эти высокомерные банковские служащие заставят вас бежать просто так, почему бы и нет...",
    ["听说给它起这个名字的是奥黛丽小姐和伦纳德先生。"] = "Говорят, это имя ему дали мисс Одри и мистер Леонард.",
    ["听说贵族间的相亲宴规矩很多？"] = "Я слышал, что среди дворян существует много правил сватовства?",
    ["听说这只公鸡之前是斗鸡比赛的种子选手，难怪这么高产，不愧是“战斗鸡”！"] = "Я слышал, что этот петух раньше был главным соперником в петушиных боях. Неудивительно, что это так продуктивно; это действительно «боевой цыпленок»!",
    ["听说这只猫的名字是“甜冰茶”，而为它起名的人似乎正是奥黛丽小姐和伦纳德先生。"] = "Я слышал, что кошку зовут «Сладкий чай со льдом», а имя дали, кажется, мисс Одри и мистер Леонард.",
    ["听说这里有喝了能梦见未来的酒？"] = "Я слышал, здесь есть вино, позволяющее мечтать о будущем?",
    ["听起来不只是这种内容。"] = "Похоже, дело не ограничивается только этим.",
    ["听起来不是什么困难的事情。"] = "Звучит не так уж и сложно.",
    ["听起来不错，给我来2个柠檬薄荷蛋糕。"] = "Это звучит неплохо. Дайте мне два лимонно-мятных пирожных.",
    ["听起来你很懂？"] = "Похоже, ты много знаешь?",
    ["听起来很不错。"] = "Звучит великолепно.",
    ["听起来很严重，这样大量泄露应该有内部人员的影子吧。"] = "Звучит серьёзно. Столь масштабная утечка наверняка не обошлась без участия кого-то из своих.",
    ["听起来很厉害。"] = "Это звучит очень впечатляюще.",
    ["听起来您不是很赞同？"] = "Похоже, ты не одобряешь?",
    ["听起来是个宏大的议题。"] = "Звучит как весьма масштабная тема.",
    ["听，它又来了！快……必须堵住门！"] = "Слушай, оно снова приближается! Быстро... надо заблокировать дверь!",
    ["吱吱吱！吱吱——"] = "Скрип, скрип, скрип! Писк—",
    ["吱吱，吱吱！<P_Heart>（松鼠眼睛一亮，抬起前爪在空中划了个不标准的圆。）</>"] = "Писк, скрип! <P_Heart>(Глаза белки загораются, и она поднимает передние лапы, чтобы нарисовать в воздухе изогнутый круг.)</>",
    ["吵架就吵架，干嘛要把礼物摔碎？"] = "Просто поссоритесь, зачем ломать подарок?",
    ["呃……事实上，我不是来抢生意的。"] = "Э-э... вообще-то я здесь не для того, чтобы отбивать клиентов.",
    ["呃……其实我觉得很多东西不需要解释，但，再见。"] = "Э-э... вообще-то, я думаю, многие вещи не нуждаются в объяснении, но, до свидания.",
    ["呃……呼……"] = "Э... уф...",
    ["呃……是的，不像吗？"] = "Э-э... да. Разве я не похож на него?",
    ["呃，亲爱的，我想我下不来了。"] = "Ох, моя дорогая, я не думаю, что смогу спуститься.",
    ["呃，可我只想买个狒狒背包……"] = "Э, но я хотел купить только рюкзак в виде павиана...",
    ["呃，我怎么记得，这里以前是个卷毛狒狒背包摊位？"] = "А почему я помню, что раньше это место было ларьком с рюкзаками кудрявых павианов?",
    ["呃，破铁盆，木头篮子，碎玻璃瓶，罐头盒，之类的？"] = "Э-э, разбитые железные тазы, деревянные корзины, разбитые стеклянные бутылки, консервные банки и тому подобное?",
    ["呜……我海那边的故乡……呜……"] = "Ууу... мой родной город за морем... ууу...",
    ["呜呜……他是市政厅的雇员！该死的大人物！呜呜……我哪里比得上他……"] = "Ууууу... он сотрудник мэрии! Чертовски важный выстрел! Уууууу... как мне с ним сравниться...",
    ["呜呜……呜呜，没想到莉娜居然会这样……"] = "Ууу... Ууу, я не ожидала, что Лина будет такой...",
    ["呜呜……真的不可以吗？好吧，我自己来写。"] = "Ууу... неужели это невозможно? Хорошо, я сделаю это сам.",
    ["周末？什么是周末？我们又不是开洗衣店的。"] = "Выходные? Что такое выходные? У нас нет прачечной.",
    ["呵……"] = "Хех...",
    ["呵……呵呵……没有这赔偿！他女儿怎么可能治好病！"] = "Хе... хе-хе... без этой компенсации! Как можно было вылечить его дочь!",
    ["呵呵……那需要我再努力一些……或者等茜茜成为政府雇员，会找到欢迎我们的地方生活的。"] = "Хе-хе... тогда мне нужно работать усерднее... или когда Чичи станет государственным служащим, мы найдем место, где нам будет удобно жить.",
    ["呵呵，他们最终会被送去圣堂。"] = "Хех, их в конечном итоге отправят в Святой Собор.",
    ["呵呵，双倍薪水？上次他也这么说，结果只多给了2便士，连买杯劣质啤酒都不够。"] = "Эх, двойная зарплата? Он сказал так и в прошлый раз, но дал только 2 лишних копейки, не хватило даже на чашку дешевого пива.",
    ["呵呵，好有什么用？没人演，没人听，没人……<P_Heart>（停顿）</>没人要。 "] = "Хех, какой смысл быть хорошим? Никто этого не выполняет, никто не слушает, никто... <P_Heart>(Пауза)</> никому это не нужно.",
    ["呵呵，真让人怀念啊。它让我想起了我的黄金时代。"] = "Хе-хе, какая ностальгия. Это напоминает мне о моем золотом веке.",
    ["呵呵，这三只鸽子从小被母鸡带大！"] = "Хе-хе, этих трех голубей с детства воспитывала курица!",
    ["呵呵，那确实很引人瞩目。"] = "Ха-ха, это и правда привлекает немало внимания.",
    ["呵，猫狗？别想。光是猫毛狗爪印，他都能从“家具磨损费”算到“空气净化费”，连隔壁房间的婴儿哭泣都能算成你的宠物吓的。"] = "Ха, кошки и собаки? Даже не думай об этом. Он подсчитал все: от кошачьей шерсти и отпечатков лап до «износа мебели» и «платы за очистку воздуха». Он даже обвинил бы вашего питомца в том, что ребенок плачет в соседней комнате.",
    ["呼，还好我机灵跑得早。马丁那家伙，竟然想租弗兰奇的公寓。"] = "Уф, хорошо, что я оказался умным и побежал рано. Этот парень Мартин на самом деле хотел снять квартиру Фрэнки.",
    ["命运咖啡厅正在营业中，不知道丽贝卡今天又准备了什么？"] = "Кафе «Судьба» открыто. Интересно, что Ребекка приготовила сегодня?",
    ["和你共度的时光总是如此愉快，让我再享受下这片刻安宁吧。"] = "Время, проведенное с тобой, всегда так приятно, позволь мне еще немного насладиться этим моментом покоя.",
    ["和那位蟾蜍少爷跳舞？不，我讨厌他。这个秋天，我就会去廷根大学报道，努力改变自己的人生。"] = "Потанцевать с этой жабой, молодой господин? Нет, я ненавижу его. Этой осенью я отправлюсь в университет Тинген и постараюсь изменить свою жизнь.",
    ["咕咕咕。"] = "Ку-ку-ку.",
    ["咕咕咕！"] = "Курлы-курлы!",
    ["咦……不对，兰格你认识他们吗？"] = "Ха... подожди, Ланге, ты их знаешь?",
    ["咦，还有和老师水平相当的对手吗？"] = "А, есть противники наравне с учителем?",
    ["咪……喵。"] = "Мяу... мяу.",
    ["咳……成熟的杀手不需要煤气灯的指……嗯？不是这一页……稍等……"] = "Кхм... Опытному убийце не нужен свет газовых рож... Э? Не та страница... Секундочку...",
    ["咳咳！不过我有点好奇，你为什么要在结业考试上捣乱？"] = "Кхм! Но мне немного любопытно, почему ты хотел создать проблемы во время выпускного экзамена?",
    ["咳咳，帮助老板收租，是我们的使命！"] = "Кхм, помочь боссу собрать арендную плату — наша миссия!",
    ["咳咳，每个人的观念不同，兰格他总是教导我们不能偷窃，实际上我也明白身为孤儿有时偷窃是无奈之举。"] = "Кхм, у всех разные понятия. Ланге всегда учит нас не воровать; на самом деле я тоже понимаю, что будучи сиротой, иногда воровать – это последнее средство.",
    ["咳咳，没有，老实说，我的肝不太好，不该再喝啤酒了，但我毕竟在恶龙酒吧里做生意……"] = "Кхе-кхе, нет. Если честно, у меня с печенью не очень хорошо, пиво пить мне бы уже не следовало, но ведь я занимаюсь бизнесом в баре \"«Злой Дракон»\"...",
    ["咳，不重要……总有一天，我要扬帆起航，去追寻海上的宝藏。就算找不到宝藏，我也能在月光下使舵，喝着烈朗齐 ，唱着水手歌……"] = "Кхе, не важно... Однажды я отправлюсь в море искать сокровища. Даже если я не найду клад, я все равно смогу управлять рулем под луной, пить Ранжи и петь матросские песни...",
    ["咳，谁？"] = "Кхе, кто это?",
    ["哇，那还真是……厉害啊。"] = "Вау, это действительно... потрясающе.",
    ["哈哈……要知道去年给动物园河马池修排水渠只用了两周，但人类居住区污水排放提案已经讨论了五年……"] = "Ха-ха... знаете, в прошлом году на ремонт дренажного канала бассейна с бегемотами в зоопарке ушло всего две недели, но предложение по сбросу сточных вод в жилых районах обсуждается уже пять лет...",
    ["哈哈哈，当然，亲爱的，想当年我就是靠这个把你追到手的——那时你可是歌剧院最耀眼的一颗明星！"] = "Ха-ха-ха, конечно, моя дорогая, в тот день я полагался на это, чтобы завоевать тебя - тогда ты была самой яркой звездой оперного театра!",
    ["哈哈！好心、热情的年轻人，陪老头子和这位远道而来的朋友喝一杯吧！"] = "Ха-ха! Добрый, славный юноша, выпей со стариком и с этим другом, приехавшим издалека!",
    ["哈哈！被你听到了，没错，两个港口，两个家，两个温柔的好女人！"] = "Ха-ха! Ты всё слышал... да, именно так: два порта, два дома, две нежные, прекрасные женщины!",
    ["哈哈，一想到这帮家伙的表情，我就要抑制不住激动的心。"] = "Ха-ха, просто думая о выражениях лиц этих парней, я не могу сдержать волнения.",
    ["哈哈，什么话，我当然是真的市长候选人！"] = "Хаха, что ты говоришь? Конечно, я настоящий кандидат в мэры!",
    ["哈哈，你找对人了。在你面前的是二十年书报经验所有人，前邮报编辑，前老实人报编辑，现自由撰稿人。"] = "Ха-ха, ты обратился к нужному человеку. Перед вами человек с двадцатилетним опытом работы в книгах и газетах, бывший редактор «Пост», бывший редактор «Тинген честный репортер» и нынешний писатель-фрилансер.",
    ["哈哈，吓到了吗？有没有出冷汗？我跟“世界”先生学的语气！"] = "Хаха, ты испугался? Вы покрылись холодным потом? Я научился этому тону у мистера Мира!",
    ["哈哈，是我的妹妹小萨拉寄回来的信。"] = "Ха-ха, это письмо от моей младшей сестрёнки Сары.",
    ["哈哈，有机会我也想见见这位先生！"] = "Ха-ха, выдайся возможность, я бы тоже хотел познакомиться с этим господином!",
    ["哈哈，风暴在上，我回来了！"] = "Ха-ха, Шторм наверху, я вернулся!",
    ["哈！难怪质检公司代表把安全预算叫“给机器喂素食”……之后怕是要提议给锅炉喂馅饼来减少事故了！"] = "Ха! Неудивительно, что представитель компании по контролю качества называет бюджет безопасности «кормлением машины вегетарианской пищей»… Боюсь, они предложат кормить котлы пирогами рядом, чтобы уменьшить количество несчастных случаев!",
    ["哈，一颗1350年的弹壳！我喜欢这种淘金的感觉！"] = "Ха, гильза от 1350! Мне нравится это ощущение промывания золота!",
    ["哈，难怪他们总慷慨发言说那些机械是“信仰装置”——原来是因为这些装置能带来不少金镑啊！"] = "Ха, неудивительно, что они во всеуслышание называют эти механизмы «устройствами веры» — оказывается, всё потому, что они приносят немало золотых фунтов!",
    ["哎……别租弗兰奇的房子，我给你介绍其他的。"] = "Эх... не снимай дом Фрэнки, я познакомлю тебя с другими.",
    ["哎……贝蒂，看。这衣服料子多好，但是这污渍多难搓干净啊，你说她们出汗不也是一样脏？"] = "Эх... Бетти, посмотри. Эта ткань такая хорошая, но эти пятна так трудно отстирать. Вам не кажется, что они так же пачкаются, когда потеют?",
    ["哎呀哎呀，你发现我了！！！"] = "О боже, о боже, ты нашел меня!!!",
    ["哎呀真拿你没办法！"] = "Ох, я действительно ничего не могу с тобой сделать!",
    ["哎呀，您还是这么善良仁慈。"] = "Ох, вы по-прежнему столь добры и милосердны.",
    ["哎呀，老了老了……听不清楚……"] = "О боже, я стар, я стар... Я плохо слышу...",
    ["哎好，这就给你挂号……{{小伙子|小姑娘}}你叫什么呀？是哪里不舒服？"] = "Хорошо, сейчас я тебя зарегистрирую... Как тебя зовут, молодой {{man/woman|}}? Где вы чувствуете себя некомфортно?",
    ["哎！谢尔敏先生不做啦！断货啦！您说，他什么时候再开发新饮料啊？我的顾客们都等不及啦！"] = "Эх! Мистер Шермин закрыл лавочку! Товар закончился! Не знаете, когда он разработает новые напитки? Мои покупатели уже заждались!",
    ["哎，现在经济不景气，反倒是这种怪人聚集的地方，能吸引来不少顾客……"] = "Эх, с экономикой сейчас плохо. Наоборот, места, где собираются вот так чудаки, могут привлечь немало клиентов...",
    ["哥哥你能教我偷东西吗？"] = "Брат, ты можешь научить меня воровать?",
    ["哥哥擅长……哦哦，哥哥比妈妈还会做裙子，小女孩的小裙子、大姐姐的大裙子，还有夫人们的帽子、手套和胸花！"] = "Мой брат хорошо умеет... ох, ох, мой брат шьет платья даже лучше, чем мама! Платья для маленьких девочек, платья для старших сестер и даже женские шляпки, перчатки и корсажи!",
    ["哥哥每次来都喊累，我都心疼了。以后，我天天给哥哥捏。"] = "Брат, ты говоришь, что устал каждый раз, когда приходишь, у меня от этого сердце болит. С этого момента я буду делать тебе массаж каждый день.",
    ["哦……"] = "Ой...",
    ["哦……不，当然不叫这个，哈哈。"] = "Ох... нет, конечно, это не так называется, хаха.",
    ["哦……嗯？哎呀我这耳朵背了没听清，{{小伙子|小姑娘}}你再说一次？"] = "Ох... хм? О боже, мои уши немного плохо слышат, {{young man| young lady}}, не мог бы ты сказать это еще раз?",
    ["哦……她离开了……她还是离开了……"] = "Ох... она ушла... всё-таки она ушла...",
    ["哦……对您造成了困扰，我很抱歉。"] = "Ох... Прости, что причинил тебе неприятности.",
    ["哦……您是好人，温和又大度。"] = "Ох... ты хороший человек, нежный и щедрый.",
    ["哦……我怀念的南大陆，我海那边的故乡……"] = "Ох... мой пропущенный Южный континент, мой родной город за морем...",
    ["哦……谢谢你的安慰，事实上，今天是我离开南大陆老家，来到鲁恩的一周年纪念日。"] = "Ох... спасибо за утешение. Фактически, сегодня ровно год с тех пор, как я покинул свой старый дом на Южном континенте и приехал в Лоэн.",
    ["哦亲爱的……可薪水一直都会有，像这样期待已久的旅程却不会一直等着我们。"] = "Ох, дорогая... зарплата всегда будет больше, но такое долгожданное путешествие не будет ждать нас вечно.",
    ["哦孩子，当然就是这里，这个拥挤的火车站！"] = "Ох, детка, конечно, он здесь, этот переполненный вокзал!",
    ["哦对了！还有迪西馅饼，“愚者”先生曾经很喜欢迪西馅饼配甜冰茶，你也可以试试。"] = "О, верно! И есть пирог Дизи. Мистеруу когда-то нравился пирог Дизи со сладким чаем со льдом; ты тоже можешь это попробовать.",
    ["哦对了，不要随便和他说话，更不要吵架哦，他会急哭的。"] = "Ах да, не разговаривайте с ним небрежно и уж точно не спорьте с ним; он будет так волноваться, что заплачет.",
    ["哦！不……"] = "Ой! Нет...",
    ["哦！女神！你绝对猜不到，“特殊服务”居然是去剧院门口排队买新话剧的票！"] = "Ой! Богиня! Никогда не догадаетесь, «спецслужба» на самом деле стояла в очереди у входа в театр за билетами на новый спектакль!",
    ["哦，不好意思，我现在有点太兴奋了。需要送你回恶龙酒吧吗，这里还挺远的。"] = "Ой, извини, я сейчас слишком взволнован. Тебе нужно, чтобы я отправил тебя обратно в бар ««Злой Дракон»»? Это довольно далеко отсюда.",
    ["哦，你好，克莱恩。你们有按时交房租，是体面的人，找我有什么事？"] = "Oh, hello, Клейн. Вы вовремя платите арендную плату и являетесь порядочными людьми. Чего ты хочешь от меня?",
    ["哦，先生！事实上你应该去这栋楼的背面，那里的占卜俱乐部更符合你的要求，并且——请一位占卜师只需要几便士。"] = "О, сэр! На самом деле вам стоит пройти на заднюю сторону этого здания — тамошний Клуб Провидцев лучше подходит под ваши требования, и притом — нанять провидца стоит всего пару пенсов.",
    ["哦，天哪！它在勾引我！"] = "Боже мой! Это соблазняет меня!",
    ["哦，对了，上车记得带上身份证明去拍照，这是王国新颁布的规定。"] = "Ах да, не забудьте взять с собой удостоверение личности для фотографии при посадке; это новое постановление, изданное Королевством.",
    ["哦，对了，他们还为我准备了终身票价优惠的回馈。"] = "Ах да, еще и в награду мне приготовили пожизненную скидку на билеты.",
    ["哦，您或许听说过，他的父亲——<P_Yellow>比奇·蒙巴顿</>，负责巡逻下街的警察。"] = "О, возможно, вы слышали о его отце — <P_Yellow> Бич Мумбатон</>, офицере полиции, ответственном за патрулирование Лоуэр-стрит.",
    ["哦，我的南大陆老家，我无时无刻不在想念它。"] = "О, мой дом на Южном континенте, я скучаю по нему каждое мгновение.",
    ["哦，我虔诚的丈夫自然不会受到打扰。那么，这块地价格如何？"] = "О, мой благочестивый муж, конечно, не будет обеспокоен. Итак, какова цена этого участка?",
    ["哦？都有些什么“神奇”议案？"] = "Ой? Какие «волшебные» купюры существуют?",
    ["哪怕那些课程很困难，她不喜欢，但为了这个家还是会努力，我不能再剥夺她更多的爱好了。"] = "Даже если эти курсы сложны и ей не нравятся, она будет усердно работать ради этой семьи. Я не могу лишить ее больше хобби.",
    ["哪有那么多问题？你是不是还要问为什么我能在这样的位置开一间诊所？"] = "Почему так много вопросов? Вы в следующий раз спросите, почему я могу открыть клинику в таком месте?",
    ["哪来的疯子……"] = "Откуда взялся этот псих...",
    ["哼……"] = "Хм...",
    ["哼，不过，我种的南瓜比他的酒好多了，如果他想要的话——我是说，我当然可以慷慨地送出去一些！"] = "Хм, однако тыквы, которые я выращиваю, намного лучше, чем его вино. Если они ему нужны — я имею в виду, конечно, я могу щедро их отдать!",
    ["哼，你会后悔的！"] = "Хм, ты пожалеешь об этом!",
    ["哼，你是不是隔壁派来偷南瓜的！丰收节想赢我，没那么容易！"] = "Хм, тебя что, соседи подослали воровать тыквы?! Победить меня на Празднике Урожая не так-то просто!",
    ["哼，嚷，都可以嚷，年轻人不懂社会，包有他好果子吃。"] = "Хм, пусть кричат. Они могут кричать, что хотят. Молодые люди не понимают общество; они обязательно почувствуют горький вкус этого.",
    ["哼，算你识相，我的南瓜一定是最大最甜的！"] = "Хм, ты соображаешь! Мои тыквы точно самые большие и сладкие!",
    ["哼，至于父母……有些人死于工厂事故，有些人被疾病带走了，还有些人……干脆把我们丢在了街头。"] = "Хм, а родители... кто-то погиб в результате несчастного случая на производстве, кого-то увезли болезни, а кто-то... просто бросил нас на улице.",
    ["哼，难听怎么了，听说“风暴使者”唱歌也特别难听！"] = "Хм, а что, если это плохо? Я слышал, что «Storm Bringer» тоже ужасно поет!",
    ["唉……我该怎么找到我的猫呢？"] = "Эх... как мне найти свою кошку?",
    ["唉！而我是如此的羡慕。所有我见到的生物都如此高兴，"] = "Вздох! И я так завидую. Все существа, которых я вижу, так счастливы,",
    ["唉，前阵子有几个外区来的生面孔在附近转悠，我正想这几天去警局汇报……这世道，还得靠您这样的正义之士啊！"] = "Эх, в последнее время неподалеку бродят несколько незнакомых лиц из отдаленных районов. Я как раз сейчас думал сообщить об этом в полицейский участок... В этом мире нам все еще приходится полагаться на таких праведных людей, как ты!",
    ["唉，外来人，唉，移民。"] = "Эх, чужаки, вздох иммигранты.",
    ["唉，我担心他因为自己的小说而魔怔了，前段时间他就怪怪的。"] = "Эх, я боюсь, что он стал одержим своим собственным романом. В последнее время он ведёт себя странно.",
    ["唉，晚一会我去罗丁家里看看。孩子们的结业考试，可不能这样草率地结束了。"] = "Эх, я пойду проверю дом Родена позже. Выпускные экзамены детей не могут заканчиваться так небрежно.",
    ["唉，瑞恩那家伙叫卖的声音比我更洪亮，出炉煎肉的速度也更快，客人全被他吸引过去了……"] = "Эх, у этого парня Райана более громкий голос, чем у меня, и он еще и жарит мясо быстрее. К нему тянутся все клиенты...",
    ["唉，看来孩子们又要挨饿了……"] = "Эх, кажется, дети снова будут голодать...",
    ["唉，算了，有总比没有强。听说有些工厂是“自愿加班”，加班一晚上连1便士都不给。"] = "Эх, забудь, что-то лучше, чем ничего. Я слышал, что на некоторых заводах работают «добровольные сверхурочные», и за работу всю ночь не дают даже ни копейки.",
    ["唉，还是专心铲煤吧，这煤越铲越硬。"] = "Эх, давайте просто сосредоточимся на выгребании угля; чем больше копаешь, тем сложнее становится.",
    ["唉，这本《王国法典》真是又厚又难啃……可要是考不上公务员，这辈子都会被困在下街。"] = "Эх, этот «Кодекс Королевства» такой толстый и заумный... Но если не сдать экзамен на госслужбу, так и останешься на всю жизнь запертым на Нижней улице.",
    ["商业手段也是很重要的一环！"] = "Деловая тактика также является очень важной частью!",
    ["啊——哈加提苦酒，少女泪水与汗水的味道——"] = "Ах — горькое вино Хагати, вкус девичьих слез и пота —",
    ["啊……你是说隔壁南瓜田的那位伦伯先生。"] = "А... ты имеешь в виду мистера Ламбера с тыквенной грядки по соседству.",
    ["啊……嗯。"] = "А... да.",
    ["啊……这些南瓜看起来的确很好吃。"] = "Ах... Эти тыквы и впрямь выглядят аппетитно.",
    ["啊哈，和我说的一样！我的船长，看来我们得先给船准备雨伞了。"] = "Ага, как я и сказал! Мой капитан, кажется, сначала нам нужно подготовить зонтики для корабля.",
    ["啊！又是一块碎龟壳，这里不会住着一只很大的乌龟吧！"] = "Ах! Еще один кусок черепашьего панциря. Может ли здесь жить очень большая черепаха!",
    ["啊！啊……是啊，我忘记了。"] = "Ах! Ах... да, я забыл.",
    ["啊！！！！"] = "Ах!!!!",
    ["啊，不必拘谨。从码头区的卸货劳工，到贝克兰德王宫中的贵人们，风暴之主的教堂对所有人开放。"] = "Ах, не нужно быть зарезервированным. От разгружающих рабочих в порту до дворян во дворце Бэкланд — Церковь Повелителя Штормов открыта для всех.",
    ["啊，你是说……海上已经很久没有他的消息了，说不准这神秘力量就与他有关。"] = "А, вы имеете в виду... давно о нем не было вестей с моря. Возможно, эта загадочная сила связана с ним.",
    ["啊，先生，我简直不知道该如何感谢您……"] = "Ах-с, я просто не знаю, как вас отблагодарить...",
    ["啊，当然有的，若您感兴趣的话，可以了解一下我们的“静夜礼赞”项链，以黑夜和繁星为主题，代表着女神的庇佑，点缀着几十颗有着无与伦比切割工艺的——"] = "Ах, конечно, если вам интересно, вы можете узнать о нашем колье «Тихая Ночь Похвала», посвященном ночи и звездам, олицетворяющим защиту Богини, украшенному десятками драгоценных камней с беспрецедентным мастерством огранки.",
    ["啊，您说什么？我怎么听到了我小女儿的名字……"] = "Ах, что ты сказал? Почему я услышал имя моей маленькой дочери...",
    ["啊，我准备好迎接爱情了……"] = "Ах, я готов приветствовать любовь...",
    ["啊，理解理解！活动持续整月，欢迎随时来试！黄色结实，蓝色迅捷，棕色安静！ "] = "Ах, понял, понял! Акция продлится весь месяц, присоединяйтесь в любое время! Желтый – крепкий, синий – быстрый, коричневый – тихий!",
    ["啊？"] = "Хм?",
    ["啊？怎么在那里……我记得，那地方发生过很多类似的事。"] = "Ах? Зачем оно там... Помню, много подобного происходило в том месте.",
    ["啊？等等！弗兰奇给你什么好处你这么帮他！我把你当兄弟，你就这么对我！"] = "А? Погоди! Что такого дал тебе Фрэнки, что ты ему так помогаешь?! Я считал тебя братом, а ты так со мной поступаешь!",
    ["啧……这点边角肉，免费送你。"] = "Тск... возьми эти мясные остатки бесплатно.",
    ["啧，走开，别人的事你少问。"] = "Тск, потеряйся. Занимайтесь своими делами.",
    ["喂……那都过去了，我们换个话题——之前经常在餐馆里蹭吃的漂亮小白猫现在跑哪去了？"] = "Эй... это дело прошлое, давай сменим тему. Куда подевалась та красивая белая кошечка, что вечно выпрашивала еду в ресторане?",
    ["喂亨特，管好你的狗，它吵得像刚出生的婴儿！"] = "Эй, Хантер, управляй своей собакой, она шумная, как новорожденный ребенок!",
    ["喂那边的臭小孩，玩狗的时候安静一点！我不能再输了！"] = "Эй, сопляк, потише там со своей собакой! Мне больше нельзя проигрывать!",
    ["喂，你一直在这偷听，是想干什么？"] = "Эй, ты здесь подслушиваешь, что ты хочешь сделать?",
    ["喂，你怎么又拖长音。"] = "Эй, а чего ты опять затягиваешь слова?",
    ["喂，兄弟，你怎么总从教堂楼顶往下跳——已经持续整整两周了！小心点，别摔断了腿！"] = "Эй, брат, почему ты все время прыгаешь с крыши церкви – это продолжается уже целых две недели! Будьте осторожны, не сломайте ногу!",
    ["喂，老兄，你可别想不开啊。 "] = "Эй, приятель, не думай о таких мрачных вещах.",
    ["喂，醒醒！你在葡萄酒学院读了四年书，怎么喝两口就倒下了！"] = "Эй, просыпайся! Ты четыре года учился в Винной академии, как ты упал после двух глотков!",
    ["善良？正直？亲爱的，这些品质在贵族圈里就像空气一样廉价——而且我们从不缺空气。 "] = "Добрый? Честный? Дорогой мой, эти качества в дворянских кругах дешевы, как воздух, а у нас никогда не бывает недостатка в воздухе.",
    ["喏，二楼有个打扮得像侦探的，这周来了好几次了，每次都盯着我看。"] = "Ну, на втором этаже есть кто-то, одетый как детектив. Он был здесь несколько раз на этой неделе и каждый раз пристально смотрит на меня.",
    ["喏，最大的那颗。不过今晚还得加点量，保证别人买回家一尝就“出状况”。"] = "Вот самый большой. Но сегодня вечером мы должны добавить больше, чтобы гарантировать, что, когда другие купят его домой и попробуют, у них «будет ситуация».",
    ["喔！这个仪式看起来真的有效！"] = "Ух ты! Кажется, этот ритуал действительно работает!",
    ["喝了这种酒，就能梦见即将发生的事吗？我愿意用我的积蓄买上一杯，我想去梦里看看美丽的赫柏小姐会不会成为我的妻子！"] = "Если я выпью это вино, смогу ли я мечтать о том, что сейчас произойдет? Я готов потратить свои сбережения, чтобы купить стакан. Я хочу погрузиться в свои сны и посмотреть, станет ли прекрасная госпожа Хебе моей женой!",
    ["喝酒就能找到灵感的话，你现在就是文豪了。先缓缓吧。"] = "Если бы выпивка могла помочь вам найти вдохновение, вы бы уже стали литературным гигантом. Успокойтесь на мгновение.",
    ["喝！"] = "Напиток!",
    ["喝！今晚不想那该死的梯子！"] = "Напиток! Я не хочу сегодня думать об этой чертовой лестнице!",
    ["喧闹的牌桌安静了一瞬，又再次喧闹了起来，你用当初挣脱出红茧的意志力狠狠地把纸牌往前掷去。"] = "Шумный карточный стол на мгновение затих, а затем снова зашумел. Вы яростно швыряли карты вперед с той силой воли, которую использовали, чтобы вырваться из красного кокона.",
    ["喵——喵——"] = "Мяу-мяу-",
    ["喵……"] = "Мяу...",
    ["喵。"] = "Мяу.",
    ["喵呜……"] = "Мяу...",
    ["喵！"] = "Мяу!",
    ["喵？"] = "Мяу?",
    ["嗨呀，都怪我这手艺太好！ 前两天研究了一种鱼干的新做法，本想自己下酒，结果这香味可捅了马蜂窝了！ "] = "Эх, это все потому, что мои навыки слишком хороши! Несколько дней назад я исследовал новый способ приготовления сушеной рыбы, собираясь выпить ее сам, но аромат проткнул осиное гнездо!",
    ["嗨！名字都在酒里泡化了！反正是那种、能解决麻烦的地方，你懂吧！"] = "Привет! Имена все пропитаны алкоголем! В любом случае, это такое место, где можно решать проблемы, знаете ли!",
    ["嗨，要来点神秘配方吗？从实验器具到药方，应有尽有。"] = "Эй, хочешь загадочных формул? У нас есть все: от экспериментального оборудования до рецептов.",
    ["嗯……{{PlayerName}}你什么时候来的？喝酒吗，我请你。"] = "Хм... {{PlayerName}}, когда ты пришел? Питьевой? Моё угощение.",
    ["嗯……他也有一些迟钝，但这点只困扰着戴莉女士。"] = "Хм... он также был немного туповатым, но это только беспокоило мисс Дейли.",
    ["嗯……你说得没错。谢谢你的建议，希望我的小昂格能跟新朋友和平相处。"] = "Хм... ты прав. Спасибо за ваше предложение, я надеюсь, что мой маленький Энг сможет мирно ужиться со своим новым другом.",
    ["嗯……我推荐紫丁香和向日葵，它们都是在郊外新鲜采摘的，还有秋海棠，牵牛花……"] = "Хм... Я рекомендую сирень и подсолнухи; все они только что собраны в пригороде. Есть еще бегонии, ипомея...",
    ["嗯……我看你的衣服品味不是一般人，有兴趣参加我们时尚协会的交流么？\n当然，你得先完成我的考验。"] = "Хм... Я вижу, у вас необычный вкус в одежде. Не желаете поучаствовать во встрече нашей Ассоциации моды?\nРазумеется, сначала вам придётся пройти моё испытание.",
    ["嗯……或许你是对的，我去厨房找些剩面包拿给她。"] = "Хм... возможно, ты прав, я пойду на кухню и найду для нее остатки хлеба.",
    ["嗯……这几个卖相不错，明天带着几个去中央广场卖吧。"] = "Хм... выглядят неплохо. Я отвезу несколько штук на Центральную площадь, чтобы продать завтра.",
    ["嗯……这样……酒保，结账！"] = "Хм... в таком случае... Бармен, проверьте, пожалуйста!",
    ["嗯……送的这一束，我想要这个捧花棒。"] = "Хм... Я хочу вот эту палочку для этого букета.",
    ["嗯……那样另类的幽默，也能算是一种说话的艺术吧。"] = "Хм... такой альтернативный юмор тоже можно считать формой разговорного искусства.",
    ["嗯……预订要交订金的规矩。"] = "Хм... правило, согласно которому за бронирование необходимо внести залог.",
    ["嗯。每周都来，每周都醉。上周他差点把酒杯砸钢琴上。"] = "Ага. Приходит каждую неделю, каждую неделю напивается. На прошлой неделе он чуть не разбил стакан о пианино.",
    ["嗯！是时候对自己的胃好一点了！"] = "Ага! Пришло время лучше лечить мой желудок!",
    ["嗯，他们也有非常易于辨认的口头禅，称赞彼此<P_Yellow> 幽默，风趣，会说笑</> 。"] = "Ну, а еще у них есть очень узнаваемая крылатая фраза, в которой они хвалят друг друга за <P_Yellow> юмор, веселье и умение шутить </> .",
    ["嗯，你对摄影艺术感兴趣吗？"] = "Хм, а ты интересуешься искусством фотографии?",
    ["嗯，后天我家所有人都过生日，一双新手套给老爸，一把新菜刀给老妈，还有一支新笔给老妹。"] = "Да, у всей моей семьи послезавтра дни рождения. Пара новых перчаток для папы, новый кухонный нож для мамы и новая ручка для моей младшей сестры.",
    ["嗯，后天我老婆孩子都过生日，我要给他们每人都扎一个玩偶。"] = "Да, у моей жены и детей послезавтра день рождения. Я собираюсь сделать куклу для каждого из них.",
    ["嗯，就这么写评价！"] = "Хм, напишу отзыв так!",
    ["嗯，恰好。"] = "Хм, случилось.",
    ["嗯，我提前占卜到了这里有人需要帮助。"] = "Да, я заранее угадал, что кому-то здесь нужна помощь.",
    ["嗯？你也跟过来了？不得不说，这个提议真不错。"] = "Хм? Ты тоже следил? Я должен сказать, что это предложение действительно хорошее.",
    ["嗯？你哪来的？走走走！"] = "А? Ты откуда взялся? Пошел вон, пошел!",
    ["嗯？你怎么还不走？"] = "Хм? Почему ты еще не ушел?",
    ["嗯？看起来是……人的发丝？"] = "Хм? Похоже на... человеческие волосы?",
    ["嗯？糊弄我？走走走！"] = "Эм? Обмануть меня? Иди, иди, иди!",
    ["嘘……她回家了，从红色的烟囱回家了！"] = "Тсс... она пошла домой, она пошла домой через красную трубу!",
    ["嘘……小声点。{{先生|女士}}，你要买画吗？那种开心的画，不贵。"] = "Тсс... потише. {{Mr.|Ms.}}, хочешь купить картину? Такая счастливая картина, не дорогая.",
    ["嘘！嘘！不要和莉莉娅说话！"] = "Тсс! Тсс! Не разговаривай с Лилией!",
    ["嘘！嘘！嘘！别别别，我这就放回去……"] = "Тсс! Тсс! Тсс! Не надо, не надо, я сейчас положу его обратно...",
    ["嘘！声音小点，你还想让他听见吗？"] = "Тсс! Потише, хочешь, чтобы он тебя услышал?",
    ["嘘！这话你也敢说……"] = "Тсс! Ты посмеешь сказать это...",
    ["嘘，嘘，怕什么。"] = "Тсс-шш, чего ты боишься?",
    ["嘤——"] = "Эх…",
    ["嘻嘻！哈哈！别、别走开，精彩的还在后面！"] = "Хи-хи! Хаха! Не уходи, самое лучшее еще впереди!",
    ["嘿嘿，我还没想好。"] = "Хе-хе, я еще об этом не думал.",
    ["嘿，不知道这艘船要开去哪里。不过我想我的机遇来了……要画画吗，{{先生|女士}}？？"] = "Эй, я не знаю, куда направляется этот корабль. Но я думаю, что моя возможность пришла... Хотите картину, {{Mr.|Ms.}}??",
    ["嘿，你听说过“黄金梦想号”吗？他们说那艘船的船帆在月光下会变成水晶！"] = "Эй, ты слышал о «Золотой мечте»? Говорят, паруса этого корабля под луной превращаются в хрусталь!",
    ["嘿，你来了！去告诉船长，我们需要等到暴风雨之后出发！"] = "Эй, ты здесь! Иди и скажи капитану, что нам нужно дождаться окончания шторма, чтобы отплыть!",
    ["嘿，你知道他是为什么被赶出来的吗？他记混了自己几位情人的名字！"] = "Эй, а ты знаешь, почему его выгнали? Он перепутал имена своих любовниц!",
    ["嘿，别踢我！"] = "Эй, не бей меня!",
    ["嘿，小子，别想那些。我们都知道大海要收些代价，但她也会给予回报。"] = "Эй, малыш, не думай об этом. Мы все знаем, что море требует платы, но оно также дает и награды.",
    ["嘿，最好是带回来一位帅气的绅士，你说呢？"] = "Эй, было бы лучше вернуть красивого джентльмена, ты так не думаешь?",
    ["嘿，机会不等人，来得晚了名额可就会被抢了——别怪我没提醒你。"] = "Эй, возможность никого не ждет, если ты опоздаешь, место будет занято — не говори, что я тебя не предупреждал.",
    ["嘿，这又不是什么稀奇事！我们在对金秋湖的湖灵献祭。它脾气很怪，但愿祭品能让它安静一阵子。"] = "Эй, это не редкость! Мы приносим жертву Духу озера Золотой Осени. У него очень странный характер, надеюсь, подношение на какое-то время успокоит его.",
    ["嘿，这家餐馆去哪了？"] = "Эй, а куда делся этот ресторан?",
    ["嘿，都别急……还有一个条件——这份工作得先交3苏勒的“介绍费”。"] = "Эй, не торопитесь... есть еще одно условие — сначала нужно внести «вступительный взнос» в размере 3 суле.",
    ["噗嗤……看来您还是个孩子，茜茜曾经也这么可爱。"] = "Пфф... Кажется, ты еще ребенок; Чичи тоже раньше была такой милой.",
    ["噢……抱歉。"] = "Ох... извини.",
    ["噢……抱歉。但我必须要坦诚地拒绝你。否则这可能给我们都带来困扰。"] = "Ох... прошу прощения. Но я вынужден прямо отказать вам, иначе это принесет неприятности нам обоим.",
    ["噢……杰西，我会一直想念你。"] = "Ох... Джесси, я всегда буду скучать по тебе.",
    ["噢等等，这是哪里来的小可怜，瞧瞧你这身打扮……"] = "Ой, подождите, откуда взялась эта бедная малышка? Посмотрите на свой наряд...",
    ["噢！你喜欢的话，到时候就尽管拿去喝。"] = "Ой! Если оно вам нравится, смело берите его и пейте.",
    ["噢！谢谢您的评价，这给予了我莫大的信心。我时常因为过去的诗人们书写了太多的佳作而感到忧郁。"] = "Ой! Спасибо за вашу оценку; это дает мне большую уверенность. Я часто чувствую меланхолию, потому что поэты прошлого написали слишком много шедевров.",
    ["噢，不是。这是我欠钱被打的。"] = "О, нет. Это потому, что меня избили за задолженность.",
    ["噢，他比妓院里的老鸨都啰嗦！"] = "О, он более многословен, чем хозяйка борделя!",
    ["噢，你好！我在这等我丈夫呢，他离开小镇去打工，应该这几天就回来。"] = "О, привет! Я жду здесь мужа. Он уехал из маленького городка на работу и должен вернуться через несколько дней.",
    ["噢，你好，有什么需要？"] = "О, привет, что тебе нужно?",
    ["噢，别担心，是爱让我来到了这里。"] = "О, не волнуйтесь, меня сюда привела любовь.",
    ["噢，别这样。我最近手头确实有些紧……等这周的工钱一发，我立刻还给你，我发誓！"] = "О, не делай этого. В последнее время у меня действительно не хватает денег... Как только будет выплачена зарплата за эту неделю, я немедленно верну вам деньги, клянусь!",
    ["噢，差点忘了。今天我只要5磅面包。"] = "Ой, чуть не забыл. Мне сегодня нужно всего 5 фунтов хлеба.",
    ["噢，很难想象，一个珠宝店居然可以装下这么多人……"] = "Ох, сложно представить, что ювелирный магазин может вместить столько людей...",
    ["噢，您好！真抱歉，我现在无法停下来和您说话，火车快来了，我必须不停地跳！"] = "О, привет! Мне очень жаль, я не могу сейчас остановиться и поговорить с тобой, поезд уже приближается, и мне приходится продолжать прыгать!",
    ["噢，我亲爱的孩子们！我这里有一份绝佳的工作机会，只需要你们每天工作12个小时，就能赚到……嗯，5个便士！"] = "О, мои дорогие дети! У меня здесь отличная возможность трудоустройства, вам нужно работать всего 12 часов в день, и вы можете заработать... хм, 5 копеек!",
    ["噢，我们的好堂弟！他回来了？"] = "О, наш добрый кузен! Он вернулся?",
    ["噢，抱歉，我的眼睛不太中用了，我实在是太老了……"] = "Ой, извини, у меня уже плохое зрение, я слишком стар...",
    ["噢，是的，先生，我们这里有叫做“未来梦”的高档白葡萄酒，如果您需要的话，欢迎进店品尝。"] = "О да, сэр, у нас есть элитное белое вино под названием «Мечта будущего». Если оно вам нужно, можете зайти и попробовать.",
    ["噢，真令人生气，你们一个个简直像蔫巴的生菜叶！"] = "Ох, как это бесит, вы, ребята, похожи на увядшие листья салата!",
    ["噢，让我们为能镶嵌在她假发上的荣耀干杯！干杯！"] = "О, выпьем за славу, которая украсит ее парик! ваше здоровье!",
    ["噢，那顿饭可是我付的钱，你当时还是个穷小子呢，兄弟！"] = "О, я заплатил за эту еду. Ты тогда был всего лишь бедным ребенком, брат!",
    ["噢？"] = "Ой?",
    ["四皇之战的历史，被我的意志与知识皇冠共同编织成了一片战场。那里有霍纳奇斯的风雪，有猎龙之城的烈火，也有廷根——身为入局者，你记忆的起始之地。"] = "The history of the War of the Four Emperors has been woven by my will and the Crown of Knowledge into a battlefield. There, you will find the snowstorms of Hornacis, the raging fires of the City of Dragon Hunting, and Tingen—as a participant, the place where your memories began.",
    ["回去吧，我并不喜欢开玩笑。"] = "Вернитесь, я не люблю шутки.",
    ["因为上面那个吹牛的醉鬼是我老爹，我得防止他摔下来！"] = "Потому что пьяница, который там хвастается, — мой старик, и я должен не дать ему упасть!",
    ["因为得有人在这里。"] = "Потому что кто-то должен здесь находиться.",
    ["因为我就是那个帮工！赶紧把违约金交出来！"] = "Потому что я тот помощник! Спешите оплатить штраф за нарушение договора!",
    ["因为我欠这个家伙的钱。"] = "Потому что я должен этому парню денег.",
    ["因为我要成名，{{先生|女士}}。我在等一趟从贝克兰德来、载满了大人物的车！等他们看我一眼！"] = "Потому что я хочу прославиться, {{sir|madam}}. Я жду карету из Баклунда, наполненную важными людьми! Я жду, когда они посмотрят на меня!",
    ["因为病人太多？"] = "Потому что пациентов слишком много?",
    ["因为这儿有最好的酒，最会聊天的姑娘们，还有……<P_Heart>（眨眨眼）</>我的舞步。 "] = "Потому что здесь лучшая выпивка, самые общительные девушки и... <P_Heart>(подмигивает)</> мои танцевальные па.",
    ["图书馆一定有相关书籍，我们去看看吧！"] = "В библиотеке наверняка есть соответствующие книги, пойдем посмотрим!",
    ["圣赛琳娜教堂是黑夜女神教会在廷根市的总部。"] = "Собор Святой Селены является штаб-квартирой церкви Богини Вечной Ночи в Тингене.",
    ["在一众闪烁着昂贵色泽的宝石衬托下，面前的戒指堪称特别——"] = "На фоне сияющих дорогим блеском драгоценных камней кольцо передо мной совершенно особенное.",
    ["在下街，我们不是可怜虫，我们是战士——为了生存而战的战士。"] = "На Лоуэр-стрит мы не несчастные, мы воины, воины, борющиеся за выживание.",
    ["在世的人往往需要一些东西去纪念逝去的人。"] = "Живым всегда нужны какие-то вещи, чтобы хранить память об ушедших.",
    ["在你证明自己足够时尚之前，我们并不想为你介绍廷根时尚协会。"] = "Мы не хотим знакомить вас с Ассоциацией моды Тинген, пока вы не докажете, что вы достаточно модны.",
    ["在值夜者之外，也需要一些自己的“消息来源”和“熟人圈子”，这些都能帮助你在非凡之路上提升自己。"] = "Помимо Ночных Ястребов полезно обзавестись собственными «источниками сведений» и «кругом знакомств» — всё это поможет совершенствоваться на пути Потустороннего.",
    ["在帮你们做纺织品时，我也学会了怎么做帽子，今年行政大臣的礼物就是我做的帽子呢！"] = "Помогая вам делать текстиль, я также научился делать шляпы. Подарок этого года от министра администрации — шляпа, которую я сделал!",
    ["在廷根的话，我很喜欢斯林面包房的柠檬蛋糕，也喜欢命运咖啡馆的“奶味可可甜茶”，这是店主丽贝卡小姐的独创。"] = "Если говорить о Тингене, мне очень нравится лимонный пирог из пекарни Слина, а ещё «Сладкий молочный чай с какао» из кафе «Судьба» — фирменный рецепт владелицы, мисс Ребекки.",
    ["在廷根，真是每天都能找到不少乐子。"] = "В Тингене действительно можно найти массу развлечений каждый день.",
    ["在我们因蒂斯，浪漫是最受欢迎的。您的好奇让我意识到，鲁恩人也能欣赏它的魅力！"] = "В нашем Интисе романтика самая популярная. Ваше любопытство заставляет меня понять, что жители Лоена тоже могут оценить его очарование!",
    ["在月亮弥撒时，我们会为亡者祈祷、为生者祈福，愿女神护佑祂的信徒，愿所有人得到宁静。"] = "Во время лунной мессы мы молимся за умерших и благословляем живых. Пусть Богиня защитит Своих верующих, и пусть все обретут покой.",
    ["在泥泞中醒来，那两个与你共饮的男人早已不见了踪影。"] = "Очнувшись в грязи, двух мужчин, с которыми вы пили, нигде не было.",
    ["在等我的朋友，真期待看见她！"] = "Я жду своего друга. Я так жду ее встречи!",
    ["在等我那位姑娘。前前后后送了二十条项链，今天这条送出去，她总该点头陪我吃顿饭了吧？ "] = "Жду эту свою даму. Всего я подарил ей двадцать ожерелий; сегодня она должна, наконец, кивнуть и согласиться пообедать со мной, верно?",
    ["在纪念品商店卖至少2苏勒，平时我卖1苏勒6便士，您现在要，我算您1苏勒怎么样。"] = "В сувенирном магазине они продаются минимум за 2 суле. Обычно я продаю их за 1 суле и 6 пенсов. Если хочешь сейчас, как насчет 1 суле?",
    ["在这儿干久了，看一眼就知道谁是来找乐的，谁是来找事的。"] = "Когда поработаешь здесь подольше, с первого взгляда понимаешь, кто пришел развлечься, а кто — нажить неприятностей.",
    ["在这片战场上，你的每一场胜利都将化为军功，积累军衔。军衔越高，离征服世界的目标就越接近。"] = "On this battlefield, every Victory you achieve will be converted into military merit, accumulating military rank. The higher your rank, the closer you are to the goal of Conquest of the world.",
    ["在这里你们可以叫我斯莉可，其实，我的笔名热可可是我家小狗的名字。"] = "Здесь ты можешь называть меня Глупым. На самом деле мой псевдоним Hot Cocoa — это имя моего щенка.",
    ["在这里完成的作品可以装裱起来带回家，送给你的家人朋友，心动的话就快走进来拿起画笔吧。"] = "Выполненные здесь работы можно оформить в рамку и забрать домой, чтобы подарить родным и друзьям. Если вам интересно, поспешите взять в руки кисть.",
    ["在野外待久了，我先找个舒服的地方坐一坐。"] = "Я слишком долго был в дикой природе, я просто ищу удобное место, чтобы немного посидеть.",
    ["在非凡世界，真正安全的决策，永远是经过多次验证、谨慎判断后，自己选择踏上的那条路。"] = "В необычном мире по-настоящему безопасным решением всегда является путь, который вы выбираете после многократных проверок и тщательного суждения.",
    ["在非凡世界，诵念陌生的尊名很有可能召唤出未知的危险。除了正神的尊名，以及塔罗会同伴的尊名，你不可诵念其他尊名。"] = "В Необыкновенном Мире повторение неизвестного почетного имени с большой вероятностью может вызвать неизвестные опасности. За исключением почетных имен истинных богов и спутников Клуба Таро, вы не должны повторять другие почетные имена.",
    ["地理位置，便宜的家具费用，当然这儿还有夏洛特……"] = "Расположение, дешевая стоимость мебели и, конечно же, здесь Шарлотта...",
    ["坚持一下，等我新的稿子出来，一定能爆火！"] = "Просто держись там. Как только мой новый проект выйдет, он обязательно станет хитом!",
    ["坚持存活120秒，打开前往下一层的大门"] = "Продержитесь в живых 120 секунд, чтобы открыть врата на следующий уровень",
    ["埃尔文一定会喜欢。"] = "Элвину это определенно понравится.",
    ["基特那个白痴！我早就说过不要和裘德混在一起，那家伙一看就是弗兰奇派来的打手！"] = "Этот идиот Кит! Я давно сказал ему не тусоваться с Джудом. Этот парень похож на бандита, подосланного Фрэнком!",
    ["堵住工厂大门，直到工厂主把钱塞到我们手上为止！谁愿意跟我们一起？"] = "Заблокируйте ворота фабрики, пока владелец фабрики не передаст нам деньги! Кто готов присоединиться к нам?",
    ["塔罗会居然有吸……有血族？！但“月亮”先生既然是塔罗会的成员，应该不会做出出格的行为吧？"] = "В Клубе Таро действительно есть вам... Сангвиник?! Но поскольку мистер Мун является членом Клуба Таро, ему не следует делать ничего сверхъестественного, верно?",
    ["外面虽然也有好看的景色，但是这里的风光，可是独一无二的。"] = "Хотя снаружи есть красивые достопримечательности, пейзажи здесь поистине уникальны.",
    ["多少？！这么贵？是鲁恩货币吗？"] = "Сколько?! Так дорого? Это в валюте Лоэн?",
    ["多说一句话的活计，你都不干？反正没损失！"] = "Вы даже не будете выполнять работу, требующую произнести одно лишнее предложение? В любом случае потерь нет!",
    ["夜班，12小时，一天6便士。"] = "Ночная смена, 12 часов, 6 копеек в день.",
    ["够了安杰拉，别再说了。那种经历我这辈子都不想再有了！"] = "Хватит, Анжела, замолчи! Я больше никогда в жизни не хочу пережить подобное!",
    ["大佬你大腿好好看"] = "Большая шишка, твои ноги так хорошо выглядят.",
    ["大概等你有自己房子的时候吧。"] = "Наверное, когда у тебя будет свой дом.",
    ["大部分狼人是危险的，至于吸血鬼，他们不喜欢被称作吸血鬼。"] = "Большинство оборотней опасны, а что касается вампиров, то им не нравится, когда их называют вампирами.",
    ["太厉害了，简直是手枪大师！"] = "Потрясающе, ты практически мастер пистолета!",
    ["太好了！"] = "Замечательно!",
    ["太好了！谢谢你！我家很好找，就是离湖边最近的那间小屋！"] = "Большой! Спасибо! Мой дом легко найти; это маленький коттедж, ближайший к берегу озера!",
    ["太好了，咖啡师先生那边有很多糕点，可以随意挑选。顺便请代我告诉咖啡师先生，红茶需要续杯。"] = "Замечательно! У господина Бариста там полно выпечки; не стесняйтесь делать свой выбор. Кстати, скажите, пожалуйста, господину Бариста, что черный чай нужно пополнить.",
    ["太恶毒了！居然要把孩子送去学校！"] = "Как злобно! Реально отправить детей в школу!",
    ["太棒了！我就知道！能得到它们的认可，比赢得任何烹饪大赛都让我高兴。这才是真正的“金牌认证”！"] = "Замечательно! Я знал это! Получение их признания делает меня более счастливым, чем победа в любом кулинарном конкурсе. Это настоящая «Золотая медаль»!",
    ["夫人曾说，抓住机遇的都搬去了更富有的地方，北区，或者贝克兰德，而没有抓住机遇的……抱歉，这个夫人没有说过。"] = "Госпожа говорила, что те, кто ухватился за возможность, переехали в более богатые края — в Северный район или в Бэкланд. А те, кто упустил свой шанс... Прошу прощения, об этом госпожа ничего не говорила.",
    ["夫人正是因此投资了许多像爱丽丝小姐一样的珠宝匠。"] = "Именно поэтому мадам поддержала стольких ювелиров, как мисс Элис.",
    ["夫人过奖了。能为您写几个字，是我的荣幸。 "] = "Вы мне льстите, мадам. Для меня большая честь написать вам несколько слов.",
    ["夫人，你还是把酬金降低一些吧，最近有不少人随便抓一只长得像毛球的流浪猫就想来领赏。"] = "Мэм, вам следует снизить награду. В последнее время многие люди хватают бездомных кошек, похожих на меховой комок, и пытаются получить награду.",
    ["夫人，我没问题的！"] = "Мэм, у меня нет с этим проблем!",
    ["夫人，需要扫烟囱吗？只要两苏勒。"] = "Мэм, вам нужно почистить дымоход? Всего два суле.",
    ["失踪的还有童工！"] = "Пропали также работающие дети!",
    ["夺回领地？"] = "Вернуть свою территорию?",
    ["奥斯汀先生是一位勇敢的英雄，他曾在前线守护鲁恩王国。回到廷根后，他依旧能给赶路的人们一个温暖可爱的住所。"] = "Мистер Остин — отважный герой, который когда-то охранял Королевство Лоэн на передовой. Вернувшись в Тинген, он все еще может стать теплым и прекрасным местом для путешественников.",
    ["奥黛丽小姐，为什么苏茜女士会说话呢？它……是神奇生物吗？"] = "Мисс Одри, а почему мисс Сьюзи умеет разговаривать? Она... необыкновенное существо?",
    ["奥黛丽小姐，听说您是鲁恩慈善助学基金会的创始人？您是如何走上慈善事业的呢？"] = "Мисс Одри, я слышал, вы являетесь основателем Благотворительного стипендиального фонда Лоен? Как вы встали на путь благотворительности?",
    ["奥黛丽小姐，听说非凡世界里存在狼人、吸血鬼？"] = "Мисс Одри, я слышал, что в Необыкновенном мире существуют оборотни и вампиры?",
    ["奥黛丽小姐，您在现实世界的身份是一位心理医生？"] = "Мисс Одри, в реальном мире вы психолог?",
    ["奥黛丽小姐，您最喜欢吃什么，有推荐吗？"] = "Мисс Одри, что вы любите есть больше всего? Есть ли у вас какие-либо рекомендации?",
    ["奥黛丽小姐，您有尊名吗？如果我想向您祈求帮助，应该诵念什么呢？"] = "Мисс Одри, у вас есть титул? Если я хочу помолиться вам о помощи, что мне следует повторять?",
    ["奥黛丽小姐，您能讲讲扇语的具体含义吗？我在报纸上读到，很感兴趣。"] = "Мисс Одри, не могли бы вы рассказать о значении языка веера? Я прочла о нем в газете, и мне стало ужасно любопытно.",
    ["奥黛丽小姐，我知道您是贵族，您对鲁恩的历史一定很了解吧？"] = "Мисс Одри, я знаю, что вы дворянин, вы, должно быть, много знаете об истории Лоэна, верно?",
    ["奥黛丽小姐，谢谢你之前赠予我的钱。"] = "Мисс Одри, спасибо за деньги, которые вы мне дали раньше.",
    ["奥黛丽小姐，除了家族财产，你还自己投资吗？"] = "Мисс Одри, помимо семейной собственности, вы инвестируете и себя?",
    ["女主演蒙巴顿小姐的崇拜者或许没钱买三等票，但能偷一张孤零零的海报？他们的敏捷能让市政厅卫兵都自愧不如！"] = "У поклонников главной актрисы мисс Маунтбеттен может не хватить денег на билет третьего класса, а украсть одинокий плакат? Из-за их ловкости стражники мэрии почувствуют себя неполноценными!",
    ["女士……"] = "Леди...",
    ["女士们……"] = "Дамы...",
    ["女士们，在店铺大门口进行激烈讨论，可能会对店家造成困扰。"] = "Дамы, такая бурная дискуссия прямо у входа в магазин может доставить неприятности владельцу.",
    ["女士，你的丈夫总是很忙碌吗？"] = "_\n\nМадам, ваш муж всегда занят?",
    ["女士，你看起来很困扰。"] = "Леди, вы выглядите обеспокоенной.",
    ["女士，您每天都会来喂鸽子吗？"] = "Мадам, вы каждый день приходите кормить голубей?",
    ["女士，您的话似乎有另外的意思。"] = "Мадам, кажется, ваши слова имеют другой смысл.",
    ["女士，这台机器是您的吗？"] = "Мэм, эта машина ваша?",
    ["女士，这块墓地是拉斐尔墓园里数一数二的好位置，面朝南，靠近圣赛琳娜教堂，还能听到唱诗班的歌声——当然，如果您的丈夫不介意偶尔被吵醒。"] = "Мэм, это место для захоронения — одно из лучших мест на кладбище Рафаэля, обращенное на юг, недалеко от собора Святой Селены, и вы можете услышать пение хора — конечно, если ваш муж не против, чтобы его время от времени будили.",
    ["女神可不管修阳台的事……"] = "Богиню не заботит ремонт балкона...",
    ["女神啊！听上去感觉比食堂强一百倍！ 咱们约个时间去一次吧！"] = "О, Богиня! Это звучит в сто раз лучше, чем столовая! Давайте назначим время, чтобы сходить туда один раз!",
    ["女神啊，总有一天我要住到北区干净的地方去，再雇十个……不，至少二十个水仙花街出身的佣人从早到晚清理巡逻，绝对不允许任何一个牡蛎入侵我的生活！"] = "Богиня, клянусь, настанет день, когда я перееду в чистый Северный район и найму десятерых... нет, как минимум двадцатерых слуг с улицы Нарциссов, чтобы они с утра до ночи убирали и патрулировали дом, и ни одной устрице не позволю вторгнуться в мою жизнь!",
    ["女神啊，我到底为什么要过这种恶臭的生活！"] = "Богиня, с какой стати я должна жить такой грязной жизнью!",
    ["女神啊，用这副模样？您真会开玩笑。"] = "Богиня в таком виде? Ты действительно умеешь шутить.",
    ["女神在上！玛莎！贝蒂！你们今早听见酒馆里人念报没？"] = "Клянусь Богиней! Марта! Бетти! Вы слышали, как люди читают газету сегодня утром в таверне?",
    ["女神庇佑，我在恶龙酒吧的斗邪恶比赛里赢了一张船票！很快我就要登船了。"] = "Защитница Богини, я выиграла билет на лодку на соревновании по борьбе со злом в баре ««Злой Дракон»»! Я скоро сяду на корабль.",
    ["女神，我祈求您让他受到应有的惩罚！"] = "Богиня, я молюсь, чтобы Ты позволил ему получить заслуженное наказание!",
    ["奶奶，现在坐班的是叔叔……"] = "Бабушка, сейчас дежурит дядя...",
    ["她、她收下了！她说她也注意我很久了！"] = "Она... она приняла его! Сказала, что тоже давно за мной наблюдает!",
    ["她丈夫报警了，警察到现在也没查到下落。（啐了一口）也是一帮没用的！"] = "Ее муж вызвал полицию, но они пока не нашли никаких зацепок. (Сплевывает) Куча бесполезных людей!",
    ["她也是为守护廷根牺牲的，愿她在黑夜的庇佑中获得安眠。"] = "Она также пожертвовала собой, чтобы защитить Тингена. Пусть она найдет сон под защитой Богини Вечной Ночи.",
    ["她从不只是站在台上。她会走进人群，像一阵风掠过你的身侧，而你甚至来不及捕捉她的温度……只余下一道眼神，让你整晚都在怀疑：刚才那一瞥，究竟是不是给你的。"] = "Она никогда просто не стоит на сцене. Она идет в толпу, словно порыв ветра, скользящий мимо, и ты даже не успеваешь ощутить ее тепло... остается лишь взгляд, заставляющий всю ночь гадать: предназначался ли этот мимолетный взор тебе.",
    ["她们不都住在纪念碑广场那边吗？罗伯特那家伙不尴尬吗？"] = "Разве они оба не живут на Мемориальной площади? Разве это не неловко для Роберта?",
    ["她们可以上一秒手挽着手说笑，也可以下一秒就开始互相扯对方的头发！"] = "В одну секунду они могут держаться за руки и смеяться, а в следующую начать тянуть друг друга за волосы!",
    ["她只会做一件事——歪着头看着您，问一句“哥哥，你今天累不累呀”。"] = "Она умеет лишь одно: склонить головку набок, посмотреть на вас и спросить: «Братик, ты сегодня не устал?»",
    ["她哪天不是故意的？上次她从我身边经过，就碰了我一下袖子，我回去三天没舍得洗那件衣服。"] = "Когда она ничего не делает намеренно? В последний раз, когда она прошла мимо меня и коснулась моего рукава, у меня не хватило духу постирать эту рубашку три дня.",
    ["她就在附近上班，她好像在一家……安保公司？对，黑荆棘。"] = "Она работает неподалеку, кажется, в... охранной компании? Да, Чёрный Чертополох.",
    ["她总来买小束的、颜色最亮的花，说要摆在桌子上，“给枯燥的公文也晒晒太阳”。她的话呀，像小鸟一样，又轻快又多，听着都让人高兴。"] = "Она всегда приходит купить маленькие букетики самых ярких цветов, говоря, что хочет поставить их на свой стол, чтобы «позволить скучным официальным документам понежиться на солнышке». Слова ее подобны птичкам, легкими и многочисленными; просто слушать делает человека счастливым.",
    ["她抿着嘴，目光十分警惕，她不敢与你争夺这里的东西，却又舍不得放弃。"] = "Она поджала губы, ее взгляд был очень бдительным. Она не смела конкурировать с тобой за вещи здесь, но и отказаться от них она тоже не могла.",
    ["她是一位性格非常爽朗奔放的女士，也喜欢开玩笑，听说她还有一个可爱的儿子。"] = "Она была очень веселой и свободной духом женщиной, которая к тому же любила пошутить. Я слышал, что у нее был милый сын.",
    ["她最后晋升到了序列5，在一场对叛徒的围猎中牺牲。"] = "В конце концов она перешла к пятой последовательности и пожертвовала собой в охоте на предателя.",
    ["她的成绩很好，很有希望。学派的老师建议她去考贝克兰德技术大学。"] = "У нее очень хорошие оценки, и она подает много надежд. Школьная учительница предложила ей сдать экзамен в Технический университет Баклунда.",
    ["她肯定是受女神的眷顾保佑，才能安稳地工作到退休。"] = "Она должна быть защищена благосклонностью Богини, чтобы иметь возможность стабильно работать до выхода на пенсию.",
    ["好……好吧，这是因为我的家庭出了些变故，我不得已才出来谋生。但是我怕遇到那些富人，那些会去贝克兰德参加晚宴的富人们，也许会认出我……"] = "Н-ну, это потому, что в моей семье произошли некоторые изменения, и мне пришлось уйти, чтобы зарабатывать на жизнь. Но я боюсь встретить тех богатых людей, которые поехали бы в Бэкланд на балы; они могли бы узнать меня...",
    ["好乖巧的松鼠。你是大自然的住户，还是迷途的客人？"] = "Какая добрая белка. Вы житель природы или заблудившийся гость?",
    ["好乖的小猫！"] = "Такой воспитанный котёнок!",
    ["好了，我们该回庄园了。霍华德勋爵一家人会来参加今晚的晚宴，让女仆为你挑选一件美丽的衣服……"] = "Ладно, нам пора возвращаться в поместье. Семья лорда Говарда придёт сегодня на званый ужин, пусть горничная подберёт для тебя красивое платье...",
    ["好像……还是不对？"] = "Кажется... все еще не так?",
    ["好吧这是美化的说辞，实际上是说：“简直笨手笨脚。”所以我开始到艺术学派学习，跳舞肯定是很好的协调训练！"] = "Ну, это украшенная версия. На самом деле они сказали: «Просто неуклюже». Итак, я начал учиться в художественной школе; танцы должны быть отличной тренировкой координации!",
    ["好吧，我尊重你的想法，这个问题就此打住吧。"] = "Ладно, я уважаю ваше мнение, давайте остановим эту тему на этом.",
    ["好吧，祝你安全，小家伙。愿女神庇佑你！"] = "Ладно, береги себя, малышка. Пусть Богиня Вечной Ночи защитит тебя!",
    ["好吧，这次放过你，下次别这样了，偷东西总归是不好的。"] = "Хорошо, на этот раз я тебя отпущу. Не делай этого снова; воровать никогда не бывает хорошо.",
    ["好啊，我该怎么做呢？"] = "Хорошо, и что мне нужно делать?",
    ["好啦，那这次的紧急会议就结束了，我们等你们的好消息，国王、外交大臣。"] = "Что ж, на этом экстренное заседание окончено. Мы ждем от вас добрых вестей, ваше величество, господин министр иностранных дел.",
    ["好嘞！请您稍后，精彩的比赛即将开始！"] = "Хорошо! Пожалуйста, подождите немного, захватывающая гонка вот-вот начнется!",
    ["好坚固的宝箱！看来没法直接撬开了。"] = "Какой прочный сундук с сокровищами! Кажется, его нельзя открыть напрямую.",
    ["好好好，等回家我们用毛巾练习。"] = "Хорошо, хорошо, мы потренируемся с полотенцами, когда вернемся домой.",
    ["好心的{{先生|女士}}，如果你喜欢我的舞蹈，请到前面的肉摊支持我姐姐玛丽珍的生意。"] = "Добрый {{Mr.|Ms.}}, если вам нравится мой танец, пожалуйста, сходите в мясной ларек впереди и поддержите бизнес моей сестры Мэри Джейн.",
    ["好想吃老维尔餐厅的黑胡椒牛排啊……"] = "Я очень хочу съесть стейк с черным перцем в ресторане Олд Уилла...",
    ["好想看小魔女的表演！"] = "Очень хочу увидеть выступление Маленькой Ведьмы!",
    ["好猫！"] = "Хороший кот!",
    ["好的，先生，我下午给您答复——或许得找通灵师亲自问问我丈夫的想法。"] = "Хорошо, сэр, я дам вам ответ во второй половине дня — возможно, мне нужно найти духовного медиума, чтобы лично спросить мысли моего мужа.",
    ["好的，吃完能让我在这休息一会儿吗？"] = "Хорошо, после еды, можешь позволить мне немного отдохнуть здесь?",
    ["好的，您坐稳了。"] = "Хорошо, держись крепче.",
    ["好的，我明白了。"] = "Хорошо, я понимаю.",
    ["好的，我记住了，优雅的苏茜女士。"] = "Хорошо, я запомню это, элегантная мисс Сьюзи.",
    ["好的，祝您每天都愉快！"] = "Хорошо, приятного дня!",
    ["好的，请坐稳！"] = "Хорошо, пожалуйста, держитесь крепче!",
    ["好的，非常感谢您！"] = "Хорошо, премного благодарен!",
    ["好看，好看！比我的领结都红呢！"] = "Это красиво, это красиво! Он даже краснее моего галстука-бабочки!",
    ["好铁经得起敲打，多去工厂看看吧小子！"] = "Хорошее железо выдержит удар молотком, ходи почаще на завод, пацан!",
    ["好饿……今天也只能吃黑面包吗？想吃肉啊。"] = "Такой голодный... можно мне сегодня есть только черный хлеб? Я хочу есть мясо.",
    ["好，现在这些垃圾都是我的了！"] = "Ладно, теперь весь этот мусор мой!",
    ["如何辨别舞会上的非凡者？"] = "Как распознать Потустороннего на балу?",
    ["如你所见，我前面有一些蜡烛，我现在就要用意念点燃它们！"] = "Как видите, передо мной стоят свечи, и я собираюсь зажечь их силой мысли!",
    ["如你所见，我正在为艺术学派创作我的新舞蹈。"] = "Как видите, я создаю свой новый танец для Школы искусств.",
    ["如您所见，结局并不圆满……所以他委托我用姑娘的遗物和他准备的婚戒做成了一枚全新的戒指，永远纪念他早逝的爱人。"] = "Как видите, финал не был идеальным... поэтому он доверил мне использовать сувениры девушки и приготовленное им обручальное кольцо, чтобы сделать совершенно новое кольцо, чтобы навсегда почтить память своей покойной возлюбленной.",
    ["如果一串项链能让她好受些，我愿意奢侈这一次。"] = "Если ожерелье поможет ей почувствовать себя лучше, я готов на этот раз проявить экстравагантность.",
    ["如果不想突然被酒瓶砸到头的话，劝你离这里远一点。"] = "Если не хотите внезапно получить удар по голове бутылкой вина, советую держаться отсюда подальше.",
    ["如果不是因为我想攒钱给珍妮弗一个婚礼，我也不会租这里的。"] = "Если бы не тот факт, что я хочу накопить денег на свадьбу Дженнифер, я бы не снимал здесь квартиру.",
    ["如果他能停止以那副高高在上的好市民姿态对我的成员说教，就更好了。"] = "Было бы еще лучше, если бы он прекратил читать моим членам эту высокомерную позицию «доброго гражданина».",
    ["如果你一定要坐在这里，请证明给我们看吧。"] = "Если вам необходимо сидеть здесь, пожалуйста, докажите нам это.",
    ["如果你去了贝克兰德，选择会更多。拉波瑞餐厅的水果焦糖布丁、奶油酥饼和胡萝卜蛋糕都很不错。"] = "Если вы поедете в Бэкланд, выбор будет больше. Фруктово-карамельный пудинг, песочное печенье с маслом и морковный пирог в ресторане Laporte очень хороши.",
    ["如果你去南大陆，记得两件事：别喝会自己冒泡的泉水，更别和戴彩纹面具的人玩骰子——他们用的骰子，可能是浸过百年执念的旧骨。 "] = "Если вы отправитесь на Южный континент, помните две вещи: не пейте родниковую воду, которая пузырится сама по себе, и определенно не играйте в кости с людьми в ярких масках — игральные кости, которые они используют, могут оказаться старыми костями, пропитанными столетием одержимости.",
    ["如果你是迪西来的，一口下去包你尝到家的味道！"] = "Если вы из Дикси, откусите один кусочек, и вы почувствуете вкус дома!",
    ["如果你要去，请帮我带一枝花给莉奥娜小姐可以吗？谢谢她上周的款待。"] = "Если ты пойдешь, не мог бы ты передать от меня цветок мисс Леоне? Спасибо ей за гостеприимство на прошлой неделе.",
    ["如果你还有时间去研究那朵该死的云，那就去把我们的水手们从酒吧里拖回来！"] = "Если у тебя еще есть время изучить это чертово облако, то иди и тащи наших матросов из бара!",
    ["如果喜欢，我可以送你一些。"] = "Если вам нравится, я могу подарить вам немного.",
    ["如果实在没有想法，不如参考一下其他人的建议？"] = "Если у вас действительно нет идей, почему бы не обратиться к предложениям других людей?",
    ["如果您只是想临时换点酒钱，可以拿走那边的猪膀胱，下街那边的外来酒贩很乐意收散货。"] = "Если вы просто хотите быстро заработать карманные деньги на выпивку, вы можете взять с собой этот свиной пузырь; иностранные торговцы спиртными напитками на Лоуэр-стрит с удовольствием покупают оптовые товары.",
    ["如果您周末再来一趟的话，就不会这么想了。"] = "Если бы вы вернулись на выходные, вы бы так не подумали.",
    ["如果您在漫游时对某个地点感到困惑，不妨随时回想我在地图上为您指出的方位，清晰的记忆是最好的路标。 "] = "Если вы запутались в местоположении во время роуминга, вы можете в любой момент вспомнить направления, которые я указал для вас на карте; ясная память – лучший дорожный знак.",
    ["如果您想补充体力，新鲜的肉鱼，外皮煎得金黄酥脆，内里鲜嫩多汁，咬一口仿佛能尝到铁十字街海风的咸香，绝对是您的不二之选！"] = "Если вы хотите пополнить свою энергию, то свежее мясо и рыба, поджаренные до золотистой и хрустящей корочки, нежные и сочные внутри, и вы можете ощутить соленый аромат морского бриза с Айрон-Кросс-стрит, когда откусите, определенно ваш лучший выбор!",
    ["如果您想要比较特别的款式，我也很乐意替您设计。"] = "Если вы хотите более особенный фасон, я с радостью разработаю его для вас.",
    ["如果您愿意，请多与他说说话吧，即使他不能用声音回应您。"] = "Если вы не против, поговорите с ним побольше, даже если он не может ответить вам голосом.",
    ["如果您手头拮据，也可以像某些常客一样，用美味的自制烤面包或漂亮的珍藏版书籍换取一晚的住宿。"] = "Если у вас мало денег, вы также можете, как и некоторые постоянные клиенты, обменять ночлег на вкусный домашний хлеб или красивые книги коллекционного издания.",
    ["如果您是一位年轻的学生或政府职员，每个周末还可以到这里借用安静的房间作为自习室。"] = "Если вы молодой студент или государственный служащий, вы также можете приходить сюда каждые выходные и арендовать тихую комнату для учебы.",
    ["如果您真想招人，还是拿出点诚意吧。"] = "Если вы действительно хотите нанять кого-то, проявите искренность.",
    ["如果您认为合适的话，或许我可以接手。您提一个合适的价格吧。"] = "Если вы считаете, что это уместно, возможно, я мог бы взять это на себя. Назовите, пожалуйста, справедливую цену.",
    ["如果我和他们一样，那就是落入了圈套！"] = "Если бы я был таким, как они, я бы попал в ловушку!",
    ["如果我被别的客人缠住了，哥哥可要来把我救走哦！"] = "Если ко мне будут приставать другие гости, ты должен прийти и спасти меня, брат!",
    ["如果是“月亮”先生的话，他听到你说吸血鬼，可能会很生气，然后告诉你他很生气，应该不会再做什么了。"] = "Если это мистер Мун, он может очень разозлиться, услышав, как вы говорите «вампир», а затем сказать вам, что он очень зол, но, вероятно, больше ничего не сделает.",
    ["如果没有想法，不如问问其他人的看法？"] = "Если нет идей, почему бы не спросить мнения остальных?",
    ["如果盖错了呢？"] = "А если поставить не ту печать?",
    ["如果说，你很珍重的，挚爱的亲人离世了……"] = "Если, скажем, ушел из жизни очень дорогой, любимый член вашей семьи...",
    ["如果送给朋友的话，我推荐紫罗兰或者雏菊。"] = "Если это подарок другу, рекомендую фиалки или ромашки.",
    ["如果需要画肖像画，可以来找我。不过我很快就要出发了，真是令人期待。"] = "Если вам понадобится портрет, обращайтесь ко мне. Правда, я скоро уезжаю... с нетерпением жду этого.",
    ["妈妈已经学会餐巾的用法了哦。"] = "Мама уже научилась пользоваться салфеткой.",
    ["妈妈擅长做大人们穿的体面衣服，比如绅士们的套装，很适合穿着去市政厅或者大学城工作。"] = "Мама хорошо умеет шить приличную одежду для взрослых, например костюмы для джентльменов, которые очень подходят для работы в мэрии или в Университетском округе.",
    ["妈妈说要和警察叔叔谈谈，马上就出来。可是都好久了……"] = "Мама сказала, что ей нужно поговорить с полицейским и что она скоро выйдет. Но прошло много времени...",
    ["妈妈，就让我去领一份……不，半份食物！"] = "Мама, дай мне принести одну... нет, половину порции еды!",
    ["姐姐今晚这身，比上次那套还要好看。"] = "Сегодня вечером ты выглядишь еще лучше, чем в прошлый раз.",
    ["婚姻真是爱情的坟墓，曾经时时刻刻在一起的人进入婚姻也变得聚少离多……"] = "Брак — поистине могила для любви. Те, кто прежде не расставался ни на миг, после свадьбы почти не видят друг друга...",
    ["学习的时候，没有些声音我不习惯。"] = "Я не привык учиться без шума.",
    ["学生布置仪式的东南角落，打算放置什么物品？"] = "Какой предмет вы собираетесь разместить в юго-восточном углу ритуальной установки ученика?",
    ["学生布置仪式的北边角落，打算放置什么物品？"] = "Какой предмет вы собираетесь поместить в северный угол ритуала студента?",
    ["学生布置仪式的西边角落，打算放置什么物品？"] = "Какой предмет вы собираетесь разместить в западном углу ритуальной установки ученика?",
    ["孩子们，声音大一点、再大一点，让女神听到你们的歌声……"] = "Дети, громче, немного громче, пусть Богиня услышит ваше пение...",
    ["孩子们，记住，现在我们虽然吃不起这样的饭菜，但总有一天会坐在那儿。"] = "Дети, помните, хотя сейчас мы не можем позволить себе такую ​​еду, однажды мы будем сидеть там.",
    ["它——弗拉德的蒙塔古四世，国王的第四子，最年幼的雄狮……"] = "Он — Монтегю IV Влада, четвертый сын короля, младший лев…",
    ["它一直不睡觉，所以叫睡不着。"] = "Он никогда не спит, поэтому его называют «Не могу спать».",
    ["它们一定陪伴了你很久……振作一点！"] = "Должно быть, они долго составляли вам компанию... не унывайте!",
    ["它们同时散发着晾晒过的香气、酒液的味道、眼泪和口水交织的生活气息。"] = "Они одновременно источают аромат высушенного на солнце белья, запах алкоголя и атмосферу жизни, переплетенную слезами и слюной.",
    ["它们好像要打起来了……或许能学到一些格斗技巧。"] = "Кажется, они собираются драться... возможно, я смогу научиться некоторым боевым приемам.",
    ["它们更多地运用了时兴复杂的工艺，造型也更加尖锐别致，齿轮、几何、星芒会让您显得高贵又潮流，价格也很友好。"] = "В них больше используется модное и сложное мастерство, а формы становятся более острыми и уникальными. Шестеренки, геометрия и звездообразования позволят вам выглядеть благородно и модно, а цена еще и очень дружелюбная.",
    ["它们的叫声很有特色。"] = "Их воркование очень уникально.",
    ["它们被薄荷、玫瑰和柠檬簇拥着，精心包装成一束又一束——正好适合抱着走去黑夜教堂的大小。"] = "Они окружены мятой, розами и лимонами и тщательно завернуты в букеты — как раз такого размера, чтобы их можно было отнести в церковь «Ночных ястребов».",
    ["它们都是古典华丽的风格，黄金、珍珠与钻石组成花束、蝴蝶与代表永恒的衔尾蛇，是非常有存在感的体面首饰。"] = "Все они выполнены в классическом богато украшенном стиле, с золотом, жемчугом и бриллиантами, образующими букеты, бабочками и Уроборосами, символизирующими вечность. Это очень приличные украшения с сильным ощущением присутствия.",
    ["它喜欢甜牛奶，也许一点甜食可以帮助你找到它……"] = "Ему нравится сладкое молоко; возможно, небольшое угощение поможет вам найти его...",
    ["它好像对名字不太满意啊。"] = "Похоже, имя ему не очень понравилось.",
    ["它就喜欢这些东西！给了之后，它半夜都不会大叫了。要是实在凑不出来，丢点石头和破木板也行。"] = "Он просто обожает эти вещи! Однажды подаренный, он не будет кричать посреди ночи. Если вы действительно не можете ничего собрать, бросьте туда несколько камней и сломанных деревянных досок.",
    ["它每次只会用力撞一扇门，每次会撞击不一样的门，上次，是离植物最近的那扇门……"] = "Каждый раз он с силой врезается только в одну дверь, и каждый раз врезается в другую дверь. В прошлый раз это было самое близкое к растениям...",
    ["它由值夜者正式成员轮换看守，里面至少还有两位教会内部的“看守者”，以及数不清的陷阱。"] = "Ее охраняют сменяющиеся официальные члены «Ночных ястребов», внутри церкви есть как минимум два «Хранителя», а также бесчисленное множество ловушек.",
    ["它竟然有这种背景？"] = "У него действительно такое прошлое?",
    ["它跑那么慢，就叫它跑不快了！"] = "Поскольку он работает так медленно, давайте назовем его «Не могу бежать быстро»!",
    ["它里面分为几个区域，保存着一定序列的魔药配方和各种神奇材料，临时关押着异端、异种、邪教徒和隐秘组织成员……"] = "Он разделен на несколько зон, в которых хранятся формулы зелий определенных Последовательностей и различные магические материалы, а также временно содержатся еретики, ксеноморфы, культисты и члены секретных организаций...",
    ["官方非凡者的身份虽然好用，但有些门路和消息，只有在这种地方才能获取。"] = "Хотя личность официального Потустороннего полезна, некоторые каналы и новости можно получить только в таких местах.",
    ["定、定制衣帽请、请找我妈……母亲，或、或者妹妹。"] = "F-по поводу шляп и одежды на заказ, пожалуйста, найдите мою маму... или мою младшую сестру.",
    ["实在想掺和的话……我看您这么有兴趣，您和那些警察有交情？去找他们吧，可别拉我下水。"] = "Если ты действительно хочешь вмешаться... Я вижу, ты так заинтересован, у тебя есть связи с этой полицией? Найди их, но не втягивай меня в это.",
    ["实际上，只有真神才能使用三段式尊名。我和塔罗会其他同伴的尊名，是借助了“愚者”先生的真神位格。"] = "Фактически, только Истинный Бог может использовать почетное имя, состоящее из трех частей. Мои почетные имена и имена других членов Клуба Таро зависят от статуса Истинного Бога Мистераа.",
    ["实际上，我们获得的好处很多——安静、安全的环境、向往市政厅工作的氛围……"] = "На самом деле мы получили очень многое — спокойную, безопасную обстановку, атмосферу, подобную работе в мэрии...",
    ["宣传，都是宣传，{{先生|女士}}，懂吗？只有这样才会吸引那些没怎么见过世面的公爵和小姐们过来买酒喝。"] = "Реклама, это всего лишь реклама, {{ Mr. | Ms. } }, понимаешь? Только тогда это привлечет тех герцогов и дам, которые мало повидали мир, прийти и купить вино.",
    ["家中破产，丈夫离世，我的儿子也遭不住打击选择了自杀……"] = "Моя семья обанкротилась, муж умер, а сын не выдержал удара и решил покончить жизнь самоубийством...",
    ["家属想进废墟搜寻遗体都得签免责书！"] = "Семьи должны подписать отказ только для того, чтобы войти в руины и найти тела!",
    ["家里人第一次来大城市，兴奋和好奇是难免的，估计他们自己玩去了。"] = "Они впервые в большом городе, поэтому волнение и любопытство неизбежны. Я думаю, они пошли играть сами по себе.",
    ["对不起！这位客人……我不是有意的！"] = "Мне жаль! Этот гость... Я не хотел!",
    ["对了，别忘了找奥斯汀先生签一个消费凭证——用这张凭证可以到转角的餐馆享受八折优惠！"] = "Кстати, не забудьте попросить мистера Остина подписать ваучер на потребление — вы можете использовать этот ваучер, чтобы получить скидку 20% d в ресторане за углом!",
    ["对了，晚上想去买甜冰茶，我要问一下今天的会不会好喝！茶叶占卜最合适！最后是我的狗会不会把我的点心给偷吃掉！气死我了，我的柠檬布丁啊——"] = "Кстати, я хочу сегодня вечером купить сладкий чай со льдом, хочу спросить, будет ли сегодняшний вкусным! Гадание на чайном листе самое подходящее! Наконец, украдет ли моя собака мои закуски! Это сводит меня с ума, мой лимонный пудинг...",
    ["对了，能麻烦您去问问他，今年的葡萄酒是否要送去一份——我记得他很爱喝。"] = "Кстати, не могли бы вы спросить у него, нужно ли прислать бутылочку вина этого года? Насколько я помню, он его очень любит.",
    ["对，“不要紧张，我们是在守护廷根”。"] = "Да, «Не нервничай, мы охраняем Тингена».",
    ["对，会陪聊、会哄人、长得还好看的。你点一个，让他叫你两声“姐姐”，保你心情好一礼拜。"] = "Да-да: и побеседует, и утешит, да еще и красавчик. Выбери одного, пусть назовет тебя разок-другой «сестрицей» — отличное настроение на целую неделю гарантировано!",
    ["对，就是你！"] = "Да, ты!",
    ["对，我最爱你了。"] = "Да, я люблю тебя больше всего.",
    ["封印解除了！那就来一起进入音乐的世界吧！"] = "Печать сломана! Тогда давайте войдем в мир музыки вместе!",
    ["尊贵的小姐，欢迎您的光临。请容我为您介绍这款售价三百金镑的宝石项链，您瞧瞧，这枚主石的火彩——"] = "Уважаемая мисс, добро пожаловать. Пожалуйста, позвольте мне представить вам это ожерелье из драгоценных камней стоимостью триста фунтов золота. Смотри, огонь этого главного камня —",
    ["小人……哈哈，好多小人……"] = "Маленькие люди... хаха, так много маленьких людей...",
    ["小可怜……"] = "Бедняжка...",
    ["小姐，能听见我说话吗？您看起来状态很差。"] = "Мисс, вы меня слышите? Вы выглядите очень плохо.",
    ["小家伙，你竟然知道这个？"] = "Малышка, ты правда это знаешь?",
    ["小心点，献祭仪式还没做完呢！"] = "Будьте осторожны, Ритуал Жертвоприношения еще не закончен!",
    ["小心观众……"] = "Берегитесь зрителей...",
    ["小昂格？"] = "Маленький Унгер?",
    ["小朋友，你在等妈妈？"] = "Малыш, ты ждешь свою маму?",
    ["小狗不语，只是一味地睡觉。"] = "Маленькая собачка ничего не говорит, просто продолжает спать.",
    ["小狗发出了一串不太礼貌的汪汪叫。"] = "Маленькая собачка издала серию довольно невежливых лаев.",
    ["小猫只是想让您给点东西吃，她看上去太瘦了。"] = "Котенок просто хочет, чтобы вы дали ему что-нибудь поесть, он выглядит слишком худым.",
    ["小罗伯特，今天还是你一个人帮爸爸看店呢？"] = "Маленький Роберт, ты сегодня снова помогаешь отцу одному присматривать за магазином?",
    ["小魔女，猫咪一般性感迷人！"] = "Маленькая Ведьма, сексуальная и очаровательная, как котенок!",
    ["少做梦了！金子铺的街道？那还不把人硌死！不过……要是真能去贝克兰德，我也想去看看。"] = "Хватит мечтать! Улицы, вымощенные золотом? Это повредит ваши ноги! Но... если бы я действительно мог поехать в Бэкланд, я бы тоже хотел его увидеть.",
    ["少打听，生意而已。你要是没有活老鼠，就别挡道。"] = "Поменьше расспрашивай, это просто бизнес. Если у тебя нет живых крыс — отойди с дороги.",
    ["少爷在廷根还有一片喜爱的领地，本想用于建一座小小的城堡。只是可惜一直没能动工。"] = "У молодого господина в Тингене остался любимый участок, где он хотел построить небольшой замок. Жаль только, строительство так и не началось.",
    ["少给我来这套，我当助教六年了，这种借口听得多了。"] = "Не надо мне этого, я шесть лет работаю ассистентом преподавателя, много раз слышала это оправдание.",
    ["尝……想了，来。"] = "Попробуй... соскучилась, держи.",
    ["尤其是我可爱的小昂格，一听见猫叫声就往门外跑。"] = "Особенно мой милый маленький Энг, он выбегает за дверь, как только слышит кошачье мяуканье.",
    ["尤瑟纳尔是个很要强的新人。"] = "Юснер – очень конкурентоспособный новичок.",
    ["就……仅此而已？"] = "И... только и всего?",
    ["就……只是聊天？"] = "Просто... просто болтаем?",
    ["就……这样？"] = "Просто... это?",
    ["就为了一晚上舞会的花儿？女神啊……她们晚上能睡着觉？"] = "Только ради цветов одного ночного бала? Богиня... они могут спать по ночам?",
    ["就像桌上的留言中写的那样，我们为您提供醇香的红茶与柔软的枕头。"] = "Как написано в сообщении на столе, мы обеспечиваем вас ароматным черным чаем и мягкими подушками.",
    ["就像鱼贩的儿子十有八九也会成为鱼贩，可怜的小蒙巴顿也想成为警察。"] = "Точно так же, как сын торговца рыбой в девяти случаях из десяти собирается стать торговцем рыбой, бедный маленький Маунтбеттен тоже хочет стать офицером полиции.",
    ["就我旁边这位吗？每次来，不超过三杯就醉了。"] = "Тот, что рядом со мной? Каждый раз, когда приходят, напиваются под три стакана.",
    ["就是会吱吱叫的动物，要还会吱吱叫的那种！花钱收！"] = "Животные, которые пищат, такие, которые еще могут пищать! Я плачу за них!",
    ["就是这样。我没有钱，当然我也不想还这笔钱。"] = "Вот и все. У меня нет денег, и я, конечно, не хочу платить этот долг.",
    ["就是那场事故之后，有些东西再也回不来了。"] = "Просто после той аварии некоторые вещи уже не могли вернуться.",
    ["就是那边那个冒险家样子的人。被他选到的……"] = "Просто тот человек, похожий на авантюриста. Кого бы он ни выбрал...",
    ["就现在这粮价……够咱这一巷子人，顿顿吃饱……吃上……女神在上，好几年都吃不完！"] = "При нынешних ценах на зерно... его достаточно, чтобы все в нашем переулке наелись досыта, при каждом приеме пищи... ибо... клянусь Богиней, мы бы не доели его годами!",
    ["就算是垃圾也有高下之分，你的慧眼迅速地给它们打着标价。"] = "Даже у мусора есть своя иерархия, и ваш проницательный глаз быстро напишет на него ценники.",
    ["就算这时候，她嘴角也带着笑的，真是个像小太阳一样的人。"] = "Даже в это время на ее губах играла улыбка, она действительно была похожа на маленькое солнышко.",
    ["就这一句。那些在外面奔波了一整天、满心烦躁的人，来这儿坐一晚，听她叫几声“哥哥”，走的时候脸上都是带着笑的。"] = "Просто это. Те, кто бегал весь день, полный раздражения, приходят сюда переночевать, слышат, как она несколько раз называет их «братом», и уходят с улыбками на лицах.",
    ["就这一句，多少人愿意在她身边坐一整晚，把这辈子没对人说过的都倒出来。"] = "Всего одна эта фраза, и так много людей готовы сидеть рядом с ней всю ночь, изливая все, что они никогда в жизни никому не говорили.",
    ["就随便这个画商处置吧，反正我是不会给钱的！"] = "Пусть этот арт-дилер обращается со мной, как хочет, я все равно не плачу!",
    ["局里追查的一个私酒贩子流窜到炼钢厂附近了，我想他应该躲在僻静的角落里，就过来这边搜查，刚好遇到这位先生倒在地上，幸好发现得还不算晚。"] = "Бутлегер, которого выследило бюро, сбежал возле сталелитейного завода. Я думаю, он, должно быть, прячется в тихом уголке, поэтому я пришел сюда, чтобы поискать. Я случайно нашел этого джентльмена лежащим на земле. К счастью, было еще не поздно.",
    ["崭新的警徽，新人啊！就是需要你这种，对新技术感兴趣的好学年轻人！"] = "Новенький полицейский значок — новичок! Нам как раз нужны такие любознательные молодые люди, которые интересуются новыми технологиями!",
    ["工伤和下岗对这儿的普通人来说是家常便饭，可是贝朵兰女士工作了整整四十年，总能避开这些不幸。她甚至从来没有迟到和缺席过！"] = "Травмы на производстве и увольнения здесь – обычное дело для простых людей, но госпожа Бертран проработала целых сорок лет и всегда удавалось избегать подобных напастей. Она даже ни разу не опаздывала и не отсутствовала!",
    ["工厂区环境差，工人们多半染了肺病，工伤率也高得很。 "] = "На территории завода плохая экология, у большинства рабочих заболевания легких, а уровень производственного травматизма также очень высок.",
    ["工厂里的活儿，一站就是十几个小时，没有点提神的东西，谁能扛得住呢？"] = "Работа на фабрике — это больше десяти часов на ногах за раз. Без чего-нибудь бодрящего разве выдержишь?",
    ["差不多也该休息了伙计，哎，这个鲁恩慈口金会是什么啊？"] = "Пришло время отдохнуть, приятель. Эй, что это за благотворительный фонд Лоен?",
    ["已经有好几个教会的人来问我我的天使是谁了……他们为什么那么紧张？"] = "Ко мне уже пришли несколько человек из Церкви спросить, кто мой Ангел... Почему они так нервничают?",
    ["希望今晚能睡个好觉……"] = "Надеюсь, сегодня я смогу хорошо выспаться...",
    ["希望你带来新的旋律，重新凝聚回响之匣。作为回报，我的酬谢亦将通过回响之匣交付于你。"] = "Я надеюсь, что вы вернете новые мелодии, чтобы заново сжать Echo Box. Взамен моя награда также будет доставлена ​​вам через Echo Box.",
    ["希望女神能听到。"] = "Надеюсь, Богиня это услышит.",
    ["希望我那女徒弟也能早日回来。"] = "Надеюсь, моя ученица скоро вернется.",
    ["希望这次约会没有恼人的事让布拉德利突然离开"] = "Надеюсь, во время этого свидания не возникнет никаких досадных обстоятельств, которые заставят Брэдли внезапно уйти.",
    ["希望这次见面她还认得出我……"] = "Надеюсь, она все еще узнает меня, когда мы встретимся...",
    ["希望那个小女孩可以如愿看到演出。"] = "Я надеюсь, что эта маленькая девочка сможет увидеть спектакль так, как ей хотелось.",
    ["希望鸽子被做成菜之后不会变成怨灵吧……"] = "Надеюсь, голубь не превратится в мстительного духа после того, как его приготовят на блюде...",
    ["带有灵性的生物？你出现在这里，难道是非凡特性聚合的性质在发挥作用……"] = "Существо с духовностью? Вы, появившись здесь, может быть, дело в природе конвергенции характеристик Потустороннего...",
    ["带点礼物给你牵挂的人怎么样？"] = "How about bringing some gifts for the people you care about?",
    ["帮助老板收租，是我们的使命！"] = "Помочь боссу собрать арендную плату – наша миссия!",
    ["帮帮我……我无法触碰他……金狼死后，我脑子里的声音终于消失。"] = "Помогите мне... Я не могу его тронуть... После смерти Золотого Волка голоса в моей голове окончательно исчезли.",
    ["常见的风衣外套和毯子，常见到几乎会出现在廷根市的每一个家庭。"] = "Обычные тренчи и одеяла настолько распространены, что встречаются почти в каждом доме Тингена.",
    ["帽子帮……是铁针和丝线他们吗？"] = "Шляпная банда... это железная игла и шелковая нить?",
    ["干什么！没看到我们正在激烈讨论时尚吗？"] = "Что ты делаешь! Разве вы не видите, что у нас идет острая дискуссия о моде?",
    ["干什么？"] = "Зачем?",
    ["干杯……"] = "За здоровье...",
    ["干杯！为我们的相遇！"] = "За нашу встречу! До дна!",
    ["干装修这行，今天在东家，明天在西家。"] = "В сфере ремонта вы сегодня находитесь у одного клиента, а завтра у другого.",
    ["平凡到一定程度，也算一种非凡？"] = "Является ли ординарность в определенной степени также формой экстраординарности?",
    ["平时就喜欢哇哇大叫跑来跑去啃来啃去，你看它这个样子，就知道……"] = "Обычно он любит плакать и бегать, кусая и жуя что-нибудь. По внешнему виду можно сказать, что...",
    ["平时都要看这么多人吗？"] = "Вам обычно приходится наблюдать за таким количеством людей?",
    ["年轻人，以前来过河与海教堂吗？"] = "Молодой человек, вы раньше бывали в церкви Реки и Моря?",
    ["年轻人，或许你听说过南大陆？"] = "Молодой человек, возможно, вы слышали о Южном континенте?",
    ["年轻人，趁着好时光，稳稳当当地走吧。"] = "Молодой человек, воспользуйтесь хорошими моментами и идите уверенно.",
    ["年轻的将士，军功不仅能换来回报，更能铺就你的军衔晋升之路。"] = "Young soldier, military merit can not only bring you rewards but also pave the way for your advancement in rank.",
    ["并不，亲爱的，珠宝需要更便宜。"] = "Вовсе нет, дорогая, украшения должны быть дешевле.",
    ["并且，它每隔一段时间就会试图撞门进来！"] = "И время от времени он пытается протаранить дверь, чтобы войти!",
    ["幸好有您这样比她们更时尚的人存在，不然她们会在门口吵上一整天的。"] = "Хорошо, что есть кто-то более модный, чем они, иначе они бы весь день спорили у дверей.",
    ["幸运的{{先生|女士}}！您步入了一年一度的盛会，动物赛跑的现场！怎么样？押注吗！"] = "Счастливчик {{Mr.|Ms.}}! Вы попали на грандиозное ежегодное событие — на сцену скачек животных! Как насчет этого? Хотите сделать ставку!",
    ["序列越高，越接近神性的深渊，就越难感受到食物带来的普通幸福。趁你还对一切好奇，去品尝那些甜蜜吧。"] = "Чем выше последовательность, тем ближе вы к бездне божественности и тем труднее ощущать обычное счастье, приносимое едой. Пока вам все еще интересно, попробуйте эти сладости.",
    ["店主也没在？"] = "А лавочника тоже нет?",
    ["廷根也被称为“大学之城”，自从王国推行雇员考试之后，居住和旅游观光的人是越来越多了。"] = "Тинген также известен как «Город университетов». С тех пор, как в королевстве были введены экзамены для сотрудников, количество людей, живущих здесь и приезжающих сюда с целью туризма, увеличилось.",
    ["廷根人都认识的东西，知识雕塑的纪念品。"] = "То, что знает каждый в Тингене, скульптура на память о знаниях.",
    ["廷根大学？那可是我们最大的对手！"] = "Тингенский университет? Это наш главный конкурент!",
    ["廷根市位于鲁恩王国北方，属于阿霍瓦郡，这里有贯穿城市的、诗人们歌颂的霍伊河，也有北区静谧庄严的正神教堂与南区热闹喧哗的码头市场。"] = "Город Тинген расположен на севере королевства Лоен, входящего в состав округа Авва. Здесь есть протекающая через город река Хой, воспетая поэтами, тихая и торжественная православная церковь в Северном районе и шумный и шумный портовый рынок в Южном.",
    ["廷根那么多地方，偏偏进来这里看看，说明你眼光不错。"] = "В Тингене так много мест, и тот факт, что вы решили прийти сюда, показывает, что у вас хороший вкус.",
    ["开头应该怎么写？“廷根的隐秘角落藏着秘密”？俗了点。"] = "Как мне начать? «Скрытые уголки Тингена хранят тайны»? Немного вульгарно.",
    ["开玩笑的。不过，听说蒸汽教堂有专门的护符，能保护工人免受意外伤害。"] = "Просто шучу. Однако я слышал, что у Парового собора есть особые чары, способные защитить рабочих от случайных травм.",
    ["开玩笑的，我只是连载的小说陷入瓶颈了，听到名字都能汗毛竖起的格尔曼先生，我连他为什么要冒险都说不清楚……"] = "Шучу, я только что столкнулся с узким местом в своих сериализованных романах. Волосы на волосах господина Германа встают дыбом, когда я слышу его имя. Я даже не могу объяснить, почему он рискует...",
    ["弗兰克先生真是太厉害了，居然能研究出公鸡下蛋的方法。"] = "Мистер Фрэнк действительно потрясающий. Ему действительно удалось найти способ заставить петухов нести яйца.",
    ["弗兰奇先生把我家门给踹开了，让我向女神发誓我不会再找人半夜斗邪恶。可恶！"] = "Мистер Фрэнки выбил мою дверь и заставил меня поклясться Богине, что я больше не найду никого, кто мог бы сражаться со злом посреди ночи. Блин!",
    ["弗兰奇到底干了什么？你宁愿毁约逃跑？"] = "Что именно сделал Фрэнк? Ты предпочитаешь разорвать контракт и сбежать?",
    ["弗兰奇把我的行李扣下了，还扬言让我在廷根租不到任何房子。"] = "Фрэнки взял мой багаж в заложники и пригрозил, что я не смогу снять дом в Тингене.",
    ["弗兰奇那儿有房子空出来了，他昨天让我帮忙宣传，和每个来买东西的客人说一遍这消息。"] = "У Фрэнка есть свободная комната. Вчера он попросил меня помочь продвинуть ее и рассказать об этой новости каждому покупателю, который придет что-то купить.",
    ["弗兰奇那家伙雇佣了帮工，四处找那些拖欠租金的人追债！"] = "Этот парень Фрэнк нанял помощников, чтобы те ходили вокруг и выслеживали тех, кто задолжал арендную плату!",
    ["弗洛西还年轻，不会做老乞丐这单生意的。"] = "Форс еще молод; она не возьмется за работу старой нищей.",
    ["弹得好是一回事，但莉莲小姐不一样——她和你说话的时候，会听完你说的话，然后问一句“然后呢”。"] = "Хорошо играть – это одно, а мисс Лилиан – другое: когда она с тобой разговаривает, она слушает все, что ты говоришь, а потом спрашивает: «А потом?»",
    ["当亲手为东区的孩子分发面包时，记得自己不仅是织梦者，更是奥黛丽·霍尔。"] = "Раздавая хлеб детям Восточного округа своими руками, я вспоминаю, что я не просто Ткач Снов, а Одри Холл.",
    ["当你接近这些回响的源头，往昔的记忆会与之共鸣，凝结成具象的回响之匣。那些散落的音符，藏着命运本身的韵律——正是我谱写诗篇所需的残章。"] = "Когда вы приближаетесь к источнику этого эха, воспоминания о прошлом будут резонировать с ним, конденсируясь в конкретный эхо-коробку. В этих разбросанных нотах скрывается сам ритм судьбы — те самые фрагменты, которые мне нужны, чтобы составить свое стихотворение.",
    ["当你积攒了足够的军功，也可以来我这里兑换相应的回报。记住，胜利永远属于勇敢者。"] = "When you have accumulated enough military merit, you can also come to me to exchange for corresponding rewards. Remember, victory always belongs to the brave.",
    ["当年为了嫁给你，连嫁妆我都没要，被骂了那么久倒贴货……"] = "Тогда, чтобы выйти за тебя замуж, я даже приданого не просила, и меня так долго ругали за «халяву»…",
    ["当年，我也在舞池的灯光下。只是现在……那盏灯照不到我了。"] = "Раньше я тоже был под огнями танцпола. Просто сейчас... этот свет больше не доходит до меня.",
    ["当我看见云雀，张开翅膀欢喜地飞向阳光。"] = "Когда я вижу жаворонка, расправившего крылья и радостно летящего к солнцу.",
    ["当然……造纸厂那边会要求您多收集一些。<P_Heart>（她侧身挡住了背后的袋子）</>"] = "Конечно... бумажная фабрика потребует от вас собрать немного больше. <P_Heart> (Она повернулась боком, чтобы заблокировать сумку позади себя) </>",
    ["当然不是！<P_Heart>(小声)</>要不是猎犬酒馆给的多，我才不折腾这个……"] = "Конечно же нет! <P_Heart>（Шёпотом）</>Если бы в таверне «Гончая» не платили так щедро, я бы ни за что не стал этим заниматься...",
    ["当然了，我只给哥哥一个人捏。"] = "Конечно, я делаю тебе только массаж, брат.",
    ["当然会记得，你们也要与我分享霍伊大学有趣的事。"] = "Конечно, я запомню, вы также должны поделиться со мной интересными вещами об Университете Хой.",
    ["当然会，但是我有一个好的前辈让我学习。"] = "Конечно, был, но у меня был хороший старший, у которого можно было поучиться.",
    ["当然啦！我听说码头那边的工人，一天能挣好几个便士呢！要是省着点花，说不定还能买条新裙子！"] = "Конечно! Я слышал, что рабочие в доке могут зарабатывать несколько копеек в день! Если я сэкономлю немного, возможно, я смогу купить новое платье!",
    ["当然是因为……"] = "Конечно, это потому, что...",
    ["当然是小镇上庆祝丰收，感恩大地的节日。看我家门口满地金黄的南瓜，多么甜美的果实，多么伟大的丰饶之力！"] = "Конечно, в маленьком городке это праздник, посвященный сбору урожая и благодарению земли. Посмотрите, какие золотые тыквы у моего порога, какие сладкие плоды, какая великая сила урожая!",
    ["当然是我自己做的，我可是天生的……这不关您的事。蒸汽在上，如果您没别的事，就请离开吧。"] = "Я, конечно, сам это сделал, я натурал... Это не ваше дело. Steam выше, если у вас больше ничего нет, пожалуйста, уходите.",
    ["当然是我自己抓的。为了吃肉，我抓空了好几个街区的老鼠！"] = "Конечно, я поймал это сам. Чтобы поесть мяса, я вычистил крыс в нескольких кварталах!",
    ["当然是那些热情过头的学生和读者！从家门口到教学楼，他们无处不在。甚至在盥洗室，都有人敲门向我请教第四纪的历史。"] = "Конечно, чрезмерно восторженные студенты и читатели! От порогов до учебных зданий — они повсюду. Даже в ванной кто-то постучал в дверь и спросил меня об истории Четвертой Эпохи.",
    ["当然记得。姐姐每次来，我都记得。只是……姐姐不常找我。"] = "Конечно, я помню. Каждый раз, когда ты приходишь, я вспоминаю. Просто... ты не часто ко мне приходишь.",
    ["当然！实在是太刺激了，没想到传闻只喜欢钱和美人的老富翁身手这么矫健，居然能躲过警察追捕！"] = "Конечно! Это было так захватывающе. Я не ожидал, что старый богач, который, по слухам, любит только деньги и красоты, окажется настолько проворным, что сможет уйти от полиции!",
    ["当然！您有什么冤屈？被厂里克扣工钱？房东不退押金？"] = "Конечно! Какие у вас претензии? Зарплату удерживает завод? Арендодатель отказывается возвращать залог?",
    ["当然！还赢过几个官司，帮人拿到过该拿的钱。"] = "Конечно! Я даже выиграл несколько дел и помог людям получить причитающиеся им деньги.",
    ["当然！那可是神秘学大师给我的配方。"] = "Конечно! Это формула, данная мне мастером мистики.",
    ["当然，一家人可不能分开太久！我们正在努力！"] = "Конечно, семья не должна разлучаться слишком надолго! Мы усердно работаем!",
    ["当然，也不是所有工人家庭都能承担得起手术费，这也是当下最让人无奈的地方。我们能做的，就是把每一台手术都做扎实，不辜负患者们的信任。 "] = "Конечно, не все семьи рабочих могут позволить себе оплату операции, а это сейчас самая беспомощная часть. Все, что мы можем сделать, — это добросовестно выполнить каждую операцию и не подвести доверие пациентов.",
    ["当然，他应该像我一样成为木匠。毕竟木头总能做成点什么，而下街已经无可救药了。"] = "Конечно, ему стоило стать плотником, как я. В конце концов, из дерева всегда можно хоть что-то смастерить, а Нижнюю улицу уже ничто не спасёт.",
    ["当然，如果您需要的不仅仅是“游览”，我也有一些特别的“漫游”。毕竟，这座城市光鲜的砖石之下，总有一些角落……需要额外的脚步去丈量。"] = "Разумеется, если вам нужно нечто большее, чем просто «экскурсия», у меня найдутся и особые «странствия». В конце концов, под сверкающей брусчаткой этого города всегда найдутся закоулки... которые так и ждут лишней пары шагов.",
    ["当然，当然，亲爱的，我想吃你做的烤苹果芝士面包。"] = "Конечно, конечно, дорогая, я хочу съесть запеченный яблочно-сырный хлеб, который ты приготовишь.",
    ["当然，当然，这是本店最精巧而令人敬畏的武器，帮助您用最优雅的方式解决那些不优雅的问题。"] = "Конечно, конечно, это самое изысканное и грозное оружие в нашем магазине, помогающее решить эти неизящные задачи самым элегантным способом.",
    ["当然，想成名就得写这些。"] = "Конечно, вам нужно писать об этих вещах, если вы хотите прославиться.",
    ["当然，我们不欢迎没钱的普通人。"] = "Конечно, мы не приветствуем простых людей без денег.",
    ["当然，我会成为一位体恤民众的好市长。"] = "Конечно, я буду хорошим мэром, который заботится о людях.",
    ["当然，我和家人都住这里面。"] = "Конечно, я и моя семья живем внутри этого.",
    ["当然，我这是在践行罗塞尔大帝的话。三十年足以让命运的河道从东到西，不要轻视贫穷的年轻人！"] = "Конечно, я воплощаю в жизнь слова императора Розеллы. Тридцати лет достаточно, чтобы река судьбы потекла с востока на запад; не стоит недооценивать бедную молодежь!",
    ["当然，最有意思的还是因蒂斯邮报，可惜廷根不怎么有。唉，真想念退休前的时光，一切都那么有趣……"] = "Конечно, самый интересный — это Интис Post, но, к сожалению, у Тинген их немного. Эх, я очень скучаю по временам перед выходом на пенсию, все было так интересно...",
    ["当然，看我棕色的皮肤，听我古老的发音。"] = "Конечно, посмотрите на мою смуглую кожу, послушайте мой древний акцент.",
    ["当然，眼见为实。看对眼了就去聊几句，不必拘束。这里没那么多规矩。 "] = "Конечно, лучше один раз увидеть, чем сто раз услышать. Если кто-то приглянется — подойдите и поболтайте, не стесняйтесь. Строгих правил здесь нет.",
    ["当然，谁不想出生在庄园中，外面的世界可没那么容易。"] = "Конечно, кто не хотел бы родиться в поместье? Внешний мир не так прост.",
    ["当然，这一切都取决于您的需求。我们“帽子帮”的宗旨是——只要价格合适，没有什么是我们办不到的。"] = "Конечно, все зависит от ваших потребностей. Цель нашей «Шляпной банды» такова: пока цена правильная, мы ничего не можем сделать.",
    ["当然，阁下，否则我为什么要出租我的老伙计？"] = "Конечно, милорд, иначе зачем бы мне сдавать в аренду своего старого приятеля?",
    ["待会我从右边过去，你和羊毛吸引他注意力。"] = "Я сейчас пойду справа; вы с Вулом отвлекаете его.",
    ["很久之前倒是有个家伙总和我争得面红耳赤……真是久远的记忆了啊。"] = "Давным-давно жил-был парень, который всегда спорил со мной, пока его лицо не покраснело... Это действительно далёкое воспоминание.",
    ["很好学嘛，不错。"] = "Очень хочет учиться, неплохо.",
    ["很好很好，给你两分钟！然后我们就开始！"] = "Очень хорошо, очень хорошо. У вас есть две минуты! Тогда мы начинаем!",
    ["很抱歉，让你坐在这有违我们的时尚标准。"] = "Простите, но позволить вам сидеть здесь нарушает наши стандарты моды.",
    ["很简单，我的朋友，随便说一个词就好，最好和工厂有关。"] = "Все просто, друг мой, скажи любое слово, желательно связанное с заводом.",
    ["得了吧，先生！您不就是想让我们互相压价吗？"] = "Забудьте об этом, сэр! Ты просто хочешь, чтобы мы подрезали друг друга, не так ли?",
    ["得到的回答越是强烈，转动的速度也就越快。"] = "Чем сильнее ответ, тем быстрее он вращается.",
    ["得看你要问什么问题，才能挑合适的占卜师。 "] = "От того, какой вопрос вы хотите задать, зависит выбор подходящего прорицателя.",
    ["心情不好？不，我只是有点累了。"] = "Не в духе? Нет, я просто немного устал.",
    ["心疼一下这个输了一整天的男人吧陌生人，这是他难得的休息时间！哈哈哈！"] = "Пожалейте этого человека, потерявшего весь день, незнакомец, это его редкое время отдыха! Ха-ха-ха!",
    ["忍着。"] = "Терпите это.",
    ["忘记自我而堕落，在奔向心头的幸福中。"] = "Забывание себя и падение в стремлении к счастью в своем сердце.",
    ["快和我说说，你都测了什么？这么神奇吗？"] = "Расскажи скорее, на что ты гадал? Неужели и правда так чудесно?",
    ["快把东西放回去，不然我马上就叫巡警来抓你……"] = "Быстро положи его обратно, а то я сейчас позвоню патрульному, чтобы он тебя арестовал...",
    ["怎么了吗？"] = "Что-то случилось?",
    ["怎么会这样呢？是学习压力太大了吗？"] = "Как это могло быть так? Академическое давление слишком велико?",
    ["怎么会这样！再过几天就是我们王国的生日聚会了——"] = "Как это могло случиться! Через несколько дней будет день рождения нашего королевства…",
    ["怎么会！你需要定制人偶吗？我把自己关起来是为了体验产品的心理。"] = "Как я мог! Вам нужна кукла на заказ? Я заперся, чтобы испытать психологию продукта.",
    ["怎么会，没人瞧得见我，瞧见了也会觉得是自己看错了。"] = "Как это могло быть? Никто не может меня видеть, а даже если бы и увидел, они бы подумали, что видят что-то.",
    ["怎么听起来像水手们喝多了编的故事……"] = "Как это похоже на историю, выдуманную пьяными моряками...",
    ["怎么就生气了呢……"] = "Почему они разозлились...",
    ["怎么我感觉头顶痒痒的……"] = "Что-то у меня макушка чешется...",
    ["怎么有个女孩倒在地上……醒醒……"] = "Почему девушка лежит на земле... проснись...",
    ["怎么样怎么样？我的新配方反响如何？ "] = "Ну как, ну как? Какие отзывы на мой новый рецепт?",
    ["怎么样？想写什么？可以算你便宜点，我就赚点酒钱。"] = "Так? Что вы хотите написать? Я могу дать вам скидку; Я просто хочу заработать немного денег на вино.",
    ["怎么突然生气了……脾气好怪！"] = "Чего вдруг рассердился... такой странный нрав!",
    ["怎么说，你就是我等的合伙人吗？"] = "Итак, ты тот партнер, которого я ждал?",
    ["怎么说？"] = "В каком смысле?",
    ["怎么，你有办法搞到票？"] = "Почему у вас есть возможность достать билеты?",
    ["怎么，欺负聋哑画家？小心我揍你！"] = "Что, издевательства над глухонемым художником? Берегись, или я тебя побью!",
    ["怕她拒绝。怕我说错话。怕她笑我。怕……什么都怕。"] = "Боюсь, она откажется. Боюсь, я скажу что-то не то. Боюсь, она будет надо мной смеяться. Боюсь... всего боюсь.",
    ["怪不得。我看的时候就觉得，第三幕那段戏，和前面完全接不上，像硬塞进来的。"] = "То-то и оно. Я ещё во время просмотра чувствовал, что сцена в третьем акте совершенно не вяжется с остальным действием, словно её вставили силой.",
    ["总之！你以后如果缺钱了，可以来找我。"] = "В общем! Если тебе в будущем понадобятся деньги, приходи ко мне.",
    ["总之，不如舒舒服服补个觉。"] = "В любом случае, лучше вздремнуть.",
    ["总之，无论如何你答应了，美丽的歌者，爱德华娜小姐，现在是萨里斯夫人，今天可以与我共进晚餐吗？"] = "В любом случае, как бы то ни было, вы согласились, прекрасная певица, мисс Эдвина, теперь миссис Сарис, можете ли вы поужинать со мной сегодня?",
    ["总有一天，我要让所有人都知道我的名字——安妮·伯尼！像艾德雯娜女士那样，成为海上传奇的一部分！"] = "Однажды я заставлю всех узнать мое имя — Энни Бонни! Как и мисс Эдвина, я стану частью морских легенд!",
    ["恭喜。"] = "Поздравляю.",
    ["恰好这个词很微妙。"] = "Слово «произошло» очень тонкое.",
    ["您……您好，需要什么帮助吗？"] = "Привет, тебе нужна помощь?",
    ["您……需要钢琴课吗？我的价格很公道。"] = "Тебе... нужны уроки игры на фортепиано? Моя цена очень справедливая.",
    ["您一直住在这儿？"] = "Вы всегда жили здесь?",
    ["您何尝不是呢，像我们这样善良的人可真不多了。"] = "Разве ты не такой же? Таких добрых людей, как мы, осталось не так много.",
    ["您再看看这金黄透亮的煎蛋，边缘微焦，内里流心，简单却充满家的味道，吃一口就能让您感受到温暖与满足，买五送一！"] = "Посмотрите на эту золотую и полупрозрачную яичницу, слегка обугленную по краям, жидкую внутри, простую, но наполненную домашним вкусом, один укус заставит вас почувствовать тепло и удовлетворение, купите пять, получите один в подарок!",
    ["您刚搬来这里？有些不习惯是正常的。"] = "Ты только что переехал сюда? Это нормально – быть немного непривычным.",
    ["您可以多在一楼逛逛，等您知道自己想要什么了，自然就明白了。"] = "По первому этажу можно побродить дальше. Как только вы поймете, чего хотите, вы, естественно, поймете.",
    ["您可以找那边的列车引导员，乘坐火车前往城堡领地。"] = "Там вы можете найти проводника поезда и доехать на поезде до территории замка.",
    ["您可以称呼我为“波洛”。"] = "Вы можете называть меня «Пуаро».",
    ["您听，一只快乐的云雀，陷入了对一名女士的单恋……多么美丽伤感的爱情故事啊。"] = "Послушайте: счастливый жаворонок безответно влюбился в даму... Какая прекрасная и печальная история любви.",
    ["您大人有大量，这一次就放过我吧……"] = "Вы щедрый человек, пожалуйста, отпустите меня на этот раз...",
    ["您夫人和孩子生日是同一天？"] = "У вашей жены и детей один день рождения?",
    ["您好！我是奥利弗，俱乐部事务的联络人。不知道您是否已经加入了某个俱乐部？有些东西只有成员才能接触到，如果还没有的话，现在加入也不迟。"] = "Привет! Я Оливер, связной по делам клуба. Интересно, ты уже вступил в клуб? Некоторые вещи доступны только участникам; если нет, еще не поздно присоединиться.",
    ["您好，{{PlayerName}}{{先生|女士}}，乐意为您效劳。"] = "Здравствуйте, {{PlayerName}} {{господин|госпожа}}, рад служить вам.",
    ["您好，{{先生|女士}}。"] = "Здравствуйте, {{господин|госпожа}}.",
    ["您好，{{先生|女士}}！您要买车票吗？"] = "Здравствуйте, {{мистер|мисс}}! Хотите купить билет?",
    ["您好，{{先生|女士}}，特好玩旅店欢迎您！"] = "Здравствуйте, {{господин|госпожа}}, добро пожаловать в отель «Супер-отдых»!",
    ["您好，想要点什么呢？项链？胸针？也欢迎您随便看看。"] = "Здравствуйте, чего бы вам хотелось? Ожерелье? Брошь? Можете и просто осмотреться, если пожелаете.",
    ["您好，我只是路过这里，听到你们的争论，感觉很有意思。"] = "Привет. Я просто проходил мимо и слышал ваши дебаты; это звучало очень интересно.",
    ["您好，我是受雇来表演的小丑，请问……"] = "Здравствуйте, я клоун, нанятый для выступления, могу ли я спросить...",
    ["您好，我是奥利弗，专门负责俱乐部事务的联络人。看来您已经是某个俱乐部的成员了——很好，这里的东西您都可以使用。需要看看有什么，或者想回俱乐部坐坐，都可以找我。"] = "Здравствуйте, я Оливер, ответственный за дела клуба. Кажется, вы уже состоите в клубе — очень хорошо, здесь можно использовать все. Если вам нужно посмотреть, что доступно, или вы хотите посидеть в клубе, вы можете найти меня.",
    ["您好，我是约瑟夫，约瑟夫就是我，我是地下市场书商。您想要的书，我为您寻找。"] = "Здравствуйте, я Джозеф. Джозеф — это я, и я продавец книг на Подземном рынке. Книги, которые вы хотите, я найду для вас.",
    ["您好，新客人，如您所见我正在为“命运”劳作……"] = "Привет, новый гость, как видишь, я работаю на «Фейт»…",
    ["您好，有什么事吗？"] = "Здравствуйте, что-то случилось?",
    ["您好，美好的一天从香喷喷的煎肉开始！您想来点什么？"] = "Здравствуйте, чудесный день начинается с ароматного жареного мяса! Что бы вы хотели?",
    ["您好，要来一束鲜花吗？"] = "Здравствуйте, хотите букет цветов?",
    ["您好，请允许我为您介绍香水版的廷根地图！"] = "Здравствуйте, позвольте представить вам парфюмерную версию карты Тинген!",
    ["您好，请问发生了什么事？"] = "Привет, что случилось?",
    ["您好，阁下，希望没有妨碍到您。"] = "Здравствуйте, сэр, надеюсь, я вас не побеспокоил.",
    ["您对绘画有研究吗？"] = "Есть ли у вас какие-либо исследования в области живописи?",
    ["您很懂画？"] = "Вы много знаете об искусстве?",
    ["您想去哪儿？"] = "Куда бы вы хотели пойти?",
    ["您是位好医生。"] = "Вы хороший доктор.",
    ["您是温柔有礼的人，会过上好生活的。"] = "Вы мягкий и вежливый человек, проживете хорошую жизнь.",
    ["您是说这其中另有隐情？"] = "Вы хотите сказать, что за этим стоит скрытая история?",
    ["您最近似乎去过南大陆？"] = "Вы, кажется, недавно бывали на Южном континенте?",
    ["您有什么计划？"] = "Каков ваш план?",
    ["您有感兴趣的武器吗？诚挚为您介绍！"] = "Есть ли какое-нибудь оружие, которое вас интересует? Искренне представляем вам!",
    ["您的品味果然无可挑剔！"] = "Ваш вкус поистине безупречен!",
    ["您的想法是？"] = "Какова ваша идея?",
    ["您的眼光不错。"] = "У тебя хороший глаз.",
    ["您看这幅画。笔触大胆，色彩浓烈……尤其是这个腰身的曲线，简直是大师手笔。"] = "Посмотрите на эту картину. Мазки смелые, цвета насыщенные... особенно изгиб талии, это действительно работа мастера.",
    ["您真是一位独具慧眼的小姐。"] = "Вы действительно молодая леди с проницательным взглядом.",
    ["您真是个好人，愿女神庇佑您！"] = "Вы действительно хороший человек, да пребудет с вами Покров Богини!",
    ["您真是太神奇了！我刚刚也感觉到小莉莉在心里呼唤我……我马上就去找她！"] = "Вы действительно потрясающие! Я просто почувствовала, как маленькая Лили зовёт меня в своём сердце... Я немедленно пойду её искать!",
    ["您真有眼光，先生！总共只要6便士，还有一束赠送的花，您想要哪束？"] = "У вас отличный глаз, сэр! Всего 6 пенсов, и букет в подарок. Какой из них вы бы хотели?",
    ["您真的……很有热情。"] = "Ты действительно... страстный.",
    ["您真的是市长候选人？"] = "Вы действительно кандидат в мэры?",
    ["您瞧，这个锁被雨淋的不成样子，我才说它看起来很好打开，并不是我要打开。"] = "Видите ли, этот замок в таком плохом состоянии из-за дождя, что я только что сказал, что его легко открыть; Я не имел в виду, что собираюсь его открыть.",
    ["您知道码头最近那起案件吗？啧……最近晚上最好别一个人去那边转悠。"] = "Знаете ли вы о недавнем случае на скамье подсудимых? Тск... в последнее время лучше не бродить там одному по ночам.",
    ["您竟然是脚踏车公司的股东！"] = "На самом деле вы являетесь акционером велосипедной компании!",
    ["您经常参加慈善拍卖吗？"] = "Вы часто посещаете благотворительные аукционы?",
    ["您若质疑，我们可以现在请第三方匠人估价，或按章程申请仲裁。请进来看单据吧。站在街上讨论具体数字，对解决问题没有帮助。"] = "Если у вас есть сомнения, мы можем попросить стороннего мастера оценить цену сейчас или обратиться в арбитраж согласно регламенту. Пожалуйста, зайдите и посмотрите квитанции. Стоять на улице и обсуждать конкретные цифры не поможет решить проблему.",
    ["您要去哪里呢？如果愿意尝试的话，这里新开了很多条新线路。"] = "Куда путь держите? Если хотите, у нас открылось множество новых маршрутов.",
    ["您见过她吗？我文静、乖巧的女儿，或许现在正躲在哪里看小说。"] = "Вы ее не видели? Моя тихая, послушная дочка, быть может, сейчас спряталась где-то и читает роман.",
    ["您见过相关的例子吗？"] = "Вы видели соответствующие примеры?",
    ["您觉得怎么样？"] = "Что вы думаете?",
    ["您认识他们？多亏了在莫雷蒂家做女仆的那段日子，我才能成为男爵家的厨师！"] = "Вы их знаете? Благодаря времени, которое я провела горничной в доме Моретти, мне удалось стать поваром у барона!",
    ["您认识罗珊？她可是我们这儿最开心的客人啦！没见人先听到她声音——“早上好呀！今天有什么太阳一样的花吗？” "] = "Ты знаешь Розель? Она наш самый счастливый клиент! Вы слышите ее голос прежде, чем видите ее: «Доброе утро!» Есть ли у тебя сегодня цветы, похожие на солнечный свет?",
    ["您说的屋子是哪间？动静又是什么？"] = "О какой комнате вы говорите? И что за переполох?",
    ["您还有什么想了解的吗？"] = "Есть ли что-нибудь еще, что вы хотели бы узнать?",
    ["您这是在做手工？"] = "Вы занимаетесь рукоделием?",
    ["您这是在唱什么呀？"] = "Что ты поешь?",
    ["您这话我有些不解。"] = "Я не совсем понимаю, что вы имеете в виду.",
    ["想妈妈的时候我就会来这里……"] = "Когда я скучаю по маме, я прихожу сюда...",
    ["想得美，还有两车呢！"] = "Мечтайте, есть еще две тележки!",
    ["想想那些体面人的生活，坐在办公室里，每个月领固定的薪水，不用总是为下一顿饭发愁。"] = "Подумайте о жизни тех порядочных людей, которые сидят в офисе, получают фиксированную зарплату каждый месяц и не беспокоятся о следующей еде.",
    ["想打开这个宝箱，你得和我玩个游戏。"] = "Чтобы открыть этот сундук с сокровищами, вам придется сыграть со мной в игру.",
    ["想拿市面上的好货不必四处奔走，拿着契约来找我就够了。"] = "You don't need to run around to get the good stuff on the market; just bring the contract to me.",
    ["想来点什么？"] = "Чего желаете?",
    ["想玩跳房子吗？"] = "Хотите поиграть в классики?",
    ["意思是，如果您的丈夫半夜爬出棺材，管理人员将负责将他的灵魂召唤回去，无需您费心。"] = "Это означает, что если ваш муж вылезет из гроба посреди ночи, администраторы будут нести ответственность за вызов его духа, и вам не придется об этом беспокоиться.",
    ["愚蠢！"] = "Глупый!",
    ["感觉都不太合适……"] = "Ни один из них не кажется вполне правильным...",
    ["感谢你伸出援手，临时借给我们流浪王国一块落脚地。亨特，你是一个好首领！"] = "Спасибо за руку помощи и за то, что временно предоставил нашему Странствующему королевству приют. Хантер, ты отличный вожак!",
    ["感谢你的好话，我也希望能成真。"] = "Спасибо за ваши добрые слова; Надеюсь, они тоже сбудутся.",
    ["感谢你的意见！以后廷根每条街上都会跑着这样的车。到时候，我们的车轮总是能比罪恶更快一步。"] = "Спасибо за ваш отзыв! В будущем такие автомобили будут ездить на каждой улице Тингена. К тому времени наши колеса всегда будут на шаг впереди преступности.",
    ["感谢女神！我这就来。"] = "Слава Богине! Я приду прямо сейчас.",
    ["感谢女神，她顺利通过并入学了……我是不是说太多了？"] = "Слава Богине, она прошла гладко и поступила... Я что, слишком много сказал?",
    ["感谢您为维护廷根市公共卫生做出的贡献，便士与勋章用于奖励您的付出，以下部分不需要念……"] = "Благодарим вас за ваш вклад в поддержание общественной гигиены в Тингене. Пенни и медаль должны вознаградить ваши усилия. Следующую часть читать не обязательно...",
    ["感谢您的启示！吉娜，我现在就出发去找你，古堡的僻静角落就是为我们互通心意准备的！"] = "Спасибо за откровение! Джина, я отправляюсь искать тебя сейчас; укромный уголок старинного замка готов для того, чтобы мы могли разделить наши сердца!",
    ["感谢您的善良。拉斐尔墓园，他在那里。"] = "Спасибо за вашу доброту. Рафаэльское кладбище, он там.",
    ["感谢您的夸奖，爱丽丝小姐的珠宝设计足够优秀。"] = "Спасибо за комплимент. Дизайн ювелирных украшений мисс Элис достаточно превосходен.",
    ["感谢您的好意，愿女神庇佑您！"] = "Спасибо за вашу доброту, пусть Богиня хранит вас!",
    ["感谢您的帮助，{{先生|女士}}。这是一点见面礼，期待我们的再会。"] = "Спасибо за помощь, {{ Mr. | Ms. }}. Это небольшой знак признательности, с нетерпением ждем нашей следующей встречи.",
    ["感谢您的祝福。"] = "Спасибо за ваше благословение.",
    ["感谢您的赞美，但我们还是先把店铺大门让出来吧。"] = "Спасибо за комплимент, но давайте сначала очистим вход в магазин.",
    ["感谢您的赞美，先生/小姐！"] = "Спасибо за ваш комплимент, сэр/леди!",
    ["愿下次，我们能一起过生日！亨特，希望你可以把这句话带给帽子帮的大家。"] = "Пусть в следующий раз мы отпразднуем день рождения вместе! Хантер, передай, пожалуйста, эти слова ребятам из банды Шляпников.",
    ["愿女神庇佑您！"] = "Пусть Богиня Вечной Ночи защитит тебя!",
    ["愿美与芬芳眷顾你。"] = "Пусть красота и аромат благоприятствуют вам.",
    ["愿黑夜女神庇佑你。"] = "Пусть Богиня Вечной Ночи хранит тебя.",
    ["愿黑夜庇护你。"] = "Пусть Богиня Вечной Ночи хранит тебя.",
    ["慧眼如炬！这枚宝石产自南大陆血钻矿，现在只需要五百金镑！而且我们也接受饰品外观的定制，您可以把它改造为喜欢的款式。"] = "Остроглазый! Этот драгоценный камень добыт на руднике кровавых алмазов Южного континента, и теперь он стоит всего пятьсот фунтов золота! И мы также принимаем настройку внешнего вида украшений; вы можете преобразовать его в тот стиль, который вам нравится.",
    ["懂一点。但比起画布上的……我更喜欢观察……动态的美。"] = "Немного разбираюсь. Но вместо того, что на холсте... я предпочитаю наблюдать... красоту в движении.",
    ["我……"] = "Я...",
    ["我……我只是听说有家诊所药到病除。"] = "Я... я просто слышал, что есть клиника, где исцеляют от любых болезней с первой же дозы.",
    ["我……我后悔没听你们的 ，第一次就遇上他…… "] = "Я... я жалею, что не послушалась тебя, я столкнулась с ним в первый раз...",
    ["我……我来评理吗？"] = "Я... я должен судить?",
    ["我……我觉得他好像注意到我们了。他的眼神好可怕，像妈妈说的那些客人一样……"] = "М-мне кажется, он нас заметил. У него такой жуткий взгляд, прямо как у тех гостей, про которых рассказывала мама...",
    ["我……我这一时半会出不去！村里多的是能借厕所的地方，你记好了——"] = "Я... Я не могу выйти какое-то время! В деревне полно мест, где можно одолжить туалет, запомни это…",
    ["我、我不是要饭的！"] = "Я, я не нищий!",
    ["我、我想过短暂热烈的一生，而不是漫长无聊的一生。"] = "Я хочу прожить короткую и страстную жизнь, а не длинную и скучную.",
    ["我一切都好，这个月，莫蒙特教授甚至亲自夸奖了我的作品。"] = "У меня все хорошо. В этом месяце профессор Момонт даже лично похвалил мою работу.",
    ["我上个月买了条会随心情变色的珍珠项链——来自“命运”途径的某位兼职珠宝商。<P_Heart>（俏皮眨眼）</>这在舞会上可帮了大忙。"] = "В прошлом месяце я купила жемчужное ожерелье, которое меняет цвет в зависимости от моего настроения — оно принадлежит ювелиру, работающему по совместительству, с пути «Судьба». <P_Heart> (игриво подмигивает) </> Это очень помогло на балу.",
    ["我不坐船，先生。不过看起来你是要乘坐那艘叫“慷慨号”的船吗？"] = "Я не сяду на корабль, сэр. Но, похоже, вы собираетесь взять тот корабль, который называется «Щедрость»?",
    ["我不想每一次和你独处都要这样躲躲藏藏……"] = "Я не хочу так прятаться каждый раз, когда я остаюсь с тобой наедине...",
    ["我不敢。我在这坐了俩小时了，腿都是软的。"] = "Я не смею. Я сижу здесь уже два часа, а ноги у меня желеобразные.",
    ["我不明白，难道城里的教育，会让我获得比善良更好的品质吗？"] = "Я не понимаю. Может быть, образование в городе даст мне лучшие качества, чем доброта?",
    ["我不缺钱，她想要什么我都能给她！"] = "У меня нет недостатка в деньгах, я могу дать ей все, что она захочет!",
    ["我不能每次都直接赠予你一笔钱，但我可以告诉你如何投资。罗塞尔大帝说过，送给人一条鱼，不如送他钓鱼的本领！"] = "Я не могу каждый раз давать вам определенную сумму денег, но я могу сказать вам, как инвестировать. Император Розель однажды сказал: дать человеку рыбу не так хорошо, как научить его ловить рыбу!",
    ["我为什么不能是鸽子？"] = "Почему я не могу быть голубем?",
    ["我为什么不走？风暴在上，我希望你能好好使用你那双美丽的眼睛。"] = "Почему бы мне не уйти? Буря наверху, я надеюсь, что ты сможешь хорошо использовать свои прекрасные глаза.",
    ["我为自己感到惊讶，我的心居然没有因欲望而立刻融化。"] = "Я удивляюсь самому себе; мое сердце не сразу растаяло от желания.",
    ["我也只是顾客。"] = "Я тоже всего лишь клиент.",
    ["我也是几天没吃东西，饿得迷了眼，才会做这种事……"] = "Я тоже несколько дней ничего не ел, от голода в глазах темнело, вот и пошел на такое...",
    ["我也要努力！不能再给爸爸添麻烦了！"] = "Я тоже должен стараться! Нельзя больше доставлять отцу хлопот!",
    ["我也要学，妈妈教我！"] = "Я тоже хочу научиться, Мама, научи меня!",
    ["我亲爱的……老比尔……您……"] = "Мой дорогой... Старый Билл... ты...",
    ["我亲爱的女儿，听说你爱上了一个费内波特的平民？这可真是令人“惊喜”。 "] = "Моя дорогая дочь, я слышал, ты влюбилась в простолюдина из Фейсака? Это действительно «сюрприз».",
    ["我今天涂了新的口红，好看吗？"] = "Я сегодня накрасила губы новой помадой, красиво?",
    ["我今晚就要露宿街头了！"] = "Сегодня вечером я окажусь на улице!",
    ["我们五个就是因为这本书结缘，写信约定在这里见面——有位笔名叫鱿鱼的先生还没到。"] = "Благодаря этой книге мы впятером подружились и письменно договорились встретиться здесь — джентльмен под псевдонимом Сквид еще не приехал.",
    ["我们什么时候溜进去玩吧？"] = "Когда нам стоит прокрасться и поиграть?",
    ["我们会一直在红月亮街为你提供咖啡、茶与宁静的心灵，欢迎你回来休息。"] = "Мы всегда обеспечим вас кофе, чаем и спокойствием на улице Красной Луны. Вы можете вернуться и отдохнуть.",
    ["我们保证安静得像墙角的老鼠！每天天不亮就出门找活，绝不弄出动静……"] = "Мы гарантируем, что будет тихо, как мыши в углу! Мы каждый день отправляемся искать работу до рассвета и никогда не издаем ни звука...",
    ["我们医院院长想让我去廷根大学做医疗讲座，普及一下医疗知识，顺便给医院做一个宣传。"] = "Директор нашей больницы хочет, чтобы я поехал в Тингенский университет, чтобы прочитать медицинскую лекцию, популяризировать некоторые медицинские знания и, кстати, продвигать больницу.",
    ["我们卖很便宜的，质量很好的。"] = "Мы продаем их очень дешево, а качество отличное.",
    ["我们好不容易攒够了这些钱！为什么不能省着点用……"] = "Мы так старались накопить эти деньги! Почему мы не можем быть более бережливыми...",
    ["我们提供各式咖啡，现在更推荐费尔默咖啡，它来自南大陆帕斯河谷。当然，如果你喜欢，我们还有好喝的红茶和甜冰茶。"] = "Мы предлагаем различные сорта кофе, и в настоящее время мы рекомендуем кофе Fermo, который производится в долине Пас на Южном континенте. Конечно, если хотите, у нас также есть вкусный черный чай и сладкий чай со льдом.",
    ["我们有四位姑娘，人称“四颗宝石”。您想先从哪颗开始？ "] = "У нас есть четыре женщины, которых называют «Четыре драгоценности». С какой из них вы бы хотели начать?",
    ["我们结婚这么多年，我从来都没有问你要过什么……"] = "Мы женаты столько лет, и я никогда ни о чем тебя не просил...",
    ["我们能拥有一个愉快且完美的湖边约会！"] = "Мы можем устроить приятное и идеальное свидание на берегу озера!",
    ["我们要不要告诉警察叔叔？"] = "Должны ли мы сказать полицейскому?",
    ["我们说的话，只是在担心房子的安危！"] = "То, что мы сказали, было просто из заботы о безопасности дома!",
    ["我们还是警察？"] = "Мы все еще полиция?",
    ["我们都看见了，这么多天，这个屋子里根本没人住。"] = "Мы все это видели; за столько дней в этом доме вообще никто не жил.",
    ["我会在这里呆到天亮……"] = "Я останусь здесь до рассвета...",
    ["我住了许久院，失去了工作、失去了财富，更失去了家庭……"] = "Я надолго попал в больницу, потерял работу, потерял богатство и даже потерял семью...",
    ["我倒是不介意赚这种钱……但我年纪大了，身上一堆病，老乞丐也不会来找我做这最后一单。"] = "Я-то не против подзаработать... но я уже стар и весь больной, старый нищий не обратится ко мне за этой последней работёнкой.",
    ["我先去拉姆德古堡安抚吉娜，然后和吉娜借钱去看莉莉，她一向会满足我的所有请求。"] = "Сначала я отправлюсь в замок Ламуд успокоить Джину, а затем одолжу у неё денег, чтобы навестить Лили — она всегда исполняет любые мои просьбы.",
    ["我再努力一些……或者等茜茜成为政府雇员，会找到欢迎我们的地方生活的。"] = "Я буду работать усерднее... или когда Чичи станет государственным служащим, мы найдем место, где нам будет удобно жить.",
    ["我写不出来……一点灵感都没有……一个疯狂的冒险家到底该怎么写才够疯狂？"] = "Я не умею писать... У меня вообще нет вдохновения... Как именно надо написать сумасшедшего искателя приключений, чтобы он был достаточно сумасшедшим?",
    ["我刚吃下了一片神秘卷心菜，感觉自己体内充满了隐秘的力量。"] = "Я только что съел кусочек загадочной капусты и почувствовал, как мое тело наполняется скрытой силой.",
    ["我前世是个厨师？拿手菜是烤乳鸽？所以我被惩罚不能变成鸽子，而是在这里喂鸽子？！"] = "Я был поваром в прошлой жизни? Моей специальностью была жареная кабачка? Получается, меня наказывают тем, что я не могу превратиться в голубя, а вместо этого кормлю голубей здесь?!",
    ["我原本不打算给陌生人留下时尚会员的位置……直到看见你从花径间走来。不过想拿到邀请函的话，还是得先通过我的品鉴。"] = "Изначально я не собирался оставлять членство в модном клубе незнакомцу... пока не увидел тебя, идущего по цветочной тропинке. Однако, если вы хотите получить приглашение, вам все равно придется сначала пройти мой тест на оценку.",
    ["我原本是个还不错的工人，有个妻子和两个可爱的孩子，直到几年前的一场传染性疾病……"] = "Раньше я был приличным работником, имел жену и двоих прекрасных детей, пока несколько лет назад не заболел инфекционным заболеванием...",
    ["我发誓以后再也不接所谓的“特殊服务”了，气得我皱纹都出来了！"] = "Клянусь, я больше ни за что не возьмусь за так называемые «особые услуги» — от злости у меня даже морщины проступили!",
    ["我受够了！无论是新鲜的牡蛎、变成钱的牡蛎还是散发着牡蛎味的丈夫！"] = "С меня хватит! И свежих устриц, и устриц, превращенных в деньги, и мужа, который пропах этими устрицами!",
    ["我只想再找一次……还想最后一次……"] = "Я просто хочу найти его еще раз... хотя бы в последний раз...",
    ["我只是个路人，对字母和知识有些兴趣罢了。"] = "Я просто прохожий, питающий некоторый интерес к грамоте и знаниям.",
    ["我只是在陈述事实，奶奶。"] = "Я просто констатирую факты, бабушка.",
    ["我只是恰好想亲手触摸几幅画……"] = "Просто мне захотелось прикоснуться к нескольким картинам собственными руками...",
    ["我只是感慨他们竟然能克制住赌场的诱惑。"] = "Я просто сокрушаюсь, что они действительно смогли устоять перед искушением казино.",
    ["我只能给你非处方药，处方药需要我叔叔问诊后才能买哦。"] = "Я могу дать вам только лекарства, отпускаемые без рецепта. Лекарства по рецепту можно купить только после консультации моего дяди.",
    ["我可以的！我未来还想和爷爷您一样，去周日免费学校教大家学习呢。"] = "Я могу сделать это! В будущем я хочу быть таким, как ты, дедушка, и пойти в воскресную бесплатную школу, чтобы всех учить.",
    ["我可以胜任很多工作，我本该是个好工人……"] = "Я могу справиться со многими работами. Я должен был быть хорошим работником...",
    ["我可是这里的灌酒大师！老板次次都夸我能让客人多喝几杯 ，但是在他这里，我一点成就感都没有。"] = "Я здешний мастер спаивания! Хозяин вечно хвалит меня за умение раскрутить гостей еще на пару бокалов... но рядом с ним я вообще не чувствую никакого удовлетворения.",
    ["我吗？乐意为您效劳，不过请你等我长大一些，至少要拿得动剪刀和熨斗。"] = "Мне? Я был бы рад служить вам, но, пожалуйста, подождите, пока я немного подрасту — по крайней мере, пока я не смогу обращаться с ножницами и утюгом.",
    ["我吗？噢……我的故事并不好玩，我大概会在这里过无聊的一生。"] = "Мне? Ох... моя история не очень интересна; Наверное, я проведу здесь свою скучную жизнь.",
    ["我听亚特先生说，他今年打算把大部分葡萄都发酵成酒，还托我来问你需不需要……"] = "Я слышал от господина Арта, что он планирует в этом году перебродить большую часть винограда в вино, и он даже просил меня спросить вас, нужно ли вам...",
    ["我听父亲提到过这一点，他也曾参加过赛艇俱乐部，他总说大学的灵魂在河边而非图书馆。"] = "Я слышал, как мой отец упомянул об этом. Он также участвовал в гребном клубе. Он всегда говорил, что душа университета – у реки, а не в библиотеке.",
    ["我和海因茨在为明天的比赛训练，我们同隔壁系的艺术团组织了一场投球友谊赛。"] = "Мы с Хайнцом готовимся к завтрашним соревнованиям; мы организовали дружеский питчинг с творческой труппой соседнего факультета.",
    ["我和爸爸妈妈哥哥同一天生日，每年生日聚会，我都在写作业，让他们在那里忙……"] = "У моего папы, мамы, брата и меня день рождения в один и тот же день. Каждый год на вечеринке по случаю дня рождения мне приходится делать домашнее задание, пока они заняты...",
    ["我哪有那么多钱！再说了，老爸老妈身体健康，老妹懂事又会读书，每年这个时候还能一起吃饭，没有比这更好的礼物了。"] = "Откуда у меня столько денег! Да и потом: отец с матерью здоровы, сестрёнка благоразумная и отлично учится, а мы каждый год в это время можем собраться за одним столом — лучшего подарка и быть не может.",
    ["我在棕熊的对手身上下了注，需要一些，简单的保障。"] = "Я поставил на противника Бурого Медведя, и мне нужны некоторые... простые гарантии.",
    ["我在海上混了二十年，就没见过哪条船敢这么吹牛。要我说，可别首航就沉了！"] = "Я двадцать лет в море и никогда не видел, чтобы корабль так хвастался. Если вы спросите меня, я надеюсь, что он не затонет во время своего первого плавания!",
    ["我在画莱茵的猫，她是对面花店的主人，她和她的猫一样可爱，对吗？"] = "Я рисую кошку Рейн, она владелица цветочного магазина через дорогу, она такая же милая, как и ее кот, правда?",
    ["我在附近已经扫了很久了！都是我一个人。"] = "Я уже давно подметаю в этих краях! И всегда в полном одиночестве.",
    ["我妻子才刚怀孕，恐怕还是稳妥行事比较好。"] = "Моя жена просто беременна, боюсь, лучше перестраховаться.",
    ["我始终相信，医生称量的是心跳，不是钱袋里的纸币。但有些人不明白，我也不愿与他们同流合污。"] = "Я всегда считал, что врач взвешивает удары сердца, а не купюры в кошельке. Но некоторые люди этого не понимают, и я не желаю валяться вместе с ними в этой грязи.",
    ["我宁愿去刷马桶，也不想去他那儿。"] = "Я лучше пойду мыть туалеты, чем пойду к нему.",
    ["我完了！我完了！"] = "Мне конец! Мне конец!",
    ["我实在是应付不了这么多人的大场面啊，我宁愿多做几台手术！我现在连演讲大纲都还没头绪。 "] = "Я действительно не могу справиться с такой большой толпой. Я лучше сделаю еще несколько операций! Я пока даже понятия не имею о плане лекции.",
    ["我对不起他，也害怕未来……在这廷根，一个学文学的，出路究竟在哪？ "] = "Я его подвела и боюсь будущего... В этом Тингене для изучающего литературу где выход?",
    ["我对未来的一切都充满希望，相信很快我们就能在贝克兰德见面。"] = "Я полон надежд на будущее и верю, что совсем скоро мы встретимся в Бэкланде.",
    ["我就是个送货的，能有什么坏心思？"] = "Я всего лишь доставщик, какие у меня могут быть дурные намерения?",
    ["我就是想要一串自己的项链，有什么错！！！"] = "Я просто хочу собственное ожерелье. Что тут такого!!!",
    ["我就看看……妈妈昨晚又咳嗽了，说、说她想喝肉汤……"] = "Я просто смотрю... Мама вчера вечером снова кашляла и сказала, сказала, что хочет пить мясной суп...",
    ["我就看看。"] = "Я просто смотрю.",
    ["我就要成为明星了！"] = "Я собираюсь стать звездой!",
    ["我已经在附近找过了，没看见哪怕一根猫毛。"] = "Я уже осмотрелся, ни одной кошачьей шерсти не увидел.",
    ["我已经是个没有激情的老人了，客人肯定更喜欢他那样热情洋溢的摊主。"] = "Я уже старик без страсти; покупатели должны предпочесть такого же энтузиазма владельца ларька, как он.",
    ["我已经看到赢钱的画面了，只差你的投资！"] = "Я уже видел сцену выигрыша денег; не хватает только ваших инвестиций!",
    ["我已经能预见弗兰奇先生找你收精神赔偿费的场景了。"] = "Я уже прямо вижу, как мистер Франки требует с тебя компенсацию за моральный ущерб.",
    ["我已经调查清楚了，那个人在这片卖的炸鱼薯条最美味。"] = "Я уже все тщательно исследовал; этот человек продает самую вкусную рыбу с жареным картофелем в этом районе.",
    ["我希望您能帮我发掘这座城市里更多的幽默，我会给您相应的报酬。"] = "Я надеюсь, вы поможете мне отыскать больше поводов для смеха в этом городе, и я щедро вознагражу вас.",
    ["我希望茜茜能有一个安静的环境学习，文法、数学和法律……<P_Heart>（叹了一口气）</>每一个都很困难，而市场真的太吵了。"] = "Я надеюсь, что у Чичи будет спокойная обстановка для изучения грамматики, математики и права... <P_Heart> (Вздыхает) </> Каждый из них очень сложен, а рынок действительно слишком шумный.",
    ["我带他去看了我付过订金的公寓，结果他对着房子骂了一声转身就走，说他不租了。"] = "Я отвел его посмотреть квартиру, за которую уже внес залог, а он лишь обругал дом, развернулся и ушел, заявив, что снимать ее не станет.",
    ["我很同情被他点到的姐妹们。"] = "Я очень сочувствую сестрам, которых он выбирает.",
    ["我很喜欢戴莉女士那些夸张的、令人害羞的玩笑，她被调去贝克兰德教区后，我们都很想念她。"] = "Мне очень понравились преувеличенные и смущающие шутки мисс Дейли. Мы все скучали по ней после того, как ее перевели в Баклундскую епархию.",
    ["我很理解他们的心情，也羡慕他们还能找到重要的人的遗物。"] = "Я понимаю их чувства и завидую тому, что они все еще могут найти реликвии кого-то важного.",
    ["我很遗憾。"] = "Мне очень жаль это слышать.",
    ["我得找个借口请个假，你们觉得头痛这个理由怎么样？"] = "Мне нужно найти предлог, чтобы попросить отпуск. Что вы думаете об оправдании «головной боли»?",
    ["我忍无可忍，向报社举报了他们，当然结果是——我被吊销医生执照。"] = "Я не выдержал и сообщил об этом в газету. Результат, конечно же, был – у меня отозвали медицинскую лицензию.",
    ["我快三天没吃东西了……没有一份工作，我就要饿死了……"] = "Я не ел почти три дня... Если не найду работу, я просто умру с голоду...",
    ["我想向您请教一下，刚刚那段对话在人类的语言范畴内，是否能算有趣？"] = "Я хотел бы вас спросить, в рамках человеческого языка, можно ли считать интересным тот разговор, который только что произошел?",
    ["我想问个问题，这些细长的船，一百多年都没变过吗？"] = "Позвольте спросить: неужели эти узкие лодки ничуть не изменились более чем за сто лет?",
    ["我想鲁恩人和因蒂斯人也没什么不同……过早地成为小有名气的戏剧演员就会有这样的困扰，但我只想安静地完成学业。"] = "Я не думаю, что ленезе чем-то отличаются от интизианцев... Слишком рано стать известным театральным актером приносит такие неприятности, но я просто хочу спокойно закончить учебу.",
    ["我想，他一定也希望看到这片领地重新焕发生机的样子。"] = "Я думаю, он также должен надеяться, что эта территория вновь обретет свою жизнеспособность.",
    ["我感觉到有某种存在降临了！"] = "Я чувствую, что появилось какое-то существование!",
    ["我感觉，我的心脏即将处于爆炸的边缘，我的血液现在就像是沸腾的开水！手、胳膊、腿、脚，全在抖！我待会儿还有手术，我现在这样连手术刀都握不住了！"] = "Я чувствую, что мое сердце вот-вот взорвется, а моя кровь сейчас подобна кипящей воде! У меня руки, руки, ноги, ступни, все трясется! У меня потом операция, а я даже скальпель так держать не могу!",
    ["我愿意一天只要10便士，求求您给我这个工作机会吧，我父亲病了，得靠这些钱买药……"] = "Я готов работать за 10 пенсов в день, пожалуйста, дайте мне эту возможность трудоустройства, мой отец болен и мне нужны эти деньги, чтобы купить лекарства...",
    ["我愿意投资你们！投资传统比投资新兴股票更优雅。"] = "Я готов вложиться в вас! Инвестировать в традиции куда элегантнее, чем в новые сомнительные акции.",
    ["我打算把这些葡萄做成酒，只需要把它们放进木桶，再等待发酵……这一定是小镇上最好喝的葡萄酒！"] = "Я планирую превратить этот виноград в вино; Мне просто нужно положить их в бочку и подождать, пока они забродят... Это наверняка будет самое вкусное вино в городе!",
    ["我承认他们在艺术学派的演出中比我们更受欢迎，但是在比赛里肯定是我们更出色！"] = "Признаюсь, на спектаклях Школы искусств они популярнее нас, но на соревнованиях мы однозначно лучше!",
    ["我把东西放在了xxx的一个保险箱里，你想知道的东西都在里面了。"] = "Я положил вещи в сейф в ХХХ, и все, что вы хотите знать, находится внутри.",
    ["我把这件事和奥兰德也说了，那小子不是家里很有钱吗，扬言要把所有的占卜都试一遍。"] = "Я тоже рассказал об этом Орланду. Разве его семья не очень богатая? Он пригрозил попробовать все гадания.",
    ["我推荐苏尼亚海的珊瑚岛，那里有位“水手”途径的民宿老板，他的房子建在会移动的巨龟背上。"] = "Рекомендую Коралловый остров в море Сония. Там живет хозяин тропы «Матрос», и его дом построен на спине гигантской движущейся черепахи.",
    ["我收藏了些很有趣的作品。比如那幅《梦见星空的羔羊》，盯着看久了会发现云朵在缓慢流动。"] = "Я собрал несколько очень интересных работ. Например, та картина «Ягненок, мечтающий о звездном небе»; если вы будете долго смотреть на него, вы обнаружите, что облака медленно движутся.",
    ["我旁边的这位吗，她是我奶奶。别看她现在年纪大了有点健忘，年轻时是一位优秀的医生。"] = "Тот, что рядом со мной? Она моя бабушка. Не смотрите на нее как на немного забывчивую теперь, когда она старая; в молодости она была отличным врачом.",
    ["我早就购置了一年的啤酒份额，好东西就是要用来分享啊！"] = "Я уже купил пива на год; хорошие вещи предназначены для того, чтобы ими делились!",
    ["我明白了！我有灵感了！应该这么写！"] = "Я понимаю! У меня есть вдохновение! Я должен написать это так!",
    ["我明白了，谢谢您，伦纳德先生。"] = "Я понимаю, спасибо, мистер Леонард.",
    ["我是个慷慨的赌徒，只是需要一位……可靠的协助者。"] = "Я щедрый игрок, которому просто нужен... надежный помощник.",
    ["我是个流浪汉……我的猫可不是流浪猫……"] = "Я бездомный... мой кот не бездомный...",
    ["我是从乡下来城里找工作的，急需住处，您看您能不能帮忙介绍一下……"] = "Я приехал в город из сельской местности в поисках работы, и мне срочно нужно жилье. Не могли бы вы помочь мне представить его...",
    ["我是廷根之王！"] = "Я король Тингена!",
    ["我是第一次来，这里……有什么可看的？ "] = "Я здесь впервые... есть ли тут что-нибудь интересное?",
    ["我是说，这能让我一直想着你。"] = "Я имею в виду, это позволит мне продолжать думать о тебе.",
    ["我是铁十字街之王！"] = "Я король Айрон-Кросс-стрит!",
    ["我是问你，好不好看！"] = "Я вас спрашиваю, хорошо это выглядит или нет!",
    ["我最近捐赠了廷根市的铁路建设，这里现在新开了几条通往鲁恩其他城市的列车。"] = "Недавно я пожертвовал деньги на строительство железной дороги в Тингене, и теперь в Лоене ходит несколько новых поездов, ведущих в другие города.",
    ["我最近每天脑子里都是斗邪恶。上班想着，躺在公寓里也想着。"] = "В последнее время я каждый день думаю о борьбе со злом. Я думаю об этом на работе, и думаю об этом, лёжа в квартире.",
    ["我有点事先走了，你也早点出来吧，在厕所待太久对身体不好。"] = "У меня появились дела, так что я пойду. И ты выходи поскорее, долго сидеть в уборной вредно для здоровья.",
    ["我有预感，这次回去一定能翻盘。"] = "У меня есть предчувствие, что на этот раз я обязательно смогу переломить ситуацию.",
    ["我朋友买了幅《午夜舞会》，结果每天凌晨三点画中人都会消失一位。<P_Heart>（无奈）</>现在那幅画挂在“隐者”女士的船舱里。"] = "Мой друг купил картину под названием «Полуночный бал», и в результате один человек на картине исчезает каждый день в 3 часа ночи. <P_Heart> (беспомощно)</> Теперь эта картина висит в каюте дамы «Отшельника».",
    ["我服侍少爷已经很久了。他是家族最年轻的孩子，总想着脱离家族的荫蔽，自己出来闯荡。几年前，我陪同他来到廷根。可惜……"] = "Я долгое время служил молодому господину. Он младший ребенок в семье и всегда хочет вырваться из семейного приюта и отправиться в путь самостоятельно. Несколько лет назад я сопровождал его в Тинген. К сожалению...",
    ["我本想呼唤你的出现，你看，这里就正对着你的窗户。"] = "Я хотел позвать на помощь твое появление; смотри, это прямо напротив твоего окна.",
    ["我本是圣赛琳娜广场舞组织的领舞者，但是一场繁忙的期末考试让我失去了这个位置……"] = "Я была ведущей танцовщицей кадрильной организации Святой Селены, но напряженный период выпускных экзаменов заставил меня потерять эту должность...",
    ["我本来要去诊所给一个小女孩表演的，但是我从梯子上摔下来，把手摔到了。我现在什么都拿不稳。"] = "Я должен был пойти в клинику и устроить представление для маленькой девочки, но упал со стремянки и повредил руку. Теперь я даже удержать ничего толком не могу.",
    ["我正在追寻一位“守护者”的往日回响，他的命运乐章，碎裂成了三个片段，遗失在廷根各处。"] = "Я иду по следам былых эхо одного «Хранителя». Мелодия его судьбы раскололась на три фрагмента, затерянных по всему Тингену.",
    ["我正在追寻一位“老师”的往日回响，他的命运乐章，碎裂成了三个片段，遗失在古堡各处。"] = "I am pursuing the past echoes of a \"teacher.\" His movement of fate has shattered into three fragments, lost throughout the ancient castle.",
    ["我正在追寻一位“魔女”的往日回响，她的命运乐章，碎裂成了三个片段，遗失在霍纳奇斯花海各处。"] = "I am pursuing the past echoes of a \"Witch.\" Her movement of fate has shattered into three fragments, lost throughout the Hornacis Sea of Flowers.",
    ["我正要赶去上课，真的没时间……嗯？原来是你，吓我一跳。"] = "Я спешу на занятия, у меня правда нет времени... хм? Так это ты, ты меня напугал.",
    ["我每天都在这等，想用最漂亮的样子迎接他，但我今天把帽子忘在家里了。"] = "Я жду здесь каждый день, желая встретить его во всей красе, но сегодня я забыла шляпку дома.",
    ["我每天都好饿，我也想像你一样总是能吃饱肚子……"] = "Я так голоден каждый день и хочу есть досыта, как ты...",
    ["我每次都害怕再也钻不出来……"] = "Каждый раз боюсь, что уже никогда не смогу вылезти обратно...",
    ["我父亲不会允许我嫁给一个只能租房的男人……"] = "Отец никогда не позволит мне выйти замуж за мужчину, способного лишь снимать жилье...",
    ["我父亲在几年前的战争去世了，颅骨粉碎性骨折。不过还好，父亲当场身亡，没有经历太多痛苦。"] = "Мой отец погиб на войне несколько лет назад от оскольчатого перелома черепа. Но, к счастью, мой отец погиб на месте и особо не пострадал.",
    ["我特地准备了这样一套服饰，用拜亚姆当地人的话来说，这就是文明人的标志！"] = "Я специально подготовил такой наряд; по словам местных жителей Баяма, это символ цивилизованного человека!",
    ["我猜是去向坎柏莉小姐求爱了。"] = "Думаю, он пошел ухаживать за мисс Кэмпбелл.",
    ["我猜是爱丽儿小姐。"] = "Думаю, это была мисс Ариэль.",
    ["我现在可是序列五的淑女！"] = "Теперь я леди Последовательности 5!",
    ["我理解他，剧院的工作总是忙碌的，他作为经理工作就更多了。"] = "Я понимаю его. Работа в театре всегда загружена, а как у менеджера у него работы еще больше.",
    ["我甚至幻想我养的宠物能变身为人……成为家里的一份子……"] = "Я даже мечтаю о том, как мой питомец превратится в человека... станет частью семьи...",
    ["我的丈夫布拉德利总是不着家，就算回来也是披星戴月。"] = "Моего мужа Брэдли вечно нет дома, а если он и возвращается, то глубокой ночью.",
    ["我的咸鱼……我的猫……到底跑哪去了……"] = "Моя соленая рыбка... мой кот... куда же они убежали...",
    ["我的尊名是——洞察一切的圣灵，黄黑之王的眷者，梦境与心灵的旅者。"] = "Моё почетное имя — Святой Дух, который видит всё, Благословенный Короля Желтого и Чёрного, Путешественник Снов и Разумов.",
    ["我的朋友琼，她刚结束一段旅程，我们早就写信约好，去霍伊大学拜访从前的老师。"] = "Моя подруга Джоан только что закончила путешествие. Мы давно написали друг другу, чтобы навестить нашего бывшего преподавателя в университете Хоя.",
    ["我的画室欢迎一切想要交朋友的人！如果你是一位活泼开朗的顾客，那么整个画室的大画家们都会很喜欢你！"] = "Моя студия приветствует всех, кто хочет подружиться! Если вы живой и веселый клиент, то вы понравитесь всем замечательным художникам студии!",
    ["我的诗，好像只肯生在这里的灯光下。换个地方，我怕就写不出来了。 "] = "Мои стихи словно рождаются лишь под этим светом. Боюсь, в другом месте я уже не смогу ничего написать. ",
    ["我相信你肯定不愿意错过这次赚钱的好机会，拳王阿比对战下一个倒霉蛋，赔率一比三十！"] = "Я верю, что вы не захотите упустить эту прекрасную возможность заработать деньги. Чемпион Аби против следующего неудачника, шансы один к тридцати!",
    ["我看你面善，帮朋友个忙。你拿一包去，走一圈，帮我验证验证，是不是全天下的猫都一样馋？我有预感， 这将成为一门好生意！"] = "Я вижу, у тебя доброе лицо, окажи мне услугу как другу. Возьми сумку, прогуляйся и помоги мне проверить, все ли коты в мире такие жадные? Я чувствую, что это станет хорошим бизнесом!",
    ["我看她们是把金子当花瓣撒吧？"] = "Думаю, они рассыпают золото, как лепестки?",
    ["我看得出，这是你内心的渴望。我愿意给好学的人一些优惠。只要五便士，我就带你整个廷根看一圈。"] = "Я вижу, что это ваше внутреннее желание. Я готов дать некоторые скидки тем, кто хочет учиться. Всего за пять пенсов я проведу вам экскурсию по всему Тингену.",
    ["我看您穿得不差，还是租好一点的地方吧。"] = "Ты выглядишь хорошо одетым, тебе следует снять жилье получше.",
    ["我看看……有效治疗耳部疾病？！"] = "Дайте взглянуть... Эффективное лечение ушных болезней?!",
    ["我真的很准的！虽然我是一位驯兽师，但是一点不比俱乐部里的占卜师们差。"] = "Я очень точен! Хоть я и укротитель зверей, я не хуже прорицателей клуба.",
    ["我知道……所以第一堂课我不收钱。我只是想证明，我能教好。总得……总得有个开始。"] = "Я знаю... поэтому не беру деньги за первый урок. Я просто хочу доказать, что могу хорошо преподавать. Должно быть... должно быть начало.",
    ["我知道您，和警察有关系的年轻人。"] = "Я знаю тебя, молодого человека, имеющего связи с полицией.",
    ["我知道，他是为了保护廷根而牺牲的。"] = "Я знаю, он пожертвовал собой, чтобы защитить Тингена.",
    ["我知道，夫人，是火车站。"] = "Я знаю, мэм, это вокзал.",
    ["我知道，小甜心，你爱我的对吧！我也爱你！"] = "Я знаю, дорогая, ты меня любишь, правда! Я тоже тебя люблю!",
    ["我第一笔成功投资是脚踏车公司的股票，我当时并没有足够的钱购买股票，但我父亲教了我一种投资技巧。"] = "Моей первой успешной инвестицией были акции велосипедных компаний. В то время у меня не было достаточно денег, чтобы покупать акции, но мой отец научил меня технике инвестирования.",
    ["我给你三倍的报酬，你只为我一个人写。今晚就跟我走吧。 "] = "Я заплачу тебе тройную награду, если ты напишешь только для меня. Пойдем со мной сегодня вечером.",
    ["我给你开一些药方吧，价格就按照医院的五分之一来。"] = "Я выпишу вам рецепт, и цена будет равна одной пятой того, что он стоит в больнице.",
    ["我绝对不会因为一场精彩的拳击赛而毁坏誓言……"] = "Я совершенно не нарушу своей клятвы из-за прекрасного боксерского поединка...",
    ["我老了。不清楚。不是我。我教你，你向前走两条街，再左转，再右转，再直走，去那里投诉……"] = "Я старый. Я не знаю. Это был не я. Я тебя научу: пройди вперед две улицы, потом поверни налево, потом направо, потом прямо, пойди туда подать жалобу...",
    ["我耳背，新来的小家伙都嚷了些啥？"] = "Я плохо слышу. О чем кричал этот новенький?",
    ["我被委托收集一些有趣的人类对话，为某位作家提供写作灵感。"] = "Мне поручили собрать несколько занятных человеческих бесед, чтобы подарить вдохновение одной писательнице.",
    ["我要去找小爱丽丝，找她好好哭一场……"] = "Я найду маленькую Алису и поплакаю вместе с ней...",
    ["我要变有钱！"] = "Я стану богатым!",
    ["我要当全廷根最有钱！"] = "Я хочу быть самым богатым человеком во всем Тингене!",
    ["我要把小萨拉的消息告诉母亲，她一定会高兴的。"] = "Я хочу рассказать маме о новостях маленькой Сары; она обязательно будет рада.",
    ["我要用塔罗算今晚管家做什么晚饭——别再是那些菜叶子了！再用灵摆问明天翘课会不会被我妈发现！"] = "Я хочу использовать Таро, чтобы подсчитать, что дворецкий готовит сегодня на ужин — пусть это снова не будут листья овощей! Затем с помощью маятника спросите, узнает ли моя мама, если я пропущу занятия завтра!",
    ["我觉得……"] = "Я думаю...",
    ["我觉得有必要定期让家庭医生检查一下身体，虽然这么说不好，但我可不想像他那样早早地失去生命。"] = "I think it's necessary to have a family doctor check my Health regularly. Although it's unpleasant to say, I don't want to lose my life early like he did.",
    ["我觉得这位{{先生|女士}}的审美还不赖，如果你考虑加入廷根时尚协会的话……"] = "Мне кажется, у {{господина|госпожи}} весьма недурной вкус. Если вы подумываете вступить в Модную ассоциацию Тингена...",
    ["我认为可以普及一下常见急救方法，应对一些日常的突发情况。"] = "Я думаю, что мы можем популяризировать некоторые распространенные методы оказания первой помощи в некоторых повседневных чрезвычайных ситуациях.",
    ["我认为，你的妆容和气色，都和她们没区别。"] = "Я думаю, твой макияж и цвет лица ничем не отличаются от их.",
    ["我让他们在门口等着我，我上去拿攻略。但一回来就找不见人了！"] = "Я велел им подождать меня у входа, пока сбегаю наверх за руководством. Но когда вернулся — их уже и след простыл!",
    ["我试着给自己找些事情做。扫了几年地，灰尘起来又落下。奇怪的是，心反而慢慢静了。"] = "Я стараюсь найти себе занятие. После нескольких лет подметания пола пыль снова поднимается и опадает. Странно то, что мое сердце постепенно успокоилось.",
    ["我说——这难道就是它扩建后的样子吗？那些铁路匠究竟是怎么工作的！"] = "Я спросил — действительно ли это так выглядит после расширения? Как же работают эти железнодорожники!",
    ["我说的这些报纸和杂志，都值得一看。朋友，时间就是知识啊！"] = "Газеты и журналы, которые я упомянул, стоит прочитать. Друг, время – это знание!",
    ["我赞同小姐的想法，她有权选择自己的人生。"] = "Я согласен с идеей молодой леди; она имеет право выбирать свою жизнь.",
    ["我赢过的官司，比铁十字街的石头还多！"] = "Я выиграл больше судебных процессов, чем камней на улице Железного Креста!",
    ["我跑到门口的时候差点被你的高音震回去。"] = "Я добежал до дверей, и от твоей высокой ноты меня чуть обратно не отшвырнуло.",
    ["我跑的远洋航线，在群岛一呆就是几个月，不少人就在停靠的港口找当地女人成了第二个家。"] = "Я управляю океанскими маршрутами, оставаясь на архипелаге по несколько месяцев. Многие люди находят местных женщин в портах, в которых они пришвартовываются, и становятся вторым домом.",
    ["我跟你讲，这位贝朵兰女士可是被女神选中的传奇工人。"] = "Позвольте мне сказать вам, что эта госпожа Бедолан — легендарная работница, избранная Богиней.",
    ["我跳的时候，眼睛会看人——我看到了谁，谁今晚就别想忘了我。 "] = "Когда я танцую, мои глаза наблюдают за людьми — на кого бы я ни посмотрел, сегодня вечером меня не забудут.",
    ["我还不是呢，你真讨厌……"] = "Я еще нет, ты так раздражаешь...",
    ["我还从集市换了枚旧护符<P_Heart>（从颈间取出半片银叶）</>，后来发现上面附着强烈的情感印记，现在把它当灵性安抚器用。"] = "А еще я выменял на рынке старый амулет <P_Heart>*(достает с шеи половинку серебряного листка)*</>, а позже обнаружил на нем сильнейший эмоциональный отпечаток и теперь использую его для успокоения духовности.",
    ["我还是不太想承认你的时尚品味。"] = "Я до сих пор не хочу признавать твой модный вкус.",
    ["我还是再看看吧。"] = "Я лучше посмотрю еще раз.",
    ["我还等着付房租，阁下，哪怕我现在就坐在劳工阶层住房改善协会门口，没有钱他们也会让我睡大街的！"] = "Я все еще жду оплаты аренды, сэр. Даже если бы я сейчас сидел у дверей Ассоциации улучшения жилищных условий рабочего класса, они все равно заставили бы меня спать на улице, если бы у меня не было денег!",
    ["我还给她买了苹果，你也一块带过去吧。"] = "Еще я купила ей яблок, их тоже надо взять с собой.",
    ["我还记得它饿极了吃老鼠的样子，真是可怜的小流浪狗……"] = "Я до сих пор помню, каким голодным он был, когда ел мышей. Это была такая бедная маленькая бездомная собачка...",
    ["我这有个钢铁厂加班名额，我们近期要搬家，这个名额便宜点卖给你，怎么样？"] = "У меня есть место сверхурочной работы на сталелитейном заводе, мы скоро переезжаем, я продам тебе это место по дешевке, как насчет этого?",
    ["我这里是有档次的公寓，这在铁十字街可不多见。"] = "У меня приличные апартаменты, а такое на улице Железного Креста — большая редкость.",
    ["我这阳台只漏了个小洞，随便补补就行。包人工2苏勒，怎么样？"] = "У меня на балконе только маленькая дырка, надо ее залатать. 8 суле, включая работу, как насчет этого?",
    ["我长大了，花儿们也更繁茂了。这里变成了一个市集，再也不适合阅读。"] = "Я подросла, и цветы стали пышнее. Это место превратилось в рынок и больше не пригодно для чтения.",
    ["我问的是我的历史考试能不能通过。你知道的，我虽然很想认真听，但是这门课实在是催眠啊。"] = "Я спросил, смогу ли я сдать экзамен по истории. Знаете, хотя мне очень хочется слушать внимательно, этот курс действительно гипнотический.",
    ["我问的是我的历史考试能不能通过。虽然我对历史挺感兴趣的，但是我一背书就头疼啊。"] = "Я спросил, сдам ли я экзамен по истории. История мне вроде интересна, но как зубрить начну — сразу голова раскалывается.",
    ["我闻到了，罪恶、猥琐、瘟疫的气息……"] = "Я чую его... запах греха, похоти и чумы...",
    ["我非常无辜，我只不过在某个夜晚，恰好路过了这家画廊……"] = "Я совершенно невиновен, просто однажды вечером я проходил мимо этой галереи...",
    ["我非常能够理解这片领地的主人的心情……"] = "Я очень понимаю чувства владельца этой земли...",
    ["我，我睡不着，我想妈妈……"] = "Я, я не могу спать, я скучаю по маме...",
    ["我，瑞奇·纽曼带来了廷根的新财路，诚邀有意者与我搭伙开店。"] = "Я, Рикки Ньюман, предложил новый способ заработка в Тингене и искренне приглашаю желающих сотрудничать со мной и открыть магазин.",
    ["我？不，我只是普通的学生。"] = "Мне? Нет, я обычный студент.",
    ["或者也可以先付一便士，体验黑夜奉献碑讲解。再加一便士还能获得照相服务，怎么样，多么合算的买卖，你想要哪个？"] = "Или вы можете сначала заплатить один пенсов, чтобы получить представление о Ночном мемориальном памятнике. Добавьте еще копейку и вы сможете получить фотоуслуги. Как насчет этого, какая экономически эффективная сделка, какую вы хотите?",
    ["或者你愿不愿意尝试把台上那座肉山推下擂台？不要小瞧自己的实力！"] = "Или хочешь попробовать спихнуть ту гору мяса с ринга? Не недооценивай свои силы!",
    ["或许你也听过他的名字。"] = "Возможно, вы тоже слышали его имя.",
    ["或许吧……但现实只会给每个人一次构图机会，只要有一张照片抓住某个瞬间……"] = "Возможно... но реальность дает каждому только один шанс составить кадр. Пока одна фотография запечатлевает определенный момент...",
    ["或许您可以来一杯纯麦芽酿的朗齐，听说海盗也喜欢这种酒，虽然我没见过任何活海盗。"] = "Быть может, выпьете бокал чистого солодового ланти? Говорят, пираты тоже любят эту выпивку, хоть я и не видел ни одного живого пирата.",
    ["或许我可以为他献上一束花。"] = "Быть может, мне стоит возложить для него букет цветов.",
    ["或许我该想办法说清楚一些，或者，我该多解释一些……"] = "Возможно, мне следует найти способ прояснить это или объяснить больше...",
    ["或许这个花房除了贩卖鲜花，也贩卖着虔诚。"] = "Возможно, в этом цветочном магазине продаются не только живые цветы, но и благочестие.",
    ["戴莉女士是一位天才非凡者，短短两年就晋升了序列7。"] = "Мисс Дейли была гениальным Потусторонним человеком, дошедшим до седьмой серии всего за два года.",
    ["所以你在？"] = "Так где же ты?",
    ["所以你打算……"] = "Итак, вы намерены...",
    ["所以你知道哪个占卜师最准吗？我让他先给我算晚饭的事，我急着知道！ "] = "Итак, вы знаете, какой прорицатель самый точный? Сначала я позволю ему рассчитать для меня ужин, я спешу узнать!",
    ["所以你觉得真正有需要的人不在诊所里？"] = "То есть вы думаете, что людей, которым действительно нужна помощь, нет в клинике?",
    ["所以啊，这一定是神意，要我好好珍惜家人。我发誓，只要我还做得动，每年的生日礼物都不会迟到！"] = "Итак, это, должно быть, воля Божья, желающая, чтобы я дорожил своей семьей. Клянусь, пока я еще могу работать, мои ежегодные подарки на день рождения никогда не опоздают!",
    ["所以您到底帮不帮我算呀，快帮我先算晚饭的事，我急着知道！ "] = "Так вы погадаете мне или нет? Скорее погадайте про ужин, мне не терпится узнать!",
    ["所以您的第二段尊名是黄黑之王的眷者。"] = "Итак, ваша вторая почетная награда — «Благословение Желтого и Черного Короля».",
    ["所以我叫上公寓里相熟的人一起打牌，兴致上来大吼了几声，结果……"] = "Поэтому я позвал в квартиру знакомых людей поиграть в карты, а когда настроение пришло, несколько раз взревел, и в результате...",
    ["所以我才要到这该死的集市调查！要是被我发现是谁干的，他就完蛋了！"] = "Вот почему я должен исследовать этот чертов рынок! Если я узнаю, кто это сделал, им конец!",
    ["所以我连夜收拾行李搬走了，看他还怎么用手杖捶门……喂，你为什么不说话？"] = "Поэтому я собрал свой багаж на ночь и уехал. Посмотрим, как он сможет стучать в дверь тростью... Эй, почему ты молчишь?",
    ["所以最后确认了吗？"] = "Итак, вы подтвердили это в конце концов?",
    ["所以观察有结果吗？"] = "Итак, есть ли результаты вашего наблюдения?",
    ["所以，你要不要一起进来，士兵？"] = "Итак, хочешь пойти с нами, солдат?",
    ["所以，在非凡世界一定要——“小心观众”。"] = "Поэтому в Необыкновенном Мире вы всегда должны: «Остерегайтесь зрителей».",
    ["所以，我从不停止创作。我想只要我写的够多，总会有人欣赏我的诗歌！"] = "Поэтому я никогда не перестаю творить. Думаю, если я буду писать достаточно много, кто-нибудь непременно оценит мои стихи!",
    ["所以，拜托您替我保守这个秘密。拜托您了！"] = "Так что, пожалуйста, сохраните для меня эту тайну. Пожалуйста!",
    ["所有信众都可以来这里寻求女神的指引。"] = "Все верующие могут прийти сюда в поисках руководства Богини.",
    ["手头确实不太宽裕，邦妮才被厂里开除，现在想给小孩凑齐学费都困难。"] = "У меня действительно туго с деньгами, Бонни только что уволили с фабрики, теперь трудно даже собрать деньги на обучение для детей.",
    ["打扰一下……你在葡萄架附近见过一个头发很长的人吗？"] = "Простите... вы не видели человека с очень длинными волосами возле виноградной решетки?",
    ["打算去二楼坐坐。上次遇到的那位姑娘，挺有意思的。 "] = "Собираюсь пойти на второй этаж и посидеть немного. Женщина, которую я встретил в последний раз, весьма интересна.",
    ["扔垃圾？哕，我就知道，我就知道休伯特先生每天晚上准时进入盥洗室很奇怪！"] = "Выбрасывать мусор? Ох, я знал это, я знал, что это странно, что мистер Хьюберт каждый вечер вовремя заходит в туалет!",
    ["托您的福，我的孩子康复啦。从死神手上走过，也不赌了，现在琢磨着重振家业呐！"] = "Благодаря вам мой ребенок поправился! Побывав на волосок от смерти, он бросил азартные игры и теперь думает, как возродить семейное дело!",
    ["把它们放到那边的笼子里，劳驾。"] = "Посадите их вон в ту клетку, будьте добры.",
    ["把您的手给我，别怕——我曾在贝克兰德的圣艾斯汀医院当过三年医生。"] = "Дай мне руку, не бойся — я три года работал врачом в больнице Святого Эстина в Баклунде.",
    ["抠门的老汤姆从没让那盏灯熄灭过，我们也没再听到过那奇怪的齿轮声。总之，赞美蒸汽！"] = "Скупой Старый Том больше ни разу не давал той лампе погаснуть, и мы больше не слышали того странного скрежета шестерёнок. В общем, слава Пару!",
    ["报告国王，这里还有个势力叫做“帽子帮”，也是一群和我们一样的流浪儿组成的。我们或许可以向他们求助！"] = "Доложите королю: здесь есть еще одна фракция, называемая «Шляпная банда», также состоящая из таких же уличных мальчишек, как и мы. Возможно, мы сможем попросить их о помощи!",
    ["抱歉……那款并不外售，是一名先生的定制款。"] = "Извините... этот не продается; это изготовленная на заказ вещь для джентльмена.",
    ["抱歉。今天……有些累了。"] = "Извини. Сегодня... Я немного устал.",
    ["抱歉抱歉！路上我遇见了一个很可怜的孩子，就施舍了他一枚硬币……"] = "Извините, извините! По дороге сюда я встретил очень жалкого ребенка и дал ему монету...",
    ["抱歉，{{先生|女士}}。我需要尽快完成出航准备，你可以找我的副手……"] = "Прошу прощения, {{господин|госпожа}}. Мне нужно как можно скорее завершить приготовления к отплытию, обратитесь к моему помощнику...",
    ["抱歉，{{先生|女士}}，我实在是太开心了！"] = "Извините, {{Г-н|Мисс.}}, я так рада!",
    ["抱歉，实在没有这种能力，截稿日？您是一位作家？"] = "Извините, у меня действительно нет такой способности. Крайний срок? Вы писатель?",
    ["抱歉，我不太懂得该怎么向你介绍这些漂亮的小东西，请随意看看吧，希望你能喜欢它们。"] = "Извините, я действительно не знаю, как представить вам эти милые вещицы, пожалуйста, посмотрите, надеюсь, они вам понравятся.",
    ["拉姆德古堡是个不错的选择。"] = "Замок Ламуд — хороший выбор.",
    ["拼死拼活爬上来，结果不敢动，根本赚不了钱吧。"] = "Вы забрались сюда, рискуя своей жизнью, но боитесь пошевелиться. Вы вообще не заработаете денег.",
    ["拿着这个灵摆，心中默念几遍想要问的问题……"] = "Держите этот маятник и молча повторяйте в сердце вопрос, который хотите задать...",
    ["指甲高的蜡烛、沾染着粘稠液体的破布、空荡的罐头与猪膀胱……这里的货品如商店中一样琳琅满目。"] = "Свечи высотой с ноготь, тряпки, испачканные вязкой жидкостью, пустые бидоны и свиные пузыри... товары здесь ослепительны, как в магазине.",
    ["挺红的。"] = "Он совсем красный.",
    ["换班时间到了，三号炉的废渣还没清完！谁想替班？每小时多给1便士！ "] = "Смена окончена, а шлак из третьей печи еще не выгребли! Кто выйдет на подмену? Дополнительно 1 пенс в час!",
    ["据说它曾经在警局工作过，不知道怎么着被恶龙酒吧领养了。"] = "Говорят, что когда-то он работал в полицейском участке и по какой-то причине был усыновлен Драконьим Баром.",
    ["接啊，为什么不接？只要不影响日常的事务就行，赚到钱权当额外补贴，队员们都挺乐意的。"] = "Возьмите, почему бы и нет? Пока это не влияет на повседневные дела, заработок считается дополнительной субсидией, и члены команды этому вполне рады.",
    ["接着，再去市场上偶遇他们的母亲，不经意透露我的现状。"] = "Затем иду на рынок, чтобы «наткнуться» на их матерей и случайно раскрыть свою текущую ситуацию.",
    ["接着，梭哈！赢回我的一切。"] = "Далее идите ва-банк! Верни все, что я потерял.",
    ["推完这车，我们总该能下班了吧？"] = "После того, как мы толкнем эту тележку, мы сможем уйти с работы, верно?",
    ["提神饮料，劲儿大又便宜，是我这种穷光蛋的福音。"] = "Освежающий напиток, крепкий и дешевый, это находка для такого бедняка, как я.",
    ["搬走了或者倒闭了，你想听哪种说法？"] = "Он переехал или прекратил свою деятельность, какую версию вы хотите услышать?",
    ["摩卡可真是一只不好糊弄的狗。"] = "Мокко и впрямь не так-то просто провести.",
    ["撞门？"] = "Вломиться в дверь?",
    ["放心吧，亲爱的铁针，我们可是铁十字街最厉害的组合！"] = "Не бойся, милый Железная Игла, мы же лучшая команда на улице Железного Креста!",
    ["政府雇员考试？需要很多钱么？"] = "Экзамен госслужащего? Это стоит много денег?",
    ["故事主角是一位叫做道恩的富翁，正在全鲁恩的报纸上连载呢。"] = "Главный герой истории - богатый человек по имени Доун, и ее публикуют в газетах по всему Лоену.",
    ["效果达到了就行。"] = "Лишь бы эффект был достигнут.",
    ["救济食物应该留给更需要它的人，我们可以靠劳动换取食物。"] = "Вспомогательное питание следует оставить для тех, кто в нем нуждается больше. Мы можем обменивать труд на еду.",
    ["敬法律——它保佑有钱人，敬我自己——我保佑喝酒的人。"] = "За закон — он защищает богатых, и за себя — я защищаю тех, кто пьёт.",
    ["敬活着的兄弟！还有那些……喂了鱼的倒霉蛋！"] = "За выживших братьев! И за тех... бедолаг, что пошли на корм рыбам!",
    ["整个人就像……一个正在向下疯狂扎根的树桩。"] = "Весь человек подобен... пню, который бешено пускает корни вниз.",
    ["文法和古典文学还没背完，数学和逻辑题也只刷了一半，听说今年还要加一门“行测”，我要疯了！"] = "Я не доучил грамматику и классическую литературу и справился только с половиной задач по математике и логике. Я слышал, что в этом году будет добавлен «Тест на административные способности», я схожу с ума!",
    ["斗邪恶，真好玩啊。"] = "Борьба со злом – это так весело.",
    ["新来的，军功是你在沙盘中存在的证明。参与战场、击败对手、占领点位，都能为你积累军功。"] = "Newcomer, military merit is the proof of your existence on the sand table. Participating in battles, defeating opponents, and capturing points will all help you accumulate military merit.",
    ["新裙子算什么！等我有了钱，我要买一头小驴，骑着它去贝克兰德！听说那里的街道都是用金子铺的！"] = "Какое новое платье! Когда у меня будут деньги, я куплю ослика и поеду на нем в Бэкланд! Я слышал, что улицы там вымощены золотом!",
    ["新财路？唉，不挤占旧财路我都谢天谢地了。"] = "Новый способ заработка? Эх, я был бы благодарен небесам, если бы он не вытеснил наши старые привычки.",
    ["新鲜的肉鱼，外皮煎得金黄酥脆，内里鲜嫩多汁，咬一口仿佛能尝到铁十字街海风的咸香，绝对是您补充体力的不二之选！"] = "Свежее мясо и рыба с поджаренной золотистой и хрустящей кожей, нежной и сочной внутри, один укус, и вы почти можете ощутить соленый аромат морского бриза с Айрон-Кросс-стрит, это определенно ваш лучший выбор для восполнения энергии!",
    ["旋律、旋律停不下来……诅咒……是诅咒……"] = "Мелодия, мелодия не умолкает... проклятие... это проклятие...",
    ["既然你这么想知道，我愿意给好学的人一些优惠。只要五便士，我就带你整个廷根看一圈。"] = "Поскольку вы так много хотите знать, я готов предоставить некоторые скидки тем, кто хочет учиться. Всего за пять пенсов я проведу вам экскурсию по всему Тингену.",
    ["既然是全家的生日，你自己那份呢？"] = "Поскольку сегодня день рождения всей семьи, как насчет твоего собственного подарка?",
    ["既然院长想让你宣传医院，不如讲讲医院的优势？ "] = "Поскольку директор хочет, чтобы вы продвигали больницу, почему бы не рассказать о ее сильных сторонах?",
    ["日安，{{先生|女士}}。我是市政厅认证的城市向导，雅各布。我能为您规划最有效率的游览路线，并解答您对这座城市的绝大多数疑问。"] = "Добрый день, {{Mr.| Ms.}}. Я Джейкоб, гид по городу, сертифицированный мэрией. Я могу спланировать для вас наиболее эффективный маршрут экскурсии и ответить на большинство ваших вопросов об этом городе.",
    ["早上好，弗兰奇先生。"] = "Доброе утро, мистер Фрэнки.",
    ["时尚协会最近准备举办一场只限内部成员参加的交流会。我本来没打算邀请任何新人，直到看见你的搭配，才稍微改变了主意。不过想拿到邀请函的话，得先通过我的测试。"] = "Ассоциация моды недавно готовится провести встречу по обмену, ограниченную внутренними членами. Я не планировала приглашать новичков, пока не увидела ваш наряд, и немного изменила свое мнение. Однако, если вы хотите получить приглашение, сначала вам необходимо пройти мой тест.",
    ["时间过得好快，转眼间到这个时候了。"] = "Как быстро летит время, вот уже и этот час настал.",
    ["明日的传奇，国王的幼子被异族驱赶，还面临缺少食粮的危机。"] = "Легенда завтрашнего дня, младший сын короля, изгнан инопланетянами и сталкивается с кризисом нехватки продовольствия.",
    ["明智的选择。我会为您准备一杯这里的招牌。不必急着落座——四处走走，看看今晚的演出，回来时酒刚好醒到最佳状态。"] = "Мудрый выбор. Я приготовлю для тебя фирменный напиток. Не нужно спешить занимать места — прогуляйтесь, посмотрите представление сегодня вечером, и к тому времени, как вы вернетесь, вино достигнет своего наилучшего состояния.",
    ["明白了，我来实现您的心愿！"] = "Понятно, я исполню твое желание!",
    ["明白了，谢谢您，我又学到了一些非凡知识。"] = "Понятно, спасибо, я узнал еще кое-что о Потустороннем.",
    ["昨天的金梧桐区可热闹了，有位贵族老爷被他的情人赶出了家门，全身上下就只有一条毛巾！"] = "Вчера в районе Золотой Утун было весело: одного благородного господина любовница выставила за дверь в одном полотенце!",
    ["昨晚我接了个新活，给工地搬砖头搬到半夜才回家，但心里还是只有斗邪恶。"] = "Вчера вечером я нашел новую подработку: таскал кирпичи на стройке до полуночи, прежде чем вернуться домой, но в мыслях всё равно было лишь одно — борьба со злом.",
    ["是……霍伊大学文学系，但是我这大学上的啊，<P_Heart>（自嘲一笑）</>越上越想退学……"] = "Да... Факультет литературы в Университете Хоуи, но эта моя университетская жизнь... <P_Heart> (самоуничижительная улыбка) </> чем больше я учусь, тем больше мне хочется бросить учебу...",
    ["是、是的！店主先生是个好人……他说，有声音总比沉默强，对生意，对我……都是。"] = "Д-да! Лавочник - хороший человек... Он сказал, что звук лучше тишины; для бизнеса и для меня... так лучше.",
    ["是一名叫阿兹克的教员，我和他关系很好。这么久没联系，不知道那家伙怎么样了。"] = "Это инструктор по имени Азик, у меня с ним хорошие отношения. Мы так давно не общались, что мне интересно, как поживает этот парень.",
    ["是一支用金属做成的烟斗。看到那东西的人会立刻陷入幻觉，听见晦涩难懂的呓语，传闻与罗塞尔大帝笔记里的文字有关。"] = "Это труба из металла. Тот, кто это увидит, сразу же впадает в галлюцинации и слышит неясный, неразборчивый шепот. Ходят слухи, что это связано с текстом дневника императора Розеля.",
    ["是一条小蛇！"] = "Это же маленькая змейка!",
    ["是个人都能看出来这不合理，分手吧！"] = "Любой может видеть, что это неразумно. Расставаться!",
    ["是个好主意，先生。放心，猫和狗之间应该不会发生您不愿看到的事情。"] = "Это хорошая идея, сэр. Не волнуйтесь, между кошкой и собакой не должно происходить ничего такого, чего вы бы не хотели видеть.",
    ["是个笨蛋，错把运气当实力，送新财路来了。"] = "Он идиот, который принял удачу за мастерство и предложил нам новый способ заработка.",
    ["是他逝去的未婚妻的发丝，那个勇敢的姑娘在弗萨克战争中去世了，我的客户先生寻找了她很多年。"] = "Это локон волос его покойной невесты: та отважная девушка погибла на войне с Фейсаком, и мой наниматель искал ее долгие годы.",
    ["是你，就是你，除去耀眼的你，我还能呼唤谁？"] = "Это ты, это ты, кроме ослепительной тебя, кому еще я могу позвонить?",
    ["是否开启战斗？"] = "Начать битву?",
    ["是否开启荣誉挑战？"] = "Хотите начать Испытание Чести?",
    ["是哪位蒸汽与机械系同学的期末作业吗？"] = "Это что, итоговая работа какого-то студента с факультета Пара и Машин?",
    ["是啊！他们第一次来廷根，我特意提前做好了一份“廷根旅游攻略”，想带他们好好逛逛。"] = "Да! Они приезжают в Тинген впервые, поэтому я специально заранее подготовил «Путеводитель по Тингену», желая как следует их провести.",
    ["是啊，“慷慨号”！通向“慷慨之城”拜亚姆！"] = "Да-да, «Щедрость»! Корабль, идущий в «Город Щедрости» Байам!",
    ["是啊，亲爱的先生，您这价格可真是“慷慨”得让人感动呢！"] = "Да, дорогой сэр, ваша цена действительно достаточно «щедра», чтобы ее можно было тронуть!",
    ["是啊，他看起来那样年轻健康，太令人惋惜了……"] = "Yeah, he looked so young and healthy, it's such a pity...",
    ["是啊，几年前的那天，这里变成了一片废墟。我恰好不在，但我唯一的儿子就没那么幸运了……"] = "Да, несколько лет назад в тот роковой день здесь всё обратилось в руины. Меня по счастливому случаю не было, но вот моему единственному сыну не так повезло...",
    ["是啊，好些年了。老邻居一个一个搬走了，紫藤花倒是越开越好……"] = "Да, на протяжении многих лет. Старые соседи уходили один за другим, но цветы глицинии цветут все лучше и лучше...",
    ["是啊，最爱妻子的市长候选人呀！"] = "Да уж, кандидат в мэры, который так «любит» свою жену!",
    ["是啊，这个人鬼鬼祟祟的。"] = "Да, этот человек ведет себя подло.",
    ["是啊，那段骨架，是从因蒂斯一位作家的旧作里挪过来的，只不过把人名换了而已。"] = "Да, этот скелет был взят из старой работы писателя Интиса, они просто поменяли названия.",
    ["是因为弹得好？"] = "Это потому, что она хорошо играет?",
    ["是已经摆放好了？非常感谢，让我去检查下。"] = "Он уже настроен? Спасибо большое, пойду проверю.",
    ["是您健忘忘记了。"] = "Это вы забывчивы и забыли.",
    ["是您的曲子作得好。"] = "Это ваша музыка, которая хорошо написана.",
    ["是您！ 好心的{{先生|女士}}"] = "Это вы! Добрый {{господин|госпожа}}!",
    ["是我养的狗——事实上，他正处于求偶期。这实在是太可怕了，我决不允许尊贵的昂格家族与外来者结合，更何况那是一只猫！"] = "Это моя собака, на самом деле, она сейчас в фазе ухаживания. Это действительно ужасно. Я никогда не позволю знатному семейству Унгеров жениться на постороннем человеке, не говоря уже о кошке!",
    ["是我的，但不是我开的。"] = "Оно мое, но открывал(а) не я.",
    ["是的，两周前，花了全部的积蓄，从“莴苣与肉类市场”搬来这里。"] = "Да, две недели назад я потратил все свои сбережения, чтобы переехать сюда с «Салата и мясного рынка».",
    ["是的，他们以纺织相关的物品做名字，只有他们的首领有一个像样的名字，叫做亨特。"] = "Да, они используют в качестве названий предметы, связанные с текстилем. Только у их лидера приличное имя по имени Хантер.",
    ["是的，他是很好的领路人，他教会了我们很多。"] = "Да, он был отличным гидом. Он многому нас научил.",
    ["是的，后天就是截稿日了……但我写不出来……一点灵感都没有……"] = "Да, срок - послезавтра... но я ничего не могу написать... У меня совершенно нет вдохновения...",
    ["是的，呜呜，我爸爸只会打发我去扫烟囱。"] = "Да, ууу, папа посылает меня только трубочистить.",
    ["是的，尊敬的先生/女士。"] = "Да, уважаемый сэр/госпожа.",
    ["是的，我们负责廷根市黑夜女神信徒相关的事件，类似的组织还有风暴教会的代罚者、蒸汽与机械教会的机械之心。"] = "Да, мы занимаемся происшествиями, связанными с верующими Богини Вечной Ночи в Тингене. Похожие организации есть и у других: Каратели у Церкви Бурь и Сердца Машин у Церкви Пара и Машин.",
    ["是的，我正在思考怎么结尾。或许你可以给我提供一些灵感——如果你愿意的话。"] = "Да, я думаю о том, как покончить с этим. Возможно, вы сможете вдохновить меня, если захотите.",
    ["是的，是的，我知道的……"] = "Да, да, я знаю...",
    ["是的，美丽而伟大的艾德雯娜·爱德华兹女士！循循善诱的智者，博学多能的导师！"] = "Да, прекрасная и великая мисс Эдвина Эдвардс! Мудрый наставник, умело направляющий, образованный и способный учитель!",
    ["是的，茱莉亚太太，要买些蛋糕吗？我推荐今天的柠檬薄荷蛋糕。"] = "Да, миссис Джулия. Хотите купить торт? Рекомендую сегодняшний лимонно-мятный торт.",
    ["是的，街上可租赁的脚踏车，就是我之前提供的想法。"] = "Да, велосипеды, которые можно взять напрокат на улице, — это идея, которую я высказал ранее.",
    ["是的，这位{{先生|女士}}。我即将和少爷一起返回贝克兰德……"] = "Да, это {{Mr.|Ms.}}. Я собираюсь вернуться в Бэкланд с молодым мастером...",
    ["是的，黄黑之王指向了“愚者”先生。"] = "Да, Король Желтого и Чёрного указывает на господина Шута.",
    ["是租！出——租——不是卖！"] = "В аренду! В а-рен-ду, а не на продажу!",
    ["是这样的，我今早去巡逻时，发现我们的王国被封锁了。我尝试钻空子，但还是没能返回基地。"] = "Дело вот в чём: отправившись утром на патрулирование, я обнаружил, что наше королевство заблокировано. Я пытался найти лазейку, но так и не смог вернуться на базу.",
    ["是迷雾中的一盏灯，但记住——提灯的手，永远应该是清醒的你自己。"] = "Это лампа в тумане, но помните: рука, держащая лампу, всегда должна быть вашей трезвой личностью.",
    ["是那种……看完回去睡不着觉的舞。 "] = "Они из тех... которые не дают спать по ночам после того, как ты их увидел.",
    ["是，我在想……把这束花送给<P_Yellow>对面咖啡馆的收银员</>。"] = "Да, я подумываю... подарить этот букет кассиру <P_Yellow> в кафе через дорогу </>.",
    ["是，是的。是我，太、太害怕了，老师让我，缓、缓一下。"] = "Да, да. Это я, я тоже, слишком напуган, учитель сказал мне: «Сделай перерыв».",
    ["晚上好，先生。今晚想从一杯酒开始，还是想先熟悉一下这里？"] = "Добрый вечер, сэр. Хотите начать с бокала вина или сначала хотите познакомиться с местом?",
    ["晚上好，女士。今晚想从一杯酒开始，还是想先熟悉一下这里？"] = "Добрый вечер, мадам. Хотите начать с бокала вина или сначала хотите познакомиться с местом?",
    ["晚了！它们被扔到教堂旁边的<P_Yellow>小溪</>里了！这会已经不知道漂到哪里去了，哈哈哈哈！"] = "Слишком поздно! Их бросили в <P_Yellow> ручей</> рядом с церковью! Я не знаю, куда он сейчас плывет, ха-ха-ха!",
    ["更何况你们已经让步了。"] = "Кроме того, вы уже пошли на уступки.",
    ["更准确的说法是——占卜展示的是概率最高的可能性河流。"] = "Более точное утверждение – гадание показывает реку возможностей с наибольшей вероятностью.",
    ["更多款式，可以到街边“半路有雨”店铺选购！"] = "Чтобы получить больше стилей, вы можете пойти в магазин «Rain Halfway» на улице и выбрать!",
    ["更近一点，是多近？"] = "Поближе — это насколько близко?",
    ["曾经只有贵族才能定义优秀的设计，哪怕那些都太过累赘单调——大量的黄金、珍珠、珊瑚……昂贵材料的手工堆砌。"] = "Когда-то только дворяне могли определить отличный дизайн, даже если он был слишком громоздким и однообразным — ручное складывание большого количества золота, жемчуга и кораллов… дорогих материалов.",
    ["曾经我也是个大人物，直到前两年发生了一场意外。"] = "Раньше я тоже был важной шишкой, пока два года назад не произошел несчастный случай.",
    ["曾经有些小插曲，不过这是我的私事。为了流浪王国的未来，外交大臣，我跟你一起去谈判。"] = "Были небольшие эпизоды, но это мое личное дело. О будущем Странствующего Королевства, министр иностранных дел, я пойду с вами на переговоры.",
    ["最关键的是，打饭阿姨不！手！抖！"] = "Самое главное, что леди, подающая еду, этого не делает! Встряхните! Ее! Рука!",
    ["最后一段路了，跳上那艘船，抵达对岸吧。"] = "Это последний отрезок. Прыгайте на эту лодку и доберитесь до другой стороны.",
    ["最后还有个秘密：<P_Heart>（压低声音）</>真正的高序列者，他们的影子偶尔会……不太听话。"] = "Наконец, есть секрет: <P_Heart> (Понижающий голос) </> для настоящих высокопоставленных личностей, их тени иногда... не совсем их слушайте.",
    ["最后，别试着找了，你肯定不知道这东西的用途。提醒一下，我在厕所可没带纸哦！"] = "Наконец, не пытайтесь их искать; вы определенно не знаете толк в этой штуке. Напоминаю, я не носила бумагу в туалет!",
    ["最外层是“以太体”，它是你生命能量和肉体状态的表现。你看到的气场颜色，就是以太体的外显象征。"] = "Самый внешний слой — это «Эфирное тело», которое является проявлением вашей жизненной энергии и физического состояния. Цвет ауры, который вы видите, — это внешнее проявление Эфирного Тела.",
    ["最妙的是，大学生总是装作一副体面人的样子。你瞧，他们穿着补丁摞补丁的外套，却还要挺直腰板，假装自己是个绅士。"] = "Самое приятное то, что студенты всегда притворяются порядочными людьми. Посмотрите, они носят пальто, залатанные поверх заплаток, а им все равно приходится выпрямлять спины, притворяясь джентльменами.",
    ["最尴尬的是，那位小姐不小心把茶泼在了查尔斯勋爵的白色西装上——而那是他为了这场见面会特意从因蒂斯定制的。"] = "Самым неприятным было то, что юная леди случайно пролила чай на белый костюм лорда Чарльза — а это он специально заказал у Интиса для этой встречи.",
    ["最核心叫“精神体”，是每个人最根本的灵性。对于窥秘人来说，冥想和提升力量的方式都指向它。"] = "Ядро называется «Духовным телом», которое является самой фундаментальной духовностью каждого человека. Для жреца Тайн на это указывают все способы медитации и увеличения силы.",
    ["最深的棕黄色。呵，廷根市的雾气已经够黄了，家里还要刷成黄的。"] = "Самый глубокий коричнево-желтый. Хех, туман в Тингене уже достаточно желтый, и теперь мне тоже придется покрасить свой дом в желтый цвет.",
    ["最累的是哪部分？"] = "Что самое утомительное?",
    ["最近半年已经发生不下七起工厂机械失灵事故了。"] = "За последние шесть месяцев на заводе произошло не менее семи несчастных случаев с механическими неисправностями.",
    ["最近来食堂吃饭的人肉眼可见地减少了，后厨剩的菜堆得老高， 好多老面孔再也见不到了。我仔细想了好几天，也没想通食堂到底哪里出问题了！"] = "В последнее время количество людей, приходящих в столовую, заметно уменьшилось. На кухне завалены остатки еды, и я давно не видел знакомых лиц. Я думал об этом несколько дней, но не мог понять, что не так со столовой!",
    ["最近的一班航线就在三天后。"] = "Ближайший рейс через три дня.",
    ["最难的不是远航，是记住谁喜欢吃鱼，谁讨厌海鲜……<P_Heart>（打寒颤）</>我再也不会搞错了！"] = "Самое сложное - не долгое путешествие, а вспомнить, кто любит рыбу, а кто ненавидит морепродукты... <P_Heart> (Вздрагивает) </> Я больше никогда не совершу этой ошибки!",
    ["有“焦糖炸弹”吗？"] = "У вас есть «Карамельная бомба»?",
    ["有一个朋友托我来这看看。"] = "Друг попросил меня прийти сюда и посмотреть.",
    ["有一些仪式魔法的材料。窥秘人……她失控时，究竟在尝试什么？"] = "Есть некоторые материалы для Ритуальной Магии. Мистерия Прайер... что именно она пыталась сделать, когда потеряла контроль?",
    ["有了这笔钱，够我过上一段好日子了。"] = "С этими деньгами я смогу безбедно прожить некоторое время.",
    ["有些人总喜欢打听不该知道的事……您不会是那种人吧？"] = "Некоторым людям всегда нравится совать нос в то, чего им знать не следует... Ты ведь не один из тех людей, не так ли?",
    ["有些人花钱找乐子，有些人花钱……找的就是这一声“哥哥”。"] = "Кто-то тратит деньги, чтобы развлечься, кто-то тратит деньги... чтобы найти этого «брата».",
    ["有些客人坐下时只想聊一杯酒的时间，起身时却想把整颗心都留给她。"] = "Некоторые гости садятся, намереваясь поболтать во время напитка, но к тому времени, как они встают, они хотят оставить с ней все свое сердце.",
    ["有些搭配不需要繁复装饰，只要站在花影之间，便足够让人驻足。来吧，让我看看，你会如何回应这片花海的目光。"] = "Иному наряду не нужны вычурные украшения: достаточно просто встать в тени цветов, чтобы все замерли в восхищении. Ну же, покажи мне, как ты ответишь на взоры этого цветочного моря.",
    ["有些自以为有见识的客人，最喜欢点她——聊完总觉得自己比来时聪明了几分。"] = "Некоторые гости, считающие себя знающими, любят выбирать ее — после разговора с ней они всегда чувствуют себя немного умнее, чем когда они приехали.",
    ["有人偏爱盛放的热烈，也有人钟情于花瓣落下时的温柔，你的搭配又会讲述怎样的故事？让我们来进行一场时尚品鉴吧！"] = "Некоторые предпочитают интенсивность полного цветения, другие предпочитают нежность падающих лепестков. Какую историю расскажет ваш наряд? Давайте ценить моду!",
    ["有人偏爱轻盈柔软的花瓣色调，也有人钟情于精致克制的搭配方式。不同的场合，自然也有属于它的风尚语言。让我们来一场时尚品鉴吧！"] = "Одни предпочитают лёгкие и нежные тона цветочных лепестков, другие без ума от утончённой сдержанности. У каждого повода, несомненно, есть свой язык стиля. Давайте же устроим модный показ!",
    ["有人偏爱轻盈柔软的花瓣色调，也有人钟情于精致克制的搭配方式，让我们来一场品鉴挑战吧！"] = "Некоторые предпочитают легкие и мягкие лепестковые тона, а другие любят изысканные и сдержанные сочетания. Давайте устроим конкурс на оценку!",
    ["有人被她看一眼，第二天来，说“我得确认她是不是真的看见我了”。 "] = "Некоторые люди бросают на нее взгляд и возвращаются на следующий день со словами: «Мне нужно подтвердить, действительно ли она меня видела».",
    ["有人说店主赚了大钱，搬去贝克兰德，开了家更大的。也有人说店主在酒吧打斗邪恶把钱都输光了，餐馆跟着遭殃。"] = "Некоторые говорят, что владелец заработал состояние, переехал в Бэкланд и открыл магазин побольше. Другие говорят, что владелец потерял все свои деньги, борясь со злом в баре, в результате чего пострадал ресторан.",
    ["有人适合晨曦里的白蔷薇，也有人更像夜色中的鸢尾，你会如何完成属于自己的品鉴？让我们来进行一场时尚品鉴吧！"] = "Кому-то к лицу белая роза на рассвете, а кто-то больше похож на ночной ирис. Каков же твой неповторимый вкус? Давай устроим показ мод!",
    ["有人！有人上着呢！"] = "Кто-то здесь! Кто-то этим пользуется!",
    ["有什么事吗？你认识我？"] = "Что-то случилось? Ты меня знаешь?",
    ["有勇气！那就去吧！"] = "Смело! Ну тогда вперед!",
    ["有只苍蝇从我眼前飞过去了。"] = "Муха только что пролетела мимо моих глаз.",
    ["有学生举报，集市这边有人大量泄露考题，严重影响考试公平。"] = "Студент сообщил, что кто-то на рынке сливает экзаменационные вопросы в большом количестве, что серьезно влияет на честность экзамена.",
    ["有意思，你刚才是想绕过我吗？可惜，你已经被我“记住”了。"] = "Интересно, ты только что пытался обойти меня? Как жаль, я вас уже «запомнил».",
    ["有推荐吗？"] = "Есть ли у вас какие-либо рекомендации?",
    ["有时候想想自己的原因！这么多年了，工资涨没涨？有没有努力工作？"] = "Иногда думайте о своих причинах! Прошло так много лет; ваша зарплата увеличилась? Вы много работали?",
    ["有最新的廷根新闻！"] = "Свежие новости Тингена!",
    ["有柠檬的酸味和薄荷的清香，加上爸爸秘制的蛋糕配方，非常美味。"] = "В нём есть кислинка лимона и освежающий аромат мяты, а благодаря папиному секретному рецепту пирога он просто объедение.",
    ["有素描、水彩、油画等等类型，你想体验哪种呢？"] = "Есть эскизы, акварель, картины маслом и так далее. Какой тип вы хотели бы испытать?",
    ["有这么夸张？"] = "Настолько преувеличено?",
    ["有道理……比如季节交替时的流感，其实注意通风、勤洗手就能大大减少传染。很多人一咳嗽就害怕是肺痨，反而耽误了。 "] = "В этом есть смысл... Например, грипп во время сезонных изменений. Фактически, уделяя внимание вентиляции и частому мытью рук, можно значительно снизить передачу инфекции. Многие люди пугаются, что это туберкулез, как только кашляют, что приводит к задержке лечения.",
    ["有道理，大人物就应该存在于足够广阔的世界。"] = "That makes sense; big shots should exist in a world vast enough for them.",
    ["朋友介绍的。"] = "Рекомендован другом.",
    ["朋友介绍？你也是学生？"] = "Вас познакомил друг? Вы тоже студент?",
    ["期待你的演讲！"] = "С нетерпением жду вашей лекции!",
    ["期待这次你能带来全新的旋律。当然，作为回报，我的酬谢亦将通过回响之匣交付于你。"] = "Я с нетерпением жду, когда на этот раз вы принесете совершенно новую мелодию. Конечно, взамен моя награда также будет доставлена ​​вам через Эхо-Ящик.",
    ["未来？谁知道呢。但只要我们团结在一起，就没什么好怕的。"] = "Будущее? Кто знает. Но пока мы едины, бояться нечего.",
    ["机不可失时不再来，现在就找我详谈入股，入不了吃亏，入不了上当！"] = "Но однажды появится возможность, поговорите со мной об инвестировании в акции. Вы не проиграете, вас не обманут!",
    ["机遇不会亏待每一个有所准备的人，在开放政府雇员考试的那一刻，学识就是普通人最好的助力。"] = "Возможности не будут несправедливыми по отношению ко всем, кто к ним готов. С момента открытия экзамена для госслужащих знания станут лучшим подспорьем для простых людей.",
    ["材质居然是……发丝？"] = "Материал на самом деле... волосы?",
    ["村口的<P_Yellow>破木头房子</>，还有两间<P_Yellow>挨在一起</>的稻草房子，体验感特别好，快去吧！"] = "Сломанный деревянный дом <P_Yellow> </> на въезде в деревню и два соседних соломенных дома <P_Yellow> </>, впечатления особенно хорошие, идите быстро!",
    ["杜比是我的好伙计，它乖巧又强大，是个好猎手。"] = "Долби мой хороший приятель, он послушный и сильный, хороший охотник.",
    ["杜比是最敏捷的小狗，它甚至能轻松打败野猫。"] = "Добби — самый ловкий щенок; он может легко победить даже диких кошек.",
    ["来一片吗？只要20便士！"] = "Хотите кусок? Всего 20 пенсов!",
    ["来了？你确定要和邦尼的阴影一战么？"] = "Ты здесь? Вы уверены, что хотите сразиться с тенью Бонни?",
    ["来了？我就知道你能扒出那张纸。"] = "Ты здесь? Я знал, что ты сможешь откопать этот листок бумаги.",
    ["来来来，这是你的跑腿费，还有这个——我用同样配方做的香料，烤肉的时候撒一点，香极了！"] = "Давай, вот твоя плата за поручение, а это... это приправа, которую я приготовила по тому же рецепту. Посыпьте немного, когда жарите мясо; это очень вкусно!",
    ["来看病的，自然都是有需要的，只是有的人更需要帮助。"] = "Те, кто приходит на прием к врачу, естественно, нуждаются в помощи, но некоторым людям помощь нужна больше.",
    ["来艺术学派支持我的演出，帮我夺回我的一切！"] = "Приходите в Школу искусств, чтобы поддержать мое выступление и помочь мне вернуть все, что принадлежит мне!",
    ["来这里的很多客人都是这样，明明挺穷酸的，也要硬装高贵。"] = "Многие гости, приезжающие сюда, такие; они явно весьма бедны и убоги, но настаивают на том, чтобы вести себя благородно.",
    ["来！再喝一杯吧！丢掉一切的忧愁，今天是值得庆祝的日子！"] = "Приходить! Давайте выпьем еще! Отбросьте все свои заботы, сегодня тот день, который стоит отпраздновать!",
    ["杰克！怎么可以这么说你的爷爷？"] = "Джек! Как ты можешь такое говорить о своем дедушке?",
    ["杰克，老头子什么时候生病了，我怎么不知道？"] = "Джек, когда старик заболел? Почему я не знаю?",
    ["枷锁？你们坐的长椅，走的石板路……哪一样不是工人一锤子一扳手敲出来的？"] = "Кандалы? Скамейка, на которой вы сидите, мощеная дорога, по которой вы идете... какую из них не выбил рабочий молотком и гаечным ключом?",
    ["某些非凡材料开始以“复古面料”的名义进入上层社会。比如“工匠”途径制造的恒温丝绸，现在被称作“罗塞尔时期的失落工艺”。"] = "Некоторые материалы Потусторонний начинают проникать в высший свет под названием «винтажные ткани». Например, регулирующий температуру шелк, изготовленный по технологии «Ремесленник», теперь называют «утраченным мастерством эпохи Розелле».",
    ["查尼斯门来源于现代值夜者体系的创立者，查尼斯大主教的名字，在每个大城市的中央教堂地下，都有一扇。"] = "Ворота Чанис происходят от имени архиепископа Чаниса, основателя современной системы Ночного Ястреба. Под центральной церковью каждого большого города есть дверь.",
    ["查尼斯门背后是哪里？地下室竟然有这么大的门，很不寻常。"] = "Что находится за воротами Чанис? Для подвала очень необычно иметь такую ​​большую дверь.",
    ["核对？你们那本子上写的字像蜘蛛爬！谁知道当时怎么写的！你们就是吃定了我们认不全字！"] = "Проверять? Слова, написанные в этой книге, похожи на ползающих пауков! Кто знает, как это было написано в то время! Вы просто ставите на то, что мы плохо умеем читать!",
    ["格尔曼带着他的左轮手枪，出现在了一个宁静的小村庄里，是因为这里有……"] = "Герман появляется в тихой деревушке со своим револьвером, потому что там...",
    ["格尔曼来到了一个热闹的城镇，周围都是忙碌的人们，而他来这里是为了……"] = "Герман приезжает в шумный город, окруженный занятыми людьми, и приехал сюда, чтобы...",
    ["梦境污染已经清除，可以下班了。"] = "Порча снов очищена, вы можете уйти с работы.",
    ["楼下那个戴帽子的。委托人让我观察一下他在这里都见什么人。"] = "Тот, что в шляпе внизу. Клиент попросил меня понаблюдать, с кем он здесь встречается.",
    ["欠债还钱，当然合法。"] = "Долги надо возвращать, конечно это законно.",
    ["欠钱？"] = "Должен деньги?",
    ["欢迎光临！啊，您也发现了吧？我们这儿的花，开得就是比别处旺，连叶子都绿得格外精神，像被谁特别照顾着似的！"] = "Добро пожаловать! Ах, ты тоже это заметил, да? Цветы у нас цветут обильнее, чем где бы то ни было, даже листья исключительно зеленые, как будто о них кто-то специально заботится!",
    ["欢迎回来，领主大人！您可以自由地建设和装修城堡，进行工坊生产和市场交易，或是发起铁路贸易。在您的带领下，城堡正在被建设得越来越好。"] = "С возвращением, милорд! Вы можете свободно обустраивать и украшать замок, запускать производство в мастерских, торговать на рынке или развивать железнодорожную торговлю. Под вашим началом замок становится краше с каждым днём.",
    ["欢迎来到廷根，{{先生|女士}}！要乘马车吗？可以到达廷根的任何地方，还为您提供免费的讲解服务！"] = "Добро пожаловать в Тинген, {{господин|госпожа}}! Не желаете прокатиться в экипаже? Доставим в любую точку Тингена, а заодно проведем бесплатную экскурсию!",
    ["欢迎正式踏入沙盘。这里是你与战争记忆共同编织的廷根，简单来说，就是不同时空的廷根。"] = "Welcome to officially stepping into the sandbox. This is Tingen, woven together by you and the memories of war; simply put, it is Tingen from different times and spaces.",
    ["欢迎！欢迎！虽然你错过了拳王阿比的上一场比赛，噢，可怜的比利被打得满地找牙，但下一场很快就要开始了！"] = "Добро пожаловать! Добро пожаловать! Хоть ты и пропустил последний матч Чемпиона Аби — ох, бедному Билли зубы вышибли, — скоро начнется следующий!",
    ["欧维本人非常自责，自己因为出去上班，没有发现孩子的异常……他在房子里自杀了。"] = "Сам Уве очень винил себя, так как был на работе и не заметил состояния ребенка... Он покончил жизнь самоубийством в доме.",
    ["欸，我记得这里有口锅，怎么没了？"] = "Эх, я помню, здесь был горшок. Куда это делось?",
    ["歌唱——在雨中歌唱——"] = "Пение – пение под дождем –",
    ["正式场合仍有人遵守。上个月外交晚宴上，法里斯大使夫人就用扇子点了三次左肩——"] = "Некоторые до сих пор следуют за ними в официальных случаях. На дипломатическом ужине в прошлом месяце жена посла Фарис трижды постучала по левому плечу веером:",
    ["正是。仿佛连偶然吹来的风，都带着某种……宁静的诗意。该回去了，愿女神赐你一夜安眠。"] = "Точно. Как будто даже случайно дующий ветер несет в себе некое... поэтическое ощущение покоя. Пора возвращаться, пусть Богиня дарует тебе ночь сна.",
    ["母亲，请别这样说，赛斯他很特别。他善良、正直，而且…… "] = "Мама, пожалуйста, не говори так, Сет особенный. Он добрый, честный и... ",
    ["每一家报纸都有它们的特色，这真的很难抉择。晨报可以第一时间读到大新闻，比起来，老实人报更休闲一些。"] = "Каждая газета имеет свои особенности, выбрать действительно сложно. Вы можете сразу прочитать важные новости в «Утренняя почта»; для сравнения, «Честный человек» больше подходит для досуга.",
    ["每个战争纪念日，我们都会来感谢伟大的风暴之主！"] = "Каждый День памяти войны мы приходим поблагодарить великого Повелителя Штормов!",
    ["每周我都在这里。您若过来坐坐，我便再为您写一首。只给您一个人。 "] = "Я здесь каждую неделю. Если ты придешь и посидишь немного, я напишу тебе еще одно. Только для тебя.",
    ["每月来一次，我都快成你们这儿的常客了。"] = "Приходя сюда раз в месяц, я почти стал вашим постоянным клиентом.",
    ["比如建议廷根工程委员会在排污口装黄铜滤网，为了拦截淑女们丢失的珍珠耳环。"] = "Например, предложить Инженерному комитету Тингена установить на канализационных отверстиях латунные фильтры, чтобы перехватывать потерянные дамами жемчужные серьги.",
    ["比如，你现在看不到苏茜，但她确实趴在你的脚边享受午睡时光。"] = "К примеру, прямо сейчас ты не видишь Сьюзи, но она и впрямь лежит у твоих ног, сладко задремав.",
    ["比弗萨克人还高！第一次见到那群新白银城的人，渔民们惊得差点吞下鲨鱼！"] = "Выше, чем фейсакианцы! Когда рыбаки впервые увидели эту группу людей из Нью-Сильвер-Сити, они были так потрясены, что чуть не проглотили акулу!",
    ["比弗萨克人还高？"] = "Выше, чем фейсакианцы?",
    ["比起您那15%的月息，恐怕我更愿意相信银行。"] = "По сравнению с вашими 15% ежемесячных процентов, боюсь, я бы предпочел довериться банку.",
    ["毕竟我是她妈妈，阁下。"] = "Ведь я ее мать, Ваше Превосходительство.",
    ["毕竟，知识是多么美好的事物！"] = "Ведь знания – такая замечательная вещь!",
    ["水晶顺时针摆动象征肯定，逆时针摆动则相反。"] = "Вращение кристалла по часовой стрелке символизирует утверждение, а покачивание против часовой стрелки означает противоположное.",
    ["永不过时的选择！最纯粹的武器，以理服人的绝佳方式！您对哪件钝器感兴趣？"] = "Вечный выбор! Чистейшее оружие, отличный способ убедить людей разумом! Какое тупое оружие вас интересует?",
    ["求知的光芒，我想你一定想知道关于廷根景点的知识！"] = "Свет тяги к знаниям! Уверен, тебе непременно хочется узнать о достопримечательностях Тингена!",
    ["汪~汪汪~"] = "Гав~ Гав-гав~",
    ["汪汪！"] = "Гав-гав!",
    ["汪！"] = "Гав!",
    ["汪！汪！"] = "Гав! Гав!",
    ["沃特先生的服饰店、桑加小姐的咖啡厅、我的老房子……哦，水仙花街的一切都让人怀念……"] = "Магазин одежды мистера Уолтера, кафе мисс Санги, мой старый дом... ох, все на Даффодил-стрит такое ностальгическое...",
    ["没事不可以和你说话吗？"] = "Могу ли я поговорить с тобой, если ничего не происходит?",
    ["没事，第一次会紧张是正常的，之后习惯就好。"] = "Ничего страшного, нервничать в первый раз – это нормально. Позже ты привыкнешь.",
    ["没什么没什么……您听错了吧……"] = "Ничего, ничего... вам, наверное, послышалось...",
    ["没什么！只是随便画画……您有什么事吗？"] = "Ничего! Просто рисую... Тебе что-то нужно?",
    ["没什么，再见。"] = "Ничего, до свидания.",
    ["没关系，如果下次有机会，欢迎再同我交流诗歌。"] = "Нет проблем, если в следующий раз будет возможность, вы можете снова обсудить со мной поэзию.",
    ["没关系，我会等到来找我的客人。"] = "Ничего, я подожду клиента, который придет за мной.",
    ["没开门吗？"] = "Разве он не открыт?",
    ["没想到值夜者会用安保公司的招牌来遮掩，如果真有人上门委托任务怎么办？"] = "Я не ожидал, что «Ночные ястребы» будут использовать вывеску охранной компании, чтобы прикрыться. А что, если кто-то действительно придет поручить квест?",
    ["没想到它还能迎来合适的主人，真是太好了……"] = "Я все-таки не ожидал, что он найдет подходящего владельца; это действительно прекрасно...",
    ["没有也能帮您淘来。"] = "Даже если нет, я могу помочь тебе его найти.",
    ["没有人会忘记他们的，他们守护了廷根。"] = "Их никто не забудет; они охраняли Тинген.",
    ["没有什么可是，再过两年你就能去做工了，到时候就可以天天吃饱饭了。"] = "Нет никаких «но». Через два года ты сможешь работать, и тогда ты сможешь есть вдоволь каждый день.",
    ["没有特定的对象……看，注意到河对岸光影的变化了吗？画笔就很难再现瞬间的变化。"] = "Конкретной темы нет... Посмотрите, вы заметили изменение света и тени на другом берегу реки? Кисти трудно воспроизвести такие мгновенные изменения.",
    ["没这种事，先生，那只是一个名字。"] = "Ничего подобного, сэр, это просто имя.",
    ["没错！{{先生|女士}}，你也明白其中的奥妙吗？"] = "Это верно! {{ Mr. | Ms. } }, ты тоже понимаешь тайну, скрывающуюся за этим?",
    ["没错！就算不能成为首富，但在拜亚姆，生活至少不会比现在差！"] = "Верно! Даже если мне не суждено стать богатейшим человеком, в Байаме жизнь уж точно будет не хуже, чем сейчас!",
    ["没错！这位{{先生|女士}}，你一定也想登上宏伟神秘的“黄金梦想号”吧！"] = "Это верно! На этом {{ Mr. | Ms. }} вы тоже наверняка захотите подняться на борт великолепной и загадочной «Золотой мечты»!",
    ["没错，这就是我想要的人生，平平淡淡才是真。"] = "Именно, такой жизни я и желал. Простота и покой — вот истинное счастье.",
    ["没错，那位摊主被女儿接去享受了，摊位连带着三只猫都转让给我。"] = "Правильно, того владельца стойла дочь забрала радоваться жизни, а стойло вместе с тремя кошками передали мне.",
    ["没问题，茱莉亚太太。"] = "Нет проблем, миссис Джулия.",
    ["没，没错。"] = "Нет, это правда.",
    ["沿着房子顶上一路往前走，掉到水里就算输哦。"] = "Пройдите весь путь по крыше дома; если ты упадешь в воду, ты проиграешь.",
    ["注意他转桨的动作——水花溅落半径永远控制在15寸内，我愿称之为“杰尼波纹”。"] = "Обратите внимание на его поворотное движение весла — радиус всплеска всегда находится в пределах 15 дюймов. Я бы хотел назвать это «Джени Риппл».",
    ["注意安全！这位诗人……你使过铁锤吗？"] = "Будь осторожен! Этот поэт... ты когда-нибудь пользовался молотком?",
    ["济贫院排着长队，好运并不是一直眷顾我，大多时候我都排不到一份食物。"] = "В богадельне длинные очереди. Удача не всегда благоприятствует мне; большую часть времени я не могу получить даже порцию еды.",
    ["浪费水是可耻的事情，这该死的小偷！"] = "Тратить воду стыдно, проклятый вор!",
    ["海纳斯老师那样的资深占卜家，都无法占卜自己的厄运。那占卜的意义是什么？"] = "Even a veteran Seer like Mr. Haines cannot divine his own misfortune. What, then, is the point of divination?",
    ["涨工资？你这谎撒得比我高明多了。"] = "Повышение? Твоя ложь намного лучше моей.",
    ["淡金色的发丝编成花朵，簇拥着一颗浑圆温润的珍珠，犹如送给情人的表白花束。"] = "Бледно-золотистые волосы, сплетенные в цветы, окружающие круглую и теплую жемчужину, словно букет признания возлюбленному.",
    ["混混正纠缠着扫地的老人，气氛有些紧张。"] = "Бандит пристает к старику, подметающему пол, атмосфера немного напряженная.",
    ["清洁工？你说清洁工？"] = "Уборщики? Ты имеешь в виду уборщиков?",
    ["漂亮的颜色和神奇的名字能让酒卖得更贵，我们老板就是靠包装吸引有钱人过来的。"] = "Красивый цвет и диковинное название позволяют продавать вино дороже. Наш хозяин только так и заманивает богатеев красивой оберткой.",
    ["漫游的契机遍布廷根，若想节省心力，您也可以<P_Yellow>每日</>在我这里领取<P_Yellow>三项随机的漫游</>任务，领取后在任务栏的<P_Yellow>漫游分页</>查看。"] = "Возможности для роуминга есть по всему Тингену. Если вы хотите сэкономить усилия, вы также можете <P_Yellow>daily</> получить от меня <P_Yellow>три случайных квеста </> в роуминге. После их получения проверьте вкладку <P_Yellow>Roaming</> в меню Квестов.",
    ["激情！激情！还是激情！"] = "Страсть! Страсть! И еще страсть!",
    ["火漆印章的颜色代表紧急程度，红色是日常问候，黑色是重要事务，紫色……通常意味着婚礼请柬或讣告。"] = "Цвет сургучной печати символизирует срочность. Красный — для ежедневных поздравлений, черный — для важных дел, а фиолетовый… обычно означает приглашение на свадьбу или некролог.",
    ["灵视看到的颜色代表你的气场，神秘学一般将每个人非肉体的部分分为了四层。"] = "Цвета, видимые духовным зрением, представляют вашу ауру. Оккультизм обычно делит нефизическую часть каждого человека на четыре слоя.",
    ["炉子熄灭了一瞬，又重新燃起。"] = "Печь на мгновение погасла, а затем снова зажглась.",
    ["焚烧炉的操作台，需要燃料启动。"] = "Для запуска консоли мусоросжигателя требуется топливо.",
    ["焦糖炸弹！焦糖炸弹！好喝不贵，一瓶顶俩！"] = "Карамельная бомба! Карамельная бомба! Вкусно и недорого, одна бутылка стоит двух!",
    ["然后不小心把它们弄坏了。"] = "А потом случайно сломал их.",
    ["然后伸出手来，水晶会告诉你答案。"] = "Затем протяните руку, и кристалл подскажет вам ответ.",
    ["然后你就邀请我共进晚餐，噢，答应你的表白时我一定喝醉了！"] = "А потом вы пригласили меня на ужин, ох, я, должно быть, был пьян, когда принял ваше признание!",
    ["然后我就花了点零花钱做硬币占卜，结果说能过——最后真过了，分数还不低！下次我打算去占卜毕业后能不能去贝克兰德发展。 "] = "Затем я потратил немного карманных денег на гадание на монетах, и оно сказало, что я могу пройти — в конце концов я действительно это сделал, и балл был немаленьким! В следующий раз планирую поехать и угадать, смогу ли я поехать в Бэкланд развиваться после окончания учебы.",
    ["然后，在酒馆里和他们父亲再聊一会儿。"] = "Затем пообщайтесь некоторое время с их отцами в таверне.",
    ["然后，然后我的钱包就丢了！我花了很长时间才找回它！"] = "И тут, и тут у меня украли кошелек! Мне потребовалось много времени, чтобы найти его!",
    ["然后，赢两把试试水。"] = "Затем выиграйте пару раундов, чтобы проверить почву.",
    ["煤油灯晃在窄巷口，它蹲在排水沟，啃着昨夜的炸鱼骨，胡须沾满黑油。"] = "Керосиновая лампа покачивается у входа в узкий переулок, она приседает в сточной канаве, грызя вчерашние жареные рыбные кости, ее бакенбарды испачканы черным маслом.",
    ["煤灰猫，煤灰猫，破帽当窝也乐陶陶！煤灰猫，煤灰猫，<P_Heart>（破音）</>这不是你的——错！"] = "Угольно-пепельный кот, угольно-пепельный кот, ты рад даже разбитой шапке за гнездо! Угольно-зольный кот, Угольно-зольный кот, <P_Heart> (Голосовой треск) </>, это не твоя вина!",
    ["煤灰猫，煤灰猫，铁十字街你最横！教堂剩饭偷个遍，还挠过巡警的臀！"] = "Угольно-пепельный кот, угольно-пепельный кот, ты самый наглый на улице Айрон-Кросс! Ты украл из церкви все, что осталось, и даже поцарапал патрульному задницу!",
    ["煤灰猫，瞧啊，又来了一位自以为是的鉴赏家。"] = "Угольно-пепельный кот, смотри, приехал еще один самодовольный ценитель.",
    ["爱情！当然是爱情！就像街上那些吟游诗人唱的一样，爱情降临了。"] = "Любовь! Конечно это любовь! Как поют уличные барды, пришла любовь.",
    ["父亲决定去迪西海湾，医生建议他在那里休养一段时间。"] = "Отец решил поехать в Дези Бэй; врач предложил ему какое-то время подлечиться там.",
    ["爸爸对我很不好，对妈妈也很不好。妈妈走的时候，还是高德弗主教帮忙，才把妈妈埋到这里的……"] = "Папа очень плох со мной, и очень плох с мамой. Когда мама ушла, именно епископ Годфри помог похоронить ее здесь...",
    ["爸爸，妈妈，发生了什么事？"] = "Папа, мама, что произошло?",
    ["爸爸，我们为什么每天都来看别人吃饭？"] = "Папа, почему мы каждый день приходим посмотреть, как другие едят?",
    ["爸爸？难道你爸爸是……"] = "Отец? Может ли твой отец быть...",
    ["牌局很长，长得就像那个连输了十五把的男人流泻而出的悲伤。"] = "Карточная игра длинна, до тех пор, пока грусть изливается из того человека, который проиграл пятнадцать игр подряд.",
    ["特殊警察？我好像知道是什么事情了。"] = "Особый отдел полиции? Кажется, я понимаю, в чем тут дело.",
    ["牺牲的孩子们，只会被当做是“劳工损耗”！"] = "Принесенные в жертву дети рассматриваются только как «изнурение рабочей силы»!",
    ["狗生来就是要叫的……你输了老兄，不要把照看婴儿的怒气撒在狗身上。"] = "Собаки рождены, чтобы лаять... Ты проиграл, приятель, не расстраивайся из-за того, что присматриваешь за собакой.",
    ["猎犬……猎犬酒馆的老莱特告诉我，这里藏着能干事的人……什么……什么佣兵小队？"] = "Гончая... Старый Райт в таверне \"Собака\" сказал мне, что здесь спрятаны люди, способные добиться цели... Что... какой отряд наемников?",
    ["猫做得相当不错，非常称职！"] = "У кота все хорошо, очень компетентный!",
    ["猫是我最好的伙伴！"] = "Кошка — мой лучший друг!",
    ["猫猫怎么就不能是天使了！毛茸茸就是正义！"] = "Почему котёнок не может быть Ангелом! Пушистик – это справедливость!",
    ["猫跟瑞恩一样受大家的欢迎，它抓老鼠真的很棒。"] = "Кэт так же популярен, как и Райан; он действительно отлично ловит мышей.",
    ["王宫中的贵人？"] = "Дворяне во дворце?",
    ["玛莎姐，她们在舞会撒花，知不知道她们的衣服也泡在咱这大盆里呢？"] = "Сестра Марта, они разбрасывают цветы на балу, они знают, что их одежда тоже замачивается в нашем большом тазу?",
    ["现在从廷根就可以直接去往北面山脉和南面海港，驶向贝克兰德的列车数量变成了之前的两倍。"] = "Теперь из Тингена можно добраться напрямую до северных гор и южной гавани, а количество поездов, идущих в Бэкланд, удвоилось.",
    ["现在好了！裘德都撕破脸皮向他讨债了，他还以为人家是好人!"] = "Теперь смотри! Джуд сбросил маску и требует от него долга, а он все еще считает этого парня хорошим человеком!",
    ["现在我还有什么？哈哈，我还有三根卷烟……"] = "Что у меня есть сейчас? Ха-ха, у меня еще есть три сигареты...",
    ["现在的工作可不好找，如果你们愿意接受5便士的价格，我可以考虑多招一个人。"] = "Работу сейчас найти трудно, если вы готовы принять цену в 5 пенсов, я могу рассмотреть возможность найма еще одного человека.",
    ["现在购买还可以获得装饰雕花服务，无论家族纹章还是名字缩写都可以定制！"] = "Купите сейчас, и вы также сможете получить услуги декоративной гравировки; будь то фамильный герб или инициалы, его можно персонализировать!",
    ["现在购买还可以附赠品质上好的擦枪绸布——也可以定制为决斗白手套。"] = "При покупке сейчас вы также получите в подарок высококачественную шёлковую ветошь для чистки оружия — её также можно переделать в белую дуэльную перчатку.",
    ["现在那幅画的价格已经涨到一千五百镑了。"] = "Теперь цена этой картины выросла до полутора тысяч фунтов.",
    ["现在都什么年代了，还撞冰山！而且海报贴在教堂，肯定有风暴教会的庇佑。"] = "Что это за эпоха, когда еще говорят о столкновении с айсбергами! Кроме того, плакаты вывешены в церкви, значит, она должна иметь благословение Церкви Штормов.",
    ["现在，该你上场了。为了廷根的未来，开始一场大清扫吧！"] = "Теперь твоя очередь. Ради будущего Тингена начните великую уборку!",
    ["珍……我不希望你找到我给你的项链，你已经留在原地太久了。"] = "Джен... Я не хочу, чтобы ты нашла ожерелье, которое я тебе подарил. Вы слишком долго оставались на одном месте.",
    ["珍妮特奶奶年纪大了，我来帮她做宣传——来帮忙的学生，馅饼管够！"] = "Бабушка Джанет старая, я здесь, чтобы помочь ей продвигаться по службе — студенты, которые помогают, получают весь пирог, который они могут съесть!",
    ["珍是我的夫人。"] = "Джейн — моя супруга.",
    ["珍，原谅我的自私，项链就在天台的角落。"] = "Джейн, прости мой эгоизм. Ожерелье находится в углу крыши.",
    ["珠宝的耀眼会被飞雪遮掩，但得体的搭配永不会黯淡，来吧！让我看看你的品鉴方式。"] = "Блеск драгоценностей может скрыть кружащийся снег, но подобающий наряд никогда не померкнет. Ну же! Покажи мне своё чувство вкуса.",
    ["班森，你觉得呢？"] = "Бенсон, что ты думаешь?",
    ["理解您的心情。这样，我们进去，我把所有原始单据、您的签字记录、成本合约一一拿给您看。布莱克，我记得这些物品的整理你做得很好，对吧？"] = "Я понимаю, что ты чувствуешь. Как насчет этого: мы зайдем внутрь, и я покажу вам все оригиналы квитанций, подписанные вами записи и договоры сметы один за другим. Блейк, я помню, ты отлично справился с организацией этих вещей, верно?",
    ["瑞尔……什么都没留下。"] = "Риэль... ничего после себя не оставила.",
    ["瑟薇小姐，上周那场新话剧，你怎么看？"] = "Мисс Серве, что вы думаете о новой пьесе на прошлой неделе?",
    ["瑟薇小姐，你的阅读量可真惊人。 "] = "Мисс Серве, объем вашего чтения поистине поразителен.",
    ["生活会教给你这些规矩的。"] = "Жизнь научит вас этим правилам.",
    ["用旁边乐团演奏的曲子做我的配乐正合适。唔，用你来当伴舞好像也不错。怎么样有兴趣吗？"] = "Использовать в качестве аккомпанемента музыку, которую играет оркестр по соседству, — это просто правильно. Хм, использовать тебя в качестве дублера тоже неплохо. Как насчет этого, интересно?",
    ["由丝绸制成，样式工整考究，标价6苏勒。"] = "Сшито из шелка, фасон аккуратный и изысканный, цена — 6 су.",
    ["由贝克兰德的顶尖珠宝匠耗时三年打造，每一颗宝石都经过严格挑选。"] = "Каждый драгоценный камень, созданный лучшим ювелиром Баклунда на протяжении трех лет, подвергался строгому отбору.",
    ["男模？"] = "Мужская модель?",
    ["画是静止的，人是活的。您不觉得……流动的线条，更有艺术张力吗？"] = "Картины статичны, люди живы. Вам не кажется... плавные линии обладают большей художественной напряженностью?",
    ["略萨那群蠢货都以为我是喝醉了才在这里发酒疯。没人相信我真的戒酒了。"] = "Эти идиоты вроде Льосы думают, что я пьян и устраиваю здесь сцену. Никто не верит, что я действительно бросил пить.",
    ["疯了吧！弗兰奇！就算公寓水管吱嘎作响、墙壁泛潮生霉、门窗关不严实，只要不影响基本居住和收取租金，他就绝不处理！"] = "Он сумасшедший! Фрэнки! Даже если в квартире скрипят трубы, стены сырые и покрыты плесенью, а двери и окна не закрываются плотно, пока это не влияет на элементарное проживание и сбор арендной платы, он никогда с этим не справится!",
    ["病人？今天来的只是“顾客”，“医生给我开点补药”、“医生我手指头流血了”……"] = "Пациенты? Сегодня одни «клиенты»: «Доктор, выпишите мне тоники», «Доктор, у меня палец кровоточит»…",
    ["痛……头好痛……呜呜呜……声音、声音又出现了……"] = "Боль... у меня так болит голова... ууууу... звук, звук вернулся...",
    ["白天卖牡蛎，傍晚清理牡蛎，晚上运送牡蛎，牡蛎，牡蛎，全是牡蛎！"] = "Днем продаем устрицы, вечером чистим, ночью перевозим устрицы, устрицы, устрицы, это все устрицы!",
    ["白天工作，晚上还工作？老兄，早知道你是这样的工作狂，我就不和麦基拼床位了，直接睡你的不就好了！"] = "Работаете днем ​​и работаете ночью? Приятель, если бы я знал, что ты такой трудоголик, я бы не делил койку с Макки, я бы просто спал на твоей!",
    ["白天，被过道两旁的高窗染色的阳光让整个教堂都充满安宁。"] = "Днем солнечный свет, проникающий в высокие окна по обе стороны нефа, наполняет умиротворением весь собор.",
    ["白白胖胖，看起来把自己养得很好。"] = "Белый и пухлый, похоже, он очень хорошо о себе заботится.",
    ["目前最紧要的，就是为我们今晚找个落脚处。外交大臣，你熟悉廷根市场这片区域，你有什么好点子吗？"] = "Сейчас важнее всего найти ночлег на сегодняшнюю ночь. Министр иностранных дел, вы хорошо знаете район Тингенского рынка — есть какие-нибудь мысли?",
    ["相较于另一家面包店的产品来说，这里的饼干性价比低了一点。"] = "По сравнению с продукцией другой пекарни соотношение цена-качество печенья здесь немного ниже.",
    ["看什么看！不要看我！呜……不要再看我了……"] = "Что ты смотришь! Не смотри на меня! Ууу... не смотри больше на меня...",
    ["看什么看？画你的画！"] = "На что ты смотришь? Нарисуйте свою картину!",
    ["看你的指甲和牙龈颜色，是受到了铅的影响……必须离开有害的环境。"] = "Судя по цвету ваших ногтей и десен, это отравление свинцом... Вам необходимо немедленно покинуть вредное производство.",
    ["看到那艘船了吗？那是开往拜亚姆的。"] = "Видишь этот корабль? Это тот, который направляется в Баям.",
    ["看得我太憋屈了，退票！我要求退票！"] = "Было так неприятно смотреть, верните деньги! Я требую возврат денег!",
    ["看您收拾的这些行李，似乎是要离开廷根了？看起来有些不舍。"] = "Судя по собранным вещам, вы покидаете Тинген? Кажется, вам нелегко расставаться с этим местом.",
    ["看您是生面孔，现在买书，我还自掏腰包请您喝黑啤酒。"] = "Поскольку ты новое лицо, если ты купишь книгу сейчас, я заплачу из своего кармана, чтобы угостить тебя черным пивом.",
    ["看您的样子，是第一次踏足廷根的夜？那您找对地方了。这里是这座城里唯一能让时间慢下来的角落。酒是上等的，人……更是。"] = "Судя по вашему виду, вы впервые окунулись в ночную жизнь Тингена? Что ж, вы попали точно по адресу. Это единственный уголок в городе, где время словно замирает. Выпивка здесь отменная, а люди... и того краше.",
    ["看来您已经开始用自己的节奏感受这座城市了。廷根的每个角落都值得花时间品味，尤其是在不同的光线之下……总会发现新的细节。 "] = "Кажется, вы начали чувствовать этот город в своем собственном темпе. Каждый уголок Тингена стоит того, чтобы насладиться им, особенно при разном освещении... вы всегда откроете для себя новые детали.",
    ["看来我对风暴信徒的想法也该改变了。"] = "Кажется, мне стоит изменить свое мнение о последователях Шторма.",
    ["看来这位{{先生|女士}}听我们讨论很久了，您也是佛尔思小姐的忠实读者吗？"] = "Кажется, этот {{ Mr.| Ms.}} уже давно прислушивается к нашей дискуссии. Вы тоже являетесь постоянным читателем «Мисс Форс»?",
    ["看病？预约了吗？"] = "Посещение врача? Вы договорились о встрече?",
    ["看看你们多幸福，什么都不用想，也不用担心。"] = "Посмотрите, как вы счастливы, вам не нужно ни о чем думать, не нужно беспокоиться.",
    ["看看我，我8便士就够了！"] = "Посмотрите на меня, мне 8 копеек достаточно!",
    ["看着这里来往的人，心情也会变得畅快许多！"] = "Наблюдая за тем, как сюда приходят и уходят люди, настроение становится намного веселее!",
    ["看起来和其他鸡蛋也没什么差别……但是，大大提高了鸡蛋产量啊！希望能尽快推广，这样就不会有人饿肚子了……"] = "На вид обычные яйца, ничем не отличаются от других... Но они же невероятно увеличивают яйценоскость! Надеюсь, этот метод поскорее распространят, и тогда никто не будет голодать...",
    ["看起来好得没话说。"] = "Выглядит безупречно.",
    ["看起来，你是一个很深情的人。"] = "Кажется, вы очень ласковый человек.",
    ["看起来，这只狒狒对华丽的东西很有兴趣啊……"] = "Кажется, этот бабуин очень любит яркие вещи...",
    ["看跳舞。"] = "Смотрю танец.",
    ["看那曲线！他拉桨时的背阔肌展开角度，简直是艺术品。"] = "Посмотрите на эту кривую! То, как расширяется его широчайшая мышца спины, когда он тянет весло, — это просто произведение искусства.",
    ["看那边拥挤的候车区，我仿佛能闻见东区小伙子们恶心的汗臭味！"] = "Посмотрите на эту переполненную зону ожидания, мне кажется, что я чувствую отвратительный запах пота парней из Восточного округа!",
    ["看！连你们自己人都说了，就是个“印子”！哪值得三苏勒？什么百分之五的慈善，就是这么搜刮出来的吧？"] = "Смотреть! Даже ваши люди сказали, что это просто «метка»! Сколько стоят три суле? Так собирают эти «пять процентов благотворительности»?",
    ["真、真的？那我得赶紧跑了。"] = "Р-правда? Тогда мне придется бежать быстро.",
    ["真不容易。"] = "Это непросто.",
    ["真不明白他哪里来的钱修金马桶，我在另一位议员家工作的妹妹说，她的主人过得很朴素。"] = "Я правда не понимаю, откуда он взял деньги на установку золотого унитаза. Моя сестра, которая работает в доме другого советника, говорит, что ее хозяин живет очень просто.",
    ["真不知道温德姆太太是怎么打理这么多花的！"] = "Я действительно не понимаю, как миссис Уиндем удается заботиться о таком количестве цветов!",
    ["真奇怪，谁会在水里建一座拱形的房子呢？ "] = "Как странно. Кто построит арочный дом на воде?",
    ["真奇怪，这本书似乎总是自己翻到这一章。莫非是我某次阅读时，不经意折损了书脊？"] = "Как странно, эта книга, кажется, всегда сама переходит к этой главе. Может быть, я случайно повредил позвоночник во время одного из чтений?",
    ["真希望我在贝克兰德大学能经历一段奇遇。"] = "Я очень надеюсь, что меня ждет приключение в Университете Баклунда.",
    ["真希望我的猫能快点回家！"] = "Я очень надеюсь, что мой кот скоро вернется домой!",
    ["真心？哦，那真是稀有品——比我们家的古董银器还稀有。"] = "Подлинный? О, это редкость, реже, чем старинное серебро нашей семьи.",
    ["真是一次仓促的交接，但感谢女神庇佑，让这片领地有了一位合适的主人。"] = "Передача была поспешной, но благодаря благословению богини у этой территории появился подходящий владелец.",
    ["真是个特别的孩子……愿她一切顺利。"] = "Какой особенный ребенок... Пусть у нее все будет хорошо.",
    ["真是可惜，这家餐馆是我和奥杰里克先生友谊的见证，我们就是在一张餐桌上认识的！"] = "Жаль; этот ресторан является свидетельством дружбы между мной и господином Оджериком. Мы встретились за обеденным столом!",
    ["真是太感谢了，善良的{{先生|女士}}，如果你见到它，请一定告诉我。"] = "Спасибо огромное, добрый {{Mr.|Ms.}}, если увидишь, обязательно скажи.",
    ["真是太感谢您了，{{先生|女士}}，廷根时尚协会的成员真是这条街上最难接待的客人！"] = "Огромное спасибо, {{ Mr. | Ms. }}. Члены Ассоциации моды Тинген – поистине самые трудные гости на этой улице!",
    ["真是好孩子，不过我想笔是不会自己写作业的哦。"] = "Какой хороший ребенок, но боюсь ручки не делают уроки сами.",
    ["真正有病的人可走不进这里。他们付不起。"] = "Люди, которые действительно больны, не могут сюда войти. Они не могут себе этого позволить.",
    ["真正的风尚，是能在花香与微风之间，恰到好处地展现自己的气质；既然你已经站在花的世界里，不如接受这场属于花海的品鉴挑战。"] = "Настоящая мода – это способность проявить свой темперамент между ароматом цветов и ветерком; поскольку вы уже находитесь в мире цветов, почему бы не принять этот вызов, принадлежащий морю цветов.",
    ["真正的风景可都在屋顶上面！跟我一起飞一圈怎么样？"] = "Настоящие пейзажи - все на крышах! Как насчет того, чтобы пролететь со мной круг?",
    ["真没想到，这么多年过去，她现在已经是一位勇敢的冒险家了，而我还从没走出过廷根。"] = "Я никогда не ожидал, что за все эти годы она станет отважной искательницей приключений, а я даже ни разу не выходил из Тингена.",
    ["真的吗……那太好了。<P_Heart>（略显歉疚）</>那片领地一直都缺少打理，也没有正式开始什么建设。您出1000苏勒，我想就已经很合适了。"] = "Действительно? Это было бы замечательно. <P_Heart> (с легким извиняющимся видом) </> Эта земля всегда не нуждалась в уходе, и официальное строительство не началось. Думаю, 1000 суле будет вполне уместно.",
    ["真的吗？但我不觉得是我看走眼了，看那朵云……"] = "Действительно? Но я не думаю, что увидел это неправильно. Посмотрите на это облако...",
    ["真的吗？但是……像我这样的工人写的诗，会有人看吗？"] = "Действительно? Но... будет ли кто-нибудь читать стихи, написанные таким рабочим, как я?",
    ["真的吗？但是总不能无缘无故没人来吧。"] = "Неужели? Но не могут же люди перестать приходить вовсе без всякой причины.",
    ["真的吗？太好了！我欠你一个人情！"] = "Правда? Как здорово! Я твой должник!",
    ["真的有啊！那应该叫他们什么？"] = "Они действительно существуют! Тогда как мне их называть?",
    ["真的！我天天侍弄它们，最清楚了。尤其是玫瑰，刺都比别处的尖。常来的罗珊小姐也总这么说！"] = "Это правда! Я забочусь о них каждый день, поэтому знаю лучше всех. Особенно розы; даже их шипы острее других. Мисс Розель, которая часто приходит, тоже всегда так говорит!",
    ["真的？那戏我可盼了好久了。 "] = "Действительно? Я давно ждал этой пьесы.",
    ["真聪明！"] = "Такой умный!",
    ["瞧瞧这天气，看上去像晴天吗？船长还在那检查货物是否在船上，我敢说，出航两小时后我们都会在海底。"] = "Посмотрите на эту погоду, она похожа на солнечный день? Капитан все еще там, проверяет, находится ли груз на корабле. Держу пари, что через два часа после отплытия мы все окажемся на дне моря.",
    ["瞧瞧这拥有专利的减震锤柄，可以保证连续粉碎敌人的阴谋之后，也不会影响您手握下午茶茶杯的优雅！"] = "Посмотрите на эту запатентованную амортизирующую рукоятку молотка; это гарантирует, что после непрерывного разгрома заговоров врага это не повлияет на элегантность того, как вы держите чашку послеобеденного чая!",
    ["瞧瞧，墙上一个指甲盖大的印子，扣我三苏勒！窗钩生锈，又两苏勒！这破地板我搬进来就是旧的，现在跟我说磨损过度？！"] = "Смотри, отметина размером с ноготь на стене, и ты снимаешь с меня три суле! Оконный крючок ржавый, это еще две суле! Когда я въехал, этот сломанный пол уже был старым, а теперь вы говорите мне, что он сильно изношен?!",
    ["瞧瞧，这些吵闹的人，愚蠢地交出自己所剩不多的钱，还自以为能大捞一笔！"] = "Посмотрите на этих шумных людей, которые по глупости раздают те немногие деньги, которые у них остались, думая, что смогут заработать большую сумму!",
    ["知识……哼，爷爷说知识很重要，但也说有些人会用知识做坏事。您最好别打什么主意。"] = "Знания... Хм, дедушка говорит, что знания важны, но он также говорит, что некоторые люди используют их, чтобы делать плохие вещи. Лучше бы тебе ничего не затевать.",
    ["知足吧，伙计，煤还算轻的，上次推铁矿石，那才叫一个累。 "] = "Будь доволен, приятель, уголь все еще легкий, а толкать железную руду в прошлый раз было, что называется, утомительно.",
    ["知道了，这就去给那几个不知轻重的小混蛋上一课。"] = "Понял, сейчас пойду и проучу этих зарвавшихся щенков.",
    ["确实如此。上周卡洛琳夫人的茶会，名义上是品鉴新到的锡兰红茶，实际上是为她侄女物色对象。"] = "Именно так. На прошлой неделе чаепитие у госпожи Кэролайн формально устраивалось для дегустации свежего цейлонского чая, а на деле — чтобы подыскать пару для ее племянницы.",
    ["确实美得令人窒息，它的……"] = "Это действительно потрясающе красиво, это...",
    ["社交季连续赴宴是什么感受？"] = "Каково это — постоянно посещать банкеты в течение светского сезона?",
    ["祂想让我知道不要一直回头看，前面的路更美好。"] = "Она хочет, чтобы я понял: не нужно всё время оглядываться назад, ведь путь впереди куда прекраснее.",
    ["祝你好运。"] = "Удачи.",
    ["祝你好运！"] = "Удачи!",
    ["祝你好运！有需要我会来找你。"] = "Удачи! Я приду и найду тебя, если мне это понадобится.",
    ["祝您找到愿意为5便士卖命的傻瓜。"] = "Надеюсь, ты найдешь дурака, готового умереть за 5 пенсов.",
    ["祝里面的朋友好运。"] = "Удачи друзьям внутри.",
    ["神秘物品……？"] = "Таинственный объект...?",
    ["科恩老师在学术上十分严谨，我很乐意拿自己的想法跟老师聊聊。"] = "Профессор Коэн очень строг в учебе, и я рад обсудить с ним свои идеи.",
    ["租房子还是找慈善性改善住房公司吧……可我、可我又没钱接种主要的疫苗……"] = "Для аренды надо еще поискать благотворительную компанию по благоустройству жилья... а у меня, но денег на основные вакцины нет...",
    ["积累足够的军功，便可向我申请晋升军衔。从列兵到总帅，每一阶都需要用战绩来说话。"] = "Accumulate enough military merit, and you can apply to me for a promotion in rank. From private to commander-in-chief, every rank requires battle achievements to speak for itself.",
    ["窗后，深眠花恬静地开放着。"] = "За окном тихо цветут Спящие цветы.",
    ["站住！总算给我抓到了，上次逃课的也是你吧？你叫什么名字，是哪个专业的？"] = "Останавливаться! Наконец-то я тебя поймал, это ты прогулял урок в прошлый раз, верно? Как тебя зовут и на какой специальности ты учишься?",
    ["站起来！"] = "Вставай!",
    ["童工的手指纤细，工厂主招他们去清理转轴上卡住的棉絮。"] = "У детей-работников тонкие пальцы, поэтому владельцы фабрик нанимают их для очистки хлопкового ворса, застрявшего в шпинделях.",
    ["笔挺板正的衬衫，散发着体面的味道，标价9镑15便士。"] = "Накрахмаленная строгая рубашка, от которой веет респектабельностью, с ценником в 9 фунтов 15 пенсов.",
    ["笔，你是一支成熟的笔了，你得学会自己写作业。"] = "Пен, ты теперь зрелая ручка. Вы должны научиться делать домашнее задание самостоятельно.",
    ["第一阶段，声称塔索克河没什么问题。"] = "Фаза первая: заявить, что с рекой Тассок все в порядке.",
    ["第三趟了！这铁皮箱温度越来越高！不会要爆炸了吧！ "] = "Это третья поездка! Температура этого железной коробки становится все выше и выше! Он не взорвется, не так ли?",
    ["第三阶段，声称也许应该行动，但该死的，又开始连日下雨。"] = "Фаза третья: заявить, что, возможно, нам следует действовать, но, черт возьми, уже несколько дней подряд идет дождь.",
    ["第二段上难度了，每隔一段时间会陷入黑暗。"] = "Второй раздел становится сложнее; время от времени он будет погружаться во тьму.",
    ["第二阶段，声称也许会有意外出现的污染，但我们不该贸然行动。"] = "Второй этап — заявить, что может быть неожиданная Искажение, но не следует действовать опрометчиво.",
    ["第四纪的相关历史不确定的内容太多，你应该从现有的遗物入手研究，排除不确定因素。"] = "В истории Четвертой Эпохи слишком много неясностей; вам следует начать исследование с существующих реликвий и исключить неопределенные факторы.",
    ["第四阶段，声称也许应该在下雨前做点什么，但现在已经太迟了。"] = "Фаза четвертая: утверждать, что, возможно, нам следовало что-то сделать до того, как пошел дождь, но теперь уже слишком поздно.",
    ["等一下见到他，我应该矜持一些，还是扑他个满怀？"] = "Должен ли я быть сдержанным, когда увижу его позже, или мне следует броситься в его объятия?",
    ["等他毕业，找到份体面工作，我们一家人就能在廷根真正站住脚了！ "] = "Как только он закончит обучение и найдет достойную работу, наша семья сможет по-настоящему твердо стоять в Тингене!",
    ["等你到了，请记得给我你的信。"] = "Когда приедешь, пожалуйста, не забудь отправить мне письмо.",
    ["等你更加熟练后，还能看到更多。很有用的技能，对吧？"] = "Когда вы станете более опытным, вы сможете видеть больше. Очень полезный навык, правда?",
    ["等到下街的那群醉鬼打着酒嗝上工，牡蛎的臭味和猫鼠大军就把我可怜的房子淹没了。"] = "К тому времени, как эти пьяницы с Нижней улицы пойдут на работу, икая, вонь устриц и армия кошек и мышей заполонят мой бедный дом.",
    ["等我考上了，想点蜡烛就点蜡烛，还要买一盏全新的煤气灯，想亮多久就亮多久……"] = "Когда я пройду, я буду зажигать свечи, когда захочу, и куплю новенькую газовую лампу, и буду гореть столько, сколько захочу...",
    ["等我选上市长，你不就是了嘛？再忍忍，我的宝贝。"] = "Когда меня изберут мэром, ты будешь? Потерпи еще немного, мое сокровище.",
    ["等我选举成功，我向民众承诺的一切都会得到兑现！"] = "Как только я буду успешно избран, все, что я обещал народу, будет выполнено!",
    ["等爸爸当上领班，就能带你们来这里吃饭了！当然要提前学学，不能被那些绅士小姐笑话。"] = "Вот станет папа мастером — и я смогу приводить вас сюда обедать! Конечно, надо учиться заранее, чтобы господа и дамы над нами не смеялись.",
    ["等着吧，明天的头版头条就是他们俩的同框照片！"] = "Подождите, завтрашний заголовок на первой полосе будет их совместной фотографией!",
    ["等等，{{先生|女士}}。"] = "Подожди, {{sir|madam}}.",
    ["等等，怎么有一些……黑色的毛？"] = "Подождите, а почему здесь какой-то... черный мех?",
    ["等船抵达的时间总是这么短暂，又要开始干活了。"] = "Время ожидания прибытия корабля всегда так мало, что пора снова начинать работать.",
    ["答应他！答应他！答应他！"] = "Скажи да! Скажи да! Скажи да!",
    ["简直不把我们当人看！问？问也是白费功夫！"] = "Они вообще не относятся к нам по-человечески! Просить? Спрашивать – это пустая трата усилий!",
    ["算。但有钱就能摆平。<P_Heart>（叹气）</>剧院要的是叫座的名字，谁在乎剧本是谁写的？"] = "Считается. Но деньги могут уладить всё. <P_Heart>（Вздох）</>Театру нужно громкое имя для кассы, кому какое дело, кто на самом деле написал пьесу?",
    ["管她们呢，这些最终还不是丢给我们搓！"] = "Да плевать на них, все равно стирать все это придется нам!",
    ["精彩精彩，你每次都会为迟到编造理由。但是托比，没有下次了。这些故事我已经听腻了。"] = "Блестящий, блестящий. Ты каждый раз придумываешь причину опоздания. Но Тоби, следующего раза не будет. Я устал слушать эти истории.",
    ["精神体之外是“星灵体”，他是前者与灵界、星界沟通的方式，也与意志和情绪有关。占卜和别的许多魔法，都是通过星灵体来施展的。"] = "За пределами Духовного Тела находится «Астральное Мировое Тело». Именно так первый общается с Духовным миром и Астральным миром, а также связан с волей и эмоциями. Гадание и многие другие виды магии совершаются через Тело Астрального Мира.",
    ["精选上等猪肉，经过秘制烟熏工艺，每一片都散发着浓郁的果木香气，嚼劲十足，适合任何时刻享用！"] = "Свинина премиум-класса, обработанная секретной техникой копчения, каждый кусочек источает насыщенный фруктово-древесный аромат, жевательный и сытный, подходящий для любого момента!",
    ["糟了！{{他|她}}听见你说锁好打开了！"] = "О, нет! {{He|She}} слышал, как вы сказали, что замок открыт!",
    ["系列名不如就叫《廷根市的幕后交易》，这一次的主题是议员与工厂大亨的私人会面。"] = "Как насчет названия сериала «Закулисные сделки в Тингене»? На этот раз темой является частная встреча члена совета и фабричного магната.",
    ["红宝石罗莎，可以说是我们这里最好的舞者。她往台上一站，底下就安静了。"] = "Руби Роза, возможно, наша лучшая танцовщица. Как только она выходит на сцену, публика замолкает.",
    ["红月之跃，那就像鹰之翱翔一般，能让你体会真正自由的感觉！"] = "Прыжок Красной Луны, словно парящий орел, позволит вам ощутить ощущение настоящей свободы!",
    ["约定的时刻到了，我的听众，也是这段历史的见证者。"] = "Настал назначенный час, мои слушатели и свидетели этой истории.",
    ["约瑟，我说了我们只需要三等座，这为什么是二等座车票？"] = "Джозеф, я же сказала, что нам нужны билеты только в третий класс! Почему это билет во второй класс?",
    ["绑上气球，飞向这雕像的顶端吧！什么？你问我有没有危险？小丑时刻与危险相伴！不然怎么能让您捧腹大笑呢？"] = "Привяжите его к воздушному шару и взлетайте на вершину этой статуи! Что? Вы спрашиваете меня, опасно ли это? Клоуна всегда сопровождает опасность! Иначе как бы я мог заставить тебя рассмеяться?",
    ["结束了，回去吧……希望下次光临。"] = "Все кончено, возвращайтесь... Будем рады видеть вас снова.",
    ["结果呢？"] = "Результат?",
    ["结果？"] = "Как результат?",
    ["给悠哉的日子一些冲击，有点意思。"] = "Очень интересно придать немного силы этим неторопливым дням.",
    ["绝对没有！他每天忙着调配那些清洁药剂，早就忘了还有人苦苦等待着一瓶饮料！"] = "Абсолютно нет! Он каждый день занят смешиванием чистящих средств и давно забыл, что кто-то с горечью ждет бутылочку с напитком!",
    ["绿色队伍的船身比我们轻三磅，但少爷的划桨频率经过特殊设计！"] = "Лодка зеленой команды на три фунта легче нашей, но темп гребли молодого господина был рассчитан особым образом!",
    ["罗伯特那家伙，又丢下小罗伯特到哪去了？"] = "Куда убежал этот парень Роберт, снова оставив маленького Роберта?",
    ["罗塞尔大帝是这么说来着？"] = "Император Розель именно так и говорил?",
    ["罗塞尔大帝有句诗是怎么说的来着？“许多人曾爱过你美丽的青春，当你老去，我却依旧爱你脸上的皱纹”……"] = "Как прошло стихотворение императора Розеллы? «Многие любили твою прекрасную молодость, но когда ты состаришься, мне все еще нравятся морщины на твоем лице»…",
    ["罗莎今天那条裙子……是故意的吧？"] = "Сегодняшнее платье Розы... это было специально, да?",
    ["罗莎这个女人啊……让你花钱，还让你觉得花得值。"] = "Роза, эта женщина... она заставляет тебя тратить деньги и заставляет тебя чувствовать, что оно того стоит.",
    ["羊毛是剪的？不是薅的啊？"] = "Шерсть стригут? Не выщипывают, что ли?",
    ["美丽的姑娘，我只求你与我交往！"] = "Прекрасная леди, я только прошу тебя пойти со мной на свидание!",
    ["翠丝，我们离他远点！"] = "Трисс, давай держаться от него подальше!",
    ["老乔尼，你的怀表显示才三点？我流的汗都够给市长老爷的香槟塔续杯了！"] = "Старый Джонни, твои карманные часы показывают, что сейчас только три часа? Пролитого мной пота достаточно, чтобы снова наполнить башню шампанского мэра!",
    ["老人家，你们没事吧？"] = "Уважаемый, вы двое в порядке?",
    ["老兄，他那公寓臭名远扬，连水龙头都不让你多开！要是不怕客人再也不来买你的东西，你就尽管替他宣传吧！"] = "Приятель, его квартира пользуется дурной славой; он даже не позволит тебе слишком сильно открыть кран! Если вы не боитесь, что клиенты никогда больше не придут за вашим товаром, смело рекламируйте его!",
    ["老兄，你在这蹲着，肯定什么都见过！给点提示……"] = "Приятель, ты здесь сидел на корточках, ты, должно быть, все видел! Дайте мне подсказку...",
    ["老实说，我不确定……但是可以试试！不试试看怎么会知道结果呢，对吧？"] = "Честно говоря, я не уверен... но я могу попробовать! Как я узнаю результат, если не попробую, правда?",
    ["老师你工作六年了还是助教啊？"] = "Учитель, вы работаете уже шесть лет и все еще ассистент преподавателя?",
    ["老师，我是隔壁大学来旁听的，不是本班学生。"] = "Учитель, я прохожу одитинг в соседнем университете; Я не ученик этого класса.",
    ["老师，我是隔壁廷根大学来旁听的，不是本班学生。"] = "Учитель, я из Университета Тинген, который находится по соседству с аудитом, а не студент в этом классе.",
    ["老弟，来，喝一杯，哈加提草原的苦酒，后劲爽得像被金镑投怀送抱！"] = "Дружище, давай, выпей стаканчик! Горькое вино из степей Хагати — послевкусие такое приятное, словно в объятия золотых фунтов угодил!",
    ["老板，需不需要保镖？能帮你收租的！"] = "Босс, вам нужен телохранитель? Я могу помочь вам собрать арендную плату!",
    ["老规矩，你懂的……嗯？你是谁？"] = "Обычные правила, понимаешь... Хм? Кто ты?",
    ["老鼠肉？哪里来的？"] = "Крысиное мясо? Где ты это взял?",
    ["老，老师……"] = "Чай, учитель...",
    ["考试范围？"] = "Объем экзамена?",
    ["而且一定要在红月的时候体验！"] = "И вы должны испытать это во время Красной Луны!",
    ["而且我们已经委托侦探寻找它了，肯定很快就会有结果的。"] = "И мы уже поручили детективу его найти, так что результаты обязательно будут в ближайшее время.",
    ["而且是完美的引路者和投资人！"] = "И идеальный гид и инвестор!",
    ["而且这里离安布罗斯学长的书摊……不对，单纯是我习惯在这里了！"] = "Кроме того, это рядом с книжным киоском старшего Эмброуза... нет, подождите, просто я привык здесь находиться!",
    ["而且这里还闹过鬼！蒸汽在上，教会的人来看了之后就留下一盏煤油灯，也不知道有没有用。"] = "И это место населено привидениями! Наверху пара, церковники пришли посмотреть и оставили керосиновую лампу, но не знаю, пригодится ли она.",
    ["而且，尊敬的先生，如果您需要一些……嗯，不那么正式的情报，我们也有办法弄到。毕竟，在这片街区，孩子们的耳朵总是最灵的。"] = "И, уважаемый сэр, если вам нужна какая-то… ну, менее формальная информация, у нас есть способы ее получить. Ведь в этом районе детский слух всегда самый острый.",
    ["而且，那边有个失恋的醉鬼。钱包都等着了，你还等什么？"] = "К тому же вон там бродит пьяница с разбитым сердцем. Кошелёк сам просится в руки — чего же ты ждёшь?",
    ["而他唯一给你留下的东西不见了，你会怎么做？"] = "И единственное, что они оставили тебе, пропало, что бы ты сделал?",
    ["而到了夜晚，整个教堂都会在女神的庇佑下陷入静谧。"] = "А ночью весь собор погружается в спокойствие под защиту Богини.",
    ["而这里的先生女士们并不十分欢迎我们……这也是应该的，我们没有好衣服，家里杂物很多，也没有多余的钱购买会客的糕点。"] = "А здешние дамы и господа не слишком-то нам рады... Впрочем, неудивительно: у нас нет приличной одежды, в доме полно старья, да и лишних денег на пирожные для гостей нет.",
    ["耶，有男朋友了！"] = "Ура, у меня есть парень!",
    ["肉！肉！老鼠的肉！"] = "Мясо! Мясо! Крысиное мясо!",
    ["能为历史学的发展做出一点贡献，也是我的荣幸。"] = "Для меня большая честь внести небольшой вклад в развитие истории.",
    ["能否从沙盘之上，走到我的面前？这个问题，我很期待你能穿越战场，亲自回答我。"] = "Can you walk from the sand table to stand before me? I look forward to you crossing the battlefield to answer me yourself.",
    ["能趴在这里休息一会儿想来比蜷缩在角落舒服多了……"] = "Поваляться здесь и отдохнуть, должно быть, гораздо удобнее, чем свернуться калачиком в углу...",
    ["脚下留神，别让石头绊了跟头！"] = "Следите за своим шагом, не позволяйте камням сбить вас с толку!",
    ["臣民们，这次事态非常紧急，我需要大家的帮助。军情大臣，你先说明情况。"] = "Подданные, положение чрезвычайно серьёзное, мне нужна ваша помощь. Военный министр, сначала доложите обстановку.",
    ["至于她为什么会说话，这源于……一个小失误，一个所有养狗人都会犯的小错误：忘记自己的狗会开门。"] = "Что же касается того, почему она умеет говорить... все началось с одной маленькой оплошности. Ошибки, которую может совершить любой владелец собаки: забыть, что его питомец умеет открывать двери.",
    ["至少他们不用像咱这样，连养只老鼠都得算计面包屑。"] = "По крайней мере, им не обязательно быть похожими на нас, которым приходится считать хлебные крошки даже для того, чтобы поднять мышку.",
    ["至少我们还有那2便士。"] = "По крайней мере, у нас еще есть эти 2 пенсов.",
    ["艰难？当然艰难，但这让我们变得更强大。我们有自己的规矩，有自己的地盘，甚至还有自己的“生意”。"] = "Трудный? Конечно, это сложно, но это делает нас сильнее. У нас свои правила, своя территория и даже свой «бизнес».",
    ["艾克，我每天都能在这看见他。"] = "Айке, я вижу его здесь каждый день.",
    ["艾米丽，我的妻子，她值得更好的生活，只是我给不了她……"] = "Эмили, моя жена, она заслуживает лучшей жизни, но я просто не могу ей этого дать...",
    ["花？好看是好看，顶啥用？一个便士买花儿都算大钱！能花多少？二十便士顶天了吧？ "] = "Цветы? Выглядят хорошо, но для чего они нужны? Копейка на цветы – это большие деньги! Сколько это может стоить? Самое большее двадцать пенсов, верно?",
    ["苏茜原本是一只血统不太纯正的金毛犬，是我父亲购买猎狐犬时获得的赠品。但她现在是我的家人，我的助手。"] = "Сьюзи изначально была золотистым ретривером с не очень чистой родословной; она была подарком, когда мой отец купил фоксхаунда. Но теперь она моя семья, мой помощник.",
    ["苏茜女士建议用“命运”作为咖啡厅的名字，因为这个词的鲁恩语发音像摇篮曲尾声的轻叹一样让人感到平静，嗯，她的视角总是很别致。"] = "Г-жа Сьюзи предложила использовать слово «Судьба» в качестве названия кафе, потому что произношение этого слова в Лоэне кажется таким же спокойным, как вздох в конце колыбельной. Что ж, ее точка зрения всегда весьма уникальна.",
    ["苏茜的身份，让她避免了很多烦恼。当我们面对问题一筹莫展时，苏茜只要说——“我不知道，毕竟我只是一条狗”。"] = "Личность Сьюзи избавила ее от многих неприятностей. Когда мы не знали, что делать, Сьюзи просто говорила: «Я не знаю, в конце концов, я всего лишь собака».",
    ["若您是个浪漫的人，可以看看右手边的那些项链与头梳。"] = "Если вы романтический человек, обратите внимание на ожерелья и гребни для волос справа.",
    ["若您是个潮流的人，可以看看左手边的珠宝们。"] = "Если вы модный человек, можете взглянуть на украшения слева.",
    ["茜茜上晚课，出门和回家的马车也会吵到他们休息……这在搬家前甚至算不上烦恼，而现在，茜茜需要走到另一条街道坐马车。"] = "Чичи ходит на вечерние занятия, и поездка в карете домой и обратно тоже нарушает их отдых... До переезда это даже не было проблемой, но теперь Чичи нужно идти на другую улицу, чтобы сесть в карету.",
    ["茜茜喜欢看书……虽然和政府雇员考试没有关系，但她是个好孩子。"] = "Чичи любит читать... хотя это не имеет никакого отношения к экзамену на госслужащего, она хороший ребенок.",
    ["荣幸？你每次都这么说。 不过……你至少会看着我的眼睛说话。家里那位，三年没正眼瞧过我了。"] = "Честь? Ты говоришь это каждый раз. Однако... по крайней мере, ты смотришь мне в глаза, когда говоришь. Тот, кто дома, уже три года как следует на меня не смотрит.",
    ["药瓶堆得越高，命就越长。"] = "Чем выше гора склянок с лекарствами, тем дольше жизнь.",
    ["莉娜！我的脑和我的心，我全身上下的每一个器官！都在说着——我喜欢你！"] = "Лина! Мой разум и мое сердце, каждая клеточка, каждый орган моего тела — всё кричит о том, как я люблю тебя!",
    ["莉娜，这就是我的全部心意了，请我的爱人，我的女神，好好看看我的爱！"] = "Лена, это все мое сердце, пожалуйста, моя возлюбленная, моя богиня, взгляни хорошенько на мою любовь!",
    ["莉莉丝，到了贝克兰德要记得给我们写信。"] = "Лилит, не забудь написать нам, когда доберешься до Баклунда.",
    ["莫里森先生，您的好意我心领了。但现在不同了，哥温顿二世陛下下令让银行对小商人友善多了。"] = "Мистер Моррисон, я ценю вашу доброту. Но сейчас все по-другому; Его Величество Ковингтон II приказал банкам быть более дружелюбными к мелким торговцам.",
    ["萝拉，看，草莓蛋糕，双倍的奶油！"] = "Лола, смотри, клубничный торт, двойное количество сливок!",
    ["葡萄，不一样，尝？"] = "Виноград... другой... попробуешь?",
    ["蓝宝石莉莲小姐，弹琴的那位。她往钢琴前一坐，指尖落下的瞬间，整座厅的喧嚣都会退潮。"] = "Сапфир Лилиан, та, что играет на пианино. В тот момент, когда она садится за пианино и кончики ее пальцев опускаются, шум всего зала стихает.",
    ["薪水怎么样？"] = "Как жалование?",
    ["虽然不清楚发生了什么，但我本来也只是躲在厕所不被人笑话。现在就让我在这里待着吧，让我看看自己的笑话。"] = "Хотя я не знаю, что произошло, я просто прятался в туалете, чтобы все равно не смеяться надо мной. Позвольте мне пока остаться здесь; позволь мне быть моей собственной шуткой.",
    ["虽然什么？"] = "Хотя что?",
    ["虽然他们搬走的时候看起来并不快乐……我想，每一个离开水仙花街的人都会感到不舍的。"] = "Хоть они и не выглядели счастливыми при переезде... Думаю, всякому нелегко расставаться с улицей Нарциссов.",
    ["虽说是你努力的结果啦，但是听上去还是很神奇！我也想去测一下有关我以后的人生大事，婚姻啊，事业啊什么的。"] = "Хоть это и результат вашего упорного труда, оно все равно звучит очень волшебно! Я также хочу пойти и проверить некоторые важные жизненные события, такие как брак, карьера и так далее.",
    ["血族，如果你遇到塔罗会的“月亮”先生，一定不能提及吸血鬼三个字。"] = "Сангвиник. Если вы встретите мистера Муна из Клуба Таро, вы не должны упоминать слово «вампир».",
    ["行吧……至少工头说今天加班给双倍薪水。"] = "Ладно... по крайней мере бригадир сказал, что за сверхурочную работу сегодня платят вдвойне.",
    ["行吧。学的什么，哪个老师？"] = "Отлично. Что вы изучаете и кто ваш учитель?",
    ["行吧，看在你住铁十字街的份上。但如果周围的木头都烂透了，得加钱。"] = "Хорошо, учитывая, что ты живешь на Айрон-Кросс-стрит. Но если окружающая древесина полностью прогнила, придется доплатить.",
    ["行，今天先这样。明天要是少一便士，就没饭吃！"] = "Хорошо, это все на сегодня. Если завтра у тебя не будет ни копейки, ты не поешь!",
    ["被您提醒，我也该给家庭教师准备些白面包。那孩子饿得脸色发白，每次看到我们的下午茶都偷偷咽口水呢。"] = "Как вы напомнили, мне также следует приготовить для репетитора немного белого хлеба. Ребенок настолько голоден, что его лицо бледно, и он тайно сглатывает каждый раз, когда видит наш послеобеденный чай.",
    ["裘德爷爷，这是我学会的第三百四十一个单词，我可以和你一起帮大家写信了吗？"] = "Дедушка Джуд, это триста сорок первое слово, которое я выучил. Могу ли я помочь тебе сейчас писать письма для всех?",
    ["要不是我弟弟暂时征用了我的私家马车，谁愿意来坐公共火车呢？"] = "Если бы мой брат временно не завладел моей частной каретой, кто бы захотел сесть на общественный поезд?",
    ["要不然算了，我们厂罢工这么多次，也没见哪次真的有效果。"] = "Или, может быть, забудьте об этом, наша фабрика столько раз бастовала, и я никогда не видел, чтобы это принесло какой-либо реальный эффект.",
    ["要不要请假休息一阵子?"] = "Не хочешь взять отгул и немного отдохнуть?",
    ["要不试试加点增香剂？不行不行，那会让我的客人们上瘾的……"] = "А что, если добавить усилитель вкуса? Нет-нет, так мои посетители просто подсядут...",
    ["要买药和我说，问诊需要排队，看望病人病房在对面。"] = "Если хочешь купить лекарство, скажи мне. На консультации приходится стоять в очереди, а палата для посещения пациентов находится на противоположной стороне.",
    ["要听的话，一次3便士，我要赚赎身钱。"] = "Если хотите послушать — три пенса за раз. Мне нужно накопить денег на выкуп.",
    ["要想真正了解这里，不妨在教堂的钟声、市场的吆喝与酒馆的闲聊之间多走走，故事都藏在人们的日常里。 "] = "Если вы хотите по-настоящему понять это место, вам следует больше гулять между церковными колоколами, рыночными криками и разговорами в тавернах. Истории скрыты в повседневной жизни людей.",
    ["要是你愿意买上一磅肉，我就告诉你，只要前往艺术学派就能学到这么棒的舞蹈啦。"] = "Если вы готовы купить фунт мяса, я скажу вам, что такому великолепному танцу можно научиться, просто посетив художественную школу.",
    ["要是找不到，我也不想活了……"] = "Если я их не найду, мне и жить незачем...",
    ["要是真炸了，你说工厂主会给我们的寡妇多少抚恤金？够不够买块像样的墓碑？"] = "Если бы он действительно взорвался, как вы думаете, какую пенсию дал бы фабрикант нашим вдовам? Хватит ли этого, чтобы купить приличное надгробие?",
    ["要来体验一场紧张刺激的“百里挑蛋”吗？"] = "Хотели бы вы принять участие в напряженном и захватывающем испытании «Одно из ста яиц»?",
    ["要知道……墓园里的闹鬼和活尸传闻并不罕见。"] = "Знаете ли... слухи о привидениях и ходячих мертвецах на кладбище — отнюдь не редкость.",
    ["要知道，所有出事锅炉都在年初通过了质检公司的“优质级”检验。"] = "Знаете ли, все взорвавшиеся котлы в начале года успешно прошли проверку компании по контролю качества с присвоением «Высшей категории».",
    ["要说真有病……呵，哪轮到他们。"] = "Если мы говорим о том, чтобы быть по-настоящему больным... хех, сейчас не их очередь.",
    ["见鬼的弗萨克火炮跟长了眼睛一样追着我们炸，我们这边倒好，火炮一个个炸膛！"] = "Эти проклятые пушки Фейсака преследовали нас, как будто у них были глаза, а наши взрывались одна за другой!",
    ["见鬼，你在胡说什么？他可是在因蒂斯发了好大一笔财，那封信我还随身带着呢！"] = "Черт возьми, о чем ты говоришь? Он заработал состояние на Интисе, и это письмо до сих пор со мной!",
    ["观众途径非凡者不仅可以心理治疗，也可以利用精神控制，让非凡者走向崩溃。"] = "Путь зрителя Потусторонние могут не только проводить психотерапию, но и использовать контроль над разумом, чтобы довести Потусторонних до коллапса.",
    ["警官您辛苦了！我这种小本生意人，就指望治安良好混口饭吃，有事您随时吩咐！"] = "Спасибо за ваш труд, офицер! Мелкий бизнесмен, такой как я, полагается на хороший общественный порядок, чтобы зарабатывать на жизнь. Если вам что-нибудь понадобится, просто дайте мне знать!",
    ["警官，哕，你偷偷告诉我，他是不是往马桶里藏金子了？"] = "Офицер, тьфу, скажите по секрету, он золото в унитазе прячет?",
    ["认真的？"] = "Ты серьезно?",
    ["让他们钻进管道清理煤灰。"] = "Их заставляют залезать в трубы, чтобы вычистить угольную золу.",
    ["让你意外吗？不是只有水手、海盗才信仰风暴之主。奥古斯都家族从鲁恩立国开始一直信仰“风暴之主”，我的家族亦是因航海而崛起。"] = "Вас это удивляет? Не только моряки и пираты верят в Повелителя Штормов. Семья Августов верила в «Повелителя бурь» с момента основания Лоэна, и моя семья также выросла благодаря мореплаванию.",
    ["让开点，小鬼！小心我的刀砍到你！"] = "Отойди в сторону, малыш! Берегись, иначе мой нож может тебя порезать!",
    ["让我想想……"] = "Дай подумать...",
    ["让我想想……这束红玫瑰送给塔莎，白色的给黛娜。"] = "Дай подумать... этот букет красных роз - для Таши, а белые - для Даны.",
    ["让我想想我的工具箱里有什么……嗯！有灵感了——"] = "Дайте мне подумать о том, что находится в моем ящике с инструментами... Хм! У меня есть вдохновение —",
    ["让我来。"] = "Разрешите.",
    ["让我猜猜它叫什么名字！"] = "Дайте угадаю его название!",
    ["让我考虑考虑……"] = "Позвольте мне рассмотреть это...",
    ["让路人来评评理，谁的爱人一周只能分一天给你？"] = "Пусть об этом рассудит прохожий. Чей возлюбленный может уделить вам только один день в неделю?",
    ["记住每场宴会不同主人的禁忌。威尔逊家不能提海鲜，因为长子对贝类过敏；卡洛斯家忌讳谈天气，他们家族的商船曾在暴风雨中损失惨重。 "] = "Помните о табу разных хозяев на каждом банкете. В семье Уилсонов нельзя упоминать морепродукты, потому что у старшего сына аллергия на моллюсков; Семья Карлос избегает разговоров о погоде, потому что торговые суда их семьи понесли тяжелые потери во время шторма.",
    ["记住，只要你信仰女神，在这里任何东西都无法伤害你。"] = "Помните: пока вы верите в Богиню, ничто здесь не сможет вам навредить.",
    ["诊所外面的那位就是我爷爷，他在战争之后患上阿尔茨海默病。在门口走来走去就是他自能障碍的表现之一，不用在意。"] = "Тот, кто возле клиники, — мой дедушка, у него после войны развилась болезнь Альцгеймера. Ходить туда-сюда у двери — одно из проявлений его когнитивных нарушений, не обращайте на это внимания.",
    ["诗人只用语言揭露真相，就像齿轮象征着工业的枷锁。"] = "Поэты используют язык только для того, чтобы раскрыть правду, точно так же, как шестерни символизируют оковы промышленности.",
    ["诗歌不分高低贵贱，只要内容够好，一定会受到人们的喜爱的。"] = "У поэзии нет сословий: если стихи хороши, люди непременно их полюбят.",
    ["该怎么办呢……"] = "Что я должен делать...",
    ["该死的世道，逼得我们干这种活儿……"] = "Этот чертов мир, заставляющий нас делать такую ​​работу...",
    ["该死！偏偏是集市这个地方，这么多人我该从哪里开始呢？"] = "Блин! Это рынок, на котором так много людей, с чего мне начать?",
    ["该死！这鞋子是我最心爱的！你这小鬼真是该死！"] = "Блин! Эти туфли мои любимые! Ты, маленький паршивец, ты действительно напрашиваешься на это!",
    ["该死，你又来这一套！"] = "Черт возьми, ты снова это делаешь!",
    ["该死，再这样我们就分手吧！"] = "Проклятье, если так пойдет дальше — давай расстанемся!",
    ["说什么呢？不要不学好，偷东西不是什么好事情！"] = "Что вы говорите? Не приобретайте вредных привычек; воровать нехорошо!",
    ["说到这个……上周《廷根市老实人报》确实报道过一个“醉酒之后就会变老实”的专栏作家酒后说的话，他说质检员的账户每月固定收到好几笔“技术咨询费”……"] = "Кстати говоря... на прошлой неделе газета «Честный человек Тингена» сообщила о том, что сказал после выпивки обозреватель, который «становится честным после того, как напивается». Он сказал, что на счет инспектора по качеству поступает несколько «плат за технические консультации» каждый месяц...",
    ["说实在的，比起这个，我更期待成为一名真正的大学生……"] = "Честно говоря, по сравнению с этим, я с нетерпением жду возможности стать настоящим студентом университета...",
    ["说得对。{{PlayerName}}，如果你是格尔曼·斯帕罗，你会选择哪种场景作为故事的舞台呢？"] = "Ты прав. {{PlayerName}}, если бы вы были Германом Воробьем, какую сцену вы бы выбрали в качестве сцены для своей истории?",
    ["说说看，你在瞧什么呢？"] = "Скажи мне, что ты смотришь?",
    ["说起来都是你的功劳，多亏你当时的提醒，我才能写出《黑铁时代那些事》和《所罗门皇帝》，也才有了现在的成功。"] = "Кстати говоря, это все ваша заслуга. Благодаря вашему напоминанию в то время я смог написать «Дела железного века» и «Император Соломон», и именно поэтому я добился нынешнего успеха.",
    ["说起来，你有没有留意到二楼有一块专门的地方，去那儿练习的人动作都很专业。"] = "Кстати говоря, вы заметили, что на втором этаже есть особое место? Люди, которые приходят туда тренироваться, обладают очень профессиональными движениями.",
    ["说起来，温德姆太太一个人真不容易。"] = "Если подумать, миссис Уиндэм действительно нелегко одной.",
    ["说那个什么贵族夫人……搞了个舞会？光买花就花了多少？"] = "Сказать, что какая-то благородная дама... закатила мяч? Сколько она потратила только на цветы?",
    ["请不要难过，只要想，总能回去的。"] = "Пожалуйста, не грусти, если захочешь, ты всегда можешь вернуться.",
    ["请你驾驶新警车绕行一圈，给我们提供宝贵的意见。小心点，别撞到市民。"] = "Пожалуйста, прокатитесь на новой полицейской машине и оставьте нам свой ценный отзыв. Будьте осторожны, не бейте граждан.",
    ["请便，四处看看。如果姑娘们的表演不合您的口味……那边也有专门陪姐姐们聊天的，嘴甜得很。 "] = "Пожалуйста, не стесняйтесь осмотреться вокруг. Если выступления девушек вам не по вкусу... там есть и те, кто специализируются на общении с дамами; у них очень сладкий язык.",
    ["请原谅我的激动，但见证天才本就是一件令人激动的事情。请为他加油吧！"] = "Пожалуйста, простите мое волнение, но быть свидетелем гениальности всегда волнительно. Пожалуйста, поболейте за него!",
    ["请原谅，我儿子正是调皮的年纪，我会像修理他父亲一样好好修理他的。"] = "Пожалуйста, прости меня; мой сын в озорном возрасте, и я буду наказывать его так же, как исправлял бы его отца.",
    ["请原谅，自从搬到廷根，我就遇到了太多这样的事情。"] = "Прошу прощения, но с тех пор, как я переехал в Тинген, мне слишком часто приходится сталкиваться с подобным.",
    ["请息怒，先生，你觉得刚才的台词怎么样？"] = "Пожалуйста, успокойтесь, сэр. Что вы думаете о строках сейчас?",
    ["请您给予我启示！我该买去哪个地方的蒸汽列车票？"] = "Пожалуйста, дайте мне немного вдохновения! Где мне купить билет на паровоз?",
    ["请抽取一张牌吧，让我们一同观看命——呜哇！不好意思，牌没拿稳，全撒了。"] = "Пожалуйста, вытяните карту, давайте посмотрим судьбу — упс! Извините, я плохо держал карты, они все рассыпались.",
    ["请擦拭我的墓碑……让我的名字清晰起来。我最后的气息将依附于你……请代我，完成那个拥抱。"] = "Пожалуйста, протрите мое надгробие... проясните мое имя. Мой последний вздох прильнет к тебе... пожалуйста, от моего имени, заверши это объятие.",
    ["请收下你的奖金吧！这是你自己赢得的！"] = "Пожалуйста, примите свои призовые деньги! Вы сами это заслужили!",
    ["请收下我的致敬！这是你自己赢得的！"] = "Пожалуйста, примите мою дань уважения! Вы заслужили это сами!",
    ["请暂别此刻的喧嚣，来到我的身边。"] = "Пожалуйста, оставь этот шум и подойди ко мне.",
    ["请留步一分钟，您有看见那艘红色的赛艇吗？三号桨手是我家的杰尼少爷。"] = "Постойте минуточку, вы случайно не видели ту красную гребную лодку? Третий гребец — юный господин Джени из нашего дома.",
    ["请问你们刚才说的前辈是？"] = "Могу я спросить, кто тот старший, о котором вы упомянули?",
    ["请问，托这位老太太的运是什么意思？"] = "Простите, что значит «полагаться на удачу этой старушки»?",
    ["请问，有什么推荐的报刊吗？"] = "Простите, есть ли у вас рекомендуемые газеты?",
    ["读得多了，自然就记得住。 至于我没记住的……不如玩个游戏？你问，我答。答错了——你罚我一杯，还是……我罚你一杯？"] = "Чем больше вы читаете, тем естественнее вы это запомните. Что касается того, чего я не запомнил... почему бы не поиграть? Вы спрашиваете, я отвечаю. Неправильный ответ - ты даешь мне выпить в качестве наказания, или... я даю тебе выпить в качестве наказания?",
    ["谁、谁说绑架，是你听错了吧。"] = "Кто, кто сказал что-нибудь о похищении? Вы, должно быть, ослышались.",
    ["谁是世界上最可爱的小猫啊？"] = "Кто самый милый котенок в мире?",
    ["谁知道呢。"] = "Кто знает.",
    ["谁知道呢，反正总比没有强。北区工人都戴着这种护符，那边事故率确实低一些。"] = "Кто знает, но это лучше, чем ничего. Все рабочие Северного округа носят эти обереги, и уровень несчастных случаев там действительно ниже.",
    ["调配魔药那天，苏茜开门进了实验室，舔舐了一份观众魔药。幸好我当时准备了两份材料。"] = "В день приготовления зелья Сьюзи открыла дверь, вошла в лабораторию и слизала порцию зелья Зрителя. К счастью, я тогда заготовила два комплекта ингредиентов.",
    ["谢尔敏先生还在认真研发新的“焦糖炸弹”吗？"] = "Г-н Шермин все еще усердно разрабатывает новую «Карамельную бомбу»?",
    ["谢谢你的夸奖，达利。"] = "Спасибо за комплимент, Дейли.",
    ["谢谢你的鼓励，我会去尝试的。"] = "Спасибо за вашу поддержку, я попробую.",
    ["谢谢你！你那首歌虽然……虽然那个……"] = "Спасибо! Хотя твоя песня была... хотя это...",
    ["谢谢你，感觉我又学到了很多……不早了，我先回家了。"] = "Спасибо, кажется, я снова многому научился... Уже поздно, я пойду домой.",
    ["谢谢你，我突然没有那么焦虑了。我做完下一台手术后，晚上就把演讲大纲赶出来！"] = "Спасибо, я внезапно перестал так волноваться. После того, как я закончу следующую операцию, я поспешу закончить конспект лекции сегодня вечером!",
    ["谢谢你，谢谢你……孩子们今天有面包吃了……"] = "Спасибо, спасибо... Детям сегодня будет хлеб есть...",
    ["谢谢各位慷慨的观众，明天在这里还有演出！"] = "Благодарю щедрую публику! Завтра на этом же месте состоится новое представление!",
    ["谢谢您的安慰，阁下。"] = "Благодарю за ваше утешение, Ваше Превосходительство.",
    ["谢谢您的慷慨！要赔偿的话，爸爸今晚的拳又白打了……"] = "Спасибо за вашу щедрость! Если мне придется выплатить компенсацию, сегодняшняя драка моего отца окажется напрасной...",
    ["谢谢您的提醒，让我看看——日用品消费满2苏勒可参与食品换购，布料消费会员当日可凭购物证明换咖啡豆，先到先得……"] = "Спасибо за напоминание, давайте посмотрим — покупки предметов первой необходимости на сумму более 2 суле имеют право на обмен едой, и участники могут в тот же день обменять товарные чеки на кофейные зерна на покупки тканей в порядке очереди…",
    ["谢谢您的支持，{{先生|女士}}。"] = "Спасибо за вашу поддержку, {{Mr.|Ms.}}.",
    ["谢谢您的理解，阁下，也祝您幸福。"] = "Спасибо за понимание, ваша милость, и да пребудет с вами счастье.",
    ["谢谢您的祝福，阁下。"] = "Благодарю за благословение, Ваше Превосходительство.",
    ["谢谢您的陪伴，阁下。"] = "Спасибо за вашу компанию, Ваше Превосходительство.",
    ["谢谢您！我要把小萨拉的消息告诉母亲，她一定会高兴的。"] = "Спасибо! Я хочу рассказать маме о новостях маленькой Сары; она обязательно будет рада.",
    ["谢谢您，{{先生|女士}}，医学派发的誓里可没写‘先数铜板再数脉搏’，无论如何，我会将医生的操守坚持到最后。"] = "Спасибо, {{Mr.|Ms.}}. Медицинская клятва не гласит: «Считайте монеты, прежде чем считать пульс». Несмотря ни на что, я буду отстаивать честность врача до конца.",
    ["谢谢您，弗兰奇先生。"] = "Спасибо, мистер Фрэнки.",
    ["谢谢您，这里真干净。"] = "Спасибо, здесь очень чисто.",
    ["谢谢，我会留神的。"] = "Спасибо, буду следить.",
    ["贝克兰德最近流行什么服饰？"] = "Какая мода популярна в Баклунде в последнее время?",
    ["财富的堆砌已经过时了，它们应该好好待在保险柜里，以后，工艺才是流行风尚，而爱丽丝小姐在这方面的嗅觉一向敏锐。"] = "Накопление богатства устарело; он должен оставаться в безопасности в хранилище. Отныне в моде мастерство, и мисс Алиса всегда отличалась острым нюхом на это.",
    ["贪心鬼，今天没有了，不过我还会再来的。"] = "Жадный призрак, сегодня его больше нет, но я приду снова.",
    ["贵族之间写信有很多讲究？"] = "Много ли нюансов в написании писем у дворян?",
    ["资本家们把安全阀换成便宜铜芯，省下的钱去雇更多工人。"] = "Капиталисты заменяют предохранительные клапаны дешевыми медными сердечниками и используют сэкономленные деньги, чтобы нанять больше рабочих.",
    ["赛琳娜的未婚夫还在旁边，你小声些，我过一会去看看。"] = "Жених Селены ещё рядом, говори тише. Я подойду взглянуть чуть позже.",
    ["赛艇运动在霍伊大学已经有了超过百年的历史。据统计，半数以上的毕业生都划得一手好船。"] = "Гребля в Университете Хой имеет более чем столетнюю историю. Статистика показывает, что более половины выпускников владеют греблей.",
    ["赞美您的眼光！这是本店华丽而具有威力的武器之首选！我们承诺它的哑火率比约翰议员的头发密度低23%！"] = "Хвалите свой глаз за качество! Это лучший выбор великолепного и мощного оружия в нашем магазине! Мы обещаем, что его процент осечек на 23% ниже, чем густота волос члена совета Джона!",
    ["赢了，我赢了！哈哈！"] = "Я выиграл, я выиграл! Хаха!",
    ["赫蒂小姐能来，是我的荣幸。"] = "Для меня большая честь, что мисс Хеди смогла прийти.",
    ["走开走开！"] = "Уходи, уходи!",
    ["赶快出来！带上你肮脏的行李滚出去！"] = "Немедленно выходи! Забирай свои грязные пожитки и убирайся вон!",
    ["赶快到周四啊！"] = "Торопитесь и пусть это будет четверг!",
    ["越强大越应该得到足够多的目光？不错的想法。"] = "Чем вы могущественнее, тем больше внимания вам следует уделять? Хорошая идея.",
    ["足以匹配您高贵品味的选择！这把枪用到了最新专利的螺旋膛线设计——能击落野鸭，也能在800码外将敌人送去见黑夜女神！"] = "Выбор, соответствующий вашему благородному вкусу! В этом ружье используется новейшая запатентованная конструкция спиральных нарезов: оно может сбивать диких уток и отправлять врагов на встречу с Богиней Вечной Ночи с расстояния 800 ярдов!",
    ["趴下！"] = "Спускайся!",
    ["路人都这么说了，你就原谅我这次吧。"] = "Раз так сказал прохожий, на этот раз ты должен меня простить.",
    ["路灯修好了！这下走夜路可以放心了。"] = "Уличный фонарь починен! Теперь я могу спокойно ходить ночью.",
    ["路边的室友果然靠不住！"] = "Соседи по комнате с обочины действительно ненадежны!",
    ["路过的好心人呐，帮帮可怜的老头吧。"] = "Добрый прохожий, помогите, пожалуйста, бедному старику.",
    ["路过，进来看看。 "] = "Проходя мимо, зашёл посмотреть.",
    ["路过，随便看看。"] = "Просто проходил мимо, оглядывался.",
    ["输了多少次？赢了多少次？没人记得了，你们似乎厮杀到了世界的末日、宇宙的尽头。"] = "Сколько раз вы проиграли? Сколько раз вы выиграли? Никто не помнит; ты словно сражался до конца света, края вселенной.",
    ["边走边说，带你去个地方。"] = "Давай поговорим на ходу, я отвезу тебя куда-нибудь.",
    ["达利！"] = "Дэйли!",
    ["近到……你能闻到我头发上的香水味。够近吗？ "] = "Настолько близко... чтобы ты почувствовал аромат духов в моих волосах. Достаточно близко? ",
    ["还不用担心饿肚子，每天都有人来喂你们。"] = "Не беспокойтесь о том, что вы останетесь голодными, вас кто-нибудь будет кормить каждый день.",
    ["还不错，欢迎你下次来找我们交流时尚知识。"] = "Неплохо, добро пожаловать к нам в следующий раз, чтобы обменяться знаниями о моде.",
    ["还好主教大人降临，他一上甲板，风向就变了，火炮也没再出问题，指哪打哪，真是神了！"] = "К счастью, епископ спустился; как только он ступил на палубу, направление ветра изменилось, и артиллерия перестала давать сбои, поражая все, во что была нацелена, это было поистине божественно!",
    ["还好这篇稿子也收了……"] = "По крайней мере, этот проект был принят...",
    ["还好邻居帮她度过了最难过的时候。"] = "Повезло, что соседи помогли ей пережить самые трудные времена.",
    ["还差鱿鱼先生？他在信里说晚点到，我们再等等。"] = "Не хватает только мистера Кальмара? Он написал в письме, что задержится, давайте подождем еще немного.",
    ["还挺神奇的。"] = "А это довольно занятно.",
    ["还挺神秘……不会是要拿去做什么坏事吧？"] = "Как-то всё это подозрительно... Не задумали ли они чего недоброго?",
    ["还是不对，你唱歌真难听。"] = "Всё-таки не так, ты очень плохо поёшь.",
    ["还是先好好复习吧，毕竟我连蜡烛都买不起，只能来这里凑合。"] = "Лучше как следует повторить материал. В конце концов, я даже свечи купить не могу, приходится перебиваться здесь.",
    ["还是算了吧，这钱我挣不了，你还是拿钱去看病吧。"] = "Забудь об этом, я не могу заработать эти деньги. Лучше возьми и обратись к врачу.",
    ["还有一家披肩店推出了联合消费券。好在在这家百货开业之前，我们还有很长的时间来计算出最划算的购买方案……"] = "Также есть магазин платков, который запустил талоны на совместное потребление. К счастью, до открытия этого универмага у нас еще есть достаточно времени, чтобы рассчитать наиболее экономически эффективный план закупок...",
    ["还有人提议预算再增加40%，因为承包商表示需要特殊工艺处理贵族区的香水残留物。"] = "Также есть предложение увеличить бюджет на 40%, поскольку подрядчик заявил, что для обращения с остатками парфюмерии в аристократическом районе необходимы специальные процессы.",
    ["还有什么事吗？"] = "Что-нибудь еще?",
    ["还有什么事？"] = "Что-нибудь еще?",
    ["还有介绍费？这……"] = "Есть вступительный взнос? Этот...",
    ["还有他说的“明珠”是什么猪？“鸣猪”……只听说过打鸣的公鸡，难道还有会打鸣的猪吗？"] = "И что это за свинья такая — «жем-чушка»? Поющая свинья?.. Слыхал я о поющих петухах, но неужели бывают и поющие свиньи?",
    ["还有伤口处理，不少人直接用不干净的水冲洗，或者随便找块布裹上，这反而容易化脓。正确的清洁、消毒和包扎，其实不难学。 "] = "А еще обработка ран: многие просто промывают их грязной водой или заматывают первой попавшейся тряпкой, из-за чего рана только быстрее начинает гноиться. А ведь правильной очистке, дезинфекции и перевязке совсем не трудно научиться. ",
    ["还有你的小……兔子？熊？呃，鸭子？总之，无论是什么，奶奶都帮你修好了，和之前一模一样。"] = "А твой маленький... кролик? Медведь? Э, утка? В любом случае, что бы это ни было, бабушка все для тебя починила, как и было раньше.",
    ["还有六只！我都数着呢！ "] = "Есть еще шесть! Я считал!",
    ["还有刚刚出炉的精选上等猪肉，经过秘制烟熏工艺，每一片都散发着浓郁的果木香气，嚼劲十足，适合任何时刻享用！"] = "Также есть свежезапеченная свинина премиум-класса, обработанная секретной техникой копчения, каждый кусочек источает насыщенный фруктово-древесный аромат, жевательный и сытный, подходящий к любому моменту!",
    ["还有别的可以看看吗？"] = "Есть ли что-нибудь еще, на что я могу посмотреть?",
    ["还有我的花！奇怪，它连三明治都不碰，就喜欢这些漂亮摆设。"] = "И мои цветы! Странно, но к бутербродам он даже не прикасается, ему просто нравятся эти красивые украшения.",
    ["还有那塞牙的炖肉和焦黑的煎蛋……<P_Heart>（反胃）</>够了够了，想想就已经要吐了！"] = "А эта жилистая тушенка и подгоревшая яичница... <P_Heart> (тошнит) </> Хватит, хватит! От одной мысли об этом меня тошнит!",
    ["还有，我爸送的表放左口袋还是右口袋不容易被偷？这个得用星盘细算！ "] = "Кроме того, следует ли мне положить часы, подаренные мне отцом, в левый или правый карман, чтобы их меньше украли? Это необходимо тщательно рассчитать с помощью звездной карты!",
    ["这……"] = "Этот...",
    ["这……不太好说出口。 "] = "Это... нелегко сказать вслух.",
    ["这……真的吗？难道我应该带他出来晒晒太阳？"] = "Это... правда? Стоит ли мне вывести его погреться на солнышке?",
    ["这……这里是……玛丽与天使衣帽店……"] = "Э-это... Магазин шляп Мэри и ангела...",
    ["这一带的气氛，确实有些不同。"] = "Атмосфера в этом районе действительно немного другая.",
    ["这不就是偷吗？"] = "Разве это не просто воровство?",
    ["这不是传统意义上的隐身，而是“心理学隐身”——当认知被暗示引导时，真实也会从视野中滑落。"] = "Это не невидимость в традиционном понимании, а «психологическая невидимость» — когда познание направляется внушением, реальность также ускользает из поля зрения.",
    ["这不是我第一次遇到这种事情……"] = "Я уже не первый раз сталкиваюсь с подобным...",
    ["这不是打算和未来的合伙人商量嘛，我们一起成为廷根商界新星！"] = "Разве это не просто планы обсудить с будущими партнерами? Давайте вместе станем новыми звездами делового мира Тингена!",
    ["这世道啊……真是越来越看不懂了。您说呢？"] = "Этот мир... становится все труднее и труднее понять. Вам не кажется?",
    ["这个价钱只能买最下等的材料，阳台会漏雨的。"] = "По этой цене можно купить только материалы самого низкого качества, во время дождя балкон будет протекать.",
    ["这个孩子嘛，哎，真不让人省心。"] = "Что касается этого ребенка, вздох, он действительно не дает мне покоя.",
    ["这个花房贩卖鲜花，也贩卖着虔诚。"] = "В этом цветочном магазине продаются свежие цветы, а также продается благочестие.",
    ["这个锁看起来也很好打开……"] = "Кажется, этот замок тоже не составит труда открыть...",
    ["这个问题相当棘手。当然，我们必须要做点什么。"] = "Эта проблема довольно сложная. Конечно, мы должны что-то сделать.",
    ["这么厉害？给我也整一瓶。"] = "Это хорошо? Принеси мне тоже.",
    ["这么喜欢羊的话，来我家剪羊毛吧！这家伙的毛每周需要剪两次……"] = "Если ты так любишь овец, приходи ко мне домой стричь шерсть! Шерсть этого парня нужно стричь два раза в неделю...",
    ["这么大的船，要是撞上点什么就要命了，比如冰山……"] = "Для такого большого корабля столкновение с чем-нибудь, например с айсбергом, было бы фатальным...",
    ["这么好的时光，也许我们可以聊一些轻松的话题。作为你的心理医生，你可以在我面前畅所欲言。"] = "В такое чудесное время, возможно, мы сможем поговорить на какие-нибудь беззаботные темы. Как ваш психиатр, вы можете свободно говорить передо мной.",
    ["这么害怕高处的话，为什么要上来呢？"] = "Если ты так боишься высоты, зачем ты поднялся?",
    ["这么晚了，扫烟囱吗？"] = "Уже так поздно, ты чистишь дымоходы?",
    ["这二者之间有什么关联？"] = "Какая связь между ними?",
    ["这些孩子们手脚麻利，头脑灵活。您可以靠红帽子的特征找到我们，我们非常擅长跑腿和编织小工艺品。"] = "Эти дети сообразительны и сообразительны. Вы можете найти нас по красной шляпе; мы очень хорошо справляемся с поручениями и плетением небольших поделок.",
    ["这些植物，有的来自危险的苏尼亚海底，有的来自弗萨克边境雪地……当然，卖得最好的还是女神喜爱的夜香草和深眠花。"] = "Эти растения, некоторые родом из опасного дна моря Сония, некоторые из заснеженных земель границы Фейсака... Конечно, бестселлерами по-прежнему остаются любимые Богиней Ночная Ароматная Трава и Сонный Цветок.",
    ["这些知识确实能帮到很多人。而且你看，你明明很擅长讲这些。 "] = "Эти знания действительно могут помочь многим людям. И слушай, ты явно очень хорошо объясняешь эти вещи.",
    ["这些碎片简直是浑然天成！我要用它们做一件雕塑——破碎的心……"] = "Эти фрагменты просто натуральные! Я хочу использовать их, чтобы сделать скульптуру — разбитое сердце…",
    ["这些私酒贩子毫无底线可言，用工厂都看不上的工业原料酿酒，损人利己，您也千万要注意别上当受骗，如果碰到疑似私酒贩子的人，麻烦您告诉我。"] = "Эти бутлегеры не имеют никакой прибыли; они используют промышленное сырье, из которого даже заводы не хотят варить спирт, вредя другим ради своей выгоды. Вы также должны быть осторожны, чтобы не быть обманутыми. Если вы встретите кого-то, кого подозревают в бутлегере, пожалуйста, дайте мне знать.",
    ["这些花都可以看看。"] = "Смело взгляните на любой из этих цветов.",
    ["这些葡萄看上去好极了！"] = "Этот виноград выглядит великолепно!",
    ["这些规矩现在还有人用吗？"] = "Неужели этим правилам кто-то еще следует?",
    ["这些贵族老爷们哟……他们养着那么多位情人，每个月得花不少钱吧？"] = "Эти благородные лорды... у них так много любовниц, что им приходится тратить много денег каждый месяц, верно?",
    ["这位同学，想算算今天的运势吗？我是占卜俱乐部的会员，包你满意。"] = "Этот одноклассник, хочешь посчитать сегодняшнее состояние? Я член Клуба Гадания, гарантирую, вы останетесь довольны.",
    ["这傻小子一点防备都没有，手快拿麻袋把他套住，直接搜走他身上的钱……"] = "Этот глупый ребенок вообще не имеет охраны. Давайте побыстрее, поймаем его и возьмем на себя все деньги...",
    ["这取决于序列层次。高序列的圣者或天使确实可能引发大范围的异常天象，但那通常意味着失控或神性外溢，是相当危险的现象。"] = "Это зависит от уровня последовательности. Высокопоследовательные Святые или Ангелы действительно могут вызвать крупномасштабные аномальные погодные явления, но это обычно означает потерю контроля или переполнение божественности, что является довольно опасным явлением.",
    ["这只母猫在我家门口叫了三天！全家人都被它打搅得睡不着觉。"] = "Эта кошка мяукает у моей двери уже три дня! Вся моя семья настолько обеспокоена этим, что мы не можем спать.",
    ["这只猫好像在笑，会不会能听懂人的指令？"] = "Кажется, этот кот улыбается... неужели он понимает человеческие команды?",
    ["这只猫的名字是“甜冰茶”？"] = "Этого кота зовут «Сладкий чай со льдом»?",
    ["这只猫的眼睛怎么看上去不一样大？"] = "Почему глаза этой кошки кажутся разного размера?",
    ["这叫什么“特殊服务”？我穿得那么少，还踩着高跟鞋，在风口里排队……"] = "Что это за «специальная служба»? Я была так скудно одета, на высоких каблуках, стояла в очереди на ветру...",
    ["这可是最新科技，听说光是钢板就厚得吓人。而且你看这规模，十层甲板呢！"] = "Это новейшая технология; Я слышал, что стальные пластины сами по себе ужасно толстые. И посмотрите на масштаб, десять колод!",
    ["这可能是因为我来自贝克兰德的西区……抱歉，我的意思是，我接受的教育可能……不太一样……对不起，我不知道该怎么说……"] = "Возможно, это потому, что я родом из Западного округа Баклунда... Извините, я имею в виду, образование, которое я получил, может быть... немного другим... Извините, я не знаю, как это сказать...",
    ["这合法吗？"] = "Это законно?",
    ["这周他一直都在约同一位小姐，听说那位小姐出手也不低。唉，有钱真好啊。"] = "Он всю неделю приглашал на свидание одну и ту же даму. Я слышал, что у нее тоже довольно глубокие карманы. Эх, очень приятно быть богатым.",
    ["这孩子名叫吃不饱，你看这橘红的条纹，是不是很肥美？"] = "Этого ребенка зовут «Не могу насытиться». Посмотрите на эти оранжево-красные полоски, разве они не пухлые и красивые?",
    ["这孩子虽然看着活泼，其实跑得可慢了，所以才坐在椅子上不肯动弹。"] = "Хотя этот ребенок выглядит живым, на самом деле он бегает очень медленно, поэтому сидит на стуле и отказывается двигаться.",
    ["这家伙机灵又凶悍，但凡是上了酒吧禁入名单的人，它一准能闻出来。"] = "Этот малый смышлёный и свирепый: если кто-то внесён в чёрный список бара, он учует его за версту.",
    ["这家伙欠了我一大笔钱。你看门口这些画，都是被他毁掉的！"] = "Этот парень должен мне огромную сумму денег. Посмотрите на эти картины у двери, они все испорчены им!",
    ["这就是为什么我变成了流浪者，记者先生。"] = "Вот почему я стал странником, господин репортер.",
    ["这就是命运戏弄我的时刻了，但我的爱依旧真挚。"] = "Это момент, когда судьба издевается надо мной, но моя любовь остаётся искренней.",
    ["这就是我的活儿。有人闹事就拖出去，有人喝醉了就盯着，有人想上二楼……得确认他付得起那个价。"] = "Такая уж у меня работа. Кто буянит — вышвыриваю, кто напился — приглядываю, а если кто хочет на второй этаж... сперва нужно убедиться, что ему это по карману.",
    ["这就是谋杀！"] = "Это убийство!",
    ["这总让我想起莫雷蒂一家——那是我当年的邻居，那家的大哥参加了当年的第一届政府雇员考试，如今，他们已经搬到贝克兰德去了。"] = "Это всегда напоминает мне о семье Моретти — тогда они были моими соседями. В том же году старший сын этой семьи сдал первый экзамен на государственного служащего, и теперь они переехали в Бэкланд.",
    ["这是一个创新点……我得抓紧科研，搞清楚这里的作物为什么长得这么快。"] = "Это инновационная точка... Надо поторопиться с исследованиями и разобраться, почему урожай здесь растет так быстро.",
    ["这是一瓶特制的药剂，我需要你在赛前把它混进棕熊的酒里，毕竟他也很需要休息了。"] = "Это особое зелье. Мне нужно, чтобы ты подмешал его в напиток Бурого Медведя перед матчем. Ведь ему очень нужен отдых.",
    ["这是个惬意的地方，不过我当时的邻居们大多都搬走了，很遗憾……"] = "Это уютное место, но большинство моих соседей тогда уехали, очень жаль...",
    ["这是临时起草的交接契约，您在这里签字就好。"] = "Это временно составленный договор передачи. Просто подпишите здесь.",
    ["这是什么意思？"] = "Что это значит?",
    ["这是什么？看起来很特别，不像是外面能买到的。"] = "Что это? Он выглядит особенным, его нельзя купить на улице.",
    ["这是令人欣喜的进展，对吧？"] = "Это отрадный прогресс, не так ли?",
    ["这是你写的诗吗？"] = "Это стихотворение, которое ты написал?",
    ["这是卖什么的地方？"] = "Что это за место?",
    ["这是哪里来的小可怜，瞧瞧这身搭配……"] = "Откуда взялась эта бедная малышка? Посмотрите на этот наряд...",
    ["这是因为，是因为……"] = "Это потому, потому что...",
    ["这是对食物的谋杀！煮过头的卷心菜、干硬的炖莴苣、像水一样的豌豆汤…… "] = "Это убийство против еды! Переваренная капуста, сухой и жесткий тушеный салат, гороховый суп со вкусом воды...",
    ["这是我们第三次约会，也是你第三次迟到。"] = "Это наше третье свидание, и ты уже в третий раз опаздываешь.",
    ["这是我第一次见到羊……没想到摸起来这么软。"] = "Я впервые вижу овцу... Я не ожидала, что она окажется такой мягкой.",
    ["这是我见过最差劲的小丑……我敢打赌，他今天赚不到一个便士。"] = "Это худший клоун, которого я когда-либо видел... Держу пари, что он сегодня не заработает ни копейки.",
    ["这是最新款的蒸汽警车，看看这车身线条，多流畅！起步够快，追得上码头区最滑溜的贼。"] = "Это новейшая модель паровой полицейской машины. Посмотрите на эти линии тела, какие плавные! Он начинается достаточно быстро, чтобы поймать самых скользких воров в районе Дока.",
    ["这是种……很特别的疗法，似乎有效，只是需要一点点勇气。"] = "Это... весьма своеобразный метод лечения. Кажется, он действует, нужно лишь немного мужества.",
    ["这是给谁准备的礼物吗？"] = "Эти подарки приготовлены для кого-то?",
    ["这是自然。我希望我们以后在除了利益之外的地方，还能发展一些友谊，亨特。"] = "Это естественно. Я надеюсь, что в будущем, помимо интересов, у нас появится еще и дружба, Хантер.",
    ["这是诬陷！你就等着我的律师来找你麻烦吧！"] = "Это подстава! Просто подожди, пока придет мой адвокат и доставит тебе неприятности!",
    ["这束花，是你的吗？"] = "Этот букет твой?",
    ["这样吧，我可以去试试！我、我算是见习小丑。"] = "Как насчет такого: я могу попробовать! Я... я вроде как клоун-стажер.",
    ["这样子啊。"] = "Это так?",
    ["这样最帅啊！你想想，从教堂顶一跃而下，你的背后是一轮巨大的红月！"] = "Это самое крутое! Только представьте, вы прыгаете с вершины церкви, а позади вас стоит огромная красная луна!",
    ["这样没人敢合作吧？"] = "Никто бы не осмелился так сотрудничать с тобой, верно?",
    ["这样，如果你愿意放过我，我告诉你xxx的秘密。"] = "Давай так: если ты отпустишь меня, я раскрою тебе тайну xxx.",
    ["这根本不重要。"] = "Это совсем не важно.",
    ["这次走得太匆忙，这片领地还来不及找到新的主人，恐怕要荒废了。"] = "Отъезд был слишком поспешным, для этих земель так и не успели найти нового хозяина — боюсь, они придут в запустение.",
    ["这正是医院的金字招牌！是最好的宣传！"] = "Это именно золотой стандарт репутации больницы! Это лучшая акция!",
    ["这没什么。别忘了，暂住领地的另一条代价是你们要给我们帽子帮让出一部分的跑腿利润。"] = "Ничего. Не забывайте, что другая цена за пребывание на территории — это то, что вам придется отдать часть прибыли от поручений нашей шляпной банде.",
    ["这片领地似乎已经很久没有人拜访了，要去的乘客很少见呢。您要去这里的话，以后也可以随时找我上车。"] = "Кажется, давно никто не посещал эту землю; пассажиры, идущие туда, довольно редки. Если вы собираетесь туда, вы всегда можете найти меня, чтобы сесть на поезд в будущем.",
    ["这玩意儿真管用？不会是那些神棍编出来骗钱的把戏吧？"] = "Эта штука действительно работает? Разве это не какая-то уловка, придуманная этими шарлатанами, чтобы выманить деньги, не так ли?",
    ["这破东西像从墓地里埋了五十年再挖出来，也能叫礼物？我是垃圾桶吗！"] = "Этот кусок хлама выглядит так, будто его пятьдесят лет хоронили на кладбище, прежде чем его выкопали, и вы называете это подарком? Я мусорный бак!",
    ["这确实值得期待。请把它定制为项圈吧，我想我的小猎犬正需要这样一件足够优雅的生日礼物。"] = "Этого действительно стоит с нетерпением ждать. Пожалуйста, настройте его как ошейник; Думаю, моей маленькой собачке нужен такой элегантный подарок на день рождения.",
    ["这要是能登出来了，我就发财了。"] = "Если это будет опубликовано, я стану богатым.",
    ["这该死的船是沉到海底喂鱼了吗？等得我都快睡着了。"] = "Неужели этот чертов корабль опустился на дно моря, чтобы накормить рыбу? Я так долго ждал, что почти сплю.",
    ["这起初也有愚者的帮助。后来发现……<P_Heart>（眼神温和）</>这是保持人性最好的锚点之一。"] = "Первоначально в этом также помог Шут. Позже я обнаружил... <P_Heart>(Нежные глаза)</> это один из лучших якорей для поддержания человечества.",
    ["这车煤真重，推得我胳膊都快断了。"] = "Эта тележка с углем очень тяжелая, у меня такое ощущение, будто руки вот-вот сломаются, если ее толкнуть.",
    ["这里为什么有口锅？"] = "Зачем здесь горшок?",
    ["这里是公共空间……我认为，谁都可以在这里活动，不存在“妨碍”。"] = "Это общественное пространство... Я считаю, что здесь может проявлять активность каждый, нет такого понятия, как «тревожать».",
    ["这里是鲁恩，没有扎尔哈这种拜亚姆地方特产。"] = "Это Лоэн; здесь нет местных деликатесов, таких как Захар Баяма.",
    ["这里有些军官驻扎，你可以向他们了解更多内容。"] = "There are some military officers stationed here; you can learn more from them.",
    ["这里灯光有点暗，要不凑近一点，让我先看清楚？"] = "Освещение здесь немного тусклое. Почему бы тебе не подойти поближе, чтобы я мог ясно тебя видеть?",
    ["这里的风尚从不追求张扬，而是在凛冬之中依旧保持从容，既然你来到这片冰雪之间，不如让我见识一下你的品鉴方式。"] = "Мода здесь никогда не стремится быть показной, а скорее сохранять спокойствие в разгар зимы. Раз уж ты пришел в этот лед и снег, почему бы не позволить мне увидеть твой способ признательности.",
    ["这里的风景真不错。很适合坐下来，安静地喝一杯茶、看几页书……"] = "Пейзажи здесь действительно хороши. Он очень подходит для того, чтобы сесть, спокойно выпить чашечку чая и прочитать несколько страниц книги...",
    ["这食堂再吃下去，我的胃怕是要趁我睡着的时候叛逃了！"] = "Если я продолжу есть в этой столовой, боюсь, мой желудок попытается отказать, пока я сплю!",
    ["这首诗很美，你从什么时候开始写诗的？"] = "Это стихотворение прекрасное, когда вы начали писать стихи?",
    ["这黑烟钻肺里比烈酒还烧得慌，上周又抬走两个咳血的可怜虫，大伙们可都看见了。 "] = "Этот черный дым обжигает легкие сильнее, чем крепкий алкоголь. На прошлой неделе унесли двух бедняков, кашлявших кровью, все это видели.",
    ["连敷衍的理由都懒得编，我还能对你抱有什么期望……"] = "Тебе лень даже придумать дежурную отговорку, чего ещё мне от тебя ожидать...",
    ["送给家人，我建议是这边的郁金香……或许还应该加上你的陪伴。"] = "Для семьи предлагаю вот эти тюльпаны... возможно, вам тоже стоит добавить свою компанию.",
    ["送给恋人可以是玫瑰或者百合。"] = "Возлюбленной можно подарить розы или лилии.",
    ["送货？送到哪儿？总不会是餐馆吧？"] = "Доставка? Куда? Это не будет ресторан, не так ли?",
    ["选项不设置Action的跳转测试"] = "Вариант без теста прыжка действия",
    ["选项跳转测试"] = "Тест прыжка опциона",
    ["透过洁净的窗子，你看到深眠花恬静地开放着。"] = "Через чистое окно вы видите безмятежно цветущие Спящие цветы.",
    ["通关了，这是你的奖励。"] = "Уровень пройден, это ваша награда.",
    ["速度谁都能拉起来，但真正难的是控制。让我看看你的极限？"] = "Разогнаться может каждый, а вот совладать со скоростью — настоящее искусство. Покажи мне свой предел!",
    ["遇到什么事了吗？"] = "Что-то случилось?",
    ["遗憾？也许这一切都是女神的指引。"] = "Сожалеть? Возможно, все это — руководство Богини.",
    ["遵循医嘱就是对我最好的感激，女士。"] = "Выполнение предписаний врача - лучший способ отблагодарить меня, мадам.",
    ["邓恩·史密斯。"] = "Данн Смит.",
    ["邓恩队长是廷根的上一任值夜者小队队长，他的性格非常温和，也是位富有经验的非凡者。"] = "Капитан Данн был предыдущим капитаном отряда Тинген Найтхокс. У него был очень мягкий характер, а также он был опытным Потусторонним.",
    ["那{{PlayerName}}，如果你是格尔曼，那个格尔曼，你想在什么样的地方掀起风浪呢？"] = "Тогда {{PlayerName}}, если бы ты был Германом, этим Германом, в каком месте ты бы хотел устроить беспорядки?",
    ["那、那我再加半瓶黑兰德！这可是我最后的家当了！"] = "Т-тогда я добавлю полбутылки Black Land! Это все, что у меня осталось!",
    ["那上周这出，也是他写的？"] = "Значит, эпизод прошлой недели тоже был написан им?",
    ["那个小女孩病得很重，现在最大的愿望就是想看一场小丑表演。唉，这么一个简单的承诺都被我搞砸了。"] = "Эта маленькая девочка очень больна, и ее самое большое желание сейчас — увидеть представление клоуна. Эх, я испортил такое простое обещание.",
    ["那个探险家又来了，哦！女神庇佑，今天他千万不要点到我！"] = "Этот исследователь снова здесь. Ой! Богиня Защиты, надеюсь, он не выберет меня сегодня!",
    ["那个营销家庭美满、爱妻爱女的市长候选人，有个秘密情人，就在这个剧院当演员。"] = "У того кандидата в мэры, который выставляет себя примерным семьянином, любящим жену и дочь, есть тайная любовница — здешняя театральная актриса.",
    ["那个，我只是路过……"] = "Ну я просто проходил мимо...",
    ["那么请问您们是否有兴趣……"] = "Тогда позвольте мне спросить, интересно ли вам...",
    ["那么这一切会给那些目光带来什么呢？"] = "Тогда что же все это принесет этим взглядам?",
    ["那也比一辈子困在码头上强！至少那些水手们、海盗们见识过真正的海上传奇！"] = "Это всё равно лучше, чем застрять в доках на всю жизнь! По крайней мере, эти моряки и пираты стали свидетелями настоящих морских легенд!",
    ["那些忙了一天、心里烦的人，来这儿坐一晚上，听她叫几声哥哥，走的时候脸上都是带着笑的。"] = "Уставшие за день люди с тяжестью на сердце приходят сюда посидеть вечерком, услышат, как она ласково назовет их братом, и уходят с улыбкой на лице.",
    ["那些绅士老爷们或许会嫌弃，但穿丝绸裙的女士有时候会心软。凯西娜，再教教他。"] = "Эти джентльмены могут смотреть на них свысока, но у дам в шелковых платьях иногда бывают мягкие сердца. Кэсси, научи его еще раз.",
    ["那些街上晃悠的行人全是欲望的化身——所以你尽管放手去干！干他个天翻地覆，用暴烈、疯狂的手段来维护这脆弱的秩序！"] = "Все эти пешеходы, бродящие по улицам, — воплощения желания, так что не стесняйтесь изо всех сил! Переверните его с ног на голову и используйте жестокие, безумные средства, чтобы сохранить этот хрупкий порядок!",
    ["那今晚，您只当被好好看着的人。"] = "Тогда сегодня вечером именно на тебя будут обращать должное внимание.",
    ["那低序列者呢？"] = "А как насчет людей с низкой последовательностью?",
    ["那你为什么还在这里？"] = "Тогда почему ты все еще здесь?",
    ["那你快出来把钱给我！"] = "Тогда выходи и дай мне деньги!",
    ["那你想让我找你吗？"] = "Тогда ты хочешь, чтобы я пришёл к тебе?",
    ["那你算来对地方了。不过光看跳舞多没意思，要不要试试……让这里的先生陪你坐坐？"] = "Тогда вы пришли в нужное место. Но смотреть танец скучно; почему бы не попробовать... чтобы джентльмены сидели рядом с тобой?",
    ["那你觉得，剧本差在哪儿？"] = "И в чём же, по-твоему, изъян сценария?",
    ["那几个到处捣乱的混小子藏哪儿去了？等我逮到他们，非得让他们知道点规矩不可！"] = "Где спрятались эти нарушители порядка? Как только я их поймаю, я позабочусь о том, чтобы они узнали кое-что о правилах!",
    ["那占卜的意义是？"] = "В чем смысл гадания?",
    ["那可不行！我还打算趁学生们有热情，在晚上多开几节课呢！"] = "Так не пойдет! Я как раз собираюсь воспользоваться пылом студентов и провести еще несколько вечерних занятий!",
    ["那可是我们鲁恩王国在苏尼亚海殖民统治的支点，数一数二的大城！是神灵许诺的流淌着奶和蜜酒的宝藏之地！"] = "Это точка опоры колониального правления нашего Королевства Лоэн в море Сония, одного из крупнейших крупных городов! Это земля сокровищ, текущая молоком и медом, обещанная богами!",
    ["那可真够呛。对了，听说圣数教堂最近有免费的医疗救助，你可以去看看。"] = "Это действительно тяжело. Кстати, я слышал, что в соборе Святого числа недавно появилась бесплатная медицинская помощь, вам стоит сходить туда и провериться.",
    ["那如果快速摇扇呢？"] = "Что, если быстро встряхнуть вентилятор?",
    ["那姑娘逃跑时，一只鞋卡在火炉口……"] = "Когда девушка убегала, одна туфелька застряла в устье камина...",
    ["那它成功逗笑了多少人？"] = "Тогда скольких людей это успешно рассмешило?",
    ["那它的名字叫？"] = "Тогда как оно называется?",
    ["那就好，你可千万不要出声，我在蹲守一件大新闻！"] = "Это хорошо, ты не должен издавать ни звука. Я делаю большую сенсацию!",
    ["那就帮我擦干净摊子。"] = "Тогда помоги мне вытереть прилавок.",
    ["那屋里的动静……今晚又该睡不着了。"] = "Суматоха в этой комнате... Сегодня ночью я снова не смогу заснуть.",
    ["那当然。至少现在，我是您唯一的“演奏家”。 "] = "Конечно. По крайней мере, на данный момент я ваш единственный «исполнитель».",
    ["那当然很好……"] = "Это, конечно, было бы здорово...",
    ["那当然是因为……哦，那些乡下人的事我怎么会知道呢？我只关心能换多少便士，阁下。"] = "Это потому что... ох, откуда мне знать об этих деревенских делах? Меня волнует только то, сколько пенсов я смогу получить, милорд.",
    ["那当然，票我都让人买好了，双人连座。 "] = "Конечно, я уже попросил кого-то купить билеты на два места вместе.",
    ["那得看您怎么聊了。有的人，就真的只是聊天；有的人呢，聊高兴了就能谈成一笔生意；<P_Heart>（低声）</>还有的人，聊着聊着，就去二楼了。"] = "Это зависит от того, как вы общаетесь. Некоторые люди просто болтают; некоторые люди, находясь в хорошем настроении, могут заключить деловую сделку; <P_Heart>(Тихий голос)</> и несколько человек, болтая, в конечном итоге поднимаются на второй этаж.",
    ["那怎么不进去？"] = "Тогда почему бы тебе не войти?",
    ["那意味着“请离我远些”。而把扇子竖直抵着下巴，是在说“我愿与您交谈”。"] = "Это означает: «Пожалуйста, держитесь от меня подальше». А держать веер вертикально у подбородка означает сказать: «Я хочу с тобой поговорить».",
    ["那我以后要去哪里找你？ "] = "Тогда где мне найти тебя в будущем?",
    ["那我们是不是变聪明了！"] = "Значит, мы теперь стали умнее?!",
    ["那我们继续，“坚持”这个单词……"] = "Тогда продолжим, слово «настойчивость»…",
    ["那我就不客气了。"] = "Тогда я не буду вежливым.",
    ["那我就算没白背这三脚架！"] = "Тогда я не зря таскал этот штатив!",
    ["那我就说我养的是……一根会自己移动的皮带？"] = "Тогда я просто скажу, что я держу... ремень, который движется сам по себе?",
    ["那我给哥哥捏捏，捏完就不累了。"] = "Тогда позволь мне помассировать тебя, брат, ты не устанешь, когда я закончу.",
    ["那我说说我的问题！"] = "Тогда позвольте мне рассказать вам мои вопросы!",
    ["那我辛苦研究了一晚上做的攻略算什么呢？"] = "Тогда в чем смысл руководства, за исследованием которого я провел всю ночь?",
    ["那是“窥秘人”途径的画家在灵性饱满时创作的。不过买这类画作要小心……"] = "Это было создано художником пути «Таинственного Прайера», когда его духовность была полной. Однако будьте осторожны при покупке таких картин...",
    ["那是一只很有灵性的黑猫，从前无论跑到哪里，都会在太阳落山前回家……"] = "Это очень духовный черный кот. Раньше, куда бы он ни убегал, он всегда возвращался домой до захода солнца...",
    ["那是一只麻雀，亲爱的，它现在飞到了对面的房顶上。"] = "Это воробей, дорогой мой, он только что залетел на крышу напротив.",
    ["那是你没见识。听说船上有游泳池、舞厅和壁球室。啧啧，简直就是海上的皇宫！等我攒够钱，非要上去看看。"] = "Это потому, что ты невежественен. Я слышал, что на корабле есть бассейн, бальный зал и площадка для сквоша. Тск-цк, это практически дворец на море! Как накоплю достаточно денег, обязательно проверю.",
    ["那是我最喜欢的一部！不过，佛尔思小姐最近写了新的作品。"] = "Это мой любимый! Однако в последнее время мисс Форс написала новые произведения.",
    ["那有没有可能，是饭菜本身不好吃呢？"] = "Тогда возможно ли, что сама еда просто невкусная?",
    ["那滋味，就像被一群矿工在脑子里敲敲打打！"] = "Это ощущение похоже на то, как будто группа шахтеров работает у вас в голове!",
    ["那现在宣传的这位编剧，干了什么？"] = "Тогда что же сделал драматург, которого они сейчас продвигают?",
    ["那站好吧，首先声明——要是又掉进谁家烟囱里，记得帮我保密！"] = "Тогда стойте спокойно. Во-первых, отказ от ответственности: если я снова упаду в чей-то дымоход, не забудьте сохранить это для меня в секрете!",
    ["那等我攒攒钱，给我和玛丽各买一个吧。虽然这得让我少喝三个月的黑麦啤酒……"] = "Потом, когда я накоплю немного денег, я куплю один для себя и Мэри. Хотя это значит, что мне придется пить на три месяца меньше ржаного пива...",
    ["那算你运气好，今天号满了——都是些“我头晕，你给我开这点药怎么够”的主。"] = "Тогда вам повезло. Места сегодня заполнены — все это люди, которые говорят: «У меня кружится голова, как этого небольшого количества лекарства, которое вы прописали, достаточно?»",
    ["那群人有超过两米五的身高，站起来像一堵堵高墙。"] = "Эта группа людей была ростом более двух с половиной метров и стояла, как высокие стены.",
    ["那请自便，我要在这里构思一阵子。"] = "Тогда, пожалуйста, не стесняйтесь; Мне нужно какое-то время провести мозговой штурм.",
    ["那还不是因为您的房子一切都好！"] = "Это потому, что в вашем доме все в порядке!",
    ["那里可太棒了，长满香料的丛林、喷出黄金的土地、热辣的女孩儿和我面前这位棕色的朋友！"] = "Там было просто фантастично — джунгли, переполненные специями, земля, извергающая золото, горячие девушки и мой темнокожий друг здесь передо мной!",
    ["那里怎么了？"] = "Что там произошло?",
    ["那里的孩子们在丰收季非常喜欢将果实投入筐里，从而在劳作中衍生出了一系列的规则。"] = "Тамошние дети любили бросать фрукты в корзины во время сезона сбора урожая, что привело к появлению ряда правил, вытекающих из их труда.",
    ["那队长第一次出任务的时候会紧张吗?"] = "А капитан нервничал, когда впервые отправился на задание?",
    ["邪恶就隐藏在人群之中，它们喜爱在最欢乐的时候破坏一切，例如一个庆典……"] = "Зло прячется среди толпы; он любит все разрушать в самые радостные моменты, например, на празднике...",
    ["都在传，是惹上了不该惹的东西。连那些穿黑衣服的“特殊警察”都来了好几趟，但也没什么说法。"] = "Все говорят, что это потому, что они напортачили с чем-то, чего делать не следовало. Даже эти «спецназовцы» в черной одежде приходили несколько раз, но объяснений нет.",
    ["都在村口，也就是说，一下马车就能去厕所……真是方便，也许我可以记下来。"] = "Они все у въезда в деревню, а значит, в туалет можно пойти, как только выйдешь из вагона... это очень удобно, может, запишу.",
    ["都讲讲，老兄，你知道我喜欢听故事。"] = "Расскажи все, чувак, ты же знаешь, я люблю истории.",
    ["酒保……再来一杯马丁尼……"] = "Бармен... еще один Мартини...",
    ["酒保，再来一杯、来一杯扎尔哈。赞美扎尔哈，海盗最爱的啤酒！"] = "Бармен, еще один, дайте мне Захара. Слава Зархару, пиво пираты любят больше всего!",
    ["酒贩子收它干什么呢？"] = "Что от этого хотят торговцы спиртным?",
    ["酒馆？"] = "Таверна?",
    ["酒鬼，要有酒……要喝酒……想喝了……"] = "Пьяница, надо выпить... надо выпить... хочется выпить...",
    ["醉汉骂它挡了路，它甩尾翻个跟头——“嘿！老兄，你的裤脚，早破成拖布喽！”"] = "Пьяница обругал его за то, что он преграждает путь, он хлестнул хвостом и сделал сальто — «Эй! Старик, у тебя штанины уже порваны, как швабра!»",
    ["金秋湖或许更适合你。"] = "Озеро Золотая Осень может подойти вам больше.",
    ["鉴定后发现是赝品。但更戏剧性的是——画家本人恰好在场，当场提出以一千镑买下，说这是“史上最成功的致敬之作”。"] = "После экспертизы выяснилось, что это подделка. Но что было еще более драматично, так это то, что сам художник присутствовал при этом и сразу же предложил купить картину за тысячу фунтов, заявив, что это «самая успешная дань уважения в истории».",
    ["铁与血的征伐从未终结，历史沙盘等待着新的主宰——入局吧，征服者。"] = "Крестовый поход железа и крови никогда не заканчивается; историческая песочница ждет нового хозяина — вступай в игру, Завоеватель.",
    ["铁路是城市的勋章，我只是这枚勋章的一部分，廷根火车站应该包括每一位廷根市民的名字。"] = "Железная дорога — медаль города; Я всего лишь часть этой медали, и на вокзале Тингена должно быть указано имя каждого жителя Тингена.",
    ["铁针，小声些，羊毛提醒我们好几次了。"] = "Железная Игла, потише, — несколько раз предупреждал нас Вул.",
    ["铆钉……这是我最熟悉的物件了。一些诗句在我的脑海里自然地浮现——"] = "Заклепки... это предмет, который мне знаком больше всего. Некоторые строки естественным образом возникают в моей голове:",
    ["银链与水晶，看似随机的摆动，其实是命运给你的回答。"] = "Серебряная цепочка и кристалл, кажущиеся случайными покачивания, на самом деле являются ответом, который дает вам судьба.",
    ["错过了点名，也就是有了旷课记录，也就是错过了奖金，那我也就不需要那么努力考前几名了……"] = "Раз уж пропустил перекличку, значит, есть прогул, а значит, плакала стипендия... Тогда можно и не надрываться ради первых мест...",
    ["闭嘴！再散播谣言就把你们开除！三号炉温度又降了——谁去调整压力阀？"] = "Замолчи! Распусти слухи еще раз, и я тебя уволю! Температура печи номер три снова упала — кто будет регулировать клапан давления?",
    ["阁下……如果您愿意，可以将它卖给南边的造纸厂，这样不需要给垃圾大王中转费。"] = "Милорд... если хотите, можете продать его бумажной фабрике на юге, чтобы вам не пришлось платить посреднику Королю Мусора.",
    ["阁下，您看起来并不常干这一行。"] = "Милорд, кажется, вы не часто это делаете.",
    ["阁楼只要一苏勒的租金，六便士的面包，至少还能留下半瓶酒……"] = "Чердак стоит всего один соль за аренду, шесть пенсов за хлеб, по крайней мере, у меня еще останется полбутылки вина...",
    ["阿尔菲，我见到比尔了！"] = "Алфи, я видел(а) Билла!",
    ["阿斯顿，我相信你明白，教会是有立场的。要剔除这一点很难……"] = "Астон, я думаю, ты понимаешь, что у Церкви есть своя позиция. Трудно это удалить...",
    ["附近的路灯最近突然坏了，下班走的时候什么都看不见！"] = "Близлежащие уличные фонари недавно были сломаны; Я ничего не вижу, когда ухожу с работы!",
    ["除了喝酒就是打牌，你血的滋味也不怎么样啊。"] = "Если не считать питья и игры в карты, твоя кровь тоже не такая уж и вкусная.",
    ["随便看，十苏勒一把。当装饰挂墙上挺好看的。"] = "Вы только посмотрите: десять солей за горсть. Он отлично смотрится, если повесить его на стену в качестве украшения.",
    ["随手拿走了一片看起来还算干净的碎布，并没有想该去哪里处置它。"] = "Вы машинально прихватили кусок относительно чистой тряпки, даже не подумав, куда его деть.",
    ["隐蔽包厢？"] = "Скрытый ящик?",
    ["难得我们有同样的心情，老汤姆。或许，我们以后还能去更远、更舒适的城市。"] = "Редко мы сходимся во мнении, старина Том. Быть может, когда-нибудь мы сможем перебраться в ещё более далёкий и уютный город.",
    ["难道是因为……"] = "Неужели из-за того, что...",
    ["集市的，还有她家里，都是花！天台上也有她种的花。"] = "На рынке, у нее дома — повсюду цветы! И на крыше тоже цветут посаженные ею цветы.",
    ["需要……八百镑?!<P_Heart>（这价格相当于普通工人十五年的薪水！）</>"] = "Это стоит... восемьсот фунтов?! <P_Heart> (Эта цена эквивалентна пятнадцатилетней зарплате обычного рабочего!) </>",
    ["需要导游服务就来找我！"] = "Приходите ко мне, если вам нужны услуги гида!",
    ["需要注意什么吗？"] = "Есть ли что-нибудь, на что мне нужно обратить внимание?",
    ["霍纳奇斯，还是老样子……上次是我输了，不过下次，我会带新的“玩具”，再来一场“欺诈的游戏”。"] = "Хорнацис, все как всегда... В прошлый раз я проиграл, но в следующий раз принесу новые \"игрушки\" и устрою еще одну \"игру в обман\".",
    ["非凡者能够影响天气吗？"] = "Могут ли Потусторонние влиять на погоду?",
    ["非凡者该如何安排假期？"] = "Как Потусторонние должны организовать свой отпуск?",
    ["非常、非常感谢您的理解！您真是一个善良的人，和店主先生一样！愿女神庇佑您！"] = "Огромное вам спасибо за понимание! Вы действительно добрый человек, как и продавец! Пусть Богиня Вечной Ночи защитит тебя!",
    ["非常成功。我身后跟着一支浩浩荡荡的小尾巴，太幸福了！ "] = "Очень успешно. За мной следует длинный суетливый хвост – это чистое блаженство!",
    ["非常热情地开始推销了……"] = "С большим энтузиазмом начал рекламную кампанию...",
    ["靠你了，我……已经没有力气了……"] = "Решать тебе, у меня... сил не осталось...",
    ["音符在这里"] = "Заметка здесь",
    ["顺便一提，我父亲毕业于廷根大学。"] = "Кстати, мой отец окончил Тингенский университет.",
    ["额……"] = "Хм...",
    ["风……带来启示，也带走尘埃。"] = "Ветер... приносит откровение и уносит прах.",
    ["风尚不是炫耀华服，而是身份、礼仪与审美的平衡。既然你站到了这里，不妨接受一场真正的品鉴挑战。"] = "Мода – это не демонстрация модной одежды, а баланс индивидуальности, этикета и эстетики. Раз уж вы здесь, почему бы не принять настоящий вызов моде?",
    ["风尚会随着花期流转，也会随着心境改变；既然来到这片花海，不妨用你的搭配留下属于自己的颜色，让我们来进行一场时尚品鉴吧！"] = "Мода течет вместе с сезоном цветения и меняется вместе с настроением; раз уж вы попали в это море цветов, почему бы не оставить свой цвет в своем наряде? Давайте устроим конкурс на оценку моды!",
    ["风尚品鉴通常会从基础挑战开始安排。等获得廷根<P_Yellow>五位</>初级时尚会员的认可，成为中级时尚会员后，再来和我交流搭配心得吧。"] = "Оценка стиля обычно начинается с базовых испытаний. Завоюйте признание <P_Yellow>пяти</> младших знатоков моды в Тингене, станьте знатоком среднего ранга — и тогда приходите обсудить со мной тонкости стильных образов.",
    ["风暴之主……黑夜女神……嗯……老学长也保佑……"] = "Повелитель Штормов... Богиня Вечной Ночи... Хм... Пусть старый старший тоже благословит меня...",
    ["风暴之主就像大海一样包容。祂并不在意跪在祂面前的人是贵族还是水手，因为在浩瀚的大海面前，我们都一样渺小。"] = "Повелитель Штормов такой же инклюзивный, как море. Ему все равно, будет ли человек, преклоняющий колени перед Ним, дворянином или моряком, потому что перед огромным морем мы все одинаково малы.",
    ["风暴在上……那其实都是我丈夫的意愿。嗯……我只是他的妻子，只要支持他就好。"] = "Буря наверху... на самом деле это было желание моего мужа. Эм... Я всего лишь его жена, мне просто нужно его поддержать.",
    ["风暴在上！你修好的，绝不仅仅是风车……"] = "Буря выше! То, что вы починили, это точно не просто ветряная мельница...",
    ["风暴在上，保佑我平安回到妻子们的身边。"] = "Пусть Буря будет выше, благослови меня, чтобы я благополучно вернулся к своим женам.",
    ["风暴在上，我已经向朋友、家人发誓，我要戒赌……"] = "Наверху буря, я поклялся своим друзьям и семье, что брошу играть в азартные игры...",
    ["风暴在上，我的朋友想家了……"] = "Буря надо мной, мой друг соскучился по дому...",
    ["风险与机遇，财富与美人……"] = "Риск и возможности, богатство и красота...",
    ["风雨无阻！孩子，你也感兴趣吗？"] = "Дождь или блеск! Детка, тебе тоже интересно?",
    ["首先要避开月圆之夜、灵潮高峰日和正神教会的大型庆典期。"] = "Прежде всего нужно избегать ночей полнолуния, дней пика приливов духовности и периодов больших празднеств Церквей Истинных Богов.",
    ["首先，身体保持挺直，然后在空中伴随一个转体，使用背部着陆至草垛中。"] = "Сначала держите тело прямо, затем сделайте поворот в воздухе и приземлитесь на спину в стоге сена.",
    ["首先，躲开赌场的那帮猎狗，悄悄地伪装进去。"] = "Во-первых, избегайте гончих из казино и прокрадитесь туда переодетым.",
    ["香水是想象力的转化，廷根的特色地点印象都被我浓缩进了瓶子里，您要试试吗？"] = "Духи – это трансформация воображения. Впечатления от характерных мест Тингена я собрал в бутылки. Хотели бы вы их попробовать?",
    ["马上就到选举了，希望您能为我投出宝贵的一票！"] = "Скоро выборы; Надеюсь, вы сможете отдать за меня свой драгоценный голос!",
    ["骗子！全是骗人的！“百分之五的慈善”？我呸！"] = "Лжецы! Это все ложь! «Пять процентов благотворительности»? Пффф!",
    ["高、高贵的夫、夫人……这苹果，这苹果……我需要练习！"] = "Нет, благородная ля, леди... это яблоко, это яблоко... Мне нужно потренироваться!",
    ["高明什么，我回去真的加了一礼拜班，不然哪来的钱今晚再点她？"] = "Что такого умного? Я действительно работал сверхурочно неделю, когда вернулся. Иначе где бы у меня были деньги, чтобы заказать ее снова сегодня вечером?",
    ["高级风尚品鉴只会向通过中级时尚会员考核的人开放。先去参加廷根前面<P_Yellow>两场</>普通难度的中级时尚品鉴挑战吧！等你成为时尚协会高级会员，再来和我讨论搭配心得吧！"] = "Продвинутая оценка моды открыта только для тех, кто прошел промежуточную аттестацию для членов индустрии моды. Сначала примите участие в двух конкурсах </> средней сложности средней сложности <P_Yellow> в Тингене! Как только вы станете старшим членом Ассоциации моды, вернитесь и обсудите со мной идеи стиля!",
    ["魔药象征的意义在它的名称中，作为“占卜家”，你可以多想想这个名字的象征含义。"] = "Символическое значение зелья заключено в его названии. Будучи «Провидцем», вы можете больше задуматься о символическом значении этого имени.",
    ["鲁恩慈善助学基金会，听说是从贝克兰德来的，他们可以资助孩子继续上学。"] = "Благотворительный фонд Лоен, я слышал, он появился из Баклунда; они могут спонсировать детям продолжение обучения.",
    ["鲁恩是位于北大陆的工业强国。西边和因蒂斯共和国以间海、霍纳奇斯山脉为界，北部与弗萨克帝国接壤，东邻苏尼亚海，南面是迪西海湾。"] = "Лоен — промышленная держава, расположенная на Северном континенте. Он граничит с Республикой Интис на западе, Мидсиширом и горным хребтом Хорнацис, граничит с Империей Фейсак на севере, граничит с морем Сония на востоке и заливом Дизи на юге.",
    ["鲁恩的首都是贝克兰德，人们称之为伟大的“万都之都”。我曾听一个自称罗塞尔大帝同乡的非凡者说，贝克兰德很像“伦敦”。"] = "Столица Лоена — Баклунд, который люди называют великим «Городом городов». Однажды я слышал, как некий Потусторонний, утверждавший, что является земляком императора Розеллы, сказал, что Баклунд очень похож на «Лондон».",
    ["鸽子！你帽子里有鸽子！放出来！"] = "Голуби! В твоей шляпе голуби! Выпустите их!",
    ["黄水晶黛西小姐，这里最年轻的一位。不弹琴，不跳舞，也不聊天下大事。"] = "Мисс Цитрин Дейзи, самая младшая здесь. Не играть на пианино, не танцевать, не говорить о больших вещах.",
    ["黑夜女神教会的节礼日并不多，最重要的是冬礼日，其次就是满月时的月亮弥撒。"] = "В церкви Богини Вечной Ночи не так уж много фестивалей. Самым важным является Зимний фестиваль, за которым следует Лунная месса в полнолуние.",
    ["黑夜教会的人来了又走，他们把这里清理得很干净。现在你看，花廊多漂亮，一点痕迹都没留下。"] = "Люди из Церкви Ночи приходили и уходили и поддерживали чистоту. Теперь вы видите, насколько прекрасна цветочная галерея, не оставляющая вообще никаких следов.",
